--
-- Name: erase_public_entry_reactions(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.erase_public_entry_reactions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.kind='erased' THEN DELETE FROM agent.public_entry_reactions WHERE entry_id=NEW.entry_id; END IF;
 RETURN NEW;
END $$;


--
-- Name: erase_owner_event_source_custody(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.erase_owner_event_source_custody() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NOT public.account_erasure_authorized(NEW.owner_id) THEN
  RAISE EXCEPTION 'original account erasure authority required' USING ERRCODE='42501';
 END IF;
 DELETE FROM agent.owner_event_subscriptions WHERE owner_id=NEW.owner_id;
 DELETE FROM agent.owner_source_input_receipts WHERE owner_id=NEW.owner_id;
 DELETE FROM agent.owner_command_receipts WHERE owner_id=NEW.owner_id AND command_kind IN
  ('owner.event_source.control.v1','owner.event_source.observe.v1','owner.event_source.deliver.v1');
 DELETE FROM agent.owner_outbox WHERE owner_id=NEW.owner_id AND topic='owner_event_source';
 -- The Goal may already have been deleted. Its original private conversation
 -- still owns the durable release demand; do not rely on the live Goal row.
 DELETE FROM event_store.outbox o USING conversation.conversations c
  WHERE o.tenant_id=c.tenant_id AND o.conversation_id=c.conversation_id
   AND c.created_by=NEW.owner_id AND c.purpose='owner_goal_execution'
   AND o.topic='owner.event_source.desired.v1';
 RETURN NEW;
END $$;


--
-- Name: erase_owner_goal_creation_receipts(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.erase_owner_goal_creation_receipts() RETURNS trigger
