--
-- Name: guard_device_tool_publication(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_device_tool_publication() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Dialogue tool publication group is immutable'; END IF;
 IF NEW.execution_home='device' AND NOT (
  (NEW.device_subject_kind='intent' AND EXISTS(SELECT 1 FROM agent.device_admissions a
   JOIN agent.device_grant_heads h ON h.intent_id=a.intent_id
   JOIN agent.device_grant_versions v ON v.intent_id=h.intent_id AND v.revision=h.admitted_revision
   WHERE a.tenant_id=NEW.tenant_id AND a.intent_id=NEW.source_intent_id AND a.run_id=NEW.source_run_id
   AND a.admitted_at_ms IS NOT NULL AND a.admitted_snapshot_hash=NEW.device_snapshot_hash AND v.signed_grant_hash=NEW.device_grant_proof_hash))
  OR (NEW.device_subject_kind='work_item' AND EXISTS(SELECT 1 FROM collaboration.work_item_device_admitted_custody d
   JOIN collaboration.work_item_execution_reservations r USING(work_item_id,goal_revision,control_revision,assignment_epoch)
   JOIN collaboration.work_items w USING(work_item_id)
   WHERE d.run_id=NEW.source_run_id AND r.tenant_id=NEW.tenant_id AND w.source_intent_id=NEW.source_intent_id
   AND d.admitted_at_ms IS NOT NULL AND d.admitted_snapshot_hash=NEW.device_snapshot_hash AND d.signed_grant_hash=NEW.device_grant_proof_hash))
 ) THEN RAISE EXCEPTION 'Device publication lacks original admitted custody' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_erased_history_search(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_erased_history_search() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM agent.agent_dialogue_entries WHERE entry_id=NEW.entry_id AND kind='erased') THEN
  RAISE EXCEPTION 'erased public source cannot be indexed';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_goal_tool_publication(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_goal_tool_publication() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.source_goal_id IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM runtime.runs r
  JOIN agent.dialogue_sessions s ON s.tenant_id=r.tenant_id AND s.conversation_id=r.conversation_id
  JOIN tool.tool_invocations i ON i.tenant_id=r.tenant_id AND i.run_id=r.run_id
  WHERE r.tenant_id=NEW.tenant_id AND r.run_id=NEW.source_run_id AND r.activity_kind=3
   AND s.subject_kind='goal' AND s.source_goal_id=NEW.source_goal_id AND s.source_intent_id IS NULL
   AND i.invocation_id=NEW.invocation_id AND i.tool_ref=NEW.tool_ref)
 THEN RAISE EXCEPTION 'Goal publication requires its original execution Tool custody' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_native_dialogue_interaction_command(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_native_dialogue_interaction_command() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Original Device command receipt is retained'; END IF;
 IF TG_OP='UPDATE' AND ((to_jsonb(NEW)-ARRAY['outcome','owner_ack','rejected_code','acknowledged_at_ms']) IS DISTINCT FROM
 (to_jsonb(OLD)-ARRAY['outcome','owner_ack','rejected_code','acknowledged_at_ms']) OR OLD.outcome IS NOT NULL OR NEW.outcome IS NULL)
 THEN RAISE EXCEPTION 'Original Device command has one immutable acknowledgement'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_native_dialogue_interaction_projection(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_native_dialogue_interaction_projection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Original Device Interaction observation is retained'; END IF;
 -- Stored generated columns are recomputed after BEFORE triggers; their source
 -- run_id/subject_kind remain immutable and must be compared here instead.
 IF TG_OP='UPDATE' AND ((to_jsonb(NEW)-ARRAY['intent_run_id','work_item_run_id','state_sha256','projection_sha256','projection_bytes','observed_run_sequence','control_open','status','updated_at_ms']) IS DISTINCT FROM
  (to_jsonb(OLD)-ARRAY['intent_run_id','work_item_run_id','state_sha256','projection_sha256','projection_bytes','observed_run_sequence','control_open','status','updated_at_ms'])
  OR NEW.observed_run_sequence<OLD.observed_run_sequence OR (OLD.status<>1 AND NEW.state_sha256<>OLD.state_sha256)
  OR (NEW.observed_run_sequence=OLD.observed_run_sequence AND NEW.projection_sha256<>OLD.projection_sha256))
 THEN RAISE EXCEPTION 'Device Interaction request is immutable and observations are monotonic'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_native_dialogue_terminal(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_native_dialogue_terminal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Original Native terminal fact and acknowledgement are immutable'; END IF;
 PERFORM 1 FROM agent.device_admissions WHERE intent_id=NEW.intent_id FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM agent.device_admissions a
   JOIN agent.device_grant_heads h ON h.intent_id=a.intent_id
   JOIN agent.device_grant_versions v ON v.intent_id=h.intent_id AND v.revision=h.admitted_revision
   WHERE a.intent_id=NEW.intent_id AND a.tenant_id=NEW.tenant_id AND a.owner_id=NEW.owner_id
    AND a.agent_id=NEW.agent_id AND a.dialogue_id=NEW.dialogue_id AND a.conversation_id=NEW.conversation_id
    AND a.run_id=NEW.run_id AND a.device_id=NEW.device_id AND a.installation_id=NEW.installation_id
    AND a.admitted_at_ms IS NOT NULL AND a.source_digest=NEW.source_digest
    AND a.admitted_snapshot_hash=NEW.snapshot_hash AND v.signed_grant_hash=NEW.grant_proof_hash)
 THEN RAISE EXCEPTION 'Native terminal requires exact actual admitted Intent custody' USING ERRCODE='23514'; END IF;
 IF NEW.resolution='published' AND NOT EXISTS(SELECT 1 FROM agent.dialogue_publications p
   WHERE p.tenant_id=NEW.tenant_id AND p.owner_id=NEW.owner_id AND p.agent_id=NEW.agent_id
    AND p.dialogue_id=NEW.dialogue_id AND p.source_intent_id=NEW.intent_id
    AND p.source_conversation_id=NEW.conversation_id AND p.source_run_id=NEW.run_id
    AND p.source_native_terminal_run_id=NEW.run_id AND p.source_kind='native_terminal_owner'
    AND p.execution_home='device' AND p.device_subject_kind='intent'
    AND p.entry_id=NEW.entry_id AND p.purpose='blocked')
 THEN RAISE EXCEPTION 'Native terminal acknowledgement requires its exact original publication' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_native_terminal_publication(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_native_terminal_publication() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND NEW.source_native_terminal_run_id IS DISTINCT FROM OLD.source_native_terminal_run_id
 THEN RAISE EXCEPTION 'Native terminal publication source is immutable'; END IF;
 IF NEW.source_kind='native_terminal_owner' AND NOT EXISTS(SELECT 1 FROM agent.native_dialogue_terminals t
  WHERE t.tenant_id=NEW.tenant_id AND t.owner_id=NEW.owner_id AND t.agent_id=NEW.agent_id
   AND t.dialogue_id=NEW.dialogue_id AND t.intent_id=NEW.source_intent_id
   AND t.conversation_id=NEW.source_conversation_id AND t.run_id=NEW.source_run_id
   AND t.run_id=NEW.source_native_terminal_run_id AND t.entry_id=NEW.entry_id
   AND t.resolution='published' AND t.outcome='failed')
 THEN RAISE EXCEPTION 'Native terminal publication lacks its exact acknowledged fact' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_dialogue_admission_exclusion(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_dialogue_admission_exclusion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE target UUID;
BEGIN
    IF TG_TABLE_NAME='dialogue_sessions' THEN
        IF NEW.subject_kind IN ('work_item','work_item_report') THEN
            RETURN NEW;
        END IF;
        target:=NEW.source_intent_id;
    ELSE
        target:=NEW.intent_id;
    END IF;
    PERFORM 1 FROM agent.dialogue_user_intents WHERE intent_id=target FOR NO KEY UPDATE;
    IF EXISTS(SELECT 1 FROM agent.device_admissions WHERE intent_id=target) THEN
        IF TG_TABLE_NAME='dialogue_sessions' THEN
            RAISE EXCEPTION 'dialogue input is in Device custody' USING ERRCODE='23514';
        ELSIF NEW.reason<>'source_authority_changed' OR NOT agent.dialogue_source_failure_qualified(target,NEW.facts_sha256) THEN
            RAISE EXCEPTION 'Native source failure requires exact qualified no-admission' USING ERRCODE='23514';
        END IF;
    ELSIF TG_TABLE_NAME='dialogue_admission_outcomes' THEN
        IF NEW.reason='source_authority_changed' AND NOT agent.dialogue_source_failure_qualified(target,NEW.facts_sha256) THEN
            RAISE EXCEPTION 'source failure requires original Native source owner' USING ERRCODE='23514';
        END IF;
    END IF;
    IF TG_TABLE_NAME='dialogue_sessions' THEN
        IF EXISTS(SELECT 1 FROM agent.dialogue_intent_admissions WHERE intent_id=target AND execution_target='origin_device') THEN
            RAISE EXCEPTION 'dialogue input destination is Device' USING ERRCODE='23514';
        END IF;
        IF EXISTS(SELECT 1 FROM agent.dialogue_admission_outcomes WHERE intent_id=target) THEN
            RAISE EXCEPTION 'dialogue input already has a terminal admission outcome' USING ERRCODE='23514';
        END IF;
    ELSE
        IF EXISTS(SELECT 1 FROM agent.dialogue_sessions WHERE source_intent_id=target AND subject_kind='intent') THEN
            RAISE EXCEPTION 'dialogue input already admitted' USING ERRCODE='23514';
        END IF;
        IF NEW.outcome IN ('rejected','failed') AND NOT EXISTS(SELECT 1 FROM agent.agent_dialogue_entries e
            WHERE e.entry_id=NEW.entry_id AND e.tenant_id=NEW.tenant_id AND e.owner_id=NEW.owner_id
              AND e.dialogue_id=NEW.dialogue_id AND e.source_intent_id=target
              AND e.author_agent_id=NEW.agent_id AND e.kind='agent_message'
              AND e.created_at_ms=NEW.created_at_ms) THEN
            RAISE EXCEPTION 'dialogue rejection must own its key message' USING ERRCODE='23514';
        END IF;
        IF NOT EXISTS(SELECT 1 FROM agent.dialogue_user_intents i
            JOIN agent.agent_dialogues d USING(dialogue_id)
            WHERE i.intent_id=target AND i.tenant_id=NEW.tenant_id AND i.owner_id=NEW.owner_id
              AND i.dialogue_id=NEW.dialogue_id AND d.agent_id=NEW.agent_id) THEN
            RAISE EXCEPTION 'dialogue admission outcome scope mismatch' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END $$;


