-- Name: guard_dialogue_admission_outcome_immutable(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_dialogue_admission_outcome_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN RAISE EXCEPTION 'dialogue admission outcome is immutable' USING ERRCODE='23514'; END $$;


--
-- Name: guard_dialogue_admission_terminal(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_dialogue_admission_terminal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.status IN ('rejected','cancelled','failed') AND NEW IS DISTINCT FROM OLD THEN
  RAISE EXCEPTION 'dialogue admission outcome is terminal' USING ERRCODE='23514';END IF;
 IF NEW.status IN ('rejected','cancelled','failed') AND NOT EXISTS(
  SELECT 1 FROM agent.dialogue_admission_outcomes o WHERE o.intent_id=NEW.intent_id AND o.outcome=NEW.status AND o.created_at_ms=NEW.terminal_at_ms)
  AND NOT (NEW.status='cancelled' AND EXISTS(SELECT 1 FROM agent.native_execution_not_admitted n WHERE n.intent_id=NEW.intent_id AND n.recorded_at_ms=NEW.terminal_at_ms))
 THEN RAISE EXCEPTION 'dialogue terminal queue requires its receipt' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_device_custody(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_device_custody() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM 1 FROM agent.dialogue_user_intents WHERE intent_id=NEW.intent_id FOR NO KEY UPDATE;
 IF EXISTS(SELECT 1 FROM agent.dialogue_sessions WHERE source_intent_id=NEW.intent_id AND subject_kind='intent')
 OR EXISTS(SELECT 1 FROM agent.dialogue_admission_outcomes WHERE intent_id=NEW.intent_id)
 OR NOT EXISTS(SELECT 1 FROM agent.dialogue_intent_admissions q
   WHERE q.intent_id=NEW.intent_id AND q.execution_target='origin_device'
   AND q.target_device_id=NEW.device_id AND q.target_installation_id=NEW.installation_id
   AND q.status='claimed' AND q.claim_generation=NEW.claim_generation) THEN
  RAISE EXCEPTION 'dialogue device custody does not own original acceptance' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_device_grant_version(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_device_grant_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE custody agent.device_admissions; previous agent.device_grant_versions;
BEGIN
 IF TG_OP IN ('UPDATE','DELETE') THEN RAISE EXCEPTION 'Dialogue grant version is immutable'; END IF;
 SELECT * INTO STRICT custody FROM agent.device_admissions WHERE intent_id=NEW.intent_id FOR UPDATE;
 IF NEW.source_digest<>custody.source_digest THEN RAISE EXCEPTION 'Dialogue grant source differs'; END IF;
 IF NEW.revision=1 THEN
  IF NEW.signed_grant_hash IS DISTINCT FROM custody.signed_grant_hash
   OR NEW.signed_grant_proof IS DISTINCT FROM custody.signed_grant_proof THEN
   RAISE EXCEPTION 'Dialogue first grant differs';
  END IF;
 ELSE
  SELECT * INTO STRICT previous FROM agent.device_grant_versions
   WHERE intent_id=NEW.intent_id AND revision=NEW.revision-1;
  IF NEW.previous_grant_hash<>previous.signed_grant_hash OR custody.admitted_at_ms IS NOT NULL
   OR NOT EXISTS(SELECT 1 FROM agent.device_grant_heads WHERE intent_id=NEW.intent_id
      AND current_revision=NEW.revision-1 AND admitted_revision IS NULL) THEN
   RAISE EXCEPTION 'Dialogue grant successor does not own current custody';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_device_resource_publication(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_device_resource_publication() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND NEW IS DISTINCT FROM OLD) THEN RAISE EXCEPTION 'Canonical Resource publication proof is immutable'; END IF;
 IF NOT EXISTS(SELECT 1 FROM agent.dialogue_tool_publication_groups g JOIN resource.device_commands c ON c.invocation_id=NEW.producer_invocation_id
  JOIN artifact.device_resource_versions v ON v.invocation_id=c.invocation_id AND v.artifact_version_id=NEW.artifact_version_id
  WHERE g.invocation_id=NEW.publication_invocation_id AND g.tenant_id=c.tenant_id AND g.source_intent_id=c.intent_id AND g.source_run_id=c.run_id
  AND g.execution_home='device' AND g.device_resource_commitment IS NOT NULL AND c.committed_at_ms IS NOT NULL) THEN
  RAISE EXCEPTION 'Canonical publication lacks exact committed producer' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_device_work_creation_receipt(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_device_work_creation_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.execution_home='device' AND NOT EXISTS(
   SELECT 1 FROM resource.device_commands c WHERE c.invocation_id=NEW.device_source_invocation_id
    AND c.tenant_id=NEW.tenant_id AND c.owner_id=NEW.owner_id AND c.agent_id=NEW.agent_id
    AND c.run_id=NEW.source_run_id AND c.outcome='succeeded' AND c.receipt_content_id IS NOT NULL
 ) THEN
  RAISE EXCEPTION 'native work creation requires its successful original receipt' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_dialogue_execution_control_counts(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_dialogue_execution_control_counts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_TABLE_NAME='dialogue_execution_control_snapshots' THEN
  IF NEW.target_count<>(SELECT count(*) FROM agent.dialogue_execution_control_targets WHERE agent_id=NEW.agent_id AND activity_revision=NEW.activity_revision) THEN RAISE EXCEPTION 'Dialogue observation target count mismatch' USING ERRCODE='23514'; END IF;
 ELSE
  IF NEW.target_count<>(SELECT count(*) FROM agent.dialogue_execution_cancellation_targets WHERE cancellation_id=NEW.command_id) THEN RAISE EXCEPTION 'Dialogue cancellation target count mismatch' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_dialogue_execution_control_immutable(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_dialogue_execution_control_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN RAISE EXCEPTION 'Dialogue execution control fact is immutable' USING ERRCODE='23514'; END $$;


--
-- Name: guard_dialogue_failed_progress(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_dialogue_failed_progress() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND OLD.stage=4 AND NEW IS DISTINCT FROM OLD THEN
  RAISE EXCEPTION 'dialogue pre-run failure observation is terminal' USING ERRCODE='23514';
 END IF;
 IF NEW.stage=4 THEN
  IF TG_OP='UPDATE' AND OLD.stage=3 THEN
   RAISE EXCEPTION 'admitted execution cannot become a pre-run failure' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS(
   SELECT 1 FROM agent.dialogue_admission_outcomes o
   JOIN agent.dialogue_intent_admissions q USING(intent_id)
   WHERE o.intent_id=NEW.intent_id AND o.outcome='failed'
     AND ((o.reason='runtime_contract_failure' AND o.internal_failure_code='invalid_preparation'
       AND NOT EXISTS(SELECT 1 FROM agent.device_admissions c WHERE c.intent_id=o.intent_id))
       OR (o.reason='source_authority_changed' AND agent.dialogue_source_failure_qualified(o.intent_id,o.facts_sha256)))
     AND q.status='failed' AND q.terminal_at_ms=o.created_at_ms
     AND NEW.observed_at_ms=o.created_at_ms
  ) OR EXISTS(SELECT 1 FROM agent.dialogue_sessions s WHERE s.source_intent_id=NEW.intent_id) THEN
   RAISE EXCEPTION 'dialogue failed progress requires its original pre-run failure' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_owner_goal_draft_registration(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_owner_goal_draft_registration() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE creation agent.agent_work_creation_publications%ROWTYPE;
BEGIN
 IF TG_OP='UPDATE' THEN
  RAISE EXCEPTION 'saved Goal draft registration is immutable' USING ERRCODE='23514';
 END IF;
 SELECT * INTO creation FROM agent.agent_work_creation_publications WHERE creation_id=NEW.creation_id;
 IF NOT FOUND OR creation.work_kind<>3 OR NEW.registered_at_ms<creation.created_at_ms OR NOT EXISTS(
   SELECT 1 FROM runtime.standing_goals g
   JOIN agent.dialogue_sessions s ON s.tenant_id=g.tenant_id AND s.owner_id=g.owner_principal_id
     AND s.agent_id=g.target_agent_id AND s.source_goal_id=g.goal_id AND s.conversation_id=g.conversation_id AND s.subject_kind='goal'
   JOIN agent.owner_goal_setup_deliveries d ON d.creation_id=creation.creation_id
   WHERE g.tenant_id=creation.tenant_id AND g.owner_principal_id=creation.owner_id
     AND g.target_agent_id=creation.agent_id AND g.goal_id=creation.work_id AND g.mode=2 AND g.status=1
     AND g.revision=NEW.goal_revision
     AND NOT EXISTS(SELECT 1 FROM runtime.goal_deletions e WHERE e.tenant_id=g.tenant_id AND e.goal_id=g.goal_id)
 ) THEN RAISE EXCEPTION 'saved draft requires its current original Goal revision' USING ERRCODE='23514'; END IF;
 IF NOT ((NEW.execution_home='cloud' AND EXISTS(
   SELECT 1 FROM tool.tool_invocations inv JOIN runtime.runs r ON r.tenant_id=inv.tenant_id AND r.run_id=inv.run_id
   JOIN agent.dialogue_sessions s ON s.tenant_id=r.tenant_id AND s.conversation_id=r.conversation_id
   JOIN agent.dialogue_user_intents i ON i.intent_id=s.source_intent_id AND i.tenant_id=s.tenant_id AND i.owner_id=s.owner_id
   WHERE inv.invocation_id=NEW.source_invocation_id AND inv.tool_ref='goal.draft.save@1'
     AND inv.run_id=NEW.source_run_id AND inv.tenant_id=creation.tenant_id
     AND s.owner_id=creation.owner_id AND s.agent_id=creation.agent_id AND s.subject_kind='intent'
     AND s.purpose='intent_coordination' AND i.origin_surface<>'schedule' AND i.task_target IS NULL
     AND r.parent_run_id IS NULL AND r.delegation_id IS NULL
 )) OR (NEW.execution_home='device' AND EXISTS(
   SELECT 1 FROM resource.device_commands c
   JOIN agent.dialogue_user_intents i ON i.intent_id=c.intent_id AND i.tenant_id=c.tenant_id AND i.owner_id=c.owner_id
   WHERE c.invocation_id=NEW.device_source_invocation_id AND c.tool_key='goal.draft.save@1'
     AND c.run_id=NEW.source_run_id AND c.tenant_id=creation.tenant_id AND c.owner_id=creation.owner_id
     AND c.agent_id=creation.agent_id AND c.admission_kind='intent' AND i.origin_surface<>'schedule' AND i.task_target IS NULL
 ))) THEN RAISE EXCEPTION 'saved draft requires original direct-user Tool custody' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_owner_goal_draft_registration_receipt(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_owner_goal_draft_registration_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NOT ((NEW.execution_home='cloud' AND EXISTS(
   SELECT 1 FROM tool.tool_invocations i WHERE i.invocation_id=NEW.source_invocation_id
    AND i.run_id=NEW.source_run_id AND i.tool_ref='goal.draft.save@1' AND i.status=4 AND i.result_content_id IS NOT NULL
 )) OR (NEW.execution_home='device' AND EXISTS(
   SELECT 1 FROM resource.device_commands c WHERE c.invocation_id=NEW.device_source_invocation_id
    AND c.run_id=NEW.source_run_id AND c.tool_key='goal.draft.save@1' AND c.outcome='succeeded'
    AND c.receipt_content_id IS NOT NULL AND c.result_content_id IS NOT NULL
 ))) THEN RAISE EXCEPTION 'saved draft requires its successful original receipt' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_owner_goal_setup_delivery(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_owner_goal_setup_delivery() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.ready_at_ms IS NOT NULL OR NOT EXISTS (
   SELECT 1 FROM agent.agent_work_creation_publications c JOIN runtime.standing_goals g
    ON g.tenant_id=c.tenant_id AND g.goal_id=c.work_id AND g.owner_principal_id=c.owner_id AND g.target_agent_id=c.agent_id
   WHERE c.creation_id=NEW.creation_id AND c.work_kind=3 AND g.mode=2
  ) THEN RAISE EXCEPTION 'Goal setup delivery requires its pending original creation' USING ERRCODE='23514'; END IF;
 ELSE
  IF NEW.creation_id IS DISTINCT FROM OLD.creation_id OR OLD.ready_at_ms IS NOT NULL OR NEW.ready_at_ms IS NULL
    OR NOT EXISTS (
      SELECT 1 FROM agent.agent_work_creation_publications c JOIN runtime.standing_goals g
       ON g.tenant_id=c.tenant_id AND g.goal_id=c.work_id AND g.owner_principal_id=c.owner_id
        AND g.target_agent_id=c.agent_id
      WHERE c.creation_id=NEW.creation_id AND c.work_kind=3 AND g.mode=2 AND g.status=2
       AND g.revision=NEW.goal_revision AND NEW.ready_at_ms>=c.created_at_ms
    ) THEN RAISE EXCEPTION 'Goal setup delivery evidence is append-only at its active owner revision' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_native_control_source(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_native_control_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM 1 FROM agent.dialogue_user_intents WHERE intent_id=NEW.intent_id FOR UPDATE;
 IF NOT EXISTS(
  SELECT 1 FROM agent.device_admissions d
  JOIN agent.dialogue_execution_cancellation_targets t ON t.command_id=NEW.command_id AND t.intent_id=d.intent_id AND t.run_id=d.run_id AND t.conversation_id=d.conversation_id AND t.native_target IS NOT NULL
  JOIN agent.dialogue_execution_cancellations c ON c.command_id=t.cancellation_id
  WHERE d.intent_id=NEW.intent_id AND d.run_id=NEW.run_id AND d.tenant_id=NEW.tenant_id AND d.owner_id=NEW.owner_id AND d.agent_id=NEW.agent_id AND d.dialogue_id=NEW.dialogue_id
    AND d.device_id=NEW.device_id AND d.installation_id=NEW.installation_id AND d.source_digest=NEW.source_digest
    AND coalesce((SELECT current_revision FROM agent.device_grant_heads WHERE intent_id=d.intent_id),0)=NEW.grant_revision
    AND (NEW.grant_revision=0 OR EXISTS(SELECT 1 FROM agent.device_grant_versions v WHERE v.intent_id=d.intent_id AND v.revision=NEW.grant_revision AND v.source_digest=NEW.source_digest AND v.signed_grant_hash=NEW.grant_proof_hash))
    AND c.command_id=NEW.cancellation_id AND c.tenant_id=NEW.tenant_id AND c.owner_id=NEW.owner_id AND c.agent_id=NEW.agent_id AND c.dialogue_id=NEW.dialogue_id AND c.created_at_ms=NEW.created_at_ms
 ) THEN RAISE EXCEPTION 'Native stop requires original exact account target and custody' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_native_controlled_grant(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_native_controlled_grant() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM 1 FROM agent.dialogue_user_intents WHERE intent_id=NEW.intent_id FOR UPDATE;
 IF agent.dialogue_execution_source_cancelled(NEW.intent_id)
 THEN RAISE EXCEPTION 'Stopped Native source cannot receive a new grant' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_native_not_admitted(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_native_not_admitted() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM 1 FROM agent.dialogue_user_intents WHERE intent_id=NEW.intent_id FOR UPDATE;
 PERFORM 1 FROM agent.device_admissions WHERE intent_id=NEW.intent_id FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM agent.native_execution_controls c JOIN agent.device_admissions d USING(intent_id,run_id)
  WHERE c.command_id=NEW.command_id AND c.intent_id=NEW.intent_id AND c.run_id=NEW.run_id AND d.admitted_at_ms IS NULL)
  OR EXISTS(SELECT 1 FROM agent.native_dialogue_terminals WHERE run_id=NEW.run_id)
  OR EXISTS(SELECT 1 FROM agent.device_source_not_admitted WHERE intent_id=NEW.intent_id)
  OR EXISTS(SELECT 1 FROM agent.device_grant_heads WHERE intent_id=NEW.intent_id AND admitted_revision IS NOT NULL)
 THEN RAISE EXCEPTION 'NotAdmitted cannot contradict original admission or terminal' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_native_stopped_custody(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_native_stopped_custody() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.admitted_at_ms IS NOT NULL AND EXISTS(SELECT 1 FROM agent.native_execution_not_admitted WHERE intent_id=NEW.intent_id)
 THEN RAISE EXCEPTION 'NotAdmitted permanently excludes admission ACK' USING ERRCODE='23514';END IF;
 IF NEW.signed_grant_hash IS DISTINCT FROM OLD.signed_grant_hash AND agent.dialogue_execution_source_cancelled(NEW.intent_id)
 THEN RAISE EXCEPTION 'Stopped Native source cannot change original grant' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_dialogue_publication_home(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_dialogue_publication_home() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.source_kind='tool_owner' AND NOT EXISTS(SELECT 1 FROM agent.dialogue_tool_publication_groups g
  WHERE g.invocation_id=NEW.source_tool_invocation_id AND g.tenant_id=NEW.tenant_id
  AND g.source_run_id=NEW.source_run_id AND g.source_intent_id IS NOT DISTINCT FROM NEW.source_intent_id AND g.source_goal_id IS NOT DISTINCT FROM NEW.source_goal_id
  AND g.execution_home=NEW.execution_home AND g.device_subject_kind=NEW.device_subject_kind)
 THEN RAISE EXCEPTION 'Dialogue publication home differs from original tool group' USING ERRCODE='23514'; END IF;
 IF NEW.execution_home='device' AND NEW.device_subject_kind='work_item' AND NOT EXISTS(
  SELECT 1 FROM collaboration.work_item_device_custody d
  JOIN collaboration.work_item_execution_reservations r USING(work_item_id,goal_revision,control_revision,assignment_epoch)
  JOIN collaboration.work_items w USING(work_item_id)
  WHERE d.run_id=NEW.source_run_id AND d.conversation_id=NEW.source_conversation_id
  AND r.tenant_id=NEW.tenant_id AND r.owner_id=NEW.owner_id AND (
   (NEW.source_kind<>'task_result_owner' AND r.executing_agent_id=NEW.agent_id AND r.executing_dialogue_id=NEW.dialogue_id)
   OR (NEW.source_kind='task_result_owner' AND r.requesting_agent_id=NEW.agent_id AND w.source_dialogue_id=NEW.dialogue_id
       AND EXISTS (SELECT 1 FROM collaboration.work_item_result_items item JOIN collaboration.work_item_result_deliveries delivery USING(result_id)
        WHERE item.item_id=NEW.source_task_result_item_id AND delivery.device_terminal_run_id=d.run_id))) AND w.source_intent_id=NEW.source_intent_id AND d.admitted_at_ms IS NOT NULL)
 THEN RAISE EXCEPTION 'Task publication requires its exact original admitted custody' USING ERRCODE='23514'; END IF;
 IF NEW.execution_home='device' AND NEW.source_kind='interaction_owner' AND NOT EXISTS(
  SELECT 1 FROM agent.native_dialogue_interaction_projections i WHERE i.interaction_id=NEW.source_interaction_id
  AND i.tenant_id=NEW.tenant_id AND i.owner_id=NEW.owner_id AND i.agent_id=NEW.agent_id
  AND i.dialogue_id=NEW.dialogue_id AND i.intent_id=NEW.source_intent_id AND i.conversation_id=NEW.source_conversation_id
  AND i.run_id=NEW.source_run_id AND i.device_subject_kind=NEW.device_subject_kind)
 THEN RAISE EXCEPTION 'Interaction publication requires its exact original Device observation' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND (NEW.execution_home,NEW.source_run_id,NEW.source_conversation_id,NEW.source_intent_id,
  NEW.source_tool_invocation_id,NEW.source_interaction_id,NEW.source_kind,NEW.device_subject_kind,NEW.source_goal_id) IS DISTINCT FROM
  (OLD.execution_home,OLD.source_run_id,OLD.source_conversation_id,OLD.source_intent_id,
  OLD.source_tool_invocation_id,OLD.source_interaction_id,OLD.source_kind,OLD.device_subject_kind,OLD.source_goal_id)
 THEN RAISE EXCEPTION 'Dialogue publication execution home is immutable'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_device_refused_custody(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_device_refused_custody() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.admitted_at_ms IS NOT NULL AND EXISTS(SELECT 1 FROM agent.device_source_not_admitted WHERE intent_id=NEW.intent_id) THEN
  RAISE EXCEPTION 'qualified source refusal excludes admission ACK' USING ERRCODE='23514'; END IF;
 IF NEW.signed_grant_hash IS DISTINCT FROM OLD.signed_grant_hash
  AND EXISTS(SELECT 1 FROM agent.device_source_refusals WHERE intent_id=NEW.intent_id) THEN
  RAISE EXCEPTION 'refused Native source cannot bind its first grant' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_device_refused_grant(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_device_refused_grant() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM 1 FROM agent.dialogue_user_intents WHERE intent_id=NEW.intent_id FOR NO KEY UPDATE;
 IF EXISTS(SELECT 1 FROM agent.device_source_refusals WHERE intent_id=NEW.intent_id) THEN
  RAISE EXCEPTION 'refused Native source cannot receive a new grant' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_device_refused_grant_head(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_device_refused_grant_head() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.admitted_revision IS NOT NULL AND EXISTS(SELECT 1 FROM agent.device_source_not_admitted WHERE intent_id=NEW.intent_id) THEN
  RAISE EXCEPTION 'qualified source refusal excludes admitted grant' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF EXISTS(SELECT 1 FROM agent.device_source_refusals WHERE intent_id=NEW.intent_id) THEN
   RAISE EXCEPTION 'refused source cannot create grant head' USING ERRCODE='23514'; END IF;
 ELSIF NEW.current_revision IS DISTINCT FROM OLD.current_revision
   AND EXISTS(SELECT 1 FROM agent.device_source_refusals WHERE intent_id=NEW.intent_id) THEN
  RAISE EXCEPTION 'refused source cannot advance grant head' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_dialogue_reply_binding(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_dialogue_reply_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.reply_binding IS DISTINCT FROM OLD.reply_binding THEN
  RAISE EXCEPTION 'Accepted reply context is immutable' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_dialogue_reply_origin(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_dialogue_reply_origin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.reply_origin_device_id,NEW.reply_origin_installation_id,NEW.reply_origin_subject_proof)
   IS DISTINCT FROM (OLD.reply_origin_device_id,OLD.reply_origin_installation_id,OLD.reply_origin_subject_proof) THEN
  RAISE EXCEPTION 'Accepted input origin is immutable' USING ERRCODE='23514';
 END IF;
 IF NEW.reply_origin_device_id IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM agent.dialogue_user_intents i WHERE i.intent_id=NEW.intent_id AND i.reply_binding IS NOT NULL) THEN
  RAISE EXCEPTION 'Reply input origin requires accepted binding' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_dialogue_source_failure_settlement(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_dialogue_source_failure_settlement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM agent.dialogue_admission_outcomes o
   JOIN agent.dialogue_intent_admissions q USING(intent_id)
   WHERE o.intent_id=NEW.intent_id AND o.outcome='failed'
     AND o.reason='source_authority_changed' AND o.facts_sha256=NEW.receipt_sha256
     AND o.created_at_ms=NEW.recorded_at_ms
     AND q.status='failed' AND q.terminal_at_ms=o.created_at_ms) THEN
  RAISE EXCEPTION 'source no-admission proof requires its atomic failed outcome' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $$;


--
-- Name: guard_device_source_not_admitted(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_device_source_not_admitted() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM 1 FROM agent.dialogue_user_intents WHERE intent_id=NEW.intent_id FOR NO KEY UPDATE;
 PERFORM 1 FROM agent.device_admissions WHERE intent_id=NEW.intent_id FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM agent.device_source_refusals r
   JOIN agent.device_admissions d USING(intent_id,run_id)
   JOIN agent.dialogue_intent_admissions q USING(intent_id)
   WHERE r.intent_id=NEW.intent_id AND r.run_id=NEW.run_id
     AND d.admitted_at_ms IS NULL AND q.status IN('pending','claimed')
     AND NEW.canonical_receipt=convert_to('musteragent.device-source-not-admitted.v1','UTF8')||decode('00','hex')||r.canonical_refusal)
   OR EXISTS(SELECT 1 FROM agent.device_grant_heads WHERE intent_id=NEW.intent_id AND admitted_revision IS NOT NULL)
   OR EXISTS(SELECT 1 FROM agent.native_dialogue_terminals WHERE run_id=NEW.run_id)
   OR EXISTS(SELECT 1 FROM agent.native_execution_not_admitted WHERE intent_id=NEW.intent_id)
 THEN RAISE EXCEPTION 'source no-admission proof contradicts original custody' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_device_source_refusal(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_device_source_refusal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected BYTEA;
BEGIN
 PERFORM 1 FROM agent.dialogue_user_intents WHERE intent_id=NEW.intent_id FOR NO KEY UPDATE;
 PERFORM 1 FROM agent.device_admissions WHERE intent_id=NEW.intent_id FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM agent.device_admissions d
   LEFT JOIN agent.device_grant_heads h USING(intent_id)
   WHERE d.intent_id=NEW.intent_id AND d.run_id=NEW.run_id
     AND d.tenant_id=NEW.tenant_id AND d.owner_id=NEW.owner_id
     AND d.agent_id=NEW.agent_id AND d.dialogue_id=NEW.dialogue_id
     AND d.conversation_id=NEW.conversation_id AND d.device_id=NEW.device_id
     AND d.installation_id=NEW.installation_id AND d.source_digest=NEW.source_digest
     AND d.admitted_at_ms IS NULL AND h.admitted_revision IS NULL
     AND coalesce(h.current_revision,0)=NEW.grant_revision
     AND (NEW.grant_revision=0 OR EXISTS(SELECT 1 FROM agent.device_grant_versions v
       WHERE v.intent_id=d.intent_id AND v.revision=NEW.grant_revision
         AND v.source_digest=NEW.source_digest AND v.signed_grant_hash=NEW.grant_proof_hash)))
   OR EXISTS(SELECT 1 FROM agent.native_dialogue_terminals WHERE run_id=NEW.run_id)
   OR EXISTS(SELECT 1 FROM agent.dialogue_admission_outcomes WHERE intent_id=NEW.intent_id)
 THEN RAISE EXCEPTION 'source refusal requires original unacknowledged custody' USING ERRCODE='23514'; END IF;
 expected:=convert_to('musteragent.device-source-refusal.v1','UTF8')||decode('00','hex')
   ||set_byte(decode('00','hex'),0,NEW.reason::integer)||int8send(NEW.detected_at_ms)
   ||agent.native_control_target_bytes(NEW.tenant_id,NEW.owner_id,NEW.agent_id,NEW.dialogue_id,
      NEW.intent_id,NEW.run_id,NEW.conversation_id,NEW.device_id,NEW.installation_id,
      NEW.source_digest,NEW.grant_revision,NEW.grant_proof_hash);
 IF expected<>NEW.canonical_refusal THEN RAISE EXCEPTION 'noncanonical source refusal' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_dialogue_user_stop_outcome(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_dialogue_user_stop_outcome() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.reason='user_requested' AND NOT EXISTS(
  SELECT 1 FROM agent.dialogue_execution_cancellations c JOIN agent.dialogue_execution_cancellation_targets t ON t.cancellation_id=c.command_id
  WHERE c.command_id=NEW.cancellation_id AND c.tenant_id=NEW.tenant_id AND c.owner_id=NEW.owner_id AND c.agent_id=NEW.agent_id AND c.dialogue_id=NEW.dialogue_id AND t.intent_id=NEW.intent_id AND t.run_id IS NULL AND t.native_target IS NULL
 ) THEN RAISE EXCEPTION 'Dialogue user stop requires its retained accepted target' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_agent_work_creation_publication(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.guard_agent_work_creation_publication() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF (NEW.creation_id,NEW.tenant_id,NEW.owner_id,NEW.agent_id,NEW.source_run_id,NEW.source_invocation_id,
   NEW.work_kind,NEW.work_id,NEW.definition_revision,NEW.category,NEW.title,NEW.created_at_ms,NEW.execution_home,NEW.device_source_invocation_id) IS DISTINCT FROM
   (OLD.creation_id,OLD.tenant_id,OLD.owner_id,OLD.agent_id,OLD.source_run_id,OLD.source_invocation_id,
   OLD.work_kind,OLD.work_id,OLD.definition_revision,OLD.category,OLD.title,OLD.created_at_ms,OLD.execution_home,OLD.device_source_invocation_id)
   OR OLD.entry_id IS NOT NULL THEN
   RAISE EXCEPTION 'work creation receipt is immutable' USING ERRCODE='23514';
  END IF;
 ELSE
  IF NOT ((NEW.execution_home='cloud' AND EXISTS(SELECT 1 FROM tool.tool_invocations i WHERE i.invocation_id=NEW.source_invocation_id
    AND i.tenant_id=NEW.tenant_id AND i.run_id=NEW.source_run_id
    AND ((NEW.work_kind=1 AND i.tool_ref IN ('tasks.start@1','tasks.start@2','tasks.start@3'))
      OR (NEW.work_kind=2 AND i.tool_ref='schedules.create@1')
      OR (NEW.work_kind=3 AND i.tool_ref='goal.create@3'))))
    OR (NEW.execution_home='device' AND NEW.work_kind IN (1,3) AND EXISTS(
      SELECT 1 FROM resource.device_commands c WHERE c.invocation_id=NEW.device_source_invocation_id
        AND c.tenant_id=NEW.tenant_id AND c.owner_id=NEW.owner_id AND c.agent_id=NEW.agent_id
        AND c.run_id=NEW.source_run_id AND c.admission_kind='intent' AND ((NEW.work_kind=3 AND c.tool_key='goal.create@3') OR (NEW.work_kind=1 AND c.tool_key='tasks.start@3' AND EXISTS(SELECT 1 FROM collaboration.work_item_native_sources n WHERE n.invocation_id=c.invocation_id)))))) THEN
   RAISE EXCEPTION 'work creation requires original owner tool custody' USING ERRCODE='23514';
  END IF;
  IF NOT ((NEW.work_kind=1 AND EXISTS(SELECT 1 FROM collaboration.work_items w
    WHERE w.work_item_id=NEW.work_id AND w.tenant_id=NEW.tenant_id AND w.owner_id=NEW.owner_id
     AND w.agent_id=NEW.agent_id AND w.parent_work_item_id IS NULL AND w.erasure_job_id IS NULL))
   OR (NEW.work_kind=2 AND EXISTS(SELECT 1 FROM agent.owner_schedules s
    WHERE s.schedule_id=NEW.work_id AND s.tenant_id=NEW.tenant_id AND s.owner_id=NEW.owner_id
     AND s.agent_id=NEW.agent_id AND s.revision=NEW.definition_revision AND s.status<>'deleted'))
   OR (NEW.work_kind=3 AND NEW.category=3 AND EXISTS(SELECT 1 FROM runtime.standing_goals g
     JOIN agent.dialogue_sessions s ON s.source_goal_id=g.goal_id AND s.tenant_id=g.tenant_id
       AND s.owner_id=g.owner_principal_id AND s.conversation_id=g.conversation_id AND s.subject_kind='goal'
     WHERE g.goal_id=NEW.work_id AND g.tenant_id=NEW.tenant_id AND g.owner_principal_id=NEW.owner_id
       AND g.target_agent_id=NEW.agent_id AND s.agent_id=NEW.agent_id AND g.mode=2
       AND g.revision=NEW.definition_revision
       AND NOT EXISTS(SELECT 1 FROM runtime.goal_deletions d WHERE d.tenant_id=g.tenant_id AND d.goal_id=g.goal_id)))) THEN
   RAISE EXCEPTION 'work creation must refer to its original public root' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM agent.dialogue_publications p
   JOIN agent.agent_dialogue_entries e USING(entry_id)
   WHERE p.entry_id=NEW.entry_id AND p.tenant_id=NEW.tenant_id AND p.owner_id=NEW.owner_id
    AND p.agent_id=NEW.agent_id AND p.source_run_id=NEW.source_run_id AND e.kind='agent_message' AND p.execution_home=NEW.execution_home
    AND ((NEW.execution_home='cloud' AND EXISTS(SELECT 1 FROM tool.tool_invocations i WHERE i.invocation_id=NEW.source_invocation_id
      AND i.tenant_id=NEW.tenant_id AND i.run_id=NEW.source_run_id AND i.status=4))
      OR (NEW.execution_home='device' AND EXISTS(SELECT 1 FROM resource.device_commands c
        WHERE c.invocation_id=NEW.device_source_invocation_id AND c.tenant_id=NEW.tenant_id
          AND c.owner_id=NEW.owner_id AND c.agent_id=NEW.agent_id AND c.run_id=NEW.source_run_id
          AND c.outcome='succeeded' AND c.receipt_content_id IS NOT NULL)))) THEN
  RAISE EXCEPTION 'work card must join an authorized message from its creating run' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: keep_device_custody(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.keep_device_custody() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF (NEW.intent_id,NEW.tenant_id,NEW.owner_id,NEW.agent_id,NEW.dialogue_id,NEW.device_id,NEW.installation_id,
 NEW.command_id,NEW.conversation_id,NEW.run_id,NEW.claim_generation,NEW.source_digest,NEW.source_sha256,NEW.source_envelope,NEW.created_at_ms)
 IS DISTINCT FROM
 (OLD.intent_id,OLD.tenant_id,OLD.owner_id,OLD.agent_id,OLD.dialogue_id,OLD.device_id,OLD.installation_id,
 OLD.command_id,OLD.conversation_id,OLD.run_id,OLD.claim_generation,OLD.source_digest,OLD.source_sha256,OLD.source_envelope,OLD.created_at_ms)
 OR (OLD.signed_grant_proof IS NOT NULL AND (NEW.signed_grant_proof,NEW.signed_grant_hash) IS DISTINCT FROM (OLD.signed_grant_proof,OLD.signed_grant_hash))
 OR (OLD.admitted_at_ms IS NOT NULL AND (NEW.admitted_at_ms,NEW.admitted_snapshot_hash) IS DISTINCT FROM (OLD.admitted_at_ms,OLD.admitted_snapshot_hash))
 THEN RAISE EXCEPTION 'Dialogue device custody is immutable'; END IF;
 RETURN NEW;
END $$;


--
-- Name: keep_device_grant_head(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.keep_device_grant_head() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.current_revision<>1 OR NEW.admitted_revision IS NOT NULL THEN
   RAISE EXCEPTION 'Dialogue grant head must start at first authorization';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.intent_id<>OLD.intent_id
 OR NEW.current_revision NOT IN (OLD.current_revision,OLD.current_revision+1)
 OR (OLD.admitted_revision IS NOT NULL AND (NEW.admitted_revision IS DISTINCT FROM OLD.admitted_revision
      OR NEW.current_revision<>OLD.current_revision))
 OR (NEW.current_revision<>OLD.current_revision AND NEW.admitted_revision IS NOT NULL)
 THEN RAISE EXCEPTION 'Dialogue grant head or admission is immutable'; END IF;
 RETURN NEW;
END $$;


--
-- Name: keep_dialogue_execution_target(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.keep_dialogue_execution_target() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF (NEW.execution_target,NEW.target_device_id,NEW.target_installation_id,NEW.native_subject_proof)
   IS DISTINCT FROM (OLD.execution_target,OLD.target_device_id,OLD.target_installation_id,OLD.native_subject_proof)
 THEN RAISE EXCEPTION 'accepted execution home is immutable'; END IF;
 RETURN NEW;
END $$;


--
-- Name: keep_device_source_refusal_until_custody_erasure(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.keep_device_source_refusal_until_custody_erasure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM agent.device_admissions WHERE intent_id=OLD.intent_id) THEN
  RAISE EXCEPTION 'source refusal proof survives until original custody erasure' USING ERRCODE='23514'; END IF;
 RETURN OLD;
END $$;


--
-- Name: mark_dialogue_activity_dirty(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.mark_dialogue_activity_dirty() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE selected_agent uuid;
BEGIN
 IF TG_TABLE_SCHEMA='runtime' THEN
  SELECT s.agent_id INTO selected_agent FROM agent.dialogue_sessions s
   JOIN runtime.runs r ON r.conversation_id=s.conversation_id AND r.tenant_id=s.tenant_id
   WHERE r.run_id=NEW.run_id;
 ELSIF TG_TABLE_SCHEMA='collaboration' THEN
  SELECT x.executing_agent_id INTO selected_agent FROM collaboration.work_item_device_custody d
   JOIN collaboration.work_item_execution_reservations x USING(work_item_id,goal_revision,control_revision,assignment_epoch)
   WHERE d.run_id=NEW.run_id;
 ELSE selected_agent:=NEW.agent_id;
 END IF;
 IF selected_agent IS NOT NULL THEN
  INSERT INTO agent.dialogue_activity_dirty(agent_id) VALUES(selected_agent)
   ON CONFLICT(agent_id) DO UPDATE SET agent_id=EXCLUDED.agent_id;
  PERFORM pg_notify('musteragent_execution_activity',selected_agent::text);
 END IF;
 RETURN NEW;
END $$;


--
-- Name: mark_dialogue_cancellation_activity_dirty(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.mark_dialogue_cancellation_activity_dirty() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 INSERT INTO agent.dialogue_activity_dirty(agent_id) VALUES(NEW.agent_id) ON CONFLICT(agent_id) DO NOTHING;
 PERFORM pg_notify('musteragent_execution_activity',NEW.agent_id::text);
 RETURN NEW;
END $$;


--
-- Name: mark_native_stop_settlement_dirty(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.mark_native_stop_settlement_dirty() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE agent UUID;
BEGIN
 SELECT agent_id INTO STRICT agent FROM agent.device_admissions WHERE intent_id=NEW.intent_id;
 INSERT INTO agent.dialogue_activity_dirty(agent_id) VALUES(agent) ON CONFLICT(agent_id) DO NOTHING;
 PERFORM pg_notify('musteragent_execution_activity',agent::text);
 RETURN NEW;
END $$;


--
-- Name: mark_dialogue_preparation_activity_dirty(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.mark_dialogue_preparation_activity_dirty() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE selected_agent uuid;
BEGIN
 SELECT d.agent_id INTO selected_agent FROM agent.dialogue_user_intents i
 JOIN agent.agent_dialogues d ON d.dialogue_id=i.dialogue_id AND d.tenant_id=i.tenant_id AND d.owner_id=i.owner_id
 WHERE i.intent_id=NEW.intent_id;
 IF selected_agent IS NOT NULL THEN
  INSERT INTO agent.dialogue_activity_dirty(agent_id) VALUES(selected_agent)
   ON CONFLICT(agent_id) DO UPDATE SET agent_id=EXCLUDED.agent_id;
  PERFORM pg_notify('musteragent_execution_activity',selected_agent::text);
 END IF;
 RETURN NEW;
END $$;


--
-- Name: mark_agent_task_preparation_dirty(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.mark_agent_task_preparation_dirty() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE selected_agent UUID;
BEGIN
 IF NEW.failure_code IS NOT DISTINCT FROM OLD.failure_code AND NEW.delivered_at_ms IS NOT DISTINCT FROM OLD.delivered_at_ms THEN RETURN NEW; END IF;
 SELECT agent_id INTO selected_agent FROM collaboration.work_items WHERE work_item_id=NEW.work_item_id AND erasure_job_id IS NULL;
 IF selected_agent IS NOT NULL THEN
  INSERT INTO agent.dialogue_activity_dirty(agent_id,work_changed) VALUES(selected_agent,true)
   ON CONFLICT(agent_id) DO UPDATE SET work_changed=true;
  PERFORM pg_notify('musteragent_execution_activity',selected_agent::text);
 END IF;
 RETURN NEW;
END $$;


--
-- Name: mark_agent_work_dirty(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.mark_agent_work_dirty() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE selected_agent uuid; row_data jsonb;
BEGIN
 row_data:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 IF TG_TABLE_SCHEMA='runtime' AND TG_TABLE_NAME='runs' THEN
  SELECT s.agent_id INTO selected_agent FROM agent.dialogue_sessions s
   WHERE s.tenant_id=(row_data->>'tenant_id')::uuid AND s.conversation_id=(row_data->>'conversation_id')::uuid;
 ELSIF TG_TABLE_SCHEMA='runtime' THEN
  SELECT s.agent_id INTO selected_agent FROM agent.dialogue_sessions s
   WHERE s.tenant_id=(row_data->>'tenant_id')::uuid AND s.source_goal_id=(row_data->>'goal_id')::uuid
    AND s.subject_kind='goal';
 ELSIF TG_TABLE_NAME='work_items' THEN
  IF row_data->>'parent_work_item_id' IS NULL AND EXISTS(
   SELECT 1 FROM agent.dialogue_user_intents WHERE intent_id=(row_data->>'source_intent_id')::uuid AND origin_surface<>'schedule') THEN
   selected_agent:=(row_data->>'agent_id')::uuid;
  END IF;
 ELSIF TG_TABLE_NAME='owner_schedule_occurrences' THEN
  SELECT agent_id INTO selected_agent FROM agent.owner_schedules WHERE schedule_id=(row_data->>'schedule_id')::uuid;
 ELSIF TG_TABLE_NAME IN ('dialogue_admission_outcomes','agent_dialogue_entries') THEN
  SELECT s.agent_id INTO selected_agent FROM agent.owner_schedules s
   JOIN agent.owner_schedule_occurrences o USING(schedule_id)
   WHERE o.intent_id=COALESCE(row_data->>'intent_id',row_data->>'source_intent_id')::uuid;
 ELSE selected_agent:=(row_data->>'agent_id')::uuid;
 END IF;
 IF selected_agent IS NOT NULL AND EXISTS(SELECT 1 FROM agent.owned_agents WHERE agent_id=selected_agent AND status<>'deleted') THEN
  INSERT INTO agent.dialogue_activity_dirty(agent_id,work_changed) VALUES(selected_agent,true)
   ON CONFLICT(agent_id) DO UPDATE SET work_changed=true;
  PERFORM pg_notify('musteragent_execution_activity',selected_agent::text);
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;


