SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: agent_dialogue_entries; Type: TABLE; Schema: agent; Owner: -
--

CREATE TABLE agent.agent_dialogue_entries (
    entry_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    dialogue_id uuid NOT NULL,
    epoch bigint NOT NULL,
    seq bigint NOT NULL,
    kind text NOT NULL,
    source_intent_id uuid,
    author_agent_id uuid,
    content_ref bytea,
    interaction_id uuid,
    artifact_id uuid,
    artifact_version_id uuid,
    visible_revision bigint NOT NULL,
    created_at_ms bigint NOT NULL,
    partner_creation_command_id uuid,
    partner_agent_id uuid,
    partner_dialogue_id uuid,
    partner_display_name text,
    partner_description text,
    partner_avatar_ref bytea,
    partner_profile_revision bigint,
    input_attachments bytea DEFAULT '\x'::bytea NOT NULL,
    input_attachment_count smallint DEFAULT 0 NOT NULL,
    erasure_job_id uuid,
    erased_source_payload_sha256 bytea,
    presentation text DEFAULT 'standard'::text NOT NULL,
    CONSTRAINT agent_dialogue_content_shape CHECK ((((kind = ANY (ARRAY['user_message'::text, 'agent_message'::text])) AND (content_ref IS NOT NULL) AND (octet_length(content_ref) > 0) AND (interaction_id IS NULL) AND (artifact_id IS NULL) AND (artifact_version_id IS NULL)) OR ((kind = 'interaction'::text) AND (content_ref IS NULL) AND (interaction_id IS NOT NULL) AND (artifact_id IS NULL) AND (artifact_version_id IS NULL)) OR ((kind = 'artifact'::text) AND (content_ref IS NULL) AND (interaction_id IS NULL) AND (artifact_id IS NOT NULL) AND (artifact_version_id IS NOT NULL)) OR ((kind = 'partner_created'::text) AND (content_ref IS NULL) AND (interaction_id IS NULL) AND (artifact_id IS NULL) AND (artifact_version_id IS NULL)) OR (kind = 'erased'::text))),
    CONSTRAINT agent_dialogue_entries_epoch_check CHECK ((epoch > 0)),
    CONSTRAINT agent_dialogue_entries_input_attachment_count_check CHECK (((input_attachment_count >= 0) AND (input_attachment_count <= 64))),
    CONSTRAINT agent_dialogue_entries_kind_check CHECK ((kind = ANY (ARRAY['user_message'::text, 'agent_message'::text, 'interaction'::text, 'artifact'::text, 'partner_created'::text, 'erased'::text]))),
    CONSTRAINT agent_dialogue_entries_presentation_check CHECK ((presentation = ANY (ARRAY['standard'::text, 'progress'::text]))),
    CONSTRAINT agent_dialogue_entries_seq_check CHECK ((seq > 0)),
    CONSTRAINT agent_dialogue_entries_visible_revision_check CHECK ((visible_revision > 0)),
    CONSTRAINT agent_dialogue_erasure_shape CHECK ((((kind = 'erased'::text) AND (erasure_job_id IS NOT NULL) AND (octet_length(erased_source_payload_sha256) = 32)) OR ((kind <> 'erased'::text) AND (erasure_job_id IS NULL) AND (erased_source_payload_sha256 IS NULL)))),
    CONSTRAINT agent_dialogue_partner_shape CHECK ((((kind = 'partner_created'::text) AND (partner_creation_command_id IS NOT NULL) AND (partner_agent_id IS NOT NULL) AND (partner_dialogue_id IS NOT NULL) AND (partner_display_name IS NOT NULL) AND ((octet_length(partner_display_name) >= 1) AND (octet_length(partner_display_name) <= 120)) AND (partner_description IS NOT NULL) AND (octet_length(partner_description) <= 2048) AND (partner_profile_revision IS NOT NULL) AND (partner_profile_revision > 0) AND ((partner_avatar_ref IS NULL) OR (octet_length(partner_avatar_ref) > 0))) OR ((kind <> 'partner_created'::text) AND (partner_creation_command_id IS NULL) AND (partner_agent_id IS NULL) AND (partner_dialogue_id IS NULL) AND (partner_display_name IS NULL) AND (partner_description IS NULL) AND (partner_avatar_ref IS NULL) AND (partner_profile_revision IS NULL)))),
    CONSTRAINT dialogue_entry_attachment_shape CHECK ((((input_attachment_count = 0) AND (octet_length(input_attachments) = 0)) OR ((input_attachment_count > 0) AND ((octet_length(input_attachments) >= 1) AND (octet_length(input_attachments) <= 32768)) AND (kind = 'user_message'::text) AND (author_agent_id IS NULL) AND (source_intent_id IS NOT NULL))))
);


--
-- Name: dialogue_context_index_entry(agent.agent_dialogue_entries); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.dialogue_context_index_entry(value agent.agent_dialogue_entries) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE target_agent UUID; previous_hash BYTEA; payload_hash BYTEA;
BEGIN
 SELECT agent_id INTO STRICT target_agent FROM agent.agent_dialogues
 WHERE dialogue_id=value.dialogue_id AND tenant_id=value.tenant_id AND owner_id=value.owner_id;
 IF value.seq=1 THEN
  previous_hash:=sha256(convert_to('musteragent.dialogue-context-source@1','UTF8')
    ||uuid_send(value.tenant_id)||uuid_send(value.owner_id)||uuid_send(target_agent)
    ||uuid_send(value.dialogue_id)||int8send(value.epoch));
 ELSE
  SELECT chain_sha256 INTO STRICT previous_hash FROM agent.dialogue_context_source_entries
  WHERE dialogue_id=value.dialogue_id AND epoch=value.epoch AND seq=value.seq-1;
 END IF;
 payload_hash:=sha256(uuid_send(value.entry_id)||int8send(value.epoch)||int8send(value.seq)
  ||int8send(CASE value.kind WHEN 'user_message' THEN
       CASE WHEN value.input_attachment_count>0 THEN 6 ELSE 1 END
       WHEN 'agent_message' THEN 2 WHEN 'interaction' THEN 3
       WHEN 'artifact' THEN 4 WHEN 'partner_created' THEN 5 END)
  ||agent.dialogue_context_optional(uuid_send(value.source_intent_id))
  ||agent.dialogue_context_optional(uuid_send(value.author_agent_id))
  ||agent.dialogue_context_optional(CASE
       WHEN value.kind='user_message' AND value.input_attachment_count>0 THEN
        agent.dialogue_input_attachment_payload(value)
       WHEN value.kind='partner_created' THEN
        uuid_send(value.partner_creation_command_id)||uuid_send(value.partner_agent_id)
        ||uuid_send(value.partner_dialogue_id)
        ||int8send(octet_length(convert_to(value.partner_display_name,'UTF8'))::BIGINT)
        ||convert_to(value.partner_display_name,'UTF8')
        ||int8send(octet_length(convert_to(value.partner_description,'UTF8'))::BIGINT)
        ||convert_to(value.partner_description,'UTF8')
        ||agent.dialogue_context_optional(value.partner_avatar_ref)
        ||int8send(value.partner_profile_revision)
       ELSE value.content_ref END)
  ||agent.dialogue_context_optional(uuid_send(value.interaction_id))
  ||agent.dialogue_context_optional(uuid_send(value.artifact_id))
  ||agent.dialogue_context_optional(uuid_send(value.artifact_version_id))
  ||int8send(value.visible_revision)||int8send(value.created_at_ms));
 INSERT INTO agent.dialogue_context_source_entries(entry_id,tenant_id,owner_id,agent_id,
  dialogue_id,epoch,seq,source_visible_revision,payload_sha256,previous_sha256,chain_sha256)
 VALUES(value.entry_id,value.tenant_id,value.owner_id,target_agent,value.dialogue_id,
  value.epoch,value.seq,value.visible_revision,payload_hash,previous_hash,sha256(previous_hash||payload_hash));
END $$;


--
-- Name: dialogue_context_index_insert(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.dialogue_context_index_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN PERFORM agent.dialogue_context_index_entry(NEW); RETURN NEW; END $$;


--
-- Name: dialogue_context_optional(bytea); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.dialogue_context_optional(value bytea) RETURNS bytea
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT CASE WHEN value IS NULL THEN decode('00','hex')
 ELSE decode('01','hex') || int8send(octet_length(value)::BIGINT) || value END
$$;


--
-- Name: dialogue_context_source_immutable(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.dialogue_context_source_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected_job UUID; original_digest BYTEA;
BEGIN
 IF NEW.kind='erased' AND OLD.kind<>'erased' THEN
  SELECT privacy_erasure.work_item_execution_job(p.tenant_id,p.source_conversation_id),s.payload_sha256
  INTO expected_job,original_digest FROM agent.dialogue_publications p
  JOIN agent.dialogue_context_source_entries s USING(entry_id) WHERE p.entry_id=OLD.entry_id;
  IF expected_job IS NULL THEN
   SELECT privacy_erasure.work_item_execution_job(x.tenant_id,x.conversation_id),s.payload_sha256
   INTO expected_job,original_digest FROM collaboration.work_item_execution_reservations x
   JOIN agent.dialogue_context_source_entries s ON s.entry_id=x.partner_input_entry_id
   WHERE x.partner_input_entry_id=OLD.entry_id AND x.tenant_id=OLD.tenant_id
    AND x.owner_id=OLD.owner_id AND x.executing_dialogue_id=OLD.dialogue_id;
  END IF;
  IF expected_job IS NULL AND OLD.interaction_id IS NOT NULL THEN
   SELECT privacy_erasure.work_item_source_command_job(i.requested_by_invocation_id),s.payload_sha256
   INTO expected_job,original_digest FROM approval.interactions i
   JOIN agent.dialogue_context_source_entries s ON s.entry_id=OLD.entry_id
   WHERE i.interaction_id=OLD.interaction_id AND i.tenant_id=OLD.tenant_id;
  END IF;
  IF expected_job IS NULL OR NEW.erasure_job_id IS DISTINCT FROM expected_job
   OR NEW.erased_source_payload_sha256 IS DISTINCT FROM original_digest
   OR NEW.visible_revision<>OLD.visible_revision+1
   OR (to_jsonb(NEW)-ARRAY['kind','erasure_job_id','erased_source_payload_sha256','visible_revision',
      'partner_creation_command_id','partner_agent_id','partner_dialogue_id','partner_display_name',
      'partner_description','partner_avatar_ref','partner_profile_revision'])
    IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['kind','erasure_job_id','erased_source_payload_sha256','visible_revision',
      'partner_creation_command_id','partner_agent_id','partner_dialogue_id','partner_display_name',
      'partner_description','partner_avatar_ref','partner_profile_revision']) THEN
   RAISE EXCEPTION 'public erasure requires original frozen Task coverage';
  END IF;
  RETURN NEW;
 END IF;
 IF OLD.kind='erased' AND NEW IS DISTINCT FROM OLD THEN
  RAISE EXCEPTION 'erased public entry is immutable';
 END IF;
 IF (to_jsonb(NEW)-'visible_revision') IS DISTINCT FROM (to_jsonb(OLD)-'visible_revision')
    OR NEW.visible_revision<OLD.visible_revision THEN
  RAISE EXCEPTION 'dialogue public source is immutable';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: dialogue_execution_source_cancelled(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.dialogue_execution_source_cancelled(source_intent uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM agent.dialogue_execution_cancellation_targets WHERE intent_id=source_intent) OR EXISTS(SELECT 1 FROM agent.dialogue_execution_source_roots s JOIN agent.dialogue_execution_cancellation_roots f ON f.root_intent_id=s.root_intent_id AND f.tenant_id=s.tenant_id AND f.owner_id=s.owner_id AND f.agent_id=s.agent_id AND f.dialogue_id=s.dialogue_id AND f.root_entry_id=s.root_entry_id AND f.root_content_ref=s.root_content_ref AND f.root_epoch=s.root_epoch AND f.root_seq=s.root_seq WHERE s.intent_id=source_intent AND s.direct_user_root)
$$;


--
-- Name: dialogue_input_attachment_complete(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.dialogue_input_attachment_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE target UUID; original agent.dialogue_user_intents; entry agent.agent_dialogue_entries; amount BIGINT; last_ordinal SMALLINT;
BEGIN
 IF TG_TABLE_NAME='dialogue_user_intents' THEN target:=COALESCE(NEW.intent_id,OLD.intent_id);
 ELSIF TG_TABLE_NAME='agent_dialogue_entries' THEN target:=COALESCE(NEW.source_intent_id,OLD.source_intent_id);
 ELSE target:=COALESCE(NEW.intent_id,OLD.intent_id); END IF;
 SELECT * INTO original FROM agent.dialogue_user_intents WHERE intent_id=target;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO STRICT entry FROM agent.agent_dialogue_entries WHERE entry_id=original.source_entry_id;
 SELECT count(*),max(ordinal) INTO amount,last_ordinal FROM agent.dialogue_input_attachments WHERE intent_id=target;
 IF amount<>original.input_attachment_count OR amount<>entry.input_attachment_count
  OR (amount>0 AND last_ordinal<>amount-1) THEN RAISE EXCEPTION 'incomplete Dialogue input attachment snapshot'; END IF;
 RETURN NULL;
END $$;


