-- Name: dialogue_input_attachment_insert_guard(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.dialogue_input_attachment_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM agent.dialogue_user_intents i JOIN agent.agent_dialogue_entries e
  ON e.entry_id=i.source_entry_id WHERE i.intent_id=NEW.intent_id) THEN
  RAISE EXCEPTION 'accepted input attachment rows cannot be replaced';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: dialogue_input_attachment_payload(agent.agent_dialogue_entries); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.dialogue_input_attachment_payload(value agent.agent_dialogue_entries) RETURNS bytea
    LANGUAGE plpgsql
    AS $$
DECLARE item agent.dialogue_input_attachments; bytes BYTEA; ref BYTEA; attachment BYTEA; position INTEGER:=0;
BEGIN
 bytes:=convert_to('musteragent.dialogue-user-entry-attachments.v1','UTF8')||decode('00','hex')
  ||int8send(octet_length(value.content_ref)::BIGINT)||value.content_ref||int8send(value.input_attachment_count::BIGINT);
 FOR item IN SELECT * FROM agent.dialogue_input_attachments
  WHERE intent_id=value.source_intent_id AND tenant_id=value.tenant_id AND owner_id=value.owner_id ORDER BY ordinal LOOP
  IF item.ordinal<>position THEN RAISE EXCEPTION 'input attachment order is not contiguous'; END IF;
  position:=position+1;
  ref:=uuid_send(item.content_id)||int8send(octet_length(convert_to(item.media_type,'UTF8'))::BIGINT)
   ||convert_to(item.media_type,'UTF8')||int8send(item.byte_length)||item.content_hash;
  attachment:=int8send(octet_length(ref)::BIGINT)||ref
   ||int8send(octet_length(convert_to(item.display_name,'UTF8'))::BIGINT)||convert_to(item.display_name,'UTF8');
  bytes:=bytes||int8send(octet_length(attachment)::BIGINT)||attachment;
 END LOOP;
 IF position<>value.input_attachment_count THEN RAISE EXCEPTION 'input attachment count differs'; END IF;
 RETURN bytes;
END $$;


