CREATE FUNCTION agent.dialogue_intent_attachment_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.input_attachments<>NEW.input_attachments OR OLD.input_attachment_count<>NEW.input_attachment_count THEN
  RAISE EXCEPTION 'accepted input attachment snapshot is immutable';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: native_control_target_bytes(uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, bytea, bigint, bytea); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.native_control_target_bytes(tenant uuid, owner_id uuid, agent uuid, dialogue uuid, intent uuid, run uuid, conversation uuid, device uuid, installation uuid, source bytea, grant_revision bigint, grant_proof bytea) RETURNS bytea
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT convert_to('musteragent.device-control-target.v1', 'UTF8') || decode('00', 'hex') || uuid_send(tenant)||uuid_send(owner_id)||uuid_send(agent)||uuid_send(dialogue)
 ||uuid_send(intent)||uuid_send(run)||uuid_send(conversation)||uuid_send(device)||uuid_send(installation)
 ||source||int8send(grant_revision)||coalesce(grant_proof,''::bytea)
$$;


