    AS $$
BEGIN
 IF NEW.subject_kind='intent' THEN
  NEW.source_dialogue_id:=COALESCE(NEW.source_dialogue_id,NEW.dialogue_id);
  NEW.requesting_agent_id:=COALESCE(NEW.requesting_agent_id,NEW.agent_id);
 END IF;
 RETURN NEW;
