--
-- Name: dialogue_source_failure_qualified(uuid, bytea); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.dialogue_source_failure_qualified(target uuid, proof bytea) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM agent.dialogue_intent_admissions q WHERE q.intent_id=target AND q.execution_target='origin_device')
 AND NOT EXISTS(SELECT 1 FROM agent.dialogue_sessions s WHERE s.source_intent_id=target)
 AND ((proof IS NULL AND NOT EXISTS(SELECT 1 FROM agent.device_admissions d WHERE d.intent_id=target))
 OR EXISTS(SELECT 1 FROM agent.device_source_not_admitted n
   JOIN agent.device_source_refusals r USING(intent_id,run_id)
   JOIN agent.device_admissions d USING(intent_id,run_id)
   WHERE n.intent_id=target AND n.receipt_sha256=proof AND d.admitted_at_ms IS NULL
     AND NOT EXISTS(SELECT 1 FROM agent.device_grant_heads h WHERE h.intent_id=target AND h.admitted_revision IS NOT NULL)
     AND NOT EXISTS(SELECT 1 FROM agent.native_dialogue_terminals t WHERE t.run_id=d.run_id)))
$$;


