--

CREATE FUNCTION agent.queue_dialogue_history_search() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.kind='erased' THEN
  DELETE FROM agent.dialogue_history_search_documents WHERE entry_id=NEW.entry_id;
  DELETE FROM agent.dialogue_history_search_pending WHERE entry_id=NEW.entry_id;
 ELSE
  INSERT INTO agent.dialogue_history_search_pending(entry_id) VALUES(NEW.entry_id)
  ON CONFLICT(entry_id) DO UPDATE SET next_attempt_at_ms=0;
 END IF;
 RETURN NEW;
END $$;


