--
-- Name: require_dialogue_capability_origin(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.require_dialogue_capability_origin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.origin_surface='capability' AND NOT EXISTS(
  SELECT 1 FROM approval.interactions i
  JOIN approval.interaction_responses response USING(interaction_id)
  JOIN runtime.runs r ON r.run_id=i.run_id AND r.tenant_id=i.tenant_id AND r.conversation_id=i.conversation_id
  JOIN agent.dialogue_sessions s ON s.conversation_id=r.conversation_id AND s.tenant_id=r.tenant_id
  JOIN agent.agent_dialogue_entries e ON e.entry_id=NEW.source_entry_id AND e.interaction_id=i.interaction_id
  WHERE i.interaction_id=NEW.continuation_interaction_id AND i.status=2 AND i.kind=6
    AND i.response_schema_key='capability.completion@1' AND response.response_kind=3 AND r.status=5
    AND s.owner_id=NEW.owner_id AND s.tenant_id=NEW.tenant_id AND s.dialogue_id=NEW.dialogue_id
    AND s.source_intent_id=NEW.reply_to_intent_id AND s.purpose='intent_coordination' AND NEW.origin_installation_id IS NULL
    AND e.kind='interaction' AND e.dialogue_id=NEW.dialogue_id AND e.epoch=NEW.accepted_epoch AND e.seq=NEW.accepted_seq
 ) AND NOT EXISTS(
  SELECT 1 FROM agent.native_dialogue_interaction_projections i
  JOIN agent.native_dialogue_interaction_commands c USING(interaction_id)
  JOIN agent.native_dialogue_terminals t ON t.run_id=i.run_id AND t.tenant_id=i.tenant_id AND t.owner_id=i.owner_id AND t.intent_id=i.intent_id
  JOIN agent.agent_dialogue_entries e ON e.entry_id=NEW.source_entry_id AND e.interaction_id=i.interaction_id
  WHERE i.interaction_id=NEW.continuation_interaction_id AND i.status=2 AND c.outcome='applied' AND t.outcome='succeeded'
    AND i.installation_id=NEW.origin_installation_id AND i.tenant_id=NEW.tenant_id AND i.owner_id=NEW.owner_id AND i.dialogue_id=NEW.dialogue_id AND i.intent_id=NEW.reply_to_intent_id
    AND e.kind='interaction' AND e.dialogue_id=NEW.dialogue_id AND e.epoch=NEW.accepted_epoch AND e.seq=NEW.accepted_seq
 ) THEN RAISE EXCEPTION 'capability continuation requires original completed Interaction and Run' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


