  JOIN agent.owner_schedules s USING(schedule_id)
  JOIN agent.agent_dialogues d USING(agent_id)
  WHERE o.intent_id=NEW.intent_id AND s.tenant_id=NEW.tenant_id AND s.owner_id=NEW.owner_id
    AND d.dialogue_id=NEW.dialogue_id
 ) THEN RAISE EXCEPTION 'scheduled input requires original occurrence' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: validate_agent_version_insert(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.validate_agent_version_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    definition_built_in BOOLEAN;
    material_available BOOLEAN;
BEGIN
    IF NEW.retired_at_ms IS NOT NULL THEN
        RAISE EXCEPTION 'new Agent versions cannot be retired';
    END IF;
    IF NEW.material_schema_version IS DISTINCT FROM 1
       OR NEW.manifest_content_id IS NULL
       OR NEW.manifest_hash IS NULL
       OR NEW.policy_content_id IS NULL
       OR NEW.memory_policy_content_id IS NULL
       OR NEW.memory_policy_hash IS NULL THEN
        RAISE EXCEPTION 'new Agent versions require complete immutable material';
    END IF;
    IF NEW.manifest_content_id = NEW.persona_content_id
       OR NEW.manifest_content_id = NEW.policy_content_id
       OR NEW.manifest_content_id = NEW.memory_policy_content_id
       OR NEW.persona_content_id = NEW.policy_content_id
       OR NEW.persona_content_id = NEW.memory_policy_content_id
       OR NEW.policy_content_id = NEW.memory_policy_content_id THEN
        RAISE EXCEPTION 'Agent version material ContentRefs must be distinct';
    END IF;
    IF NEW.user_memory_collection_id IS NOT NULL
       OR NEW.long_term_memory_collection_id IS NOT NULL THEN
        RAISE EXCEPTION 'Memory Collection ownership authority is unavailable';
    END IF;

    SELECT definition.built_in
      INTO definition_built_in
      FROM agent.agent_definitions AS definition
     WHERE definition.agent_id = NEW.agent_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Agent definition is unavailable';
    END IF;

    SELECT TRUE
      INTO material_available
      FROM artifact.content_refs AS persona
      JOIN artifact.content_refs AS manifest
        ON manifest.content_id = NEW.manifest_content_id
      JOIN artifact.content_refs AS policy
        ON policy.content_id = NEW.policy_content_id
      JOIN artifact.content_refs AS memory_policy
        ON memory_policy.content_id = NEW.memory_policy_content_id
     WHERE persona.content_id = NEW.persona_content_id
       AND persona.content_hash = NEW.persona_hash
       AND manifest.content_hash = NEW.manifest_hash
       AND policy.content_hash = NEW.policy_hash
       AND memory_policy.content_hash = NEW.memory_policy_hash
       AND persona.state = 2
       AND manifest.state = 2
       AND policy.state = 2
       AND memory_policy.state = 2
       AND manifest.tenant_id IS NOT DISTINCT FROM persona.tenant_id
       AND policy.tenant_id IS NOT DISTINCT FROM persona.tenant_id
       AND memory_policy.tenant_id IS NOT DISTINCT FROM persona.tenant_id
       AND (NOT definition_built_in OR persona.tenant_id IS NULL);
    IF material_available IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'Agent version material is unavailable or crosses ownership scope';
    END IF;

    IF NEW.version = 1 AND NEW.supersedes_agent_version_id IS NULL THEN
        RETURN NEW;
    END IF;
    IF NEW.version <= 1 OR NEW.supersedes_agent_version_id IS NULL OR NOT EXISTS (
        SELECT 1
        FROM agent.agent_versions AS parent
        WHERE parent.agent_version_id = NEW.supersedes_agent_version_id
          AND parent.agent_id = NEW.agent_id
          AND NEW.version = parent.version + 1
    ) THEN
        RAISE EXCEPTION 'invalid immutable Agent version lineage';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_owner_event_subscription(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.validate_owner_event_subscription() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NOT EXISTS (
  SELECT 1 FROM agent.owner_spaces s
  JOIN agent.owned_agents a ON a.space_id=s.space_id
  JOIN agent.goal_source_bindings b ON b.agent_id=a.agent_id
  JOIN runtime.standing_goals g ON g.tenant_id=s.tenant_id AND g.owner_principal_id=s.owner_id AND g.target_agent_id=a.agent_id
  JOIN agent.dialogue_sessions session ON session.tenant_id=g.tenant_id AND session.source_goal_id=g.goal_id
  WHERE s.space_id=NEW.space_id AND s.tenant_id=NEW.tenant_id AND s.owner_id=NEW.owner_id
    AND a.agent_id=NEW.agent_id AND b.binding_id=NEW.application_binding_id
    AND b.tenant_id=NEW.tenant_id AND b.owner_id=NEW.owner_id
    AND g.goal_id=NEW.goal_id AND g.mode=2 AND session.subject_kind='goal'
 ) THEN RAISE EXCEPTION 'event subscription requires its original account Goal and host source binding' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: validate_agent_foundation_upgrade_mutation(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.validate_agent_foundation_upgrade_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='INSERT' THEN
        IF num_nonnulls(NEW.committed_version_id,NEW.committed_pointer_version,NEW.committed_agent_revision)<>0 THEN
            RAISE EXCEPTION 'Owned foundation preparation cannot insert a committed receipt';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Owned foundation provenance is retained'; END IF;
    IF ROW(NEW.tenant_id,NEW.owner_id,NEW.agent_id,NEW.space_id,NEW.root_command_id,NEW.root_version_id,
           NEW.predecessor_version_id,NEW.target_version_id,NEW.target_template_ref,NEW.target_template_hash,
           NEW.expected_pointer_version,NEW.expected_agent_revision,NEW.prepared_at_ms)
       IS DISTINCT FROM
       ROW(OLD.tenant_id,OLD.owner_id,OLD.agent_id,OLD.space_id,OLD.root_command_id,OLD.root_version_id,
           OLD.predecessor_version_id,OLD.target_version_id,OLD.target_template_ref,OLD.target_template_hash,
           OLD.expected_pointer_version,OLD.expected_agent_revision,OLD.prepared_at_ms)
       OR OLD.committed_version_id IS NOT NULL OR NEW.committed_version_id IS NULL THEN
        RAISE EXCEPTION 'Owned foundation preparation and receipt are immutable';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM agent.published_agent_version_pointers p
                   JOIN agent.owned_agents a USING(agent_id)
                   WHERE p.agent_id=NEW.agent_id AND p.pointer_version=NEW.committed_pointer_version
                     AND p.agent_version_id=NEW.target_version_id AND p.previous_agent_version_id=NEW.predecessor_version_id
                     AND p.previous_pointer_version=NEW.expected_pointer_version AND p.change_kind=2
                     AND p.published_by=NEW.owner_id AND p.published_at_ms=NEW.prepared_at_ms
                     AND a.published_version_id=NEW.target_version_id AND a.revision=NEW.committed_agent_revision) THEN
        RAISE EXCEPTION 'Owned foundation receipt requires both original published pins';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_owner_goal_coordinator_context(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.validate_owner_goal_coordinator_context() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.goal_coordinator_conversation_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM conversation.conversations c
  JOIN conversation.participants executor ON executor.conversation_id=c.conversation_id
    AND executor.tenant_id=c.tenant_id AND executor.participant_id=c.execution_owner_participant_id
    AND executor.kind=2 AND executor.agent_ref=NEW.requesting_agent_id AND executor.left_at_ms IS NULL
  JOIN conversation.participants owner ON owner.conversation_id=c.conversation_id
    AND owner.tenant_id=c.tenant_id AND owner.kind=1 AND owner.principal_ref=NEW.owner_id AND owner.left_at_ms IS NULL
  WHERE c.tenant_id=NEW.tenant_id AND c.conversation_id=NEW.goal_coordinator_conversation_id
    AND c.created_by=NEW.owner_id AND c.purpose='owner_goal_coordination'
 ) THEN RAISE EXCEPTION 'Goal coordination requires the original private coordinator context' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: validate_owner_goal_session(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.validate_owner_goal_session() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.subject_kind='goal' AND NOT EXISTS(
  SELECT 1 FROM runtime.standing_goals g
  JOIN agent.owned_agents a ON a.agent_id=NEW.agent_id
  JOIN agent.owner_spaces s ON s.space_id=a.space_id AND s.tenant_id=NEW.tenant_id AND s.owner_id=NEW.owner_id
  JOIN agent.owned_agents requester ON requester.agent_id=NEW.requesting_agent_id AND requester.space_id=s.space_id
  WHERE g.tenant_id=NEW.tenant_id AND g.goal_id=NEW.source_goal_id AND g.owner_principal_id=NEW.owner_id
   AND g.conversation_id=NEW.conversation_id AND g.target_agent_id=NEW.agent_id AND g.mode=2
 ) THEN RAISE EXCEPTION 'Owner-scoped Goal session requires its original account-owned Goal' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


