 RETURN NEW;
END $$;


--
-- Name: validate_published_pointer_insert(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.validate_published_pointer_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    candidate_version NUMERIC(20, 0);
    candidate_parent UUID;
    candidate_published_at BIGINT;
    candidate_retired_at BIGINT;
    candidate_material_schema SMALLINT;
    previous_version NUMERIC(20, 0);
    previous_changed_at BIGINT;
BEGIN
    SELECT version, supersedes_agent_version_id, published_at_ms, retired_at_ms,
           material_schema_version
      INTO candidate_version, candidate_parent, candidate_published_at,
           candidate_retired_at, candidate_material_schema
      FROM agent.agent_versions
     WHERE agent_id = NEW.agent_id
       AND agent_version_id = NEW.agent_version_id;
    IF NOT FOUND
       OR candidate_published_at <> NEW.published_at_ms
       OR candidate_retired_at IS NOT NULL THEN
        RAISE EXCEPTION 'Published Pointer target is unavailable or non-canonical';
    END IF;

    IF NEW.change_kind = 1 THEN
        IF candidate_version <> 1
           OR candidate_parent IS NOT NULL
           OR candidate_material_schema IS DISTINCT FROM 1 THEN
            RAISE EXCEPTION 'initial publication requires a complete root Agent version';
        END IF;
        RETURN NEW;
    END IF;

    SELECT version.version, pointer.changed_at_ms
      INTO previous_version, previous_changed_at
      FROM agent.published_agent_version_pointers AS pointer
      JOIN agent.agent_versions AS version
        ON version.agent_id = pointer.agent_id
       AND version.agent_version_id = pointer.agent_version_id
     WHERE pointer.agent_id = NEW.agent_id
       AND pointer.pointer_version = NEW.previous_pointer_version
       AND pointer.agent_version_id = NEW.previous_agent_version_id;
    IF NOT FOUND OR NEW.changed_at_ms < previous_changed_at THEN
        RAISE EXCEPTION 'Published Pointer predecessor is unavailable or audit time regressed';
    END IF;
    IF NEW.change_kind = 2
       AND (candidate_material_schema IS DISTINCT FROM 1
            OR candidate_parent <> NEW.previous_agent_version_id
            OR candidate_version <> previous_version + 1) THEN
        RAISE EXCEPTION 'forward publication requires the next complete Agent version';
    END IF;
    IF NEW.change_kind = 3 AND candidate_version >= previous_version THEN
        RAISE EXCEPTION 'rollback must target an earlier immutable Agent version';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_schedule_source(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.validate_schedule_source() RETURNS trigger
    LANGUAGE plpgsql
