            RAISE EXCEPTION 'schedule run authority missing' USING ERRCODE='23503';
        END IF;
    END IF;
    RETURN NEW;
END $$;


--
-- Name: validate_work_item_execution_session(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.validate_work_item_execution_session() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.subject_kind='work_item' AND NOT EXISTS(
 SELECT 1 FROM collaboration.work_item_execution_reservations x JOIN runtime.runs r ON r.run_id=x.run_id
 WHERE x.work_item_id=NEW.work_item_id AND x.goal_revision=NEW.work_item_goal_revision
 AND x.control_revision=NEW.work_item_control_revision AND x.assignment_epoch=NEW.work_item_assignment_epoch
 AND x.conversation_id=NEW.conversation_id AND r.conversation_id=NEW.conversation_id AND r.tenant_id=NEW.tenant_id
 AND x.owner_id=NEW.owner_id AND x.requesting_agent_id=NEW.requesting_agent_id AND x.executing_agent_id=NEW.agent_id AND x.executing_dialogue_id=NEW.dialogue_id
 ) THEN RAISE EXCEPTION 'Task session requires its original admitted Runtime Run'; END IF;
 RETURN NEW;
END $$;


--
-- Name: validate_work_item_report_session(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.validate_work_item_report_session() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.subject_kind='work_item_report' AND NOT EXISTS(SELECT 1 FROM collaboration.work_item_execution_reports p
 JOIN runtime.runs r ON r.run_id=p.report_run_id AND r.tenant_id=p.tenant_id AND r.conversation_id=p.report_conversation_id
 WHERE p.producing_run_id=NEW.report_from_run_id AND p.tenant_id=NEW.tenant_id AND p.owner_id=NEW.owner_id
 AND p.requesting_agent_id=NEW.agent_id AND p.source_dialogue_id=NEW.dialogue_id
 AND p.report_conversation_id=NEW.conversation_id) THEN RAISE EXCEPTION 'Report continuation requires exact report/Runtime binding'; END IF;
 RETURN NEW;
END $$;


--
-- Name: assert_evolution_approval_source(); Type: FUNCTION; Schema: approval; Owner: -
--

CREATE FUNCTION approval.assert_evolution_approval_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    matching_sources INTEGER;
BEGIN
    SELECT count(*) INTO matching_sources
    FROM (
        SELECT interaction.interaction_id
        FROM approval.interactions AS interaction
        JOIN approval.interaction_responses AS response
          ON response.interaction_id = interaction.interaction_id
        JOIN artifact.content_refs AS content
          ON content.content_id = interaction.prompt_content_id
         AND content.tenant_id = interaction.tenant_id
        WHERE NEW.execution_home='cloud' AND NEW.tool_invocation_id IS NULL
          AND interaction.interaction_id = NEW.approval_interaction_id
          AND interaction.kind = 1
          AND interaction.status = 2
          AND interaction.prompt_content_id = NEW.prompt_content_id
          AND content.content_hash = NEW.prompt_content_hash
          AND interaction.responded_by = NEW.approved_by
          AND interaction.responded_at_ms = NEW.approved_at_ms
          AND response.response_kind = 1
          AND response.approval_decision = 1
          AND response.responded_by = NEW.approved_by
          AND response.responded_at_ms = NEW.approved_at_ms
        UNION ALL
        SELECT interaction.interaction_id
        FROM approval.management_interactions AS interaction
        WHERE NEW.execution_home='cloud' AND NEW.tool_invocation_id IS NULL
          AND interaction.interaction_id = NEW.approval_interaction_id
          AND interaction.proposal_id = NEW.proposal_id
          AND interaction.evaluation_id = NEW.evaluation_id
          AND interaction.prompt_content_id = NEW.prompt_content_id
          AND interaction.prompt_content_hash = NEW.prompt_content_hash
          AND interaction.approved_by = NEW.approved_by
          AND interaction.approved_at_ms = NEW.approved_at_ms
          AND interaction.approval_decision = 1
        UNION ALL
        SELECT interaction.interaction_id
        FROM approval.evolution_management_interactions AS interaction
        WHERE NEW.execution_home='cloud' AND NEW.tool_invocation_id IS NULL
          AND interaction.interaction_id = NEW.approval_interaction_id
          AND interaction.proposal_id = NEW.proposal_id
          AND interaction.evaluation_id = NEW.evaluation_id
          AND interaction.prompt_content_id = NEW.prompt_content_id
          AND interaction.prompt_content_hash = NEW.prompt_content_hash
          AND interaction.approved_by = NEW.approved_by
          AND interaction.approved_at_ms = NEW.approved_at_ms
          AND interaction.approval_decision = 1
        UNION ALL
        SELECT interaction.interaction_id
        FROM approval.interactions AS interaction
        JOIN approval.interaction_responses AS response
          ON response.interaction_id=interaction.interaction_id
        JOIN tool.tool_invocations AS invocation
          ON invocation.invocation_id=interaction.requested_by_invocation_id
         AND invocation.interaction_id=interaction.interaction_id
         AND invocation.tenant_id=interaction.tenant_id
        JOIN evolution.proposals AS proposal
          ON proposal.proposal_id=NEW.proposal_id AND proposal.tenant_id=interaction.tenant_id
        JOIN evolution.evaluations AS evaluation
          ON evaluation.proposal_id=proposal.proposal_id AND evaluation.evaluation_id=NEW.evaluation_id
        JOIN artifact.content_refs AS statement
          ON statement.content_id=NEW.prompt_content_id AND statement.tenant_id=proposal.tenant_id
         AND statement.content_hash=NEW.prompt_content_hash
         AND statement.media_type='application/vnd.musteragent.legacy.evolution-approval.v2+text'
        JOIN artifact.content_refs AS envelope
          ON envelope.content_id=NEW.tool_prompt_content_id AND envelope.tenant_id=proposal.tenant_id
         AND envelope.content_hash=NEW.tool_prompt_content_hash AND envelope.media_type='application/json'
        WHERE NEW.execution_home='cloud' AND invocation.invocation_id=NEW.tool_invocation_id
          AND invocation.tool_ref='experience.publish@1' AND invocation.approval_policy=3
          AND invocation.status=3
          AND interaction.interaction_id=NEW.approval_interaction_id
          AND interaction.kind=1 AND interaction.status=2
          AND interaction.prompt_content_id=envelope.content_id
          AND interaction.responded_by=NEW.approved_by AND interaction.responded_at_ms=NEW.approved_at_ms
          AND response.response_kind=1 AND response.approval_decision=1
          AND response.responded_by=NEW.approved_by AND response.responded_at_ms=NEW.approved_at_ms
          AND evaluation.passed=TRUE AND evaluation.evaluated_at_ms<=NEW.approved_at_ms
        UNION ALL
        SELECT native.interaction_id FROM memory.native_tool_approvals native
        JOIN resource.device_commands command ON command.invocation_id=native.invocation_id
        JOIN evolution.proposals proposal ON proposal.proposal_id=NEW.proposal_id AND proposal.tenant_id=native.tenant_id
        JOIN evolution.evaluations evaluation ON evaluation.proposal_id=proposal.proposal_id AND evaluation.evaluation_id=NEW.evaluation_id
        JOIN artifact.content_refs statement ON statement.content_id=NEW.prompt_content_id AND statement.tenant_id=proposal.tenant_id
         AND statement.content_hash=NEW.prompt_content_hash AND statement.media_type='application/vnd.musteragent.legacy.evolution-approval.v2+text'
        WHERE NEW.execution_home='device' AND native.interaction_id=NEW.approval_interaction_id
         AND native.invocation_id=NEW.tool_invocation_id AND command.tool_key='experience.publish@1'
         AND native.approved_by=NEW.approved_by AND native.approved_at_ms=NEW.approved_at_ms
         AND native.prompt_content_id=NEW.tool_prompt_content_id AND native.prompt_content_hash=NEW.tool_prompt_content_hash
         AND evaluation.passed=TRUE AND evaluation.evaluated_at_ms<=NEW.approved_at_ms
    ) AS source;
    IF matching_sources <> 1 THEN
        RAISE EXCEPTION 'evolution Approval requires exactly one canonical interaction source';
    END IF;
    RETURN NEW;
END;
$$;


