--
-- Name: reject_interaction_response_receipt_update(); Type: FUNCTION; Schema: approval; Owner: -
--

CREATE FUNCTION approval.reject_interaction_response_receipt_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE job UUID;
BEGIN
 IF OLD.erasure_job_id IS NULL AND NEW.erasure_job_id IS NOT NULL THEN
  SELECT COALESCE(privacy_erasure.work_item_run_erasure(run_id),privacy_erasure.work_item_source_command_job(requested_by_invocation_id)) INTO job FROM approval.interactions WHERE interaction_id=OLD.interaction_id;
  IF NEW.erasure_job_id IS DISTINCT FROM job OR job IS NULL
   OR NEW.secure_response_ref IS NOT NULL OR NEW.secure_response_ref_protected IS NOT NULL
   OR (to_jsonb(NEW)-ARRAY['secure_response_ref','secure_response_ref_protected','erasure_job_id'])
    IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['secure_response_ref','secure_response_ref_protected','erasure_job_id']) THEN
   RAISE EXCEPTION 'Interaction receipt erasure requires exact Task authority';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Interaction response receipt is immutable'; END IF;
 RETURN NEW;
END $$;


