--
-- Name: check_device_resource_version(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.check_device_resource_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND NEW IS DISTINCT FROM OLD) THEN RAISE EXCEPTION 'Device Resource author is immutable'; END IF;
 IF NOT EXISTS(SELECT 1 FROM resource.device_commands c
  JOIN artifact.artifact_versions v ON v.artifact_version_id=NEW.artifact_version_id AND v.artifact_id=NEW.artifact_id
  JOIN artifact.artifacts a ON a.artifact_id=v.artifact_id AND a.tenant_id=c.tenant_id
  JOIN resource.nodes n ON n.node_id=NEW.node_id AND n.tenant_id=c.tenant_id AND n.scope_kind=4 AND n.scope_id=c.agent_id AND n.file_artifact_id=a.artifact_id
  WHERE c.invocation_id=NEW.invocation_id AND c.source_participant_id=NEW.source_participant_id
  AND c.tool_key IN ('resource.file.create@3','resource.file.create@4','resource.file.edit.finalize@3','resource.file.edit.finalize@4','resource.change-set.commit@5','resource.change-set.commit@6')
  AND c.committed_at_ms IS NOT NULL AND c.outcome='succeeded' AND v.source_invocation_id IS NULL AND v.committed_by_principal_id IS NULL
  AND v.committed_by=NEW.source_participant_id AND v.version=NEW.canonical_version
  AND v.content_id=NEW.content_id AND v.content_hash=NEW.content_hash AND v.committed_at_ms=NEW.committed_at_ms) THEN
  RAISE EXCEPTION 'Canonical Device version lacks exact original Resource command' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: check_device_version(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.check_device_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM artifact.artifact_versions v
  WHERE v.artifact_version_id=NEW.artifact_version_id AND v.artifact_id=NEW.artifact_id
   AND v.source_invocation_id IS NULL AND v.committed_by=NEW.source_participant_id
   AND v.committed_by_principal_id IS NULL AND v.content_id=NEW.content_id
   AND v.content_hash=NEW.content_hash AND v.committed_at_ms=NEW.terminal_at_ms AND v.version=NEW.canonical_version) THEN
  RAISE EXCEPTION 'Device source mapping lacks exact original Artifact version' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: check_task_native_origin(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.check_task_native_origin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'Immutable Task device producer proof'; END IF;
 IF NOT EXISTS (SELECT 1 FROM artifact.work_item_result_asset_candidates p
   JOIN collaboration.work_item_device_admitted_custody d ON d.run_id=p.producer_run_id AND d.work_item_id=p.task_id AND d.runtime_snapshot_id=p.producer_snapshot_id
    AND d.source_digest=NEW.source_sha256 AND d.admitted_snapshot_hash=NEW.snapshot_sha256 AND d.signed_grant_hash=NEW.grant_sha256
   JOIN resource.device_commands c ON c.invocation_id=NEW.transport_invocation_id AND c.tenant_id=p.tenant_id AND c.work_item_run_id=d.run_id
    AND c.run_id=d.run_id AND c.conversation_id=d.conversation_id AND c.device_id=NEW.device_id AND c.installation_id=NEW.installation_id
    AND c.command_commitment=NEW.command_sha256 AND c.admission_kind='work_item' AND c.outcome='succeeded' AND c.receipt_content_id IS NOT NULL
   WHERE p.version_id=NEW.version_id AND p.producer_home='device'
    AND ((NEW.origin_kind='local_export' AND c.tool_key='tasks.submit_result@1') OR (NEW.origin_kind='canonical_resource' AND c.invocation_id=p.original_invocation_id)))
 THEN RAISE EXCEPTION 'Private Task asset lacks its exact signed Device command and admitted custody'; END IF;
 RETURN NEW;
END $$;


--
-- Name: erase_work_item_publication_metadata(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.erase_work_item_publication_metadata() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.execution_coverage_hash IS NOT NULL AND OLD.execution_coverage_hash IS NULL THEN
   UPDATE artifact.dialogue_publication_sources p SET state=3,title=NULL
     WHERE p.tenant_id=NEW.tenant_id AND p.state IN(1,2) AND EXISTS(
       SELECT 1 FROM tool.tool_invocations i WHERE i.tenant_id=p.tenant_id
        AND i.invocation_id=p.title_source_invocation_id AND i.run_id=ANY(NEW.execution_run_ids));
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_content_ref_shared_blob(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.guard_content_ref_shared_blob() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.blob_content_id IS NOT NULL
       AND NEW.blob_content_id IS DISTINCT FROM OLD.blob_content_id THEN
        RAISE EXCEPTION 'content_refs.blob_content_id is immutable once shared'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_device_version(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.guard_device_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND NEW IS DISTINCT FROM OLD) THEN
  RAISE EXCEPTION 'Device Artifact version proof is immutable';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM agent.device_admissions admitted
  JOIN agent.device_grant_heads h ON h.intent_id=admitted.intent_id
  JOIN agent.device_grant_versions v ON v.intent_id=h.intent_id AND v.revision=h.admitted_revision
  JOIN agent.dialogue_tool_publication_groups published ON published.invocation_id=NEW.publication_invocation_id
   AND published.tenant_id=admitted.tenant_id AND published.source_intent_id=admitted.intent_id
   AND published.source_run_id=admitted.run_id AND published.execution_home='device'
   AND published.device_snapshot_hash=admitted.admitted_snapshot_hash
   AND published.device_grant_proof_hash=v.signed_grant_hash
   AND published.device_export_commitment=NEW.export_commitment
  JOIN artifact.artifacts a ON a.artifact_id=NEW.artifact_id AND a.tenant_id=admitted.tenant_id
   AND a.conversation_id=admitted.conversation_id AND a.origin=1 AND a.kind IN (4,6)
   AND a.activity_id=NEW.source_activity_id AND a.created_by_run_id=NEW.source_created_by_run_id
   AND a.created_at_ms=NEW.source_created_at_ms
  WHERE admitted.tenant_id=NEW.tenant_id AND admitted.owner_id=NEW.owner_id AND admitted.agent_id=NEW.agent_id
   AND admitted.dialogue_id=NEW.dialogue_id AND admitted.intent_id=NEW.intent_id
   AND admitted.conversation_id=NEW.conversation_id AND admitted.run_id=NEW.run_id
   AND admitted.device_id=NEW.device_id AND admitted.installation_id=NEW.installation_id
   AND admitted.admitted_at_ms IS NOT NULL) THEN
  RAISE EXCEPTION 'Device Artifact lacks original admitted publication custody' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_dialogue_publication_source(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.guard_dialogue_publication_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Publication source identity is immutable' USING ERRCODE='23514'; END IF;
 IF (to_jsonb(NEW)-'state'-'title') IS DISTINCT FROM (to_jsonb(OLD)-'state'-'title')
    OR (NEW.title IS DISTINCT FROM OLD.title AND NEW.title IS NOT NULL)
    OR (OLD.state IN(3,4) AND NEW.state<>OLD.state)
    OR (OLD.state=2 AND NEW.state NOT IN(2,3))
    OR (NEW.state=4 AND OLD.state=1 AND OLD.prepare_expires_at_ms>artifact.dialogue_publication_now_ms())
    OR (NEW.state=2 AND OLD.state=1 AND OLD.prepare_expires_at_ms<=artifact.dialogue_publication_now_ms()) THEN
   RAISE EXCEPTION 'Publication source cannot be rewritten or resurrected' USING ERRCODE='23514';
 END IF;
 IF NEW.state IN(3,4) THEN NEW.title:=NULL; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_dialogue_publication_source_content(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.guard_dialogue_publication_source_content() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE source artifact.dialogue_publication_sources%ROWTYPE;
BEGIN
 IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'Source content identity is immutable' USING ERRCODE='23514'; END IF;
 IF TG_OP='DELETE' THEN
   IF EXISTS(SELECT 1 FROM artifact.dialogue_publication_sources WHERE binding_id=OLD.binding_id AND state IN(1,2)) THEN
     RAISE EXCEPTION 'Active source retention cannot be removed' USING ERRCODE='23514';
   END IF;
   RETURN OLD;
 END IF;
 SELECT * INTO STRICT source FROM artifact.dialogue_publication_sources WHERE binding_id=NEW.binding_id FOR UPDATE;
 IF source.state<>1 OR NOT EXISTS(SELECT 1 FROM artifact.content_refs c WHERE c.content_id=NEW.content_id
     AND c.tenant_id=source.tenant_id AND c.state=2 AND c.media_type=NEW.content_media_type
     AND c.byte_length=NEW.content_byte_length AND c.content_hash=NEW.content_hash)
    OR NOT ((NEW.content_index=0 AND EXISTS(SELECT 1 FROM artifact.artifact_versions v WHERE v.artifact_version_id=source.artifact_version_id AND v.content_id=NEW.content_id AND v.content_hash=NEW.content_hash))
     OR (NEW.content_index>0 AND EXISTS(SELECT 1 FROM artifact.artifact_version_dependencies d WHERE d.artifact_version_id=source.artifact_version_id AND d.content_id=NEW.content_id AND d.content_media_type=NEW.content_media_type AND d.content_byte_length=NEW.content_byte_length AND d.content_hash=NEW.content_hash))) THEN
   RAISE EXCEPTION 'Source content is not part of exact prepared artifact version' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_source_attachment_import(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.guard_source_attachment_import() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE original tool.tool_invocations%ROWTYPE; expected_job UUID; erased BOOLEAN;
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION 'Source attachment provenance cannot be deleted' USING ERRCODE='23514';
    END IF;
    SELECT * INTO STRICT original FROM tool.tool_invocations WHERE invocation_id=NEW.invocation_id;
    IF original.tenant_id<>NEW.tenant_id OR original.run_id<>NEW.run_id
        OR original.tool_ref<>'sources.attachments.import@1' THEN
        RAISE EXCEPTION 'Source attachment must belong to its original Tool' USING ERRCODE='23514';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM artifact.invocation_content_outputs o
        JOIN artifact.invocation_content_outputs m ON m.invocation_id=o.invocation_id
        WHERE o.invocation_id=NEW.invocation_id AND o.content_id=NEW.output_content_id
            AND m.content_id=NEW.metadata_content_id AND m.ready_content_id=m.content_id
            AND m.media_type='application/vnd.musteragent.dialogue-source-attachment+protobuf'
            AND m.byte_length BETWEEN 1 AND 16384 AND o.byte_length BETWEEN 0 AND 8388608) THEN
        RAISE EXCEPTION 'Source attachment requires exact reserved outputs' USING ERRCODE='23514';
    END IF;
    expected_job:=privacy_erasure.work_item_execution_job(NEW.tenant_id,original.conversation_id);
    SELECT EXISTS(SELECT 1 FROM agent.dialogue_sessions s
        JOIN collaboration.work_items t ON t.work_item_id=s.work_item_id AND t.tenant_id=s.tenant_id AND t.owner_id=s.owner_id
        WHERE s.tenant_id=NEW.tenant_id AND s.conversation_id=original.conversation_id AND t.erasure_job_id IS NOT NULL)
        INTO erased;
    IF TG_OP='INSERT' AND (NEW.erasure_job_id IS NOT NULL OR erased OR original.erasure_job_id IS NOT NULL) THEN
        RAISE EXCEPTION 'Source attachment cannot enter an erased execution' USING ERRCODE='23514';
    END IF;
    IF TG_OP='UPDATE' THEN
        IF OLD.erasure_job_id IS NOT NULL AND NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION 'Erased Source provenance is immutable' USING ERRCODE='23514';
        END IF;
        IF (to_jsonb(NEW)-ARRAY['artifact_version_id','erasure_job_id']) IS DISTINCT FROM
           (to_jsonb(OLD)-ARRAY['artifact_version_id','erasure_job_id']) THEN
            RAISE EXCEPTION 'Source attachment selection is immutable' USING ERRCODE='23514';
        END IF;
        IF NEW.erasure_job_id IS NOT NULL THEN
            IF NEW.erasure_job_id IS DISTINCT FROM expected_job OR NEW.artifact_version_id IS DISTINCT FROM OLD.artifact_version_id THEN
                RAISE EXCEPTION 'Source provenance erasure requires original Task coverage' USING ERRCODE='23514';
            END IF;
        ELSIF erased OR original.erasure_job_id IS NOT NULL THEN
            RAISE EXCEPTION 'Source publication cannot follow erasure' USING ERRCODE='23514';
        END IF;
        IF OLD.artifact_version_id IS NOT NULL AND NEW.artifact_version_id IS DISTINCT FROM OLD.artifact_version_id THEN
            RAISE EXCEPTION 'Source attachment publication is immutable' USING ERRCODE='23514';
        END IF;
    END IF;
    IF NEW.artifact_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM artifact.artifact_versions v JOIN artifact.artifacts a ON a.artifact_id=v.artifact_id
        WHERE v.artifact_version_id=NEW.artifact_version_id AND a.tenant_id=NEW.tenant_id
          AND v.source_invocation_id=NEW.invocation_id AND v.content_id=NEW.output_content_id) THEN
        RAISE EXCEPTION 'Source publication must retain its exact output and invocation' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: guard_work_item_asset_return(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.guard_work_item_asset_return() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'Verified Task asset return is immutable'; END IF;
 IF NEW.publication_invocation_id IS NOT NULL AND EXISTS(SELECT 1 FROM artifact.requester_file_publications WHERE entry_id=NEW.entry_id) THEN RETURN NEW; END IF;
 IF NOT EXISTS(SELECT 1 FROM agent.agent_dialogue_entries e
   JOIN agent.agent_dialogues d USING(dialogue_id,tenant_id,owner_id)
   JOIN agent.dialogue_publications p ON p.entry_id=e.entry_id AND p.source_task_result_item_id=NEW.item_id AND p.source_kind='task_result_owner'
   JOIN collaboration.authorized_result_deliveries delivery ON delivery.result_id=NEW.result_id AND delivery.publication_run_id=p.source_run_id
     AND delivery.report_run_id IS NOT DISTINCT FROM NEW.report_run_id AND delivery.verification_invocation_id IS NOT DISTINCT FROM NEW.verify_invocation_id
     AND delivery.accepted_state_revision=NEW.accepted_state_revision AND delivery.work_item_id=NEW.task_id
     AND delivery.tenant_id=NEW.tenant_id AND delivery.owner_id=NEW.owner_id AND delivery.source_dialogue_id=NEW.dialogue_id
     AND delivery.requesting_agent_id=NEW.requester_id
   JOIN collaboration.work_item_result_items item ON item.item_id=NEW.item_id AND item.result_id=NEW.result_id AND item.artifact_id=NEW.artifact_id AND item.artifact_version_id=NEW.version_id AND item.asset_authority_sha256=NEW.authority_sha256
   JOIN collaboration.work_item_revisions v ON v.work_item_id=NEW.task_id AND v.state_revision=NEW.accepted_state_revision AND v.status='completed'
   JOIN collaboration.work_item_execution_reservations x ON x.work_item_id=v.work_item_id AND x.run_id=NEW.producer_run_id
     AND x.tenant_id=e.tenant_id AND x.owner_id=e.owner_id AND x.requesting_agent_id=d.agent_id AND x.executing_agent_id=NEW.producer_id
     AND (x.goal_revision,x.control_revision,x.assignment_epoch)=(v.goal_revision,v.control_revision,v.assignment_epoch)
   WHERE e.entry_id=NEW.entry_id AND e.tenant_id=NEW.tenant_id AND e.owner_id=NEW.owner_id AND d.agent_id=NEW.requester_id
     AND e.dialogue_id=NEW.dialogue_id AND (NEW.verify_invocation_id IS NULL OR EXISTS (SELECT 1 FROM tool.tool_invocations i WHERE i.invocation_id=NEW.verify_invocation_id AND i.erasure_job_id IS NULL))
     AND e.kind='artifact' AND e.artifact_id=NEW.artifact_id AND e.artifact_version_id=NEW.version_id)
 THEN RAISE EXCEPTION 'Verified Task asset return is not bound to its accepted public entry'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_result_asset_candidate(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.guard_work_item_result_asset_candidate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
   IF OLD.erasure_job_id IS NULL AND NEW.erasure_job_id IS NOT NULL AND NEW.capsule IS NULL AND NEW.root_content_id IS NULL
     AND (to_jsonb(NEW)-ARRAY['erasure_job_id','capsule','root_content_id'])=(to_jsonb(OLD)-ARRAY['erasure_job_id','capsule','root_content_id'])
     AND EXISTS(SELECT 1 FROM collaboration.work_items t WHERE t.work_item_id=OLD.task_id AND t.tenant_id=OLD.tenant_id AND t.erasure_job_id=NEW.erasure_job_id)
   THEN RETURN NEW; END IF;
   RAISE EXCEPTION 'Task asset candidate is immutable outside original erasure';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM collaboration.work_item_execution_reservations x
    JOIN collaboration.work_items t ON t.work_item_id=x.work_item_id AND t.erasure_job_id IS NULL
    JOIN collaboration.work_item_revisions r ON r.work_item_id=t.work_item_id AND r.state_revision=t.state_revision
      AND (r.goal_revision,r.control_revision,r.assignment_epoch)=(x.goal_revision,x.control_revision,x.assignment_epoch)
    WHERE x.run_id=NEW.producer_run_id AND x.result_protocol='verified_result_v1' AND x.tenant_id=NEW.tenant_id
      AND (x.work_item_id,x.goal_revision,x.control_revision,x.assignment_epoch)=(NEW.task_id,NEW.goal_revision,NEW.control_revision,NEW.assignment_epoch))
 THEN RAISE EXCEPTION 'Task asset has no matching current reservation'; END IF;
 RETURN NEW;
END $$;


--
-- Name: invalidate_content_cache(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.invalidate_content_cache() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE artifact.content_cache_revision SET revision = revision + 1 WHERE singleton;
    PERFORM pg_notify('musteragent_content_invalidated', '');
    RETURN NULL;
END;
$$;


--
-- Name: invalidate_dialogue_publication_source(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.invalidate_dialogue_publication_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_TABLE_SCHEMA='artifact' AND TG_TABLE_NAME='content_refs' THEN
   IF NEW.state<>2 THEN
     UPDATE artifact.dialogue_publication_sources SET state=3,title=NULL WHERE state IN(1,2)
       AND binding_id IN(SELECT binding_id FROM artifact.dialogue_publication_source_contents WHERE content_id=NEW.content_id);
   END IF;
 ELSIF TG_TABLE_SCHEMA='artifact' AND TG_TABLE_NAME='artifact_versions' THEN
   IF NEW.work_item_erasure_job_id IS NOT NULL THEN
     UPDATE artifact.dialogue_publication_sources SET state=3,title=NULL WHERE state IN(1,2) AND artifact_version_id=NEW.artifact_version_id;
   END IF;
 ELSIF TG_TABLE_SCHEMA='artifact' AND TG_TABLE_NAME='artifacts' THEN
   IF NEW.lifecycle NOT IN(1,2) THEN
     UPDATE artifact.dialogue_publication_sources SET state=3,title=NULL WHERE state IN(1,2) AND artifact_id=NEW.artifact_id;
   END IF;
 ELSIF TG_TABLE_SCHEMA='agent' AND TG_TABLE_NAME='owned_agents' THEN
   IF NEW.status='deleted' THEN
     UPDATE artifact.dialogue_publication_sources SET state=3,title=NULL WHERE state IN(1,2) AND agent_id=NEW.agent_id;
   END IF;
 ELSIF TG_TABLE_SCHEMA='resource' AND TG_TABLE_NAME='nodes' THEN
   IF NEW.lifecycle<>1 AND NEW.file_artifact_id IS NOT NULL AND NEW.scope_kind=4 THEN
     UPDATE artifact.dialogue_publication_sources SET state=3,title=NULL WHERE state IN(1,2)
       AND tenant_id=NEW.tenant_id AND agent_id=NEW.scope_id AND artifact_id=NEW.file_artifact_id;
   END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: device_resource_owned(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.device_resource_owned(p_tenant uuid, p_owner uuid, p_agent uuid, p_artifact uuid, p_version uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM artifact.device_resource_versions p JOIN resource.device_commands c USING(invocation_id)
 WHERE c.tenant_id=p_tenant AND c.owner_id=p_owner AND c.agent_id=p_agent AND p.artifact_id=p_artifact
 AND (p_version IS NULL OR p.artifact_version_id=p_version))
$$;


--
-- Name: device_version_owned(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.device_version_owned(p_tenant uuid, p_owner uuid, p_agent uuid, p_artifact uuid, p_version uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM artifact.device_versions proof
  JOIN agent.device_admissions admitted ON admitted.tenant_id=proof.tenant_id
   AND admitted.owner_id=proof.owner_id AND admitted.agent_id=proof.agent_id AND admitted.dialogue_id=proof.dialogue_id
   AND admitted.intent_id=proof.intent_id AND admitted.conversation_id=proof.conversation_id AND admitted.run_id=proof.run_id
   AND admitted.device_id=proof.device_id AND admitted.installation_id=proof.installation_id AND admitted.admitted_at_ms IS NOT NULL
  JOIN agent.device_grant_heads h ON h.intent_id=admitted.intent_id
  JOIN agent.device_grant_versions v ON v.intent_id=h.intent_id AND v.revision=h.admitted_revision
  JOIN agent.dialogue_tool_publication_groups published ON published.invocation_id=proof.publication_invocation_id
   AND published.tenant_id=admitted.tenant_id AND published.source_intent_id=admitted.intent_id
   AND published.source_run_id=admitted.run_id AND published.execution_home='device'
   AND published.device_snapshot_hash=admitted.admitted_snapshot_hash AND published.device_grant_proof_hash=v.signed_grant_hash
   AND published.device_export_commitment=proof.export_commitment
  WHERE proof.tenant_id=p_tenant AND proof.owner_id=p_owner AND proof.agent_id=p_agent
   AND proof.artifact_id=p_artifact AND (p_version IS NULL OR proof.artifact_version_id=p_version))
$$;


--
-- Name: dialogue_publication_now_ms(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.dialogue_publication_now_ms() RETURNS bigint
    LANGUAGE sql
    AS $$
 SELECT (extract(epoch FROM clock_timestamp())*1000)::bigint
$$;


--
-- Name: protect_source_identity(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.protect_source_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (NEW.tenant_id, NEW.conversation_id, NEW.workspace_id)
       IS DISTINCT FROM (OLD.tenant_id, OLD.conversation_id, OLD.workspace_id) THEN
        RAISE EXCEPTION 'Artifact source identity is immutable';
    END IF;
    RETURN NEW;
END
$$;


