--
-- Name: reject_erased_version_projection(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.reject_erased_version_projection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE erased UUID;
BEGIN
 SELECT work_item_erasure_job_id INTO erased FROM artifact.artifact_versions
  WHERE artifact_version_id=NEW.artifact_version_id FOR SHARE;
 IF erased IS NOT NULL THEN RAISE EXCEPTION 'erased version projection cannot be recreated' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


