    AS $$ BEGIN
    RAISE EXCEPTION 'media generation results are append-only';
END $$;


--
-- Name: reject_note_authoring_history_mutation(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.reject_note_authoring_history_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'Note authoring segment, version block and command history are immutable';
END;
$$;


--
-- Name: release_dialogue_publication_source_pins(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.release_dialogue_publication_source_pins() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.state IN(3,4) THEN
   DELETE FROM agent.dialogue_content_references WHERE tenant_id=NEW.tenant_id AND owner_id=NEW.owner_id
     AND agent_id=NEW.agent_id AND reference_kind='artifact_publication_source' AND reference_id=NEW.binding_id;
   DELETE FROM artifact.dialogue_publication_source_contents WHERE binding_id=NEW.binding_id;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: validate_file_restore_source(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.validate_file_restore_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.restored_from_version_id IS DISTINCT FROM OLD.restored_from_version_id THEN
   RAISE EXCEPTION 'File restore provenance is immutable';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.restored_from_version_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM artifact.artifact_versions source
  JOIN artifact.artifacts a ON a.artifact_id=source.artifact_id
  JOIN artifact.content_refs original ON original.tenant_id=a.tenant_id AND original.content_id=source.content_id
  JOIN artifact.content_refs replacement ON replacement.tenant_id=a.tenant_id AND replacement.content_id=NEW.content_id
  WHERE source.artifact_version_id=NEW.restored_from_version_id AND source.artifact_id=NEW.artifact_id
   AND source.version<NEW.version AND source.work_item_erasure_job_id IS NULL AND original.state=2 AND replacement.state=2
   AND source.content_hash=NEW.content_hash AND original.media_type=replacement.media_type
   AND original.byte_length=replacement.byte_length
 ) THEN RAISE EXCEPTION 'File restore source is not the exact available historical version'; END IF;
 RETURN NEW;
END $$;


--
-- Name: validate_dialogue_version_author(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.validate_dialogue_version_author() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE source_agent UUID; source_tenant UUID; source_owner UUID;
BEGIN
 SELECT origin.agent_id,origin.tenant_id,origin.owner_id INTO source_agent,source_tenant,source_owner FROM (
  SELECT s.agent_id,s.tenant_id,s.owner_id FROM artifact.artifacts a JOIN agent.dialogue_sessions s ON s.tenant_id=a.tenant_id AND s.conversation_id=a.conversation_id WHERE a.artifact_id=NEW.artifact_id
  UNION SELECT d.agent_id,d.tenant_id,d.owner_id FROM artifact.artifacts a JOIN agent.device_admissions d ON d.tenant_id=a.tenant_id AND d.conversation_id=a.conversation_id WHERE a.artifact_id=NEW.artifact_id
  UNION SELECT x.executing_agent_id,x.tenant_id,x.owner_id FROM artifact.artifacts a
   JOIN collaboration.work_item_device_custody d ON d.conversation_id=a.conversation_id
   JOIN collaboration.work_item_execution_reservations x ON x.run_id=d.run_id AND x.tenant_id=a.tenant_id
   WHERE a.artifact_id=NEW.artifact_id AND d.admitted_snapshot_hash IS NOT NULL
 ) origin;
 IF NOT FOUND THEN RETURN NEW; END IF;
 IF NEW.committed_by_principal_id IS NOT NULL THEN
  IF NEW.source_invocation_id IS NOT NULL OR NOT resource.agent_edit_version_authorized(source_tenant,NEW.artifact_id,NEW.committed_by_principal_id,NEW.version,NEW.content_id,NEW.content_hash) THEN
   RAISE EXCEPTION 'Agent file account version lacks original edit proof'; END IF;
 ELSIF NEW.source_invocation_id IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM tool.tool_invocations i JOIN runtime.runs r ON r.tenant_id=i.tenant_id AND r.run_id=i.run_id
   JOIN conversation.participants p ON p.tenant_id=r.tenant_id AND p.conversation_id=r.conversation_id AND p.participant_id=r.executor_participant_id
   JOIN agent.dialogue_sessions s ON s.tenant_id=r.tenant_id AND s.conversation_id=r.conversation_id
   WHERE i.invocation_id=NEW.source_invocation_id AND i.tenant_id=source_tenant AND s.agent_id=source_agent
    AND s.owner_id=source_owner AND p.participant_id=NEW.committed_by AND p.kind=2 AND p.agent_ref=source_agent) THEN
   RAISE EXCEPTION 'Agent file Cloud version is outside its Agent'; END IF;
 ELSE
  IF NOT artifact.device_version_owned(source_tenant,source_owner,source_agent,NEW.artifact_id,NEW.artifact_version_id)
   AND NOT artifact.device_resource_owned(source_tenant,source_owner,source_agent,NEW.artifact_id,NEW.artifact_version_id)
   AND NOT EXISTS(SELECT 1 FROM artifact.work_item_result_native_origins o JOIN artifact.work_item_result_asset_candidates t USING(version_id)
     JOIN artifact.content_refs c ON c.tenant_id=t.tenant_id AND c.content_id=NEW.content_id AND c.content_hash=NEW.content_hash AND c.state=2
     WHERE t.version_id=NEW.artifact_version_id AND t.artifact_id=NEW.artifact_id AND o.source_participant_id=NEW.committed_by AND t.root_content_id=NEW.content_id AND t.candidate_version=NEW.version
     AND artifact.verified_task_native_version_owned(source_tenant,source_owner,source_agent,NEW.artifact_id,NEW.artifact_version_id)) THEN
   -- Keep the original author contract for historical Cloud-only versions
   -- that predate source invocation attribution. New Device file origins
   -- cannot acquire this legacy exception.
   IF NOT EXISTS(SELECT 1 FROM artifact.artifacts a JOIN agent.dialogue_sessions origin
    ON origin.tenant_id=a.tenant_id AND origin.conversation_id=a.conversation_id
    JOIN conversation.participants p ON p.tenant_id=origin.tenant_id AND p.participant_id=NEW.committed_by
    JOIN agent.dialogue_sessions author ON author.tenant_id=p.tenant_id AND author.conversation_id=p.conversation_id
    WHERE a.artifact_id=NEW.artifact_id AND origin.agent_id=source_agent AND author.agent_id=source_agent
     AND author.owner_id=source_owner) THEN
    RAISE EXCEPTION 'Agent file Device version lacks exact canonical producer'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: validate_workspace_version_author(); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.validate_workspace_version_author() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    source artifact.artifacts%ROWTYPE;
BEGIN
    SELECT * INTO STRICT source FROM artifact.artifacts WHERE artifact_id = NEW.artifact_id;
    IF NEW.committed_by_principal_id IS NOT NULL THEN
        IF source.kind <> 6 OR NOT (
            -- Direct Workspace creation precedes insertion of its Resource node.
            (source.workspace_id IS NOT NULL AND EXISTS (
                SELECT 1 FROM resource.workspace_roots
                 WHERE tenant_id = source.tenant_id AND workspace_id = source.workspace_id
                   AND owner_principal_id = NEW.committed_by_principal_id
            )) OR
            -- A conversation-sourced File must already have a live placement in
            -- that Conversation's current project, owned by the actual author.
            (source.conversation_id IS NOT NULL AND EXISTS (
                SELECT 1 FROM conversation.conversations AS conversation
                JOIN resource.nodes AS node
                  ON node.tenant_id = conversation.tenant_id
                 AND node.scope_kind = 1 AND node.scope_id = conversation.workspace_id
                 AND node.file_artifact_id = source.artifact_id
                 AND node.kind = 2 AND node.lifecycle = 1
                JOIN resource.workspace_roots AS root
                  ON root.tenant_id = conversation.tenant_id
                 AND root.workspace_id = conversation.workspace_id
                JOIN resource.workspace_authority AS authority
                  ON authority.tenant_id = root.tenant_id AND authority.workspace_id = root.workspace_id
                 WHERE conversation.tenant_id = source.tenant_id
                   AND conversation.conversation_id = source.conversation_id
                   AND conversation.lifecycle IN (1, 2)
                   AND root.owner_principal_id = NEW.committed_by_principal_id
                   AND authority.status = 2
            ))
            OR (NEW.source_invocation_id IS NULL AND resource.agent_edit_version_authorized(
                source.tenant_id,source.artifact_id,NEW.committed_by_principal_id,
                NEW.version,NEW.content_id,NEW.content_hash))
        ) THEN
            RAISE EXCEPTION 'Project File author does not match current file authority'
                USING ERRCODE = '23514', CONSTRAINT = 'workspace_file_version_author';
        END IF;
    ELSIF source.workspace_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM conversation.participants AS participant
        JOIN conversation.conversations AS conversation
          ON conversation.conversation_id = participant.conversation_id
         AND conversation.tenant_id = participant.tenant_id
        WHERE participant.participant_id = NEW.committed_by
          AND conversation.tenant_id = source.tenant_id
          AND conversation.workspace_id = source.workspace_id
    ) THEN
        RAISE EXCEPTION 'Workspace File participant is outside its Workspace'
            USING ERRCODE = '23514', CONSTRAINT = 'workspace_file_version_author';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: verified_task_native_version_owned(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: artifact; Owner: -
--

CREATE FUNCTION artifact.verified_task_native_version_owned(tenant uuid, owner uuid, producer uuid, artifact uuid, version uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
 SELECT EXISTS(SELECT 1 FROM artifact.work_item_result_asset_returns ret

  JOIN collaboration.work_item_result_items item ON item.item_id=ret.item_id AND item.result_id=ret.result_id AND item.artifact_id=ret.artifact_id AND item.artifact_version_id=ret.version_id AND item.asset_authority_sha256=ret.authority_sha256
  JOIN artifact.work_item_result_asset_candidates cap ON cap.version_id=ret.version_id AND cap.artifact_id=ret.artifact_id AND cap.task_id=ret.task_id AND cap.producer_run_id=ret.producer_run_id AND cap.capsule_sha256=ret.authority_sha256 AND cap.producer_home='device'
  JOIN artifact.work_item_result_native_origins origin ON origin.version_id=cap.version_id
  JOIN resource.device_commands cmd ON cmd.invocation_id=origin.transport_invocation_id AND cmd.command_commitment=origin.command_sha256 AND cmd.run_id=ret.producer_run_id AND cmd.work_item_run_id=ret.producer_run_id AND cmd.tenant_id=ret.tenant_id AND cmd.agent_id=ret.producer_id AND cmd.owner_id=ret.owner_id AND cmd.outcome='succeeded'
  JOIN collaboration.work_item_device_admitted_custody custody ON custody.run_id=cmd.run_id AND custody.runtime_snapshot_id=cap.producer_snapshot_id AND custody.work_item_id=ret.task_id AND custody.source_digest=origin.source_sha256 AND custody.admitted_snapshot_hash=origin.snapshot_sha256 AND custody.signed_grant_hash=origin.grant_sha256
  WHERE (EXISTS (SELECT 1 FROM collaboration.work_item_result_deliveries d WHERE d.result_id=ret.result_id AND d.publication_run_id=COALESCE(ret.report_run_id,ret.producer_run_id) AND d.verification_invocation_id IS NOT DISTINCT FROM ret.verify_invocation_id) OR EXISTS (SELECT 1 FROM artifact.requester_file_publications p WHERE p.entry_id=ret.entry_id))
    AND ret.tenant_id=$1 AND ret.owner_id=$2 AND ret.producer_id=$3 AND ret.artifact_id=$4 AND ret.version_id=$5)
$_$;


