$$;


--
-- Name: guard_cloud_work_item_target(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.guard_cloud_work_item_target() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.subject_kind='work_item' AND EXISTS(SELECT 1 FROM collaboration.work_item_device_targets d
 WHERE d.work_item_id=NEW.work_item_id AND d.goal_revision=NEW.work_item_goal_revision
 AND d.control_revision=NEW.work_item_control_revision AND d.assignment_epoch=NEW.work_item_assignment_epoch)
 THEN RAISE EXCEPTION 'Device Task cannot acquire a Cloud session'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_native_task_source(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.guard_native_task_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Native Task source custody is immutable' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM resource.device_commands c
   JOIN agent.device_admissions d ON d.intent_id=c.intent_id AND d.run_id=c.run_id AND d.tenant_id=c.tenant_id AND d.owner_id=c.owner_id
   JOIN agent.device_grant_heads h ON h.intent_id=d.intent_id
   JOIN agent.device_grants_for_receipts v ON v.intent_id=h.intent_id AND v.revision=h.admitted_revision
   WHERE c.invocation_id=NEW.invocation_id AND c.admission_kind='intent' AND c.tool_key IN ('tasks.start@3','tasks.control@1','tasks.amend@2','tasks.handoff@1')
     AND d.agent_id=c.agent_id AND d.dialogue_id=c.dialogue_id AND d.device_id=c.device_id AND d.installation_id=c.installation_id
     AND d.admitted_at_ms IS NOT NULL AND d.source_digest=NEW.source_digest AND d.admitted_snapshot_hash=NEW.snapshot_hash AND v.signed_grant_hash=NEW.grant_proof_hash)
 THEN RAISE EXCEPTION 'Native Task requires exact admitted source custody' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_device_custody(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.guard_work_item_device_custody() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Task Device custody is retained'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.current_grant_revision<>1 OR NEW.admitted_grant_revision IS NOT NULL OR NEW.admitted_at_ms IS NOT NULL
   OR NOT EXISTS(SELECT 1 FROM collaboration.work_item_execution_reservations x
    WHERE x.work_item_id=NEW.work_item_id AND x.goal_revision=NEW.goal_revision AND x.control_revision=NEW.control_revision
    AND x.assignment_epoch=NEW.assignment_epoch AND x.run_id=NEW.run_id AND x.conversation_id=NEW.conversation_id)
  THEN RAISE EXCEPTION 'Task Device custody must start at exact original reservation'; END IF;
 ELSIF NEW IS DISTINCT FROM OLD THEN
  IF (to_jsonb(NEW)-'admitted_snapshot_hash'-'admitted_at_ms'-'current_grant_revision'-'admitted_grant_revision') IS DISTINCT FROM
     (to_jsonb(OLD)-'admitted_snapshot_hash'-'admitted_at_ms'-'current_grant_revision'-'admitted_grant_revision')
     OR OLD.admitted_grant_revision IS NOT NULL
     OR NOT (
       (NEW.current_grant_revision=OLD.current_grant_revision+1 AND NEW.admitted_grant_revision IS NULL
        AND NEW.admitted_snapshot_hash IS NULL AND NEW.admitted_at_ms IS NULL)
       OR (NEW.current_grant_revision=OLD.current_grant_revision AND NEW.admitted_grant_revision IS NOT NULL
        AND NEW.admitted_snapshot_hash IS NOT NULL AND NEW.admitted_at_ms IS NOT NULL))
  THEN RAISE EXCEPTION 'Task Device source, first proof and actual admission are immutable'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_device_grant_version(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.guard_work_item_device_grant_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE custody collaboration.work_item_device_custody; previous collaboration.work_item_device_grant_versions;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Task grant evidence is immutable'; END IF;
 SELECT * INTO STRICT custody FROM collaboration.work_item_device_custody WHERE run_id=NEW.run_id FOR UPDATE;
 IF NEW.source_digest<>custody.source_digest THEN RAISE EXCEPTION 'Task grant source differs'; END IF;
 IF NEW.revision=1 THEN
  IF NEW.signed_grant_hash<>custody.signed_grant_hash OR NEW.signed_grant_proof<>custody.signed_grant_proof
  THEN RAISE EXCEPTION 'Task first grant differs'; END IF;
 ELSE
  SELECT * INTO STRICT previous FROM collaboration.work_item_device_grant_versions
   WHERE run_id=NEW.run_id AND revision=custody.current_grant_revision;
  IF custody.admitted_at_ms IS NOT NULL OR NEW.revision<>custody.current_grant_revision+1
   OR NEW.previous_grant_hash<>previous.signed_grant_hash
  THEN RAISE EXCEPTION 'Task successor does not own current custody'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_device_placement(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.guard_work_item_device_placement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND OLD.device_placement_captured AND
  (NOT NEW.device_placement_captured OR NEW.device_workspace_id IS DISTINCT FROM OLD.device_workspace_id)
 THEN RAISE EXCEPTION 'Task physical placement is immutable'; END IF;
 IF NEW.device_placement_captured AND NOT EXISTS (
  SELECT 1 FROM collaboration.work_item_device_targets t WHERE t.work_item_id=NEW.work_item_id
   AND t.goal_revision=NEW.goal_revision AND t.control_revision=NEW.control_revision
   AND t.assignment_epoch=NEW.assignment_epoch)
 THEN RAISE EXCEPTION 'Physical placement requires the original Device target'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_device_stop(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.guard_work_item_device_stop() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Task local admission fence is immutable'; END IF;
 IF NOT EXISTS(SELECT 1 FROM collaboration.work_item_device_custody d WHERE d.run_id=NEW.run_id AND d.admitted_snapshot_hash IS NULL)
 THEN RAISE EXCEPTION 'Admitted Task requires actual original terminal evidence'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_device_stopped_admission(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.guard_work_item_device_stopped_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.admitted_snapshot_hash IS NOT NULL AND EXISTS(SELECT 1 FROM collaboration.work_item_device_stops s WHERE s.run_id=NEW.run_id)
 THEN RAISE EXCEPTION 'Fenced Task cannot later become admitted'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_device_target(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.guard_work_item_device_target() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Task Device destination is immutable'; END IF;
 IF EXISTS(SELECT 1 FROM collaboration.work_item_execution_reservations x
 JOIN runtime.runs run ON run.run_id=x.run_id WHERE x.work_item_id=NEW.work_item_id
 AND x.goal_revision=NEW.goal_revision AND x.control_revision=NEW.control_revision AND x.assignment_epoch=NEW.assignment_epoch)
 THEN RAISE EXCEPTION 'Task already has a Cloud admission'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_device_terminal(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.guard_work_item_device_terminal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Task Device terminal evidence is immutable'; END IF;
 IF NOT EXISTS(SELECT 1 FROM collaboration.work_item_device_custody d WHERE d.run_id=NEW.run_id AND d.admitted_snapshot_hash IS NOT NULL)
 THEN RAISE EXCEPTION 'Task terminal requires exact acknowledged original local admission'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_followup_immutable(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.guard_work_item_followup_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN RAISE EXCEPTION 'accepted Task followup identity is immutable'; END $$;


--
-- Name: guard_work_item_report(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.guard_work_item_report() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Task report evidence is immutable'; END IF;
 IF NEW.producer_home='device' THEN
  IF NOT EXISTS(SELECT 1 FROM collaboration.work_item_execution_reservations x
   JOIN collaboration.work_item_device_custody d ON d.run_id=x.run_id
   JOIN collaboration.work_item_device_terminals terminal ON terminal.run_id=d.run_id
   WHERE x.work_item_id=NEW.work_item_id AND x.goal_revision=NEW.goal_revision AND x.control_revision=NEW.control_revision
   AND x.assignment_epoch=NEW.assignment_epoch AND x.owner_id=NEW.owner_id AND x.tenant_id=NEW.tenant_id
   AND x.executing_agent_id=NEW.producing_agent_id AND x.requesting_agent_id=NEW.requesting_agent_id
   AND x.run_id=NEW.producing_run_id AND d.runtime_snapshot_id=NEW.producing_snapshot_id AND d.admitted_snapshot_hash IS NOT NULL AND terminal.outcome=NEW.outcome
   AND terminal.publication_commitment=NEW.publication_sha256)
  THEN RAISE EXCEPTION 'Task report requires exact settled Device admission and publication cut'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM collaboration.work_item_execution_reservations x
   JOIN agent.dialogue_sessions s ON s.conversation_id=x.conversation_id AND s.subject_kind='work_item'
   JOIN runtime.runs r ON r.tenant_id=x.tenant_id AND r.run_id=x.run_id AND r.conversation_id=x.conversation_id
   JOIN capability.runtime_snapshots snap ON snap.tenant_id=r.tenant_id AND snap.run_id=r.run_id
   WHERE x.work_item_id=NEW.work_item_id AND x.goal_revision=NEW.goal_revision AND x.control_revision=NEW.control_revision
   AND x.assignment_epoch=NEW.assignment_epoch AND x.owner_id=NEW.owner_id AND x.tenant_id=NEW.tenant_id
   AND x.executing_agent_id=NEW.producing_agent_id AND x.requesting_agent_id=NEW.requesting_agent_id
   AND r.run_id=NEW.producing_run_id AND snap.runtime_snapshot_id=NEW.producing_snapshot_id
   AND r.status=CASE NEW.outcome WHEN 'completed' THEN 5 WHEN 'failed' THEN 6 ELSE 7 END
   AND NOT EXISTS(SELECT 1 FROM runtime.leases l WHERE l.run_id=r.run_id))
  THEN RAISE EXCEPTION 'Task report requires exact terminal Cloud execution'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_source_home(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.guard_work_item_source_home() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND OLD.source_invocation_id IS NOT NULL AND
  (NEW.source_home,NEW.source_run_id,NEW.source_invocation_id,NEW.source_snapshot_id) IS DISTINCT FROM
  (OLD.source_home,OLD.source_run_id,OLD.source_invocation_id,OLD.source_snapshot_id)
 THEN RAISE EXCEPTION 'Task execution source is immutable' USING ERRCODE='23514'; END IF;
 IF NEW.source_home='device' AND (NEW.source_invocation_id IS NULL OR NOT EXISTS(
   SELECT 1 FROM collaboration.work_item_native_sources n JOIN resource.device_commands c USING(invocation_id)
   JOIN collaboration.work_items t ON t.work_item_id=NEW.work_item_id AND t.tenant_id=c.tenant_id AND t.owner_id=c.owner_id AND t.agent_id=c.agent_id
   WHERE n.invocation_id=NEW.source_invocation_id AND n.snapshot_id=NEW.source_snapshot_id AND c.run_id=NEW.source_run_id
     AND c.tenant_id=NEW.tenant_id AND c.owner_id=NEW.owner_id))
 THEN RAISE EXCEPTION 'Task Native source differs from original command scope' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: notify_supervisor_lane(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.notify_supervisor_lane() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM pg_notify('musteragent_supervisor_wake', TG_ARGV[0]);
    RETURN NULL;
END $$;


--
-- Name: notify_work_item_schedule(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.notify_work_item_schedule() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE lane text;
BEGIN
    IF NEW.delivered_at_ms IS NOT NULL THEN RETURN NULL; END IF;
    lane := CASE NEW.event_kind
      WHEN 'execution_requested' THEN 'dispatch' WHEN 'execution_reported' THEN 'dispatch'
      WHEN 'control_requested' THEN 'control' WHEN 'goal_amended' THEN 'control'
      WHEN 'execution_admitted' THEN 'report' END;
    IF lane IS NOT NULL THEN PERFORM pg_notify('musteragent_supervisor_wake', lane); END IF;
    RETURN NULL;
END $$;


--
-- Name: preserve_result_fact(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.preserve_result_fact() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'immutable Task result fact' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END $$;


--
-- Name: preserve_result_protocol(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.preserve_result_protocol() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (NEW.result_protocol, NEW.requester_uses_result) IS DISTINCT FROM (OLD.result_protocol, OLD.requester_uses_result) THEN
        RAISE EXCEPTION 'Task result protocol is immutable' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: preserve_work_item_command_cause(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.preserve_work_item_command_cause() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.operation IS NOT NULL AND
   (NEW.operation,NEW.source_run_id,NEW.source_invocation_id,NEW.source_snapshot_id)
   IS DISTINCT FROM (OLD.operation,OLD.source_run_id,OLD.source_invocation_id,OLD.source_snapshot_id)
 THEN RAISE EXCEPTION 'immutable WorkItem command execution causation'; END IF;
 RETURN NEW;
END; $$;


--
-- Name: preserve_work_item_erasure_fence(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.preserve_work_item_erasure_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.erasure_job_id IS NOT NULL AND
       (NEW.erasure_job_id IS DISTINCT FROM OLD.erasure_job_id OR NEW.state_revision <> OLD.state_revision) THEN
        RAISE EXCEPTION 'WorkItem privacy fence cannot be replaced or advanced' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: require_native_private_result_receipt(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.require_native_private_result_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE run UUID;
BEGIN
 IF TG_TABLE_SCHEMA='resource' THEN
    IF NEW.tool_key <> 'tasks.submit_result@1' OR NEW.outcome IS DISTINCT FROM 'succeeded' THEN RETURN NEW; END IF;
    run := NEW.run_id;
 ELSE
    IF NEW.producer_home <> 'device' THEN RETURN NEW; END IF;
    run := NEW.producing_run_id;
 END IF;
 IF NOT EXISTS (
    SELECT 1 FROM collaboration.work_item_result_submissions s
    JOIN resource.device_commands c ON c.invocation_id=s.submission_invocation_id
      AND c.tenant_id=s.tenant_id AND c.owner_id=s.owner_id AND c.agent_id=s.producing_agent_id
      AND c.work_item_run_id=s.producing_run_id AND c.run_id=s.producing_run_id
      AND c.admission_kind='work_item' AND c.tool_key='tasks.submit_result@1' AND c.outcome='succeeded'
      AND c.receipt_content_id IS NOT NULL AND c.receipt_commitment IS NOT NULL AND c.result_content_id=s.receipt_content_id
    JOIN collaboration.work_item_device_admitted_custody d ON d.run_id=c.run_id AND d.conversation_id=c.conversation_id
      AND d.work_item_id=s.work_item_id AND d.goal_revision=s.goal_revision AND d.control_revision=s.control_revision AND d.assignment_epoch=s.assignment_epoch
      AND d.admitted_at_ms IS NOT NULL AND d.admitted_snapshot_hash IS NOT NULL
    JOIN collaboration.work_item_device_targets t ON t.work_item_id=d.work_item_id AND t.goal_revision=d.goal_revision AND t.control_revision=d.control_revision AND t.assignment_epoch=d.assignment_epoch
    JOIN artifact.content_refs req ON req.tenant_id=c.tenant_id AND req.content_id=c.request_content_id AND req.content_hash=s.request_sha256 AND req.state=2
    WHERE s.producing_run_id=run AND s.producer_home='device' AND c.device_id=t.device_id AND c.installation_id=t.installation_id
      AND NOT EXISTS (SELECT 1 FROM collaboration.work_item_device_terminals closed WHERE closed.run_id=run)
 ) THEN RAISE EXCEPTION 'private Task result requires its successful signed Native resource command' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: require_native_task_result_cut(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.require_native_task_result_cut() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE protocol TEXT; prefix BYTEA; body BYTEA; result RECORD;
BEGIN
 SELECT x.result_protocol INTO STRICT protocol FROM collaboration.work_item_execution_reservations x WHERE x.run_id=NEW.run_id;
 IF protocol='public_result_v1' AND NEW.result_cut IS NULL THEN RETURN NEW; END IF;
 IF protocol<>'verified_result_v1' OR NEW.result_cut IS NULL THEN RAISE EXCEPTION 'Native Task terminal result protocol mismatch' USING ERRCODE='23514'; END IF;
 prefix := convert_to('musteragent.work-item-device-result-cut.v1','UTF8') || decode('00','hex');
 SELECT s.submission_invocation_id,c.command_commitment,c.receipt_commitment,content.content_hash,content.byte_length INTO result
 FROM collaboration.work_item_result_submissions s JOIN resource.device_commands c ON c.invocation_id=s.submission_invocation_id
  AND c.run_id=s.producing_run_id AND c.result_content_id=s.receipt_content_id AND c.outcome='succeeded' AND c.admission_kind='work_item'
 JOIN artifact.content_refs content ON content.tenant_id=s.tenant_id AND content.content_id=s.receipt_content_id
 WHERE s.producing_run_id=NEW.run_id AND s.producer_home='device';
 IF NOT FOUND THEN
    IF NEW.outcome='completed' OR NEW.result_cut<>(prefix || decode('00','hex')) THEN RAISE EXCEPTION 'successful verified Task terminal requires an original private result' USING ERRCODE='23514'; END IF;
 ELSE
    prefix:=prefix || decode('01','hex') || uuid_send(result.submission_invocation_id) || result.command_commitment || result.receipt_commitment || int4send(result.byte_length::integer);
    body:=substring(NEW.result_cut FROM octet_length(prefix)+1);
    IF substring(NEW.result_cut FROM 1 FOR octet_length(prefix))<>prefix OR octet_length(body)<>result.byte_length OR sha256(body)<>result.content_hash THEN
       RAISE EXCEPTION 'Native terminal must retain the complete original Task submission' USING ERRCODE='23514';
    END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: require_native_task_source_receipt(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.require_native_task_source_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM resource.device_commands c WHERE c.invocation_id=NEW.invocation_id AND c.outcome='succeeded' AND c.receipt_content_id IS NOT NULL)
 THEN RAISE EXCEPTION 'Native Task and original successful resource receipt must commit together' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: require_private_submission(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.require_private_submission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
       SELECT 1 FROM collaboration.work_item_execution_reservations x
       JOIN collaboration.work_items t USING(work_item_id)
       WHERE x.tenant_id=NEW.tenant_id AND x.owner_id=NEW.owner_id AND x.run_id=NEW.producing_run_id
         AND (x.work_item_id,x.goal_revision,x.control_revision,x.assignment_epoch)=(NEW.work_item_id,NEW.goal_revision,NEW.control_revision,NEW.assignment_epoch)
         AND x.requesting_agent_id=NEW.requesting_agent_id AND x.executing_agent_id=NEW.producing_agent_id
         AND t.source_dialogue_id=NEW.source_dialogue_id AND t.source_intent_id=NEW.source_intent_id
         AND x.result_protocol='verified_result_v1'
         AND (SELECT count(*) FROM collaboration.work_item_result_items z WHERE z.result_id=NEW.result_id)=NEW.item_count
         AND ((NEW.producer_home='cloud' AND EXISTS(
             SELECT 1 FROM runtime.runs r JOIN tool.tool_invocations i USING(tenant_id,run_id)
             WHERE r.run_id=x.run_id AND r.tenant_id=x.tenant_id AND r.runtime_snapshot_id=NEW.producing_snapshot_id
               AND i.invocation_id=NEW.submission_invocation_id AND i.tool_ref='tasks.submit_result@1' AND i.request_hash=NEW.request_sha256
               AND i.status=4 AND i.result_content_id=NEW.receipt_content_id))
           OR (NEW.producer_home='device' AND EXISTS(
             SELECT 1 FROM collaboration.work_item_device_admitted_custody d WHERE d.run_id=x.run_id AND d.work_item_id=x.work_item_id
               AND d.admitted_at_ms IS NOT NULL AND d.admitted_snapshot_hash IS NOT NULL)))
    ) THEN RAISE EXCEPTION 'Task submission lacks the original source and complete item set' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END $$;


--
-- Name: require_result_promotion(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.require_result_promotion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE target_result uuid;
BEGIN
 IF TG_TABLE_NAME='dialogue_publications' THEN
   IF NEW.source_kind<>'task_result_owner' THEN RETURN NEW; END IF;
   SELECT result_id INTO STRICT target_result FROM collaboration.work_item_result_items WHERE item_id=NEW.source_task_result_item_id;
 ELSE target_result=NEW.result_id;
 END IF;
 IF NOT EXISTS (SELECT 1 FROM collaboration.authorized_result_deliveries d WHERE d.result_id=target_result AND
   (SELECT count(*) FROM collaboration.work_item_result_items item JOIN agent.dialogue_publications p ON p.source_task_result_item_id=item.item_id
     WHERE item.result_id=d.result_id AND p.tenant_id=d.tenant_id AND p.owner_id=d.owner_id AND p.agent_id=d.requesting_agent_id
      AND p.dialogue_id=d.source_dialogue_id AND p.source_run_id=d.publication_run_id AND p.source_kind='task_result_owner'
      AND p.source_intent_id=d.source_intent_id AND p.execution_home=CASE WHEN d.device_terminal_run_id IS NULL THEN 'cloud' ELSE 'device' END)=d.item_count)
 THEN RAISE EXCEPTION 'Task delivery lacks its terminal or assessment proof and exact requester entries' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: require_unfenced_work_item_revision(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.require_unfenced_work_item_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM collaboration.work_items
               WHERE work_item_id=NEW.work_item_id AND erasure_job_id IS NOT NULL FOR UPDATE) THEN
        RAISE EXCEPTION 'WorkItem is permanently fenced for privacy erasure' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: validate_work_item_command_cause(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.validate_work_item_command_cause() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.operation IS NULL THEN RETURN NEW; END IF;
 IF NEW.source_home='device' THEN
  IF NEW.operation NOT IN ('cancel','amend') OR NOT EXISTS(
   SELECT 1 FROM collaboration.work_item_native_sources n JOIN resource.device_commands c USING(invocation_id)
   JOIN collaboration.work_items t ON t.work_item_id=NEW.work_item_id AND t.tenant_id=c.tenant_id AND t.owner_id=c.owner_id AND t.agent_id=c.agent_id
   JOIN collaboration.work_item_revisions rev ON rev.work_item_id=t.work_item_id AND rev.state_revision=NEW.state_revision
   WHERE c.invocation_id=NEW.source_invocation_id AND c.run_id=NEW.source_run_id AND n.snapshot_id=NEW.source_snapshot_id
    AND c.tenant_id=NEW.tenant_id AND c.owner_id=NEW.owner_id AND c.dialogue_id=t.source_dialogue_id
    AND c.admission_kind='intent' AND c.outcome='succeeded' AND c.result_content_id IS NOT NULL AND c.receipt_content_id IS NOT NULL
    AND ((NEW.operation='cancel' AND c.tool_key='tasks.control@1') OR (NEW.operation='amend' AND c.tool_key='tasks.amend@2')) AND rev.status='blocked')
  THEN RAISE EXCEPTION 'Task command lacks original Native receipt causation' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF NOT EXISTS (
  SELECT 1 FROM collaboration.work_items task
  JOIN agent.dialogue_sessions s ON s.tenant_id=task.tenant_id AND s.owner_id=task.owner_id AND s.agent_id=task.agent_id AND s.dialogue_id=task.source_dialogue_id
  JOIN runtime.runs run ON run.tenant_id=s.tenant_id AND run.conversation_id=s.conversation_id
  JOIN tool.tool_invocations i ON i.tenant_id=run.tenant_id AND i.run_id=run.run_id AND i.conversation_id=run.conversation_id
  JOIN collaboration.work_item_revisions rev ON rev.work_item_id=task.work_item_id AND rev.state_revision=NEW.state_revision
  WHERE task.work_item_id=NEW.work_item_id AND task.tenant_id=NEW.tenant_id AND task.owner_id=NEW.owner_id
   AND ((NEW.operation IN ('cancel','amend') AND s.subject_kind='intent' AND s.purpose='intent_coordination')
    OR (s.subject_kind='work_item_report' AND s.work_item_id=NEW.work_item_id
     AND ((NEW.operation='verify' AND s.work_item_goal_revision=rev.goal_revision AND s.work_item_control_revision=rev.control_revision AND s.work_item_assignment_epoch=rev.assignment_epoch)
       OR (NEW.operation='amend' AND s.work_item_goal_revision+1=rev.goal_revision AND s.work_item_control_revision=rev.control_revision)
       OR (NEW.operation='cancel' AND s.work_item_goal_revision=rev.goal_revision AND s.work_item_control_revision+1=rev.control_revision))))
   AND run.run_id=NEW.source_run_id AND run.runtime_snapshot_id=NEW.source_snapshot_id
   AND i.invocation_id=NEW.source_invocation_id AND i.status=4 AND i.result_content_id IS NOT NULL
   AND ((NEW.operation='cancel' AND i.tool_ref='tasks.control@1') OR (NEW.operation='amend' AND i.tool_ref IN ('tasks.amend@1','tasks.amend@2')) OR (NEW.operation='verify' AND i.tool_ref IN ('tasks.verify@1','tasks.verify@2','tasks.verify@3')))
   AND ((NEW.operation IN ('cancel','amend') AND rev.status='blocked') OR (NEW.operation='verify' AND rev.status IN ('completed','blocked','verifying')))
 ) THEN RAISE EXCEPTION 'WorkItem command lacks canonical Tool execution causation'; END IF;
 RETURN NEW;
END; $$;


--
-- Name: validate_work_item_followup(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.validate_work_item_followup() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE previous collaboration.work_item_followups%ROWTYPE;
BEGIN
 SELECT * INTO previous FROM collaboration.work_item_followups WHERE work_item_id=NEW.parent_work_item_id;
 IF FOUND THEN
  IF NEW.chain_root_id<>previous.chain_root_id OR NEW.chain_sequence<>previous.chain_sequence+1
    THEN RAISE EXCEPTION 'Task followup must extend the original linear chain'; END IF;
 ELSE
  IF NEW.chain_root_id<>NEW.parent_work_item_id OR NEW.chain_sequence<>2
    THEN RAISE EXCEPTION 'first Task followup requires its original root'; END IF;
 END IF;
 IF NOT EXISTS (
  SELECT 1 FROM collaboration.work_items child
  JOIN collaboration.work_item_revisions cr ON cr.work_item_id=child.work_item_id AND cr.state_revision=1
  JOIN collaboration.work_items parent ON parent.work_item_id=NEW.parent_work_item_id
  JOIN collaboration.work_item_revisions pr ON pr.work_item_id=parent.work_item_id AND pr.state_revision=parent.state_revision
  JOIN collaboration.work_items root ON root.work_item_id=NEW.chain_root_id
  JOIN agent.dialogue_user_intents input ON input.intent_id=NEW.source_intent_id AND input.tenant_id=NEW.tenant_id AND input.owner_id=NEW.owner_id
  JOIN agent.agent_dialogue_entries e ON e.entry_id=NEW.source_entry_id AND e.dialogue_id=input.dialogue_id AND e.tenant_id=input.tenant_id AND e.owner_id=input.owner_id
  JOIN collaboration.input_task_actions a ON a.tenant_id=NEW.tenant_id AND a.action_id=NEW.action_id AND a.owner_id=NEW.owner_id
  JOIN tool.tool_invocations tool ON tool.invocation_id=a.source_invocation_id AND tool.tenant_id=a.tenant_id AND tool.run_id=a.source_run_id
  JOIN agent.dialogue_sessions s ON s.conversation_id=tool.conversation_id AND s.tenant_id=tool.tenant_id AND s.owner_id=a.owner_id
  JOIN runtime.runs run ON run.run_id=tool.run_id AND run.tenant_id=tool.tenant_id AND run.runtime_snapshot_id=a.source_snapshot_id
  JOIN collaboration.work_item_execution_reservations original ON original.work_item_id=parent.work_item_id AND original.goal_revision=NEW.parent_goal_revision AND original.control_revision=NEW.parent_control_revision AND original.assignment_epoch=NEW.parent_assignment_epoch
  JOIN collaboration.work_item_execution_reservations successor ON successor.work_item_id=child.work_item_id AND successor.goal_revision=1 AND successor.control_revision=1 AND successor.assignment_epoch=1
  WHERE child.work_item_id=NEW.work_item_id AND child.tenant_id=NEW.tenant_id AND child.owner_id=NEW.owner_id AND child.agent_id=NEW.agent_id AND child.erasure_job_id IS NULL
   AND parent.tenant_id=child.tenant_id AND parent.owner_id=child.owner_id AND parent.space_id=child.space_id AND parent.agent_id=child.agent_id AND parent.erasure_job_id IS NULL
   AND root.tenant_id=child.tenant_id AND root.owner_id=child.owner_id AND root.agent_id=child.agent_id
   AND child.source_intent_id=input.intent_id AND child.source_dialogue_id=input.dialogue_id AND sha256(input.reply_binding)=NEW.reply_binding_sha256
   AND input.origin_surface<>'schedule' AND child.parent_work_item_id IS NULL AND cr.follow_up_of=parent.work_item_id
   AND pr.status='completed' AND pr.goal_revision=NEW.parent_goal_revision AND pr.control_revision=NEW.parent_control_revision AND pr.assignment_epoch=NEW.parent_assignment_epoch
   AND a.operation='followup' AND a.work_item_id=child.work_item_id AND a.agent_id=child.agent_id AND a.source_intent_id=input.intent_id
   AND tool.tool_ref='tasks.followup@1' AND tool.status=4 AND tool.result_content_id IS NOT NULL
   AND s.subject_kind='intent' AND s.purpose='intent_coordination' AND s.source_intent_id=input.intent_id AND s.agent_id=child.agent_id
   AND run.parent_run_id IS NULL AND run.delegation_id IS NULL
   AND e.kind='agent_message' AND e.visible_revision=NEW.source_visible_revision AND e.epoch=input.accepted_epoch
   AND EXISTS(SELECT 1 FROM agent.dialogue_publications p
     JOIN collaboration.work_item_execution_reservations selected ON selected.work_item_id=NEW.selected_work_item_id
      AND selected.goal_revision=NEW.selected_goal_revision AND selected.control_revision=NEW.selected_control_revision
      AND selected.assignment_epoch=NEW.selected_assignment_epoch AND selected.run_id=NEW.selected_producing_run_id
      AND selected.tenant_id=p.tenant_id AND selected.owner_id=p.owner_id
     JOIN collaboration.work_items selected_task ON selected_task.work_item_id=selected.work_item_id AND selected_task.erasure_job_id IS NULL
     LEFT JOIN collaboration.work_item_followups selected_link ON selected_link.work_item_id=selected.work_item_id
     WHERE p.entry_id=e.entry_id AND p.tenant_id=e.tenant_id AND p.owner_id=e.owner_id
      AND coalesce(selected_link.chain_root_id,selected.work_item_id)=NEW.chain_root_id
      AND (p.source_run_id=selected.run_id OR EXISTS(SELECT 1 FROM collaboration.work_item_execution_reports report
        WHERE report.producing_run_id=selected.run_id AND report.work_item_id=selected.work_item_id
         AND report.goal_revision=selected.goal_revision AND report.control_revision=selected.control_revision
         AND report.assignment_epoch=selected.assignment_epoch AND report.report_run_id=p.source_run_id)))
   AND original.run_id=NEW.parent_producing_run_id AND original.requesting_agent_id=child.agent_id
   AND successor.executing_agent_id=original.executing_agent_id AND successor.source_run_id=a.source_run_id AND successor.source_invocation_id=a.source_invocation_id AND successor.source_snapshot_id=a.source_snapshot_id
   AND successor.device_placement_captured=original.device_placement_captured AND successor.device_workspace_id IS NOT DISTINCT FROM original.device_workspace_id
   AND NOT EXISTS(
     (SELECT device_id,installation_id,membership_id,membership_epoch,consent_id,consent_sha256,consent_authority_ref,consent_policy_ref,effective_capabilities_sha256 FROM collaboration.work_item_device_targets WHERE work_item_id=parent.work_item_id AND goal_revision=NEW.parent_goal_revision AND control_revision=NEW.parent_control_revision AND assignment_epoch=NEW.parent_assignment_epoch
      EXCEPT SELECT device_id,installation_id,membership_id,membership_epoch,consent_id,consent_sha256,consent_authority_ref,consent_policy_ref,effective_capabilities_sha256 FROM collaboration.work_item_device_targets WHERE work_item_id=child.work_item_id AND goal_revision=1 AND control_revision=1 AND assignment_epoch=1)
     UNION ALL
     (SELECT device_id,installation_id,membership_id,membership_epoch,consent_id,consent_sha256,consent_authority_ref,consent_policy_ref,effective_capabilities_sha256 FROM collaboration.work_item_device_targets WHERE work_item_id=child.work_item_id AND goal_revision=1 AND control_revision=1 AND assignment_epoch=1
      EXCEPT SELECT device_id,installation_id,membership_id,membership_epoch,consent_id,consent_sha256,consent_authority_ref,consent_policy_ref,effective_capabilities_sha256 FROM collaboration.work_item_device_targets WHERE work_item_id=parent.work_item_id AND goal_revision=NEW.parent_goal_revision AND control_revision=NEW.parent_control_revision AND assignment_epoch=NEW.parent_assignment_epoch)
   )
 ) THEN RAISE EXCEPTION 'Task followup requires exact accepted reply, completed parent and original execution destination'; END IF;
 RETURN NULL;
END $$;


--
-- Name: validate_work_item_partner_input(); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.validate_work_item_partner_input() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.partner_input_entry_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM agent.agent_dialogue_entries e
  WHERE e.entry_id=NEW.partner_input_entry_id AND e.dialogue_id=NEW.executing_dialogue_id
    AND e.tenant_id=NEW.tenant_id AND e.owner_id=NEW.owner_id AND e.kind='agent_message'
    AND e.author_agent_id=NEW.requesting_agent_id AND e.source_intent_id IS NULL
    AND e.content_ref=NEW.partner_input_ref AND e.epoch=NEW.context_epoch AND e.seq=NEW.context_seq
 ) THEN RAISE EXCEPTION 'Task partner input must bind its exact original Agent message'; END IF;
 RETURN NEW;
END $$;


--
-- Name: work_item_session_is_current(uuid); Type: FUNCTION; Schema: collaboration; Owner: -
--

CREATE FUNCTION collaboration.work_item_session_is_current(session uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM agent.dialogue_sessions s
 JOIN collaboration.work_items t ON t.work_item_id=s.work_item_id AND t.tenant_id=s.tenant_id AND t.owner_id=s.owner_id
 JOIN collaboration.work_item_revisions r ON r.work_item_id=t.work_item_id AND r.state_revision=t.state_revision
 WHERE s.conversation_id=session AND s.subject_kind IN ('work_item','work_item_report') AND t.erasure_job_id IS NULL
 AND r.goal_revision=s.work_item_goal_revision AND r.control_revision=s.work_item_control_revision
 AND r.assignment_epoch=s.work_item_assignment_epoch AND (s.subject_kind='work_item_report' OR r.status IN ('active','verifying','blocked')))
$$;


--
-- Name: protect_workspace_assignment_preparation(); Type: FUNCTION; Schema: conversation; Owner: -
--

CREATE FUNCTION conversation.protect_workspace_assignment_preparation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Workspace assignment preparation cannot be deleted'; END IF;
    IF (NEW.command_id, NEW.tenant_id, NEW.conversation_id, NEW.owner_principal_id,
        NEW.target_workspace_id, NEW.expected_home_epoch, NEW.prepared_at_ms)
       IS DISTINCT FROM
       (OLD.command_id, OLD.tenant_id, OLD.conversation_id, OLD.owner_principal_id,
        OLD.target_workspace_id, OLD.expected_home_epoch, OLD.prepared_at_ms)
       OR OLD.phase <> 1 OR NEW.phase NOT IN (2,3) THEN
        RAISE EXCEPTION 'Workspace assignment preparation identity is immutable';
    END IF;
    IF NEW.phase = 3 AND NOT EXISTS (
        SELECT 1 FROM resource.workspace_assignment_receipts AS receipt
        JOIN conversation.conversations AS conversation USING(tenant_id, conversation_id)
        WHERE receipt.command_id = NEW.command_id AND receipt.tenant_id = NEW.tenant_id
          AND receipt.conversation_id = NEW.conversation_id
          AND receipt.target_workspace_id = NEW.target_workspace_id
          AND conversation.workspace_id = NEW.target_workspace_id
    ) THEN RAISE EXCEPTION 'Workspace assignment completion requires its atomic receipt'; END IF;
    RETURN NEW;
END $$;


--
-- Name: reject_execution_owner_leave(); Type: FUNCTION; Schema: conversation; Owner: -
--

CREATE FUNCTION conversation.reject_execution_owner_leave() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.left_at_ms IS NULL
       AND NEW.left_at_ms IS NOT NULL
       AND EXISTS (
           SELECT 1
           FROM conversation.conversations AS conversation
           WHERE conversation.tenant_id = OLD.tenant_id
             AND conversation.conversation_id = OLD.conversation_id
             AND conversation.execution_owner_participant_id = OLD.participant_id
       )
    THEN
        RAISE EXCEPTION 'Conversation execution owner cannot leave';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_ledger_content_coverage(); Type: FUNCTION; Schema: event_store; Owner: -
--

CREATE FUNCTION event_store.guard_ledger_content_coverage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.content_reference_coverage<>0 THEN
            RAISE EXCEPTION 'Ledger content coverage starts pending';
        END IF;
    ELSIF NEW.record_id<>OLD.record_id OR NEW.tenant_id<>OLD.tenant_id
        OR NEW.payload_hash<>OLD.payload_hash OR NEW.schema_version<>OLD.schema_version
        OR NEW.record_kind<>OLD.record_kind THEN
        RAISE EXCEPTION 'Ledger content source identity is immutable';
    ELSIF NEW.content_reference_coverage<>OLD.content_reference_coverage AND (
        NOT ((OLD.content_reference_coverage=0 AND NEW.content_reference_coverage<>0)
          OR (OLD.content_reference_coverage IN (2,3,5) AND NEW.content_reference_coverage IN (1,6)))
        OR (NEW.content_reference_coverage NOT IN (1,6) AND EXISTS (
            SELECT 1 FROM event_store.ledger_content_references WHERE record_id=OLD.record_id))) THEN
        RAISE EXCEPTION 'Ledger content coverage is immutable';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: guard_ledger_content_reference(); Type: FUNCTION; Schema: event_store; Owner: -
--

CREATE FUNCTION event_store.guard_ledger_content_reference() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='UPDATE' OR (TG_OP='DELETE' AND EXISTS (
        SELECT 1 FROM event_store.ledger_records WHERE record_id=OLD.record_id)) THEN
        RAISE EXCEPTION 'Ledger content roots follow immutable history';
    END IF;
    IF TG_OP='INSERT' AND NOT EXISTS (SELECT 1 FROM event_store.ledger_records
        WHERE record_id=NEW.record_id AND tenant_id=NEW.tenant_id
          AND content_reference_coverage IN (0,2,3,5)) THEN
        RAISE EXCEPTION 'Ledger content roots require an open projection';
    END IF;
    RETURN COALESCE(NEW,OLD);
END $$;


