--
-- Name: enqueue_terminal_run_learning(); Type: FUNCTION; Schema: evolution; Owner: -
--

CREATE FUNCTION evolution.enqueue_terminal_run_learning() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    frozen_watermark NUMERIC(20, 0);
BEGIN
    IF NEW.status NOT BETWEEN 5 AND 8
       OR NEW.activity_kind NOT BETWEEN 1 AND 4
       OR (TG_OP = 'UPDATE' AND OLD.status BETWEEN 5 AND 8) THEN
        RETURN NEW;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM conversation.participants AS participant
        WHERE participant.tenant_id = NEW.tenant_id
          AND participant.conversation_id = NEW.conversation_id
          AND participant.participant_id = NEW.executor_participant_id
          AND participant.agent_ref IS NOT NULL
    ) THEN
        RETURN NEW;
    END IF;
    SELECT stream.last_sequence INTO STRICT frozen_watermark
    FROM event_store.ledger_streams AS stream
    WHERE stream.tenant_id = NEW.tenant_id
      AND stream.conversation_id = NEW.conversation_id;
    IF frozen_watermark < 1 THEN
        RAISE EXCEPTION 'terminal Run cannot be queued without Ledger evidence';
    END IF;
    INSERT INTO evolution.learning_run_queue (
        run_id, tenant_id, conversation_id, ledger_watermark, terminal_status,
        status, attempt_count, available_at_ms, created_at_ms, updated_at_ms
    ) VALUES (
        NEW.run_id, NEW.tenant_id, NEW.conversation_id, frozen_watermark,
        NEW.status - 4, 1, 0, COALESCE(NEW.finished_at_ms, NEW.admitted_at_ms),
        COALESCE(NEW.finished_at_ms, NEW.admitted_at_ms),
        COALESCE(NEW.finished_at_ms, NEW.admitted_at_ms)
    ) ON CONFLICT (run_id) DO NOTHING;
    RETURN NEW;
END;
$$;


