--
-- Name: reject_instinct_immutable_identity_mutation(); Type: FUNCTION; Schema: evolution; Owner: -
--

CREATE FUNCTION evolution.reject_instinct_immutable_identity_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.tenant_id <> OLD.tenant_id
       OR NEW.target_agent_id <> OLD.target_agent_id
       OR NEW.proposal_id <> OLD.proposal_id
       OR NEW.evaluation_id <> OLD.evaluation_id
       OR NEW.approval_interaction_id <> OLD.approval_interaction_id
       OR NEW.promotion_id <> OLD.promotion_id
       OR NEW.payload_content_id <> OLD.payload_content_id
       OR NEW.payload_content_hash <> OLD.payload_content_hash
       OR NEW.created_by <> OLD.created_by
       OR NEW.created_at_ms <> OLD.created_at_ms
       OR NEW.revision <> OLD.revision + 1
       OR NEW.updated_at_ms < OLD.updated_at_ms
       OR NOT EXISTS (
            SELECT 1 FROM evolution.instinct_lifecycle_receipts AS receipt
            WHERE receipt.tenant_id = OLD.tenant_id
              AND receipt.target_agent_id = OLD.target_agent_id
              AND receipt.instinct_id = OLD.instinct_id
              AND receipt.previous_revision = OLD.revision
              AND receipt.revision = NEW.revision
              AND receipt.lifecycle = NEW.lifecycle
              AND receipt.changed_at_ms = NEW.updated_at_ms
       )
    THEN
        RAISE EXCEPTION 'Instinct immutable identity or monotonic revision changed';
    END IF;
    RETURN NEW;
END;
$$;


