--
-- Name: guard_native_tool_approval(); Type: FUNCTION; Schema: memory; Owner: -
--

CREATE FUNCTION memory.guard_native_tool_approval() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Native Memory authorization is immutable'; END IF;
 IF NOT EXISTS(SELECT 1 FROM agent.native_dialogue_interaction_projections p
  JOIN resource.device_commands c ON c.invocation_id=p.invocation_id AND c.tenant_id=p.tenant_id
   AND c.owner_id=p.owner_id AND c.agent_id=p.agent_id AND c.run_id=p.run_id
   AND c.device_id=p.device_id AND c.installation_id=p.installation_id
  JOIN artifact.content_refs prompt ON prompt.content_id=p.prompt_content_id AND prompt.tenant_id=p.tenant_id
  WHERE p.interaction_id=NEW.interaction_id AND p.status=2 AND NOT p.control_open
   AND c.invocation_id=NEW.invocation_id AND c.tenant_id=NEW.tenant_id
   AND c.owner_id=NEW.approved_by AND c.request_content_id=NEW.request_content_id
   AND p.prompt_content_id=NEW.prompt_content_id AND prompt.content_hash=NEW.prompt_content_hash
   AND c.tool_key IN ('user_memory.remember@2','experience.publish@1'))
 THEN RAISE EXCEPTION 'Native Memory approval lacks original account custody' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


