--
-- Name: reject_erased_search_projection(); Type: FUNCTION; Schema: memory; Owner: -
--

CREATE FUNCTION memory.reject_erased_search_projection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    projection_is_erased BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM memory.memory_versions AS version
        JOIN memory.memories AS memory
          ON memory.memory_id = version.memory_id
        WHERE version.memory_version_id = NEW.memory_version_id
          AND memory.memory_id = NEW.memory_id
          AND memory.tenant_id = NEW.tenant_id
          AND version.content_hash = NEW.source_content_hash
          AND (
              EXISTS (
                  SELECT 1
                  FROM memory.search_erasure_tombstones AS tombstone
                  WHERE tombstone.memory_version_id = version.memory_version_id
              )
              OR memory.search_content_is_erased(
                  memory.tenant_id,
                  version.content_id,
                  version.content_hash
              )
          )
    ) INTO projection_is_erased;
    IF projection_is_erased THEN
        RAISE EXCEPTION 'Memory search projection is fenced by privacy erasure';
    END IF;
    RETURN NEW;
END;
$$;


