--
-- Name: search_content_is_erased(uuid, uuid, bytea); Type: FUNCTION; Schema: memory; Owner: -
--

CREATE FUNCTION memory.search_content_is_erased(candidate_tenant_id uuid, candidate_content_id uuid, candidate_content_hash bytea) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM privacy_erasure.receipts AS receipt
        JOIN privacy_erasure.receipt_completed_data_classes AS completed
          ON completed.tenant_id = receipt.tenant_id
         AND completed.erasure_job_id = receipt.erasure_job_id
         AND completed.data_class = 4
        JOIN privacy_erasure.root_resources AS root
          ON root.tenant_id = receipt.tenant_id
         AND root.erasure_job_id = receipt.erasure_job_id
         AND root.resource_kind = 7
        WHERE receipt.tenant_id = candidate_tenant_id
          AND root.content_id = candidate_content_id
          AND root.content_sha256 = candidate_content_hash
    )
$$;


--
-- Name: guard_source_evidence_producer(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.guard_source_evidence_producer() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE frozen_ms BIGINT; actual_objects UUID[];
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Source erasure coverage is permanent' USING ERRCODE='23514';END IF;
 SELECT p.frozen_at_ms INTO frozen_ms FROM privacy_erasure.plans p
 JOIN privacy_erasure.work_item_lineage l USING(tenant_id,erasure_job_id)
 JOIN tool.tool_invocations i ON i.invocation_id=NEW.producer_invocation_id AND i.tenant_id=l.tenant_id
 WHERE p.tenant_id=NEW.tenant_id AND p.erasure_job_id=NEW.erasure_job_id
   AND p.plan_version=2 AND p.plan_hash=NEW.plan_hash AND p.lineage_fingerprint=l.execution_coverage_hash
   AND l.execution_coverage_version=2 AND i.invocation_id=ANY(l.execution_source_invocation_ids)
   AND i.run_id=ANY(l.execution_run_ids) AND i.run_id=NEW.run_id AND i.conversation_id=NEW.conversation_id
   AND i.tool_ref='sources.attachments.import@1';
 IF frozen_ms IS NULL THEN
   RAISE EXCEPTION 'Source producer requires original frozen Task plan' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' AND num_nonnulls(NEW.completed_at_ms,NEW.object_ids,NEW.proof_digest)<>0 THEN
   RAISE EXCEPTION 'Source producer cannot invent an initial receipt' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' THEN
   IF (to_jsonb(NEW)-ARRAY['object_ids','completed_at_ms','proof_digest']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['object_ids','completed_at_ms','proof_digest']) THEN
     RAISE EXCEPTION 'Source producer identity is immutable' USING ERRCODE='23514';
   END IF;
   IF OLD.completed_at_ms IS NOT NULL AND NEW IS DISTINCT FROM OLD THEN
     RAISE EXCEPTION 'Source erasure receipt is immutable' USING ERRCODE='23514';
   END IF;
   IF NEW.completed_at_ms IS NOT NULL THEN
     SELECT coalesce(array_agg(x ORDER BY x),'{}'::uuid[]) INTO actual_objects
       FROM (SELECT DISTINCT unnest(NEW.object_ids) x) q;
     IF NEW.completed_at_ms<frozen_ms OR actual_objects IS DISTINCT FROM NEW.object_ids
       OR array_position(NEW.object_ids,NULL) IS NOT NULL
       OR '00000000-0000-0000-0000-000000000000'::uuid=ANY(NEW.object_ids)
       OR NOT EXISTS(SELECT 1 FROM tool.tool_invocations i WHERE i.invocation_id=NEW.producer_invocation_id
          AND i.erasure_job_id=NEW.erasure_job_id)
     THEN RAISE EXCEPTION 'Source receipt requires an irreversibly fenced original producer' USING ERRCODE='23514';END IF;
   END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_context_erasure(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.guard_work_item_context_erasure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected_job UUID; target_run UUID;
BEGIN
 IF TG_TABLE_NAME='dialogue_context_checkpoints' THEN
  SELECT run_id INTO target_run FROM runtime.model_invocations WHERE invocation_id=NEW.generator_invocation_id;
 ELSE target_run:=NEW.run_id;
 END IF;
 SELECT privacy_erasure.work_item_execution_job(r.tenant_id,r.conversation_id) INTO expected_job
 FROM runtime.runs r WHERE r.run_id=target_run AND r.tenant_id=NEW.tenant_id;
 IF NEW.erasure_job_id IS NOT NULL THEN
  IF TG_OP<>'UPDATE' THEN RAISE EXCEPTION 'erasure cannot fabricate context facts'; END IF;
  IF expected_job IS DISTINCT FROM NEW.erasure_job_id AND NOT EXISTS(
    SELECT 1 FROM agent.agent_dialogue_entries e WHERE e.tenant_id=NEW.tenant_id
      AND e.dialogue_id=NEW.dialogue_id AND e.epoch=NEW.epoch AND e.kind='erased'
      AND e.erasure_job_id=NEW.erasure_job_id AND e.seq<=NEW.through_seq
      AND (TG_TABLE_NAME='dialogue_context_checkpoints' OR e.seq>=(to_jsonb(NEW)->>'from_seq')::bigint)) THEN
   RAISE EXCEPTION 'context erasure requires exact source provenance';
  END IF;
  IF (to_jsonb(NEW)-'erasure_job_id') IS DISTINCT FROM (to_jsonb(OLD)-'erasure_job_id') THEN
   RAISE EXCEPTION 'context erasure preserves immutable cache identity';
  END IF;
 END IF;
 IF TG_OP='UPDATE' AND OLD.erasure_job_id IS NOT NULL AND NEW IS DISTINCT FROM OLD THEN
  RAISE EXCEPTION 'erased context cache is immutable';
 END IF;
 IF TG_OP='INSERT' THEN
  IF expected_job IS NOT NULL OR EXISTS(SELECT 1 FROM runtime.dialogue_context_bindings b
      WHERE b.run_id=target_run AND b.erasure_job_id IS NOT NULL) THEN
   RAISE EXCEPTION 'an erased source cannot produce another cache';
  END IF;
  IF TG_TABLE_NAME='dialogue_context_bindings' THEN
   IF NEW.source_wire_version<4 AND EXISTS(SELECT 1 FROM agent.agent_dialogue_entries e
      WHERE e.tenant_id=NEW.tenant_id AND e.dialogue_id=NEW.dialogue_id AND e.epoch=NEW.epoch
       AND e.seq BETWEEN NEW.from_seq AND NEW.through_seq AND e.kind='erased') THEN
    RAISE EXCEPTION 'old context format cannot bind erased source';
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_creation_field_erasure(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.guard_work_item_creation_field_erasure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE marker UUID; old_marker UUID; expected UUID; allowed TEXT[]; field_name TEXT;
BEGIN
 IF TG_TABLE_SCHEMA='resource' THEN
  marker:=NEW.sort_key_erasure_job_id; field_name:='sort_key';
  IF TG_OP='UPDATE' THEN old_marker:=OLD.sort_key_erasure_job_id; END IF;
  allowed:=ARRAY['sort_key','sort_key_erasure_job_id','updated_at_ms','revision'];
 ELSE
  marker:=NEW.key_erasure_job_id; field_name:='memory_key';
  IF TG_OP='UPDATE' THEN old_marker:=OLD.key_erasure_job_id; END IF;
  allowed:=ARRAY['memory_key','key_erasure_job_id','updated_at_ms'];
 END IF;
 IF TG_OP='INSERT' THEN
  IF marker IS NOT NULL THEN RAISE EXCEPTION 'creation cannot fabricate erasure' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF old_marker IS NOT NULL THEN
  IF marker IS DISTINCT FROM old_marker OR (to_jsonb(NEW)->field_name) IS DISTINCT FROM (to_jsonb(OLD)->field_name) THEN
   RAISE EXCEPTION 'erased creation field cannot be restored' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF marker IS NULL THEN
  IF (to_jsonb(NEW)->field_name) IS DISTINCT FROM (to_jsonb(OLD)->field_name) THEN
   RAISE EXCEPTION 'creation field requires original erasure proof to change' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-allowed) IS DISTINCT FROM (to_jsonb(OLD)-allowed) THEN
  RAISE EXCEPTION 'creation field erasure must preserve its original scope' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_SCHEMA='resource' THEN
  SELECT privacy_erasure.work_item_execution_job(i.tenant_id,i.conversation_id) INTO expected
   FROM tool.tool_invocations i WHERE i.invocation_id=NEW.source_invocation_id AND i.tenant_id=NEW.tenant_id;
 ELSE
  SELECT v.work_item_erasure_job_id INTO expected FROM memory.memory_versions v
   WHERE v.memory_id=NEW.memory_id AND v.version=1;
  -- The pre-existing full Agent Memory erasure owner has an independently
  -- admitted lineage. Keep that exact path valid without granting Task scope.
  IF expected IS DISTINCT FROM marker AND EXISTS(
    SELECT 1 FROM memory.agent_memory_erasure_lineage l
     WHERE l.tenant_id=NEW.tenant_id AND l.memory_id=NEW.memory_id
       AND l.memory_version_id=NEW.current_version_id AND l.erasure_job_id=marker
       AND NEW.lifecycle=3) THEN expected:=marker; END IF;
 END IF;
 IF expected IS NULL OR marker<>expected OR
    (to_jsonb(NEW)->>field_name) <> ('erased:'||(to_jsonb(NEW)->>(CASE WHEN TG_TABLE_SCHEMA='resource' THEN 'node_id' ELSE 'memory_id' END))) THEN
  RAISE EXCEPTION 'creation field erasure requires the original Task producer' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_edit_erasure(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.guard_work_item_edit_erasure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected UUID; allowed TEXT[];
BEGIN
 IF TG_OP='UPDATE' AND OLD.work_item_erasure_job_id IS NOT NULL THEN
  IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'erased edit cannot resume' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.work_item_erasure_job_id IS NULL THEN
  IF TG_TABLE_NAME='edit_operations' AND EXISTS(SELECT 1 FROM resource.edit_sessions e
    WHERE e.session_id=NEW.session_id AND e.work_item_erasure_job_id IS NOT NULL) THEN
   RAISE EXCEPTION 'erased edit cannot append' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF TG_OP<>'UPDATE' THEN RAISE EXCEPTION 'erasure cannot fabricate edit' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='edit_operations' THEN
  SELECT privacy_erasure.work_item_execution_job(i.tenant_id,i.conversation_id) INTO expected
   FROM tool.tool_invocations i WHERE i.invocation_id=NEW.source_invocation_id AND i.tenant_id=NEW.tenant_id;
  allowed:=ARRAY['work_item_erasure_job_id'];
 ELSE
  SELECT o.work_item_erasure_job_id INTO expected FROM resource.edit_operations o
   WHERE o.session_id=NEW.session_id AND o.checkpoint_content_id=NEW.checkpoint_content_id
    AND o.checkpoint_hash=NEW.checkpoint_hash AND o.work_item_erasure_job_id=NEW.work_item_erasure_job_id LIMIT 1;
  allowed:=ARRAY['work_item_erasure_job_id','state','session_revision'];
  IF NEW.session_revision<>OLD.session_revision+1 OR NEW.state<>(CASE WHEN OLD.state IN(1,2) THEN 4 ELSE OLD.state END) THEN
   RAISE EXCEPTION 'edit erasure must close only its original live session' USING ERRCODE='23514'; END IF;
 END IF;
 IF expected IS NULL OR NEW.work_item_erasure_job_id<>expected OR
    (to_jsonb(NEW)-allowed) IS DISTINCT FROM (to_jsonb(OLD)-allowed) THEN
  RAISE EXCEPTION 'edit erasure lacks exact original producer' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_field_erasure(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.guard_work_item_field_erasure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected UUID; producer UUID; marker UUID; before_marker UUID; allowed TEXT[];
        field_name TEXT; producer_field TEXT; known_field TEXT; object_field TEXT;
BEGIN
 IF TG_TABLE_NAME='artifacts' THEN
  marker:=NEW.title_erasure_job_id; producer:=NEW.title_source_invocation_id;
  IF TG_OP='UPDATE' THEN before_marker:=OLD.title_erasure_job_id; END IF;
  -- PostgreSQL computes GENERATED search_text after BEFORE triggers. It is
  -- not writable source data and must not be compared as producer identity.
  allowed:=ARRAY['title','title_erasure_job_id','updated_at_ms','search_text'];
  field_name:='title'; producer_field:='title_source_invocation_id';
  known_field:='title_source_known'; object_field:='artifact_id';
 ELSE
  marker:=NEW.name_erasure_job_id; producer:=NEW.name_source_invocation_id;
  IF TG_OP='UPDATE' THEN before_marker:=OLD.name_erasure_job_id; END IF;
  allowed:=ARRAY['name','comparison_name','name_erasure_job_id','updated_at_ms','revision'];
  field_name:='name'; producer_field:='name_source_invocation_id';
  known_field:='name_source_known'; object_field:='node_id';
 END IF;
 IF marker IS NULL THEN
  IF before_marker IS NOT NULL AND (
      (to_jsonb(NEW)->producer_field) IS NOT DISTINCT FROM (to_jsonb(OLD)->producer_field)
      OR (to_jsonb(NEW)->>known_field)::BOOLEAN IS NOT TRUE
      OR (to_jsonb(NEW)->field_name) IS NOT DISTINCT FROM (to_jsonb(OLD)->field_name)) THEN
   RAISE EXCEPTION 'new field requires a new original producer' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF before_marker=marker THEN
  IF TG_TABLE_NAME='artifacts' AND (to_jsonb(NEW)->'title') IS DISTINCT FROM (to_jsonb(OLD)->'title') OR
     TG_TABLE_NAME='nodes' AND (to_jsonb(NEW)->'name') IS DISTINCT FROM (to_jsonb(OLD)->'name') THEN
   RAISE EXCEPTION 'erased field cannot regain its bytes' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF TG_OP<>'UPDATE' OR before_marker IS NOT NULL OR
    (to_jsonb(NEW)-allowed) IS DISTINCT FROM (to_jsonb(OLD)-allowed) THEN
  RAISE EXCEPTION 'field erasure must preserve producer identity' USING ERRCODE='23514',
   DETAIL=TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME||':'||COALESCE((SELECT string_agg(k,',' ORDER BY k)
    FROM jsonb_object_keys(to_jsonb(NEW)-allowed) k WHERE (to_jsonb(NEW)->k) IS DISTINCT FROM (to_jsonb(OLD)->k)),''); END IF;
 SELECT privacy_erasure.work_item_execution_job(i.tenant_id,i.conversation_id) INTO expected
  FROM tool.tool_invocations i WHERE i.invocation_id=producer AND i.tenant_id=NEW.tenant_id;
 IF expected IS NULL OR marker<>expected OR
    (to_jsonb(NEW)->>field_name) <> ('erased:'||(to_jsonb(NEW)->>object_field)) OR
    (TG_TABLE_NAME='nodes' AND (to_jsonb(NEW)->>'comparison_name') <> (to_jsonb(NEW)->>'name')) THEN
  RAISE EXCEPTION 'field erasure requires its actual Task producer' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_owned_object(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.guard_work_item_owned_object() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE covered UUID[];
BEGIN
 IF TG_OP='UPDATE' AND OLD.work_item_erasure_job_id IS NOT NULL AND NEW IS DISTINCT FROM OLD THEN
  RAISE EXCEPTION 'erased authored object cannot be restored';
 END IF;
 IF NEW.work_item_erasure_job_id IS NULL THEN RETURN NEW; END IF;
 IF TG_OP<>'UPDATE' THEN RAISE EXCEPTION 'erasure cannot fabricate an authored object'; END IF;
 SELECT l.execution_run_ids INTO covered FROM privacy_erasure.work_item_lineage l
  JOIN privacy_erasure.plans p USING(tenant_id,erasure_job_id)
  WHERE l.tenant_id=NEW.tenant_id AND l.erasure_job_id=NEW.work_item_erasure_job_id
   AND p.plan_version=2 AND p.lineage_fingerprint=l.execution_coverage_hash;
 IF covered IS NULL OR NEW.lifecycle<>3 THEN RAISE EXCEPTION 'object requires frozen Task erasure coverage'; END IF;
 IF TG_TABLE_SCHEMA='artifact' THEN
  IF NOT(NEW.created_by_run_id=ANY(covered)) OR EXISTS(SELECT 1 FROM artifact.artifact_versions v
     LEFT JOIN tool.tool_invocations i ON i.invocation_id=v.source_invocation_id AND i.tenant_id=NEW.tenant_id
     WHERE v.artifact_id=NEW.artifact_id AND (i.run_id IS NULL OR NOT(i.run_id=ANY(covered)))) THEN
   RAISE EXCEPTION 'Task cannot erase a shared artifact';
  END IF;
  IF (to_jsonb(NEW)-ARRAY['work_item_erasure_job_id','lifecycle','title','updated_at_ms','search_text']) IS DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['work_item_erasure_job_id','lifecycle','title','updated_at_ms','search_text']) THEN RAISE EXCEPTION 'object erasure changed provenance'; END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM memory.memory_versions v WHERE v.memory_id=NEW.memory_id AND
     (NOT(EXISTS(SELECT 1 FROM memory.memory_version_source_runs s WHERE s.memory_version_id=v.memory_version_id AND s.run_id=ANY(covered))
       OR EXISTS(SELECT 1 FROM memory.explicit_publications p JOIN tool.tool_invocations i ON i.invocation_id=p.tool_invocation_id
          WHERE p.memory_version_id=v.memory_version_id AND i.tenant_id=NEW.tenant_id AND i.run_id=ANY(covered)))
      OR EXISTS(SELECT 1 FROM memory.memory_version_source_runs s WHERE s.memory_version_id=v.memory_version_id AND NOT(s.run_id=ANY(covered))))) THEN
   RAISE EXCEPTION 'Task cannot erase a shared memory';
  END IF;
  IF (to_jsonb(NEW)-ARRAY['work_item_erasure_job_id','lifecycle','memory_key','revoked_at_ms','updated_at_ms']) IS DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['work_item_erasure_job_id','lifecycle','memory_key','revoked_at_ms','updated_at_ms']) THEN RAISE EXCEPTION 'object erasure changed provenance'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_private_payload(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.guard_work_item_private_payload() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE tenant UUID; conversation UUID; expected_job UUID; allowed TEXT[];
BEGIN
    IF TG_TABLE_NAME IN ('domain_events','output_frames') THEN
        SELECT r.tenant_id,r.conversation_id INTO STRICT tenant,conversation
        FROM event_store.ledger_records r WHERE r.record_id=NEW.record_id;
    ELSE
        tenant:=NEW.tenant_id; conversation:=NEW.conversation_id;
    END IF;
    expected_job:=privacy_erasure.work_item_execution_job(tenant,conversation);
    IF NEW.erasure_job_id IS NOT NULL AND TG_OP='INSERT' THEN
        RAISE EXCEPTION 'erasure cannot fabricate private payload rows' USING ERRCODE='23514';
    END IF;
    IF TG_TABLE_SCHEMA='capability' AND NEW.erasure_job_id IS NOT NULL THEN
        IF NOT EXISTS(SELECT 1 FROM runtime.runs r JOIN privacy_erasure.work_item_lineage l
            ON r.run_id=ANY(l.execution_run_ids) AND l.erasure_job_id=expected_job
            WHERE r.tenant_id=tenant AND r.conversation_id=conversation AND r.run_id=NEW.run_id) THEN
            RAISE EXCEPTION 'snapshot must belong to the exact covered Run' USING ERRCODE='23514';
        END IF;
    END IF;
    IF NEW.erasure_job_id IS NOT NULL AND NEW.erasure_job_id IS DISTINCT FROM expected_job THEN
        RAISE EXCEPTION 'private payload erasure requires its original Task coverage' USING ERRCODE='23514';
    END IF;
    IF expected_job IS NOT NULL AND NEW.erasure_job_id IS NULL THEN
        RAISE EXCEPTION 'erased private payload cannot be recreated' USING ERRCODE='23514';
    END IF;
    IF TG_OP='UPDATE' AND OLD.erasure_job_id IS NULL AND NEW.erasure_job_id IS NOT NULL THEN
        allowed:=CASE TG_TABLE_NAME
            WHEN 'runtime_snapshots' THEN ARRAY['encoded_snapshot','execution_grant_proof_schema',
                'execution_grant_proof','execution_grant_proof_hash','execution_grant_claims_hash','erasure_job_id']
            WHEN 'domain_events' THEN ARRAY['encoded_event','erasure_job_id']
            WHEN 'output_frames' THEN ARRAY['encoded_frame','erasure_job_id']
            WHEN 'snapshots' THEN ARRAY['encoded_snapshot','erasure_job_id']
            WHEN 'outbox' THEN ARRAY['payload','erasure_job_id','lease_owner','lease_expires_at_ms','lease_generation']
            ELSE ARRAY[]::TEXT[] END;
        IF (to_jsonb(NEW)-allowed) IS DISTINCT FROM (to_jsonb(OLD)-allowed) THEN
            RAISE EXCEPTION 'erasure must preserve private payload identities and hashes' USING ERRCODE='23514';
        END IF;
        IF TG_TABLE_NAME='outbox' THEN
            IF NEW.lease_generation<>OLD.lease_generation+1 THEN
                RAISE EXCEPTION 'erasure must fence the original outbox lease generation' USING ERRCODE='23514';
            END IF;
        END IF;
    END IF;
    IF TG_OP='UPDATE' AND OLD.erasure_job_id IS NOT NULL AND NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION 'erased private payload is immutable' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: guard_work_item_runtime_payload(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.guard_work_item_runtime_payload() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE target_run UUID; expected_job UUID; allowed TEXT[];
BEGIN
 CASE TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME
 WHEN 'tool.tool_results' THEN
  SELECT run_id INTO STRICT target_run FROM tool.tool_invocations WHERE invocation_id=NEW.invocation_id;
 WHEN 'approval.interaction_responses' THEN
  SELECT run_id INTO STRICT target_run FROM approval.interactions WHERE interaction_id=NEW.interaction_id;
 ELSE target_run:=NEW.run_id;
 END CASE;
 expected_job:=privacy_erasure.work_item_run_erasure(target_run);
 IF expected_job IS NULL THEN
  CASE TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME
   WHEN 'tool.tool_invocations','tool.tool_results' THEN expected_job:=privacy_erasure.work_item_source_command_job(NEW.invocation_id);
   WHEN 'approval.interaction_responses' THEN SELECT privacy_erasure.work_item_source_command_job(requested_by_invocation_id) INTO expected_job FROM approval.interactions WHERE interaction_id=NEW.interaction_id;
   WHEN 'runtime.pending_tool_calls' THEN expected_job:=privacy_erasure.work_item_call_job(NEW.run_id,NEW.tool_call_id);
   ELSE NULL;
  END CASE;
 END IF;
 IF TG_OP='INSERT' AND (NEW.erasure_job_id IS NOT NULL OR expected_job IS NOT NULL) THEN
  RAISE EXCEPTION 'erased Task cannot create new private execution payload' USING ERRCODE='23514';
 END IF;
 IF NEW.erasure_job_id IS NOT NULL AND NEW.erasure_job_id IS DISTINCT FROM expected_job THEN
  RAISE EXCEPTION 'private runtime erasure requires original frozen Task' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND OLD.erasure_job_id IS NOT NULL AND NEW IS DISTINCT FROM OLD THEN
  RAISE EXCEPTION 'private runtime tombstone cannot be changed' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND OLD.erasure_job_id IS NULL AND NEW.erasure_job_id IS NOT NULL THEN
  allowed:=CASE TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME
   WHEN 'runtime.runs' THEN ARRAY['terminal_error','erasure_job_id']
   WHEN 'runtime.model_invocations' THEN ARRAY['provider_request_ref','continuation_input_ref','continuation_output_ref','completion_intent_protected','terminal_error','erasure_job_id']
   WHEN 'tool.tool_invocations' THEN ARRAY['reconciliation_ref_protected','terminal_error','terminal_reason','erasure_job_id']
   WHEN 'tool.tool_results' THEN ARRAY['provider_request_ref','provider_request_ref_protected','erasure_job_id']
   WHEN 'approval.interaction_responses' THEN ARRAY['secure_response_ref','secure_response_ref_protected','erasure_job_id']
   WHEN 'runtime.pending_tool_calls' THEN ARRAY['arguments_json','argument_diagnostic_json','erasure_job_id']
   ELSE ARRAY[]::TEXT[] END;
  IF (to_jsonb(NEW)-allowed) IS DISTINCT FROM (to_jsonb(OLD)-allowed) THEN
   RAISE EXCEPTION 'private erasure cannot rewrite execution facts' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_source_model(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.guard_work_item_source_model() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='INSERT' AND NEW.context_erasure_job_id IS NOT NULL THEN RAISE EXCEPTION 'source model tombstone requires an existing invocation' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND OLD.context_erasure_job_id IS NOT NULL AND
   (NEW.context_erasure_job_id IS DISTINCT FROM OLD.context_erasure_job_id OR num_nonnulls(NEW.provider_request_ref,NEW.continuation_input_ref,NEW.continuation_output_ref,NEW.completion_intent_protected,NEW.terminal_error)<>0) THEN
  RAISE EXCEPTION 'source model continuation cannot be restored' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND OLD.context_erasure_job_id IS NULL AND NEW.context_erasure_job_id IS NOT NULL AND (
   NOT privacy_erasure.work_item_source_model_covered(OLD.invocation_id,NEW.context_erasure_job_id)
   OR (to_jsonb(NEW)-ARRAY['provider_request_ref','continuation_input_ref','continuation_output_ref','completion_intent_protected','terminal_error','context_erasure_job_id'])
    IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['provider_request_ref','continuation_input_ref','continuation_output_ref','completion_intent_protected','terminal_error','context_erasure_job_id'])) THEN
  RAISE EXCEPTION 'source model erasure requires exact Task cause and preserves other calls' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_work_item_version_erasure(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.guard_work_item_version_erasure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE tenant UUID; covered UUID[]; owned BOOLEAN;
BEGIN
 IF TG_OP='UPDATE' AND OLD.work_item_erasure_job_id IS NOT NULL THEN
  IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'erased version cannot be changed or restored' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.work_item_erasure_job_id IS NULL THEN RETURN NEW; END IF;
 IF TG_OP<>'UPDATE' THEN RAISE EXCEPTION 'erasure cannot fabricate a version' USING ERRCODE='23514'; END IF;
 IF (to_jsonb(NEW)-'work_item_erasure_job_id') IS DISTINCT FROM (to_jsonb(OLD)-'work_item_erasure_job_id') THEN
  RAISE EXCEPTION 'version erasure cannot change its identity or provenance' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_SCHEMA='artifact' THEN
  SELECT tenant_id INTO STRICT tenant FROM artifact.artifacts WHERE artifact_id=NEW.artifact_id;
 ELSE
  SELECT tenant_id INTO STRICT tenant FROM memory.memories WHERE memory_id=NEW.memory_id;
 END IF;
 SELECT l.execution_run_ids INTO covered FROM privacy_erasure.work_item_lineage l
  JOIN privacy_erasure.plans p USING(tenant_id,erasure_job_id)
  JOIN privacy_erasure.requests r USING(tenant_id,erasure_job_id)
  WHERE l.tenant_id=tenant AND l.erasure_job_id=NEW.work_item_erasure_job_id
   AND p.plan_version=2 AND p.lineage_fingerprint=l.execution_coverage_hash
   AND r.schema_version='musteragent.privacy.work-item-execution-erasure.v2';
 IF covered IS NULL THEN RAISE EXCEPTION 'version requires frozen Task erase coverage' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_SCHEMA='artifact' THEN
  SELECT EXISTS(SELECT 1 FROM tool.tool_invocations i WHERE i.invocation_id=NEW.source_invocation_id
    AND i.tenant_id=tenant AND i.run_id=ANY(covered)) INTO owned;
 ELSE
  SELECT (EXISTS(SELECT 1 FROM memory.memory_version_source_runs s WHERE s.memory_version_id=NEW.memory_version_id AND s.run_id=ANY(covered))
     OR EXISTS(SELECT 1 FROM memory.explicit_publications p JOIN tool.tool_invocations i ON i.invocation_id=p.tool_invocation_id
       WHERE p.memory_version_id=NEW.memory_version_id AND p.tenant_id=tenant AND i.tenant_id=tenant AND i.run_id=ANY(covered)))
   AND NOT EXISTS(SELECT 1 FROM memory.memory_version_source_runs s WHERE s.memory_version_id=NEW.memory_version_id AND NOT(s.run_id=ANY(covered)))
   AND NOT EXISTS(SELECT 1 FROM memory.memory_version_evidence_records e JOIN event_store.ledger_records r ON r.record_id=e.ledger_record_id
       WHERE e.memory_version_id=NEW.memory_version_id AND (r.run_id IS NULL OR NOT(r.run_id=ANY(covered))))
   AND NOT EXISTS(SELECT 1 FROM memory.explicit_publications p JOIN tool.tool_invocations i ON i.invocation_id=p.tool_invocation_id
       WHERE p.memory_version_id=NEW.memory_version_id AND (i.tenant_id<>tenant OR NOT(i.run_id=ANY(covered)))) INTO owned;
 END IF;
 IF NOT owned THEN RAISE EXCEPTION 'Task cannot erase another producers version' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: preserve_work_item_execution_coverage(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.preserve_work_item_execution_coverage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE actual UUID[];
BEGIN
 IF (to_jsonb(NEW)-ARRAY['execution_coverage_version','execution_run_ids','execution_content_refs',
    'execution_coverage_hash','execution_covered_at_ms','execution_source_invocation_ids'])
    IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['execution_coverage_version','execution_run_ids','execution_content_refs',
    'execution_coverage_hash','execution_covered_at_ms','execution_source_invocation_ids']) THEN
   RAISE EXCEPTION 'WorkItem execution coverage cannot rewrite accepted scope' USING ERRCODE='23514';
 END IF;
 IF OLD.execution_coverage_hash IS NOT NULL AND NEW IS DISTINCT FROM OLD THEN
   RAISE EXCEPTION 'frozen WorkItem erasure coverage is immutable' USING ERRCODE='23514';
 END IF;
 IF OLD.execution_coverage_hash IS NULL AND NEW.execution_coverage_hash IS NOT NULL THEN
   SELECT coalesce(array_agg(i.invocation_id ORDER BY i.invocation_id),'{}'::uuid[]) INTO actual
   FROM tool.tool_invocations i
   WHERE i.tenant_id=NEW.tenant_id AND i.run_id=ANY(NEW.execution_run_ids)
     AND i.tool_ref='sources.attachments.import@1';
   IF actual IS DISTINCT FROM coalesce(NEW.execution_source_invocation_ids,'{}'::uuid[]) THEN
     RAISE EXCEPTION 'Source producer coverage must be the complete original invocation set' USING ERRCODE='23514';
   END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: redact_resource_snapshot(jsonb, uuid); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.redact_resource_snapshot(snapshot jsonb, job uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE tenant UUID; runs UUID[]; output JSONB:=snapshot; name_owned BOOLEAN; sort_owned BOOLEAN;
BEGIN
 IF snapshot IS NULL THEN RETURN NULL; END IF;
 SELECT l.tenant_id,l.execution_run_ids INTO tenant,runs FROM privacy_erasure.work_item_lineage l
  JOIN privacy_erasure.plans p USING(tenant_id,erasure_job_id)
  WHERE l.erasure_job_id=job AND p.plan_version=2 AND p.lineage_fingerprint=l.execution_coverage_hash;
 IF runs IS NULL OR (snapshot->>'tenant_id')::UUID<>tenant THEN
  RAISE EXCEPTION 'resource snapshot erase requires exact frozen scope' USING ERRCODE='23514'; END IF;
 SELECT EXISTS(SELECT 1 FROM tool.tool_invocations i WHERE i.tenant_id=tenant AND i.run_id=ANY(runs)
   AND i.invocation_id=(snapshot->>'name_source_invocation_id')::UUID),
  EXISTS(SELECT 1 FROM tool.tool_invocations i WHERE i.tenant_id=tenant AND i.run_id=ANY(runs)
   AND i.invocation_id=(snapshot->>'source_invocation_id')::UUID) INTO name_owned,sort_owned;
 IF sort_owned AND COALESCE((snapshot->>'name_source_known')::BOOLEAN,false)=false THEN
  RAISE EXCEPTION 'legacy resource snapshot has no exact name producer' USING ERRCODE='23514'; END IF;
 IF name_owned THEN
  output:=output||jsonb_build_object('name','erased:'||(snapshot->>'node_id'),
    'comparison_name','erased:'||(snapshot->>'node_id'),'name_erasure_job_id',job);
 END IF;
 IF sort_owned THEN
  output:=output||jsonb_build_object('sort_key','erased:'||(snapshot->>'node_id'),'sort_key_erasure_job_id',job);
 END IF;
 RETURN output;
END $$;


--
-- Name: reject_erased_object_version(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.reject_erased_object_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_TABLE_SCHEMA='artifact' THEN
  IF EXISTS(SELECT 1 FROM artifact.artifacts WHERE artifact_id=NEW.artifact_id AND work_item_erasure_job_id IS NOT NULL) THEN
   RAISE EXCEPTION 'erased artifact cannot acquire another version'; END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM memory.memories WHERE memory_id=NEW.memory_id AND work_item_erasure_job_id IS NOT NULL) THEN
   RAISE EXCEPTION 'erased memory cannot acquire another version'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: reject_mutation(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.reject_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'privacy erasure facts are append-only';
END;
$$;


--
-- Name: resource_snapshot_has_run(jsonb, uuid, uuid[]); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.resource_snapshot_has_run(snapshot jsonb, tenant uuid, runs uuid[]) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT snapshot IS NOT NULL AND EXISTS(SELECT 1 FROM tool.tool_invocations i
  WHERE i.tenant_id=tenant AND i.run_id=ANY(runs) AND
   (i.invocation_id=(snapshot->>'name_source_invocation_id')::UUID
    OR i.invocation_id=(snapshot->>'source_invocation_id')::UUID))
$$;


--
-- Name: validate_plan_components(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.validate_plan_components() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    expected_classes SMALLINT;
    expected_exceptions SMALLINT;
    frozen_at BIGINT;
    actual_classes BIGINT;
    actual_exceptions BIGINT;
    invalid_exceptions BIGINT;
BEGIN
    SELECT data_class_count, retention_exception_count, frozen_at_ms
    INTO expected_classes, expected_exceptions, frozen_at
    FROM privacy_erasure.plans
    WHERE tenant_id = NEW.tenant_id
      AND erasure_job_id = NEW.erasure_job_id
      AND plan_version = NEW.plan_version;
    SELECT count(*) INTO actual_classes
    FROM privacy_erasure.plan_data_classes
    WHERE tenant_id = NEW.tenant_id
      AND erasure_job_id = NEW.erasure_job_id
      AND plan_version = NEW.plan_version;
    SELECT count(*), count(*) FILTER (WHERE expires_at_ms <= frozen_at)
    INTO actual_exceptions, invalid_exceptions
    FROM privacy_erasure.plan_retention_exceptions
    WHERE tenant_id = NEW.tenant_id
      AND erasure_job_id = NEW.erasure_job_id
      AND plan_version = NEW.plan_version;
    IF expected_classes IS NULL
        OR actual_classes <> expected_classes
        OR actual_exceptions <> expected_exceptions
        OR invalid_exceptions <> 0
    THEN
        RAISE EXCEPTION 'privacy erasure plan components are incomplete or invalid';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: validate_plan_version(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.validate_plan_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    latest_version BIGINT;
BEGIN
    PERFORM 1 FROM privacy_erasure.requests
    WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id
    FOR UPDATE;
    SELECT coalesce(max(plan_version), 0) INTO latest_version
    FROM privacy_erasure.plans
    WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id;
    IF NEW.plan_version <> latest_version + 1 THEN
        RAISE EXCEPTION 'privacy erasure plan version is not contiguous';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_receipt_components(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.validate_receipt_components() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    expected_completed SMALLINT;
    expected_exceptions SMALLINT;
    completed_at BIGINT;
    latest_version BIGINT;
    actual_completed BIGINT;
    actual_exceptions BIGINT;
    invalid_exception_count BIGINT;
    missing_class_count BIGINT;
    extra_class_count BIGINT;
    drifted_exception_count BIGINT;
BEGIN
    SELECT completed_data_class_count, retention_exception_count, completed_at_ms
    INTO expected_completed, expected_exceptions, completed_at
    FROM privacy_erasure.receipts
    WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id;
    SELECT max(plan_version) INTO latest_version FROM privacy_erasure.plans
    WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id;
    SELECT count(*) INTO actual_completed
    FROM privacy_erasure.receipt_completed_data_classes
    WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id;
    SELECT count(*), count(*) FILTER (WHERE expires_at_ms <= completed_at)
    INTO actual_exceptions, invalid_exception_count
    FROM privacy_erasure.receipt_retention_exceptions
    WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id;
    SELECT count(*) INTO missing_class_count
    FROM privacy_erasure.plan_data_classes planned
    WHERE planned.tenant_id = NEW.tenant_id
      AND planned.erasure_job_id = NEW.erasure_job_id
      AND planned.plan_version = latest_version
      AND NOT EXISTS (
          SELECT 1 FROM privacy_erasure.receipt_completed_data_classes completed
          WHERE completed.tenant_id = planned.tenant_id
            AND completed.erasure_job_id = planned.erasure_job_id
            AND completed.data_class = planned.data_class
      )
      AND NOT EXISTS (
          SELECT 1 FROM privacy_erasure.receipt_retention_exceptions retained
          WHERE retained.tenant_id = planned.tenant_id
            AND retained.erasure_job_id = planned.erasure_job_id
            AND retained.data_class = planned.data_class
      );
    SELECT count(*) INTO extra_class_count FROM (
        SELECT data_class FROM privacy_erasure.receipt_completed_data_classes
        WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id
        UNION ALL
        SELECT data_class FROM privacy_erasure.receipt_retention_exceptions
        WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id
    ) receipt_class
    WHERE NOT EXISTS (
        SELECT 1 FROM privacy_erasure.plan_data_classes planned
        WHERE planned.tenant_id = NEW.tenant_id
          AND planned.erasure_job_id = NEW.erasure_job_id
          AND planned.plan_version = latest_version
          AND planned.data_class = receipt_class.data_class
    );
    SELECT count(*) INTO drifted_exception_count
    FROM privacy_erasure.receipt_retention_exceptions receipt_exception
    FULL JOIN (SELECT * FROM privacy_erasure.plan_retention_exceptions
               WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id
                 AND plan_version = latest_version) plan_exception
      ON plan_exception.tenant_id = receipt_exception.tenant_id
     AND plan_exception.erasure_job_id = receipt_exception.erasure_job_id
     AND plan_exception.data_class = receipt_exception.data_class
    WHERE coalesce(receipt_exception.tenant_id, plan_exception.tenant_id) = NEW.tenant_id
      AND coalesce(receipt_exception.erasure_job_id, plan_exception.erasure_job_id) = NEW.erasure_job_id
      AND (
          receipt_exception.data_class IS NULL
          OR plan_exception.data_class IS NULL
          OR receipt_exception.policy_ref <> plan_exception.policy_ref
          OR receipt_exception.owner_principal_id <> plan_exception.owner_principal_id
          OR receipt_exception.expires_at_ms <> plan_exception.expires_at_ms
      );
    IF expected_completed IS NULL
        OR actual_completed <> expected_completed
        OR actual_exceptions <> expected_exceptions
        OR invalid_exception_count <> 0
        OR missing_class_count <> 0
        OR extra_class_count <> 0
        OR drifted_exception_count <> 0
    THEN
        RAISE EXCEPTION 'privacy erasure receipt coverage or retention proof is invalid';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: validate_receipt_header(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.validate_receipt_header() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    latest_plan_hash BYTEA;
    latest_frozen_at BIGINT;
    latest_status SMALLINT;
BEGIN
    PERFORM 1 FROM privacy_erasure.requests
    WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id
    FOR UPDATE;
    SELECT plan_hash, frozen_at_ms INTO latest_plan_hash, latest_frozen_at
    FROM privacy_erasure.plans
    WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id
    ORDER BY plan_version DESC LIMIT 1;
    SELECT status INTO latest_status FROM privacy_erasure.transitions
    WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id
    ORDER BY sequence DESC LIMIT 1;
    IF latest_plan_hash IS NULL
        OR latest_plan_hash <> NEW.plan_hash
        OR NEW.completed_at_ms < latest_frozen_at
        OR (NEW.outcome = 1 AND latest_status <> 7)
        OR (NEW.outcome = 2 AND latest_status <> 8)
    THEN
        RAISE EXCEPTION 'privacy erasure receipt header does not match plan and terminal state';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_request_roots(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.validate_request_roots() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    expected_count SMALLINT;
    actual_count BIGINT;
    minimum_ordinal SMALLINT;
    maximum_ordinal SMALLINT;
BEGIN
    SELECT root_resource_count INTO expected_count
    FROM privacy_erasure.requests
    WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id;
    SELECT count(*), min(ordinal), max(ordinal)
    INTO actual_count, minimum_ordinal, maximum_ordinal
    FROM privacy_erasure.root_resources
    WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id;
    IF expected_count IS NULL
        OR actual_count <> expected_count
        OR minimum_ordinal <> 0
        OR maximum_ordinal <> expected_count - 1
    THEN
        RAISE EXCEPTION 'privacy erasure root set is incomplete or non-contiguous';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: validate_terminal_receipt(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.validate_terminal_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    receipt_count BIGINT;
BEGIN
    IF NEW.status NOT IN (7, 8) THEN
        RETURN NULL;
    END IF;
    SELECT count(*) INTO receipt_count FROM privacy_erasure.receipts
    WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id;
    IF receipt_count <> 1 THEN
        RAISE EXCEPTION 'privacy erasure terminal transition requires one atomic receipt';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: validate_transition(); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.validate_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    request_time BIGINT;
    previous_sequence BIGINT;
    previous_status SMALLINT;
    previous_time BIGINT;
    plan_count BIGINT;
BEGIN
    PERFORM 1 FROM privacy_erasure.requests
    WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id
    FOR UPDATE;
    SELECT requested_at_ms INTO request_time
    FROM privacy_erasure.requests
    WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id;
    SELECT sequence, status, occurred_at_ms
    INTO previous_sequence, previous_status, previous_time
    FROM privacy_erasure.transitions
    WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id
    ORDER BY sequence DESC LIMIT 1;
    IF previous_sequence IS NULL THEN
        IF NEW.sequence <> 1 OR NEW.status <> 1 OR NEW.occurred_at_ms < request_time THEN
            RAISE EXCEPTION 'privacy erasure initial transition is invalid';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.sequence <> previous_sequence + 1 OR NEW.occurred_at_ms < previous_time THEN
        RAISE EXCEPTION 'privacy erasure transition sequence or time is invalid';
    END IF;
    IF NOT (
        (previous_status = 1 AND NEW.status = 2)
        OR (previous_status = 2 AND NEW.status = 3)
        OR (previous_status = 3 AND NEW.status = 4)
        OR (previous_status = 4 AND NEW.status IN (5, 6, 7, 8))
        OR (previous_status = 5 AND NEW.status IN (4, 7, 8))
        OR (previous_status = 6 AND NEW.status = 4)
    ) THEN
        RAISE EXCEPTION 'privacy erasure state transition is invalid';
    END IF;
    IF NEW.status IN (2, 3, 4, 5, 6, 7, 8) THEN
        SELECT count(*) INTO plan_count FROM privacy_erasure.plans
        WHERE tenant_id = NEW.tenant_id AND erasure_job_id = NEW.erasure_job_id;
        IF plan_count = 0 THEN
            RAISE EXCEPTION 'privacy erasure transition requires an immutable plan';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: work_item_call_job(uuid, text); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.work_item_call_job(run uuid, call text) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
 SELECT privacy_erasure.work_item_source_command_job(i.invocation_id) FROM tool.tool_invocations i WHERE i.run_id=run AND i.tool_call_id=call
$$;


--
-- Name: work_item_execution_job(uuid, uuid); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.work_item_execution_job(tenant uuid, conversation uuid) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
    SELECT l.erasure_job_id
    FROM (
      SELECT tenant_id,owner_id,work_item_id,conversation_id,run_id,goal_revision,control_revision,assignment_epoch
      FROM collaboration.work_item_execution_reservations
      UNION ALL
      SELECT tenant_id,owner_id,work_item_id,report_conversation_id,report_run_id,goal_revision,control_revision,assignment_epoch
      FROM collaboration.work_item_execution_reports
    ) x
    JOIN collaboration.work_items t ON t.work_item_id=x.work_item_id AND t.tenant_id=x.tenant_id AND t.owner_id=x.owner_id
    JOIN privacy_erasure.work_item_lineage l ON l.tenant_id=t.tenant_id AND l.work_item_id=t.work_item_id AND l.erasure_job_id=t.erasure_job_id
    JOIN privacy_erasure.requests request ON request.tenant_id=l.tenant_id AND request.erasure_job_id=l.erasure_job_id
      AND request.schema_version='musteragent.privacy.work-item-execution-erasure.v2'
    JOIN privacy_erasure.plans plan ON plan.tenant_id=l.tenant_id AND plan.erasure_job_id=l.erasure_job_id
      AND plan.plan_version=2 AND plan.lineage_fingerprint=l.execution_coverage_hash
    LEFT JOIN runtime.runs r ON r.run_id=x.run_id
    WHERE x.tenant_id=tenant AND x.conversation_id=conversation
      AND x.run_id=ANY(l.execution_run_ids) AND l.execution_coverage_hash IS NOT NULL
      AND NOT EXISTS(SELECT 1 FROM runtime.leases lease WHERE lease.run_id=x.run_id)
      AND ((r.run_id IS NULL AND NOT EXISTS(SELECT 1 FROM runtime.runs foreign_run WHERE foreign_run.conversation_id=x.conversation_id))
       OR (r.tenant_id=x.tenant_id AND r.conversation_id=x.conversation_id AND r.status IN (5,6,7)
        AND EXISTS(SELECT 1 FROM agent.dialogue_sessions s WHERE s.tenant_id=x.tenant_id AND s.owner_id=x.owner_id
          AND s.conversation_id=x.conversation_id AND s.work_item_id=x.work_item_id
          AND s.subject_kind IN ('work_item','work_item_report') AND s.work_item_goal_revision=x.goal_revision
          AND s.work_item_control_revision=x.control_revision AND s.work_item_assignment_epoch=x.assignment_epoch)))
$$;


--
-- Name: work_item_run_erasure(uuid); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.work_item_run_erasure(run uuid) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
 SELECT privacy_erasure.work_item_execution_job(r.tenant_id,r.conversation_id)
 FROM runtime.runs r WHERE r.run_id=run
$$;


--
-- Name: work_item_source_command_job(uuid); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.work_item_source_command_job(invocation uuid) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
 SELECT l.erasure_job_id FROM privacy_erasure.work_item_lineage l
 JOIN privacy_erasure.plans p ON p.tenant_id=l.tenant_id AND p.erasure_job_id=l.erasure_job_id
   AND p.plan_version=2 AND p.lineage_fingerprint=l.execution_coverage_hash
 JOIN tool.tool_invocations i ON i.invocation_id=invocation AND i.tenant_id=l.tenant_id
 WHERE i.status=4 AND l.execution_coverage_hash IS NOT NULL AND (
   EXISTS(SELECT 1 FROM collaboration.work_item_execution_reservations x WHERE x.work_item_id=l.work_item_id AND x.tenant_id=l.tenant_id AND x.owner_id=l.owner_id AND x.source_invocation_id=i.invocation_id AND x.source_run_id=i.run_id)
   OR EXISTS(SELECT 1 FROM collaboration.work_item_commands c WHERE c.work_item_id=l.work_item_id AND c.tenant_id=l.tenant_id AND c.owner_id=l.owner_id AND c.source_invocation_id=i.invocation_id AND c.source_run_id=i.run_id))
$$;


--
-- Name: work_item_source_model_covered(uuid, uuid); Type: FUNCTION; Schema: privacy_erasure; Owner: -
--

CREATE FUNCTION privacy_erasure.work_item_source_model_covered(invocation uuid, job uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM runtime.model_invocations m
 JOIN privacy_erasure.work_item_lineage l ON l.tenant_id=m.tenant_id AND l.erasure_job_id=job AND l.execution_coverage_hash IS NOT NULL
 JOIN tool.tool_invocations i ON i.tenant_id=m.tenant_id AND i.run_id=m.run_id
 JOIN runtime.pending_tool_calls call ON call.run_id=i.run_id AND call.tool_call_id=i.tool_call_id
 JOIN runtime.model_invocations producer ON producer.invocation_id=call.invocation_id
 WHERE m.invocation_id=invocation AND m.status<>1 AND m.started_at_ms<=l.execution_covered_at_ms
 AND (m.started_conversation_seq>=producer.started_conversation_seq
      OR EXISTS(SELECT 1 FROM runtime.context_compaction_slots slot WHERE slot.invocation_id=m.invocation_id
        AND slot.tenant_id=m.tenant_id AND slot.run_id=m.run_id AND slot.source_sequence_to>producer.started_conversation_seq))
 AND privacy_erasure.work_item_source_command_job(i.invocation_id)=job)
 OR EXISTS(SELECT 1 FROM runtime.model_invocations m
 JOIN privacy_erasure.work_item_lineage l ON l.tenant_id=m.tenant_id AND l.erasure_job_id=job AND l.execution_coverage_hash IS NOT NULL
 WHERE m.invocation_id=invocation AND m.status<>1 AND m.started_at_ms<=l.execution_covered_at_ms AND (
   EXISTS(SELECT 1 FROM runtime.dialogue_context_bindings b WHERE b.tenant_id=m.tenant_id AND b.run_id=m.run_id AND b.erasure_job_id=job)
   OR EXISTS(SELECT 1 FROM agent.dialogue_context_checkpoints c WHERE c.tenant_id=m.tenant_id AND c.generator_invocation_id=m.invocation_id AND c.erasure_job_id=job)))
 OR EXISTS(SELECT 1 FROM runtime.model_invocations m
 JOIN privacy_erasure.work_item_lineage l ON l.tenant_id=m.tenant_id AND l.erasure_job_id=job AND l.execution_coverage_hash IS NOT NULL
 JOIN privacy_erasure.plans plan ON plan.tenant_id=l.tenant_id AND plan.erasure_job_id=l.erasure_job_id
   AND plan.plan_version=2 AND plan.lineage_fingerprint=l.execution_coverage_hash
 JOIN runtime.runs r ON r.run_id=m.run_id AND r.tenant_id=m.tenant_id
 JOIN capability.runtime_snapshots snap ON snap.run_id=r.run_id AND snap.tenant_id=r.tenant_id
 JOIN capability.runtime_snapshot_content_references refs ON refs.runtime_snapshot_id=snap.runtime_snapshot_id
 JOIN collaboration.work_item_execution_reports report ON report.tenant_id=l.tenant_id AND report.work_item_id=l.work_item_id
   AND report.owner_id=l.owner_id AND report.report_content_id=refs.content_id
 WHERE m.invocation_id=invocation AND m.status<>1 AND m.started_at_ms<=l.execution_covered_at_ms
   AND r.status IN (5,6,7) AND NOT EXISTS(SELECT 1 FROM runtime.leases lease WHERE lease.run_id=r.run_id))
$$;


--
-- Name: capture_conversation_catalog_pursuit_run(); Type: FUNCTION; Schema: projection; Owner: -
--

CREATE FUNCTION projection.capture_conversation_catalog_pursuit_run() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.active_run_id IS NOT NULL THEN
        INSERT INTO projection.conversation_catalog_pursuit_runs(tenant_id, pursuit_id, run_id)
