--
-- Name: enqueue_search_index_job(); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.enqueue_search_index_job() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    version_id_value UUID;
    tenant_id_value UUID;
    scope_kind_value SMALLINT;
    scope_id_value UUID;
    node_id_value UUID;
    artifact_id_value UUID;
    now_ms BIGINT := floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint;
BEGIN
    IF TG_TABLE_SCHEMA = 'resource' THEN
        IF NEW.kind <> 2 OR NEW.file_artifact_id IS NULL THEN
            RETURN NEW;
        END IF;
        SELECT version_row.artifact_version_id,
               NEW.tenant_id,
               NEW.scope_kind,
               NEW.scope_id,
               NEW.node_id,
               NEW.file_artifact_id
          INTO version_id_value, tenant_id_value, scope_kind_value,
               scope_id_value, node_id_value, artifact_id_value
          FROM artifact.artifacts AS artifact_row
          JOIN artifact.artifact_versions AS version_row
            ON version_row.artifact_id = artifact_row.artifact_id
           AND version_row.version = artifact_row.current_version
         WHERE artifact_row.artifact_id = NEW.file_artifact_id;
        IF NOT FOUND THEN
            RETURN NEW;
        END IF;
    ELSE
        SELECT NEW.artifact_version_id, node.tenant_id, node.scope_kind,
               node.scope_id, node.node_id, node.file_artifact_id
          INTO version_id_value, tenant_id_value, scope_kind_value,
               scope_id_value, node_id_value, artifact_id_value
          FROM resource.nodes AS node
         WHERE node.file_artifact_id = NEW.artifact_id;
        IF NOT FOUND THEN
            RETURN NEW;
        END IF;
    END IF;

    INSERT INTO resource.search_index_jobs (
        artifact_version_id, tenant_id, scope_kind, scope_id, node_id,
        artifact_id, status, available_at_ms, created_at_ms, updated_at_ms
    ) VALUES (
        version_id_value, tenant_id_value, scope_kind_value, scope_id_value,
        node_id_value, artifact_id_value,
        1, now_ms, now_ms, now_ms
    )
    ON CONFLICT (artifact_version_id) DO NOTHING;
    RETURN NEW;
END
$$;


--
-- Name: freeze_receipt_node(); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.freeze_receipt_node() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE job UUID;
BEGIN
 IF TG_OP='UPDATE' AND OLD.result_node_snapshot IS NOT NULL THEN
  IF NEW.result_node_snapshot IS DISTINCT FROM OLD.result_node_snapshot THEN
   IF (to_jsonb(NEW)-'result_node_snapshot') IS DISTINCT FROM (to_jsonb(OLD)-'result_node_snapshot')
      OR NEW.result_node_snapshot IS NULL THEN
    RAISE EXCEPTION 'resource receipt erasure cannot change operation identity' USING ERRCODE='23514'; END IF;
   IF (NEW.result_node_snapshot->'name_erasure_job_id') IS DISTINCT FROM (OLD.result_node_snapshot->'name_erasure_job_id') THEN
    job:=(NEW.result_node_snapshot->>'name_erasure_job_id')::UUID;
   ELSE job:=(NEW.result_node_snapshot->>'sort_key_erasure_job_id')::UUID; END IF;
   IF job IS NULL OR NEW.result_node_snapshot IS DISTINCT FROM
       privacy_erasure.redact_resource_snapshot(OLD.result_node_snapshot,job) THEN
    RAISE EXCEPTION 'resource receipt can only redact its original producer fields' USING ERRCODE='23514'; END IF;
  ELSIF NEW.result_node_id IS DISTINCT FROM OLD.result_node_id
    OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
    OR NEW.scope_kind IS DISTINCT FROM OLD.scope_kind OR NEW.scope_id IS DISTINCT FROM OLD.scope_id THEN
   RAISE EXCEPTION 'resource receipt node is immutable';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.result_node_id IS NOT NULL THEN
  SELECT to_jsonb(node) INTO NEW.result_node_snapshot FROM resource.nodes node
   WHERE node.node_id=NEW.result_node_id AND node.tenant_id=NEW.tenant_id
    AND node.scope_kind=NEW.scope_kind AND node.scope_id=NEW.scope_id;
  IF NEW.result_node_snapshot IS NULL THEN RAISE EXCEPTION 'new resource receipt must reference the current scope'; END IF;
 ELSE NEW.result_node_snapshot:=NULL; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_node_history_identity(); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.guard_node_history_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.node_id IS DISTINCT FROM OLD.node_id
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.file_artifact_id IS DISTINCT FROM OLD.file_artifact_id THEN
        RAISE EXCEPTION 'resource node historical identity cannot be rebound';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: guard_device_command(); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.guard_device_command() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Device Resource command is immutable'; END IF;
 -- PostgreSQL computes stored generated columns after BEFORE triggers. Compare
 -- their immutable inputs (admission_kind and intent_id), not NEW's unfinished
 -- intent_admission_id projection; otherwise every legitimate receipt fails.
 IF TG_OP='UPDATE' AND (OLD.committed_at_ms IS NOT NULL OR
  (to_jsonb(NEW)-ARRAY['result_content_id','receipt_content_id','receipt_commitment','committed_at_ms','outcome','intent_admission_id']) IS DISTINCT FROM
  (to_jsonb(OLD)-ARRAY['result_content_id','receipt_content_id','receipt_commitment','committed_at_ms','outcome','intent_admission_id'])) THEN
  RAISE EXCEPTION 'Device Resource command is immutable'; END IF;
 IF NEW.admission_kind='intent' THEN
  IF NOT EXISTS(SELECT 1 FROM agent.device_admissions d WHERE d.intent_id=NEW.intent_id
   AND d.tenant_id=NEW.tenant_id AND d.owner_id=NEW.owner_id AND d.agent_id=NEW.agent_id
   AND d.dialogue_id=NEW.dialogue_id AND d.run_id=NEW.run_id AND d.conversation_id=NEW.conversation_id
   AND d.device_id=NEW.device_id AND d.installation_id=NEW.installation_id AND d.admitted_at_ms IS NOT NULL) THEN
   RAISE EXCEPTION 'Resource command has no original Device Intent admission' USING ERRCODE='23514'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM collaboration.work_item_device_custody d
   JOIN collaboration.work_item_execution_reservations x USING(work_item_id,goal_revision,control_revision,assignment_epoch)
   JOIN collaboration.work_item_device_targets target USING(work_item_id,goal_revision,control_revision,assignment_epoch)
   JOIN collaboration.work_items t ON t.work_item_id=x.work_item_id JOIN agent.owned_agents a ON a.agent_id=x.executing_agent_id
   WHERE d.run_id=NEW.work_item_run_id AND d.run_id=NEW.run_id AND d.conversation_id=NEW.conversation_id
   AND x.tenant_id=NEW.tenant_id AND x.owner_id=NEW.owner_id AND x.executing_agent_id=NEW.agent_id
   AND a.dialogue_id=NEW.dialogue_id AND t.source_intent_id=NEW.intent_id AND d.admitted_snapshot_hash IS NOT NULL
   AND target.device_id=NEW.device_id AND target.installation_id=NEW.installation_id) THEN
   RAISE EXCEPTION 'Resource command has no original Device Task admission' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_dialogue_noop_checkpoint_release(); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.guard_dialogue_noop_checkpoint_release() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND OLD.checkpoint_content_id IS NULL THEN
   IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'completed no-op edit cannot resume' USING ERRCODE='23514'; END IF;
   RETURN NEW;
 END IF;
 IF NEW.checkpoint_content_id IS NOT NULL THEN RETURN NEW; END IF;
 IF TG_OP<>'UPDATE' OR (to_jsonb(NEW)-ARRAY['checkpoint_content_id','checkpoint_media_type','checkpoint_byte_length','checkpoint_hash'])
    IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['checkpoint_content_id','checkpoint_media_type','checkpoint_byte_length','checkpoint_hash'])
    OR NOT EXISTS (
     SELECT 1 FROM resource.edit_terminal_commands receipt
     JOIN artifact.artifact_versions version ON version.artifact_version_id=receipt.result_artifact_version_id
      AND version.artifact_id=receipt.result_artifact_id AND version.version=receipt.result_file_version
     WHERE receipt.tenant_id=NEW.tenant_id AND receipt.session_id=NEW.session_id AND receipt.operation=1
      AND receipt.resulting_state=3 AND receipt.result_artifact_id=NEW.file_artifact_id
      AND receipt.result_file_version=NEW.base_version
      AND version.content_id=OLD.checkpoint_content_id AND version.content_hash=OLD.checkpoint_hash
      AND NEW.state=3 AND NEW.agent_dialogue_id IS NOT NULL AND NEW.source_invocation_id IS NULL
      AND NOT EXISTS(SELECT 1 FROM resource.edit_operations o WHERE o.tenant_id=NEW.tenant_id AND o.session_id=NEW.session_id)) THEN
    RAISE EXCEPTION 'checkpoint release requires exact completed Dialogue no-op receipt' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


