--
-- Name: guard_workspace_authority(); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.guard_workspace_authority() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'resource workspace authority is retained';
    END IF;
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
       OR NEW.authority_generation < OLD.authority_generation
       OR (OLD.status = 2 AND NEW.status = 1) THEN
        RAISE EXCEPTION 'resource workspace authority transition is invalid';
    END IF;
    RETURN NEW;
END
$$;


