    AS $$
BEGIN NEW.name_source_known:=true; NEW.name_source_invocation_id:=NEW.source_invocation_id; RETURN NEW; END $$;


--
-- Name: account_file_owned(uuid, uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.account_file_owned(p_tenant uuid, p_owner uuid, p_agent uuid, p_dialogue uuid, p_entry uuid, p_artifact uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS (
  SELECT 1 FROM resource.edit_sessions edit
  JOIN resource.edit_terminal_commands receipt ON receipt.tenant_id=edit.tenant_id
   AND receipt.session_id=edit.session_id AND receipt.operation=1 AND receipt.resulting_state=3
  JOIN artifact.artifact_versions version ON version.artifact_version_id=receipt.result_artifact_version_id
   AND version.artifact_id=receipt.result_artifact_id AND version.version=receipt.result_file_version
  JOIN resource.nodes node ON node.tenant_id=edit.tenant_id AND node.node_id=edit.file_node_id
   AND node.file_artifact_id=edit.file_artifact_id AND node.scope_kind=4 AND node.scope_id=edit.scope_id
  JOIN agent.owned_agents agent ON agent.agent_id=edit.scope_id AND agent.dialogue_id=edit.agent_dialogue_id
  JOIN agent.owner_spaces space ON space.space_id=agent.space_id AND space.tenant_id=edit.tenant_id
   AND space.owner_id=edit.owner_principal_id AND space.product='musteragent'
  JOIN agent.agent_dialogue_entries entry ON entry.tenant_id=edit.tenant_id
   AND entry.owner_id=edit.owner_principal_id AND entry.dialogue_id=edit.agent_dialogue_id
   AND entry.entry_id=edit.dialogue_entry_id AND entry.artifact_id=edit.file_artifact_id
  WHERE edit.tenant_id=p_tenant AND edit.owner_principal_id=p_owner AND edit.scope_kind=4
   AND edit.scope_id=p_agent AND edit.agent_dialogue_id=p_dialogue AND edit.dialogue_entry_id=p_entry
   AND edit.file_artifact_id=p_artifact AND edit.state=3 AND edit.source_invocation_id IS NULL
   AND edit.work_item_erasure_job_id IS NULL
   AND receipt.result_artifact_id=edit.file_artifact_id AND receipt.result_file_version>edit.base_version
   AND version.source_invocation_id IS NULL AND version.committed_by_principal_id=p_owner
   AND version.work_item_erasure_job_id IS NULL AND node.lifecycle=1 AND agent.status='active'
   AND entry.kind IN ('artifact','erased')
   AND resource.agent_artifact_owned(p_tenant,p_agent,p_artifact)
 )
$$;


--
-- Name: agent_artifact_owned(uuid, uuid, uuid); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.agent_artifact_owned(p_tenant uuid, p_agent uuid, p_artifact uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT resource.agent_artifact_owned_before_canonical_device(p_tenant,p_agent,p_artifact) OR EXISTS(
 SELECT 1 FROM artifact.device_resource_versions p JOIN resource.device_commands c USING(invocation_id)
 JOIN artifact.artifacts a ON a.artifact_id=p.artifact_id AND a.tenant_id=c.tenant_id
 JOIN resource.nodes n ON n.file_artifact_id=a.artifact_id AND n.tenant_id=c.tenant_id AND n.scope_kind=4 AND n.scope_id=c.agent_id AND n.lifecycle=1
 WHERE c.tenant_id=p_tenant AND c.agent_id=p_agent AND a.artifact_id=p_artifact) OR EXISTS(SELECT 1 FROM artifact.work_item_result_asset_returns r JOIN artifact.artifacts a ON a.artifact_id=r.artifact_id AND a.tenant_id=r.tenant_id AND a.lifecycle IN(1,2)
    WHERE r.tenant_id=p_tenant AND r.producer_id=p_agent AND r.artifact_id=p_artifact AND artifact.verified_task_native_version_owned(r.tenant_id,r.owner_id,r.producer_id,r.artifact_id,r.version_id)
      AND ((a.kind=4 AND NOT EXISTS(SELECT 1 FROM resource.nodes n WHERE n.file_artifact_id=a.artifact_id)) OR EXISTS(SELECT 1 FROM resource.nodes n WHERE n.file_artifact_id=a.artifact_id AND n.tenant_id=r.tenant_id AND n.scope_kind=4 AND n.scope_id=r.producer_id AND n.lifecycle=1)))
$$;


--
-- Name: agent_artifact_owned_before_canonical_device(uuid, uuid, uuid); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.agent_artifact_owned_before_canonical_device(p_tenant uuid, p_agent uuid, p_artifact uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM artifact.artifacts a
   JOIN agent.dialogue_sessions origin ON origin.tenant_id=a.tenant_id AND origin.conversation_id=a.conversation_id
   JOIN agent.owned_agents agent ON agent.agent_id=origin.agent_id AND agent.dialogue_id=origin.dialogue_id
   JOIN agent.owner_spaces space ON space.space_id=agent.space_id AND space.tenant_id=origin.tenant_id AND space.owner_id=origin.owner_id
   WHERE a.tenant_id=p_tenant AND a.artifact_id=p_artifact AND origin.agent_id=p_agent
     AND space.product='musteragent' AND (
       (origin.subject_kind='intent' AND origin.purpose='intent_coordination') OR
       (origin.subject_kind='work_item' AND origin.purpose='work_item_execution' AND EXISTS(
         SELECT 1 FROM collaboration.work_item_execution_reservations x JOIN runtime.runs r ON r.run_id=x.run_id
         WHERE x.work_item_id=origin.work_item_id AND x.goal_revision=origin.work_item_goal_revision
         AND x.control_revision=origin.work_item_control_revision AND x.assignment_epoch=origin.work_item_assignment_epoch
         AND x.tenant_id=origin.tenant_id AND x.owner_id=origin.owner_id AND x.executing_agent_id=origin.agent_id
         AND x.executing_dialogue_id=origin.dialogue_id AND x.conversation_id=origin.conversation_id
         AND r.tenant_id=origin.tenant_id AND r.conversation_id=origin.conversation_id)) OR
       (origin.subject_kind='work_item_report' AND origin.purpose='work_item_report' AND EXISTS(
         SELECT 1 FROM collaboration.work_item_execution_reports p JOIN runtime.runs r ON r.run_id=p.report_run_id
         WHERE p.producing_run_id=origin.report_from_run_id AND p.work_item_id=origin.work_item_id
         AND p.goal_revision=origin.work_item_goal_revision AND p.control_revision=origin.work_item_control_revision
         AND p.assignment_epoch=origin.work_item_assignment_epoch AND p.tenant_id=origin.tenant_id
         AND p.owner_id=origin.owner_id AND p.requesting_agent_id=origin.agent_id AND p.source_dialogue_id=origin.dialogue_id
         AND p.report_conversation_id=origin.conversation_id AND r.tenant_id=origin.tenant_id AND r.conversation_id=origin.conversation_id)))
     AND (NOT EXISTS(SELECT 1 FROM resource.file_versions f WHERE f.artifact_id=a.artifact_id)
       OR EXISTS(SELECT 1 FROM resource.nodes n WHERE n.tenant_id=a.tenant_id AND n.file_artifact_id=a.artifact_id
         AND n.scope_kind=4 AND n.scope_id=p_agent AND n.kind=2 AND n.lifecycle=1)))
 OR EXISTS(SELECT 1 FROM artifact.artifacts a
  JOIN artifact.device_versions proof ON proof.artifact_id=a.artifact_id AND proof.tenant_id=a.tenant_id
  JOIN agent.owned_agents agent ON agent.agent_id=proof.agent_id AND agent.dialogue_id=proof.dialogue_id
  JOIN agent.owner_spaces space ON space.space_id=agent.space_id AND space.tenant_id=proof.tenant_id AND space.owner_id=proof.owner_id
  WHERE a.tenant_id=p_tenant AND a.artifact_id=p_artifact AND proof.agent_id=p_agent AND space.product='musteragent'
   AND artifact.device_version_owned(p_tenant,proof.owner_id,p_agent,p_artifact,proof.artifact_version_id)
   AND ((a.kind=4 AND NOT EXISTS(SELECT 1 FROM resource.file_versions f WHERE f.artifact_id=a.artifact_id))
     OR EXISTS(SELECT 1 FROM resource.nodes n WHERE n.tenant_id=a.tenant_id AND n.file_artifact_id=a.artifact_id
       AND n.scope_kind=4 AND n.scope_id=p_agent AND n.kind=2 AND n.lifecycle=1)))
$$;


--
-- Name: agent_edit_version_authorized(uuid, uuid, uuid, numeric, uuid, bytea); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.agent_edit_version_authorized(p_tenant uuid, p_artifact uuid, p_principal uuid, p_version numeric, p_content uuid, p_hash bytea) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS (SELECT 1 FROM resource.edit_sessions edit
                JOIN agent.agent_dialogue_entries entry ON entry.tenant_id=edit.tenant_id
                  AND entry.owner_id=edit.owner_principal_id AND entry.dialogue_id=edit.agent_dialogue_id
                  AND entry.entry_id=edit.dialogue_entry_id AND entry.artifact_id=p_artifact
                  AND (entry.kind='artifact' OR (entry.kind='erased' AND resource.account_file_owned(
                    edit.tenant_id,edit.owner_principal_id,edit.scope_id,edit.agent_dialogue_id,edit.dialogue_entry_id,p_artifact)))
                JOIN agent.owned_agents agent ON agent.agent_id=edit.scope_id AND agent.dialogue_id=entry.dialogue_id
                JOIN agent.owner_spaces space ON space.space_id=agent.space_id
                  AND space.tenant_id=edit.tenant_id AND space.owner_id=edit.owner_principal_id
                JOIN resource.nodes node ON node.node_id=edit.file_node_id AND node.tenant_id=edit.tenant_id
                  AND node.file_artifact_id=p_artifact AND node.scope_kind=4 AND node.scope_id=agent.agent_id
                WHERE edit.tenant_id=p_tenant AND edit.file_artifact_id=p_artifact
                  AND edit.owner_principal_id=p_principal AND edit.source_invocation_id IS NULL
                  AND edit.dialogue_entry_id IS NOT NULL AND edit.state=1 AND edit.work_item_erasure_job_id IS NULL
                  AND edit.checkpoint_content_id=p_content AND edit.checkpoint_hash=p_hash
                  AND p_version=edit.base_version+1
                  AND agent.status='active' AND space.product='musteragent' AND node.lifecycle=1
                  AND resource.agent_artifact_owned(p_tenant,agent.agent_id,p_artifact))
$$;


--
-- Name: project_receipt_node(jsonb, boolean); Type: FUNCTION; Schema: resource; Owner: -
