--
-- Name: record_scope_history(); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.record_scope_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE previous_generation BIGINT; assignment UUID;
BEGIN
    SELECT max(ownership_generation) INTO previous_generation FROM resource.scope_history
    WHERE tenant_id = NEW.tenant_id AND node_id = NEW.node_id;
    IF previous_generation IS NULL THEN
        INSERT INTO resource.scope_history (tenant_id,scope_kind,scope_id,node_id,file_artifact_id,
            ownership_generation,evidence_source,created_at_ms,updated_at_ms)
        VALUES(NEW.tenant_id,NEW.scope_kind,NEW.scope_id,NEW.node_id,NEW.file_artifact_id,
            1,1,NEW.created_at_ms,NEW.updated_at_ms);
    ELSIF (NEW.scope_kind,NEW.scope_id) IS DISTINCT FROM (OLD.scope_kind,OLD.scope_id) THEN
        IF OLD.scope_kind=2 AND NEW.scope_kind=4 AND EXISTS (
            SELECT 1 FROM resource.owned_agent_scope_assignments receipt
            WHERE receipt.tenant_id=NEW.tenant_id AND receipt.conversation_id=OLD.scope_id AND receipt.agent_id=NEW.scope_id
        ) THEN
            INSERT INTO resource.scope_history(tenant_id,scope_kind,scope_id,node_id,file_artifact_id,
                ownership_generation,evidence_source,dialogue_source_conversation_id,created_at_ms,updated_at_ms)
            VALUES(NEW.tenant_id,NEW.scope_kind,NEW.scope_id,NEW.node_id,NEW.file_artifact_id,
                previous_generation+1,6,OLD.scope_id,NEW.updated_at_ms,NEW.updated_at_ms);
            RETURN NEW;
        END IF;
        SELECT receipt.command_id INTO assignment
        FROM resource.workspace_assignment_receipts AS receipt
        JOIN conversation.workspace_assignment_preparations AS preparation USING(command_id)
        WHERE receipt.tenant_id = NEW.tenant_id AND receipt.conversation_id = OLD.scope_id
          AND receipt.target_workspace_id = NEW.scope_id AND preparation.phase = 1
          AND OLD.scope_kind = 2 AND NEW.scope_kind = 1;
        IF assignment IS NULL THEN RAISE EXCEPTION 'Resource transfer requires active assignment receipt'; END IF;
        INSERT INTO resource.scope_history (tenant_id,scope_kind,scope_id,node_id,file_artifact_id,
            ownership_generation,evidence_source,assignment_command_id,created_at_ms,updated_at_ms)
        VALUES(NEW.tenant_id,NEW.scope_kind,NEW.scope_id,NEW.node_id,NEW.file_artifact_id,
            previous_generation+1,5,assignment,NEW.updated_at_ms,NEW.updated_at_ms);
    END IF;
    RETURN NEW;
END $$;


--
-- Name: require_device_command_receipt(); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.require_device_command_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM resource.device_commands c JOIN artifact.content_refs command ON command.content_id=c.command_content_id AND command.tenant_id=c.tenant_id
  JOIN artifact.content_refs request ON request.content_id=c.request_content_id AND request.tenant_id=c.tenant_id
  LEFT JOIN artifact.content_refs result ON result.content_id=c.result_content_id AND result.tenant_id=c.tenant_id
  JOIN artifact.content_refs receipt ON receipt.content_id=c.receipt_content_id AND receipt.tenant_id=c.tenant_id
  WHERE c.invocation_id=NEW.invocation_id AND c.committed_at_ms IS NOT NULL AND c.receipt_commitment IS NOT NULL
 AND ((c.outcome='succeeded' AND result.content_id IS NOT NULL) OR c.outcome='rejected')) THEN
  RAISE EXCEPTION 'Resource mutation and exact receipt must commit together' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: validate_active_tree_edge(); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.validate_active_tree_edge() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE current_node resource.nodes%ROWTYPE;
BEGIN
    SELECT * INTO current_node FROM resource.nodes WHERE node_id=NEW.node_id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    IF current_node.lifecycle=1 AND current_node.parent_node_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM resource.nodes WHERE node_id=current_node.parent_node_id AND lifecycle=1
    ) THEN RAISE EXCEPTION 'active resource node cannot have a trashed parent'; END IF;
    IF current_node.kind=1 AND current_node.lifecycle<>1 AND EXISTS (
        SELECT 1 FROM resource.nodes WHERE parent_node_id=current_node.node_id AND lifecycle=1
    ) THEN RAISE EXCEPTION 'trashed resource folder cannot have active children'; END IF;
    RETURN NULL;
END $$;


--
-- Name: FUNCTION validate_active_tree_edge(); Type: COMMENT; Schema: resource; Owner: -
--

COMMENT ON FUNCTION resource.validate_active_tree_edge() IS 'Deferred invariant: active nodes form a tree with active parents.';


--
-- Name: validate_node(); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.validate_node() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent_row resource.nodes%ROWTYPE;
    original_parent_row resource.nodes%ROWTYPE;
    artifact_tenant UUID;
    artifact_conversation UUID;
    artifact_kind SMALLINT;
    artifact_workspace UUID;
    source_tenant UUID;
    source_workspace UUID;
    execution_conversation UUID;
BEGIN
    IF TG_OP = 'UPDATE' AND (OLD.scope_kind = 3 OR NEW.scope_kind = 3)
       AND (OLD.tenant_id, OLD.scope_kind, OLD.scope_id) IS DISTINCT FROM (NEW.tenant_id, NEW.scope_kind, NEW.scope_id) THEN
        RAISE EXCEPTION 'Private execution resources cannot transfer through legacy scope assignment';
    END IF;
    IF NEW.scope_kind = 3 THEN
        SELECT conversation_id INTO execution_conversation FROM resource.execution_workspaces
        WHERE tenant_id=NEW.tenant_id AND execution_workspace_id=NEW.scope_id;
        IF NOT FOUND OR NEW.source_conversation_id IS DISTINCT FROM execution_conversation THEN
            RAISE EXCEPTION 'Private resource provenance is outside execution workspace';
        END IF;
    END IF;
    IF NEW.parent_node_id = NEW.node_id OR NEW.original_parent_node_id = NEW.node_id THEN
        RAISE EXCEPTION 'resource node cannot parent itself';
    END IF;

    IF NEW.parent_node_id IS NOT NULL THEN
        SELECT * INTO parent_row
          FROM resource.nodes
         WHERE node_id = NEW.parent_node_id;
        IF NOT FOUND
           OR parent_row.tenant_id <> NEW.tenant_id
           OR parent_row.scope_kind <> NEW.scope_kind
           OR parent_row.scope_id <> NEW.scope_id
           OR parent_row.kind <> 1 THEN
            RAISE EXCEPTION 'resource parent is unavailable or outside scope';
        END IF;
        IF EXISTS (
            WITH RECURSIVE ancestors(node_id, parent_node_id) AS (
                SELECT node_id, parent_node_id
                  FROM resource.nodes
                 WHERE node_id = NEW.parent_node_id
                UNION
                SELECT candidate.node_id, candidate.parent_node_id
                  FROM resource.nodes AS candidate
                  JOIN ancestors AS child
                    ON candidate.node_id = child.parent_node_id
            )
            SELECT 1 FROM ancestors WHERE node_id = NEW.node_id
        ) THEN
            RAISE EXCEPTION 'resource move would create a cycle';
        END IF;
    END IF;

    IF NEW.original_parent_node_id IS NOT NULL THEN
        SELECT * INTO original_parent_row
          FROM resource.nodes
         WHERE node_id = NEW.original_parent_node_id;
        IF NOT FOUND
           OR original_parent_row.tenant_id <> NEW.tenant_id
           OR original_parent_row.scope_kind <> NEW.scope_kind
           OR original_parent_row.scope_id <> NEW.scope_id
           OR original_parent_row.kind <> 1 THEN
            RAISE EXCEPTION 'resource original parent is unavailable or outside scope';
        END IF;
    END IF;

    IF NEW.source_conversation_id IS NOT NULL THEN
        SELECT tenant_id, workspace_id
          INTO source_tenant, source_workspace
          FROM conversation.conversations
         WHERE conversation_id = NEW.source_conversation_id;
        IF NOT FOUND
           OR source_tenant <> NEW.tenant_id
           OR (NEW.scope_kind = 1 AND source_workspace IS DISTINCT FROM NEW.scope_id)
           OR (NEW.scope_kind = 2 AND NEW.source_conversation_id <> NEW.scope_id)
           OR (NEW.scope_kind = 4 AND NOT EXISTS (SELECT 1 FROM agent.dialogue_sessions
               WHERE tenant_id=NEW.tenant_id AND conversation_id=NEW.source_conversation_id AND agent_id=NEW.scope_id)) THEN
            RAISE EXCEPTION 'resource provenance Conversation is outside scope';
        END IF;
    END IF;

    IF NEW.kind = 2 THEN
        SELECT artifact_row.tenant_id,
               artifact_row.conversation_id,
               artifact_row.kind,
               COALESCE(artifact_row.workspace_id, conversation_row.workspace_id)
          INTO artifact_tenant, artifact_conversation, artifact_kind, artifact_workspace
          FROM artifact.artifacts AS artifact_row
          LEFT JOIN conversation.conversations AS conversation_row
            ON conversation_row.tenant_id = artifact_row.tenant_id
           AND conversation_row.conversation_id = artifact_row.conversation_id
         WHERE artifact_row.artifact_id = NEW.file_artifact_id;
        IF NOT FOUND OR artifact_tenant <> NEW.tenant_id OR (artifact_kind <> 6 AND NOT EXISTS (
            SELECT 1 FROM resource.file_versions AS file
            WHERE file.artifact_id = NEW.file_artifact_id
        )) THEN
            RAISE EXCEPTION 'resource file binding is unavailable or not a File Artifact';
        END IF;
        IF (NEW.scope_kind = 1 AND artifact_workspace IS DISTINCT FROM NEW.scope_id)
           OR (NEW.scope_kind = 2 AND artifact_conversation IS DISTINCT FROM NEW.scope_id)
           OR (NEW.scope_kind = 3 AND artifact_conversation IS DISTINCT FROM execution_conversation)
           OR (NEW.scope_kind = 4 AND NOT EXISTS (SELECT 1 FROM agent.dialogue_sessions
               WHERE tenant_id=NEW.tenant_id AND conversation_id=artifact_conversation AND agent_id=NEW.scope_id)
             AND NOT EXISTS(SELECT 1 FROM artifact.work_item_result_asset_returns ret
               WHERE ret.tenant_id=NEW.tenant_id AND ret.producer_id=NEW.scope_id AND ret.artifact_id=NEW.file_artifact_id
                 AND artifact.verified_task_native_version_owned(ret.tenant_id,ret.owner_id,ret.producer_id,ret.artifact_id,ret.version_id))
             AND NOT EXISTS(SELECT 1 FROM artifact.device_versions proof
               WHERE proof.tenant_id=NEW.tenant_id AND proof.agent_id=NEW.scope_id
                AND proof.artifact_id=NEW.file_artifact_id AND proof.conversation_id=artifact_conversation
                AND artifact.device_version_owned(proof.tenant_id,proof.owner_id,proof.agent_id,proof.artifact_id,proof.artifact_version_id))
             AND NOT EXISTS(SELECT 1 FROM artifact.device_resource_versions proof JOIN resource.device_commands command USING(invocation_id) WHERE proof.artifact_id=NEW.file_artifact_id AND command.tenant_id=NEW.tenant_id AND command.agent_id=NEW.scope_id)) THEN
            RAISE EXCEPTION 'resource file binding is outside scope';
        END IF;
    END IF;

    RETURN NEW;
END
$$;


--
-- Name: validate_agent_edit_entry(); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.validate_agent_edit_entry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.agent_dialogue_id,NEW.dialogue_entry_id) IS DISTINCT FROM
    (OLD.agent_dialogue_id,OLD.dialogue_entry_id) THEN
   RAISE EXCEPTION 'Agent file edit identity is immutable';
 END IF;
 IF NEW.dialogue_entry_id IS NOT NULL AND NOT EXISTS (
   SELECT 1 FROM agent.agent_dialogue_entries e
   JOIN agent.owned_agents a ON a.agent_id=NEW.scope_id AND a.dialogue_id=e.dialogue_id
   JOIN agent.owner_spaces s ON s.space_id=a.space_id AND s.tenant_id=e.tenant_id AND s.owner_id=e.owner_id
   JOIN resource.nodes n ON n.tenant_id=e.tenant_id AND n.node_id=NEW.file_node_id AND n.file_artifact_id=e.artifact_id
     AND n.scope_kind=4 AND n.scope_id=a.agent_id
   WHERE e.tenant_id=NEW.tenant_id AND e.owner_id=NEW.owner_principal_id
    AND e.dialogue_id=NEW.agent_dialogue_id AND e.entry_id=NEW.dialogue_entry_id
    AND (e.kind='artifact' OR (e.kind='erased' AND resource.account_file_owned(
      e.tenant_id,e.owner_id,a.agent_id,e.dialogue_id,e.entry_id,e.artifact_id)))
    AND e.artifact_id=NEW.file_artifact_id AND a.status='active'
    AND n.lifecycle=1 AND s.product='musteragent'
 ) THEN RAISE EXCEPTION 'Agent file edit source does not match public file authority'; END IF;
 RETURN NEW;
END $$;


--
-- Name: validate_scope_head(); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.validate_scope_head() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.scope_kind = 1 AND NOT EXISTS (
        SELECT 1
          FROM conversation.conversations
         WHERE tenant_id = NEW.tenant_id
           AND workspace_id = NEW.scope_id
        UNION ALL
        SELECT 1
          FROM resource.workspace_authority
         WHERE tenant_id = NEW.tenant_id
           AND workspace_id = NEW.scope_id
           AND status = 2
    ) THEN
        RAISE EXCEPTION 'resource Project scope is unavailable';
    ELSIF NEW.scope_kind = 2 AND NOT EXISTS (
        SELECT 1
          FROM conversation.conversations
         WHERE tenant_id = NEW.tenant_id
           AND conversation_id = NEW.scope_id
    ) THEN
        RAISE EXCEPTION 'resource Conversation scope is unavailable';
    END IF;
    IF NEW.scope_kind = 4 AND NOT EXISTS (
        SELECT 1 FROM agent.owned_agents a JOIN agent.owner_spaces s ON s.space_id=a.space_id
        WHERE a.agent_id=NEW.scope_id AND s.tenant_id=NEW.tenant_id AND s.product='musteragent'
    ) THEN RAISE EXCEPTION 'resource Account-owned Agent scope is unavailable'; END IF;
    IF NEW.scope_kind=3 AND NOT EXISTS(SELECT 1 FROM resource.execution_workspaces WHERE tenant_id=NEW.tenant_id AND execution_workspace_id=NEW.scope_id) THEN RAISE EXCEPTION 'Execution workspace scope is unavailable'; END IF;
    RETURN NEW;
END
$$;


--
-- Name: FUNCTION validate_scope_head(); Type: COMMENT; Schema: resource; Owner: -
--

COMMENT ON FUNCTION resource.validate_scope_head() IS 'Guards Project and Conversation Resource scope ownership.';


--
-- Name: validate_scope_history_insert(); Type: FUNCTION; Schema: resource; Owner: -
--

CREATE FUNCTION resource.validate_scope_history_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    live resource.nodes%ROWTYPE;
    previous_generation BIGINT;
BEGIN
    SELECT * INTO live FROM resource.nodes WHERE node_id = NEW.node_id FOR UPDATE;
    IF NOT FOUND
       OR NEW.tenant_id <> live.tenant_id
       OR NEW.scope_kind <> live.scope_kind
       OR NEW.scope_id <> live.scope_id
       OR NEW.file_artifact_id IS DISTINCT FROM live.file_artifact_id THEN
        RAISE EXCEPTION 'resource ownership proof does not match live binding';
    END IF;
    SELECT coalesce(max(ownership_generation), 0) INTO previous_generation
      FROM resource.scope_history WHERE node_id = NEW.node_id;
    IF NEW.ownership_generation <> previous_generation + 1 THEN
        RAISE EXCEPTION 'resource ownership generation must be sequential';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: check_public_repair_source(); Type: FUNCTION; Schema: runtime; Owner: -
--

CREATE FUNCTION runtime.check_public_repair_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE target runtime.model_invocations; source runtime.model_invocations;
BEGIN
 IF NEW.repair_kind IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO STRICT target FROM runtime.model_invocations WHERE invocation_id=NEW.invocation_id;
 SELECT * INTO STRICT source FROM runtime.model_invocations WHERE invocation_id=NEW.repair_source_invocation_id;
 IF (target.tenant_id,target.run_id,target.conversation_id) IS DISTINCT FROM
    (source.tenant_id,source.run_id,source.conversation_id)
    OR target.purpose<>1 OR source.purpose<>1 OR source.started_conversation_seq>NEW.repair_cutoff THEN
   RAISE EXCEPTION 'invalid delivery repair source' USING ERRCODE='23514';
 END IF;
 IF NEW.repair_content_id IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM artifact.content_refs c WHERE c.content_id=NEW.repair_content_id
   AND c.tenant_id=target.tenant_id AND c.state=2 AND c.content_hash=NEW.repair_content_hash
   AND c.byte_length=NEW.repair_content_bytes AND c.media_type='text/plain;charset=utf-8'
 ) THEN RAISE EXCEPTION 'invalid delivery repair content' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: enforce_pending_argument_diagnostic(); Type: FUNCTION; Schema: runtime; Owner: -
--

CREATE FUNCTION runtime.enforce_pending_argument_diagnostic() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.argument_diagnostic_json IS DISTINCT FROM OLD.argument_diagnostic_json AND NOT(
  OLD.erasure_job_id IS NULL AND NEW.erasure_job_id IS NOT NULL AND NEW.argument_diagnostic_json IS NULL
  AND NEW.erasure_job_id=COALESCE(privacy_erasure.work_item_run_erasure(OLD.run_id),privacy_erasure.work_item_call_job(OLD.run_id,OLD.tool_call_id))) THEN
  RAISE EXCEPTION 'argument diagnostics belong to the original call';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_compaction_execution_timing(); Type: FUNCTION; Schema: runtime; Owner: -
--

CREATE FUNCTION runtime.guard_compaction_execution_timing() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.sealed_deadline_ms IS DISTINCT FROM OLD.sealed_deadline_ms
     OR NEW.activity_timing IS DISTINCT FROM OLD.activity_timing
     OR NEW.activity_timing_hash IS DISTINCT FROM OLD.activity_timing_hash THEN
    RAISE EXCEPTION 'Original compaction timing is immutable';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_context_plan_lineage(); Type: FUNCTION; Schema: runtime; Owner: -
--

CREATE FUNCTION runtime.guard_context_plan_lineage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE prior runtime.context_plans%ROWTYPE;
DECLARE legacy_count bigint;
BEGIN
  IF TG_OP='UPDATE' THEN
    IF OLD.lineage_generation IS NOT NULL AND NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'Forward Context plan is immutable' USING ERRCODE='23514';
    END IF;
    IF ROW(OLD.lineage_generation,OLD.predecessor_snapshot_id,OLD.predecessor_generation,
           OLD.predecessor_checksum,OLD.control_record_id,OLD.control_sequence,OLD.control_kind)
       IS DISTINCT FROM
       ROW(NEW.lineage_generation,NEW.predecessor_snapshot_id,NEW.predecessor_generation,
           NEW.predecessor_checksum,NEW.control_record_id,NEW.control_sequence,NEW.control_kind) THEN
      RAISE EXCEPTION 'Context plan lineage is immutable' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  -- Defense in depth for non-application inserts. Production uses the original
  -- Conversation commit lane before reaching this Owner transaction.
  PERFORM 1 FROM runtime.runs WHERE tenant_id=NEW.tenant_id AND run_id=NEW.run_id FOR UPDATE;
  IF NEW.lineage_generation IS NULL THEN
    IF EXISTS(SELECT 1 FROM runtime.context_plans WHERE tenant_id=NEW.tenant_id
       AND run_id=NEW.run_id AND iteration=NEW.iteration AND lineage_generation IS NOT NULL) THEN
      RAISE EXCEPTION 'Legacy plan cannot overwrite a forward lineage' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  SELECT count(*) INTO legacy_count FROM runtime.context_plans
    WHERE tenant_id=NEW.tenant_id AND run_id=NEW.run_id AND iteration=NEW.iteration
      AND lineage_generation IS NULL;
  IF legacy_count>1 THEN
    RAISE EXCEPTION 'Ambiguous legacy Context plan slot' USING ERRCODE='23514';
  END IF;
  SELECT * INTO prior FROM runtime.context_plans
    WHERE tenant_id=NEW.tenant_id AND run_id=NEW.run_id AND iteration=NEW.iteration
    ORDER BY COALESCE(lineage_generation,1) DESC LIMIT 1;
  IF NOT FOUND THEN
    IF NEW.lineage_generation<>1 THEN
      RAISE EXCEPTION 'Context plan lineage has no initial generation' USING ERRCODE='23514';
    END IF;
  ELSE
    IF NEW.lineage_generation<>COALESCE(prior.lineage_generation,1)+1
       OR NEW.predecessor_snapshot_id IS DISTINCT FROM prior.snapshot_id
       OR NEW.predecessor_generation IS DISTINCT FROM COALESCE(prior.lineage_generation,1)
       OR NEW.predecessor_checksum IS DISTINCT FROM prior.checksum
       OR NEW.control_sequence IS NULL OR NEW.control_sequence<=prior.committed_sequence
       OR EXISTS(SELECT 1 FROM runtime.context_plans p JOIN runtime.model_invocations i
          ON i.tenant_id=p.tenant_id AND i.run_id=p.run_id AND i.invocation_id=p.invocation_id
          WHERE p.tenant_id=NEW.tenant_id AND p.run_id=NEW.run_id AND p.iteration=NEW.iteration) THEN
      RAISE EXCEPTION 'Context plan predecessor is not supersedable' USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.control_record_id IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM event_store.ledger_records r JOIN event_store.domain_events e USING(record_id)
    WHERE r.record_id=NEW.control_record_id AND r.tenant_id=NEW.tenant_id
      AND r.run_id=NEW.run_id AND r.conversation_id=NEW.conversation_id
      AND r.conversation_seq=NEW.control_sequence AND r.record_kind=1
      AND r.idempotency_key LIKE 'loop:control-consume:%') THEN
    RAISE EXCEPTION 'Context plan control proof has wrong source' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_control_compaction_claim(); Type: FUNCTION; Schema: runtime; Owner: -
--

CREATE FUNCTION runtime.guard_control_compaction_claim() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF runtime.needs_control_compaction_reader(NEW.tenant_id,NEW.run_id) THEN
    RAISE EXCEPTION 'worker cannot read the superseding compression control' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_control_compaction_dispatch(); Type: FUNCTION; Schema: runtime; Owner: -
--

CREATE FUNCTION runtime.guard_control_compaction_dispatch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM runtime.require_control_compaction_reader(NEW.tenant_id,NEW.run_id,NEW.owner_attempt_id);
  RETURN NEW;
END $$;


--
-- Name: guard_control_model_start(); Type: FUNCTION; Schema: runtime; Owner: -
--

CREATE FUNCTION runtime.guard_control_model_start() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM runtime.require_control_compaction_reader(NEW.tenant_id,NEW.run_id,NEW.attempt_id);
  RETURN NEW;
END $$;


--
-- Name: guard_execution_liveness(); Type: FUNCTION; Schema: runtime; Owner: -
--

CREATE FUNCTION runtime.guard_execution_liveness() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF EXISTS(SELECT 1 FROM runtime.runs WHERE run_id=OLD.run_id) THEN RAISE EXCEPTION 'Liveness is retained by its original Run'; END IF;
  RETURN OLD;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM runtime.runs WHERE run_id=NEW.run_id AND tenant_id=NEW.tenant_id)
 OR NOT EXISTS(SELECT 1 FROM runtime.attempts WHERE attempt_id=NEW.owner_attempt_id AND run_id=NEW.run_id) THEN RAISE EXCEPTION 'Liveness owner mismatch'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.revision!=1 OR NEW.record_kind!=1 OR NEW.closed OR NEW.producer_generation!=1 THEN RAISE EXCEPTION 'Liveness starts once under its original owner'; END IF;
 ELSIF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.run_id IS DISTINCT FROM OLD.run_id
 OR NEW.scope_kind IS DISTINCT FROM OLD.scope_kind OR NEW.scope_invocation_id IS DISTINCT FROM OLD.scope_invocation_id
 OR NEW.operation_identity IS DISTINCT FROM OLD.operation_identity OR NEW.policy_digest IS DISTINCT FROM OLD.policy_digest
 OR NEW.producer_generation IS DISTINCT FROM OLD.producer_generation OR NEW.revision<=OLD.revision OR OLD.closed
 OR NEW.owner_fence<OLD.owner_fence
 OR (NEW.owner_attempt_id!=OLD.owner_attempt_id AND NEW.owner_fence<=OLD.owner_fence)
 OR (NEW.owner_attempt_id=OLD.owner_attempt_id AND NEW.owner_fence!=OLD.owner_fence)
 THEN RAISE EXCEPTION 'Liveness identity, revision, and ownership are fenced';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_goal_review_retirement_immutable(); Type: FUNCTION; Schema: runtime; Owner: -
--

CREATE FUNCTION runtime.guard_goal_review_retirement_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
