--

CREATE FUNCTION runtime.guard_model_begin_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.begin_intent_hash IS DISTINCT FROM OLD.begin_intent_hash THEN
    RAISE EXCEPTION 'Original model begin intent is immutable';
  END IF;
  RETURN NEW;
