--
-- Name: guard_model_routing_reader(); Type: FUNCTION; Schema: runtime; Owner: -
--

CREATE FUNCTION runtime.guard_model_routing_reader() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM capability.runtime_snapshots
        WHERE run_id = NEW.run_id AND tenant_id = NEW.tenant_id
          AND requires_model_routing_reader
    ) THEN
        RAISE EXCEPTION 'worker does not support the frozen model routing policy'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: keep_goal_run_dialogue_observation(); Type: FUNCTION; Schema: runtime; Owner: -
--

CREATE FUNCTION runtime.keep_goal_run_dialogue_observation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.owner_pursuit_id IS NOT NULL AND
   (NEW.owner_pursuit_id,NEW.dialogue_context_epoch,NEW.dialogue_context_seq)
     IS DISTINCT FROM (OLD.owner_pursuit_id,OLD.dialogue_context_epoch,OLD.dialogue_context_seq)
 THEN RAISE EXCEPTION 'admitted Owner-scoped Goal observation is immutable'; END IF;
 RETURN NEW;
END $$;


--
-- Name: needs_control_compaction_reader(uuid, uuid); Type: FUNCTION; Schema: runtime; Owner: -
--

CREATE FUNCTION runtime.needs_control_compaction_reader(tenant uuid, target_run uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
      SELECT 1 FROM runtime.context_compaction_slots s
      JOIN event_store.ledger_records r
        ON r.tenant_id=s.tenant_id AND r.run_id=s.run_id
       AND r.record_kind=1 AND r.idempotency_key LIKE 'loop:control-consume:%'
       AND r.conversation_seq>s.ledger_cutoff
      WHERE s.tenant_id=tenant AND s.run_id=target_run
        AND s.source_key='runtime-ledger' AND s.generation=1
  )
$$;


--
-- Name: notify_dispatch_change(); Type: FUNCTION; Schema: runtime; Owner: -
--

CREATE FUNCTION runtime.notify_dispatch_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status IN (1, 2, 4, 8)
       OR (
           NEW.status = 3
           AND NEW.wait_reason IN (4, 7)
           AND NEW.not_before_ms IS NOT NULL
       ) THEN
        PERFORM pg_notify('musteragent_runtime_dispatch', NEW.run_id::text);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_compaction_source_rebind(); Type: FUNCTION; Schema: runtime; Owner: -
--

CREATE FUNCTION runtime.reject_compaction_source_rebind() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.source_key IS DISTINCT FROM OLD.source_key THEN
        RAISE EXCEPTION 'A sealed compaction source cannot be rebound';
    END IF;
    RETURN NEW;
END $$;


