--
-- Name: require_control_compaction_reader(uuid, uuid, uuid); Type: FUNCTION; Schema: runtime; Owner: -
--

CREATE FUNCTION runtime.require_control_compaction_reader(tenant uuid, target_run uuid, attempt uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM runtime.attempts a WHERE a.tenant_id=tenant AND a.run_id=target_run
      AND a.attempt_id=attempt AND NOT a.supports_control_compaction_v1)
      AND runtime.needs_control_compaction_reader(tenant,target_run) THEN
    RAISE EXCEPTION 'attempt cannot dispatch after compression source changed' USING ERRCODE='55000';
  END IF;
END $$;


