    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'security audit facts are append-only';
END;
$$;


--
-- Name: validate_canonical_binding_interactive(); Type: FUNCTION; Schema: security_audit; Owner: -
--

CREATE FUNCTION security_audit.validate_canonical_binding_interactive() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- v1 rows predate producer-owned authorities and remain immutable. Every
    -- production producer below emits v2 and is validated exhaustively.
    IF NEW.schema_version <> 'musteragent.legacy.security.audit.v2' THEN
        RETURN NEW;
    END IF;

    IF NEW.action = 8 THEN
        IF NEW.resource_count <> 2 OR NOT EXISTS (
            SELECT 1
            FROM runtime.runs AS run
            JOIN conversation.conversations AS conversation
              ON conversation.tenant_id=run.tenant_id AND conversation.conversation_id=run.conversation_id
            LEFT JOIN agent.dialogue_sessions AS dialogue_session
              ON dialogue_session.tenant_id=run.tenant_id AND dialogue_session.conversation_id=run.conversation_id
             AND dialogue_session.owner_id=conversation.created_by AND dialogue_session.conversation_purpose=conversation.purpose
             AND ((dialogue_session.subject_kind='intent' AND conversation.purpose='dialogue_intent_coordination') OR (dialogue_session.subject_kind='work_item' AND conversation.purpose='agent_work_item_execution') OR (dialogue_session.subject_kind='work_item_report' AND conversation.purpose='agent_work_item_report') OR (dialogue_session.subject_kind='goal' AND dialogue_session.source_goal_id IS NOT NULL AND conversation.purpose='owner_goal_execution'))
             AND conversation.kind=4 AND conversation.workspace_id IS NULL AND conversation.title IS NULL
             AND conversation.execution_owner_participant_id=run.executor_participant_id
            JOIN conversation.participants AS requester
              ON requester.tenant_id = run.tenant_id
             AND requester.conversation_id = run.conversation_id
             AND requester.participant_id = run.requested_by_participant_id
            JOIN event_store.ledger_records AS admitted
              ON admitted.tenant_id = run.tenant_id
             AND admitted.conversation_id = run.conversation_id
             AND admitted.conversation_seq = run.admitted_sequence
             AND admitted.record_id = NEW.source_ledger_record_id
             AND admitted.record_kind = 1
             AND admitted.participant_id = run.requested_by_participant_id
            JOIN security_audit.resource_refs AS conversation_resource
              ON conversation_resource.tenant_id = run.tenant_id
             AND conversation_resource.audit_record_id = NEW.audit_record_id
             AND conversation_resource.resource_kind = 1
             AND conversation_resource.resource_id = run.conversation_id
            JOIN security_audit.resource_refs AS run_resource
              ON run_resource.tenant_id = run.tenant_id
             AND run_resource.audit_record_id = NEW.audit_record_id
             AND run_resource.resource_kind = 4
             AND run_resource.resource_id = run.run_id
            WHERE run.tenant_id = NEW.tenant_id
              AND (
                  (conversation.purpose='standard' AND requester.kind=1 AND requester.principal_ref=NEW.actor_principal_id)
                  OR
                  (dialogue_session.owner_id=NEW.actor_principal_id AND requester.kind=3
                   AND requester.principal_ref IS NULL AND requester.agent_ref IS NULL
                   AND ((dialogue_session.subject_kind='intent' AND requester.service_ref='musteragent.dialogue-intent@1') OR (dialogue_session.subject_kind='work_item' AND requester.service_ref='musteragent.work-item@1') OR (dialogue_session.subject_kind='work_item_report' AND requester.service_ref='musteragent.work-item-report@1') OR (dialogue_session.subject_kind='goal' AND requester.service_ref='musteragent.owner-goal@1')) AND requester.left_at_ms IS NULL
                   AND EXISTS(SELECT 1 FROM conversation.participants executor
                       WHERE executor.tenant_id=run.tenant_id AND executor.conversation_id=run.conversation_id
                         AND executor.participant_id=run.executor_participant_id AND executor.kind=2
                         AND executor.agent_ref=dialogue_session.agent_id AND executor.left_at_ms IS NULL))
              )
              AND NEW.actor_principal_kind = 1
              AND admitted.correlation_id = NEW.correlation_id
              AND admitted.occurred_at_ms = NEW.occurred_at_ms
              AND decode(substring(run.traceparent FROM 4 FOR 32), 'hex') = NEW.trace_id
              AND NEW.outcome = 1
        ) THEN
            RAISE EXCEPTION 'security audit Admission authority binding mismatch';
        END IF;

    ELSIF NEW.action = 9 THEN
        IF NEW.resource_count <> 1 OR NOT EXISTS (
            SELECT 1
            FROM runtime.model_invocations AS invocation
            JOIN runtime.attempts AS attempt
              ON attempt.tenant_id = invocation.tenant_id
             AND attempt.run_id = invocation.run_id
             AND attempt.attempt_id = invocation.attempt_id
            JOIN runtime.runs AS run
              ON run.tenant_id = invocation.tenant_id
             AND run.run_id = invocation.run_id
            JOIN security_audit.run_executor_authorities AS executor
              ON executor.tenant_id = run.tenant_id AND executor.run_id = run.run_id
            JOIN event_store.ledger_records AS admitted
              ON admitted.tenant_id = run.tenant_id
             AND admitted.conversation_id = run.conversation_id
             AND admitted.conversation_seq = run.admitted_sequence
             AND admitted.record_kind = 1
             AND admitted.participant_id = run.requested_by_participant_id
            JOIN security_audit.resource_refs AS run_resource
              ON run_resource.tenant_id = run.tenant_id
             AND run_resource.audit_record_id = NEW.audit_record_id
             AND run_resource.resource_kind = 4
             AND run_resource.resource_id = run.run_id
            WHERE invocation.tenant_id = NEW.tenant_id
              AND invocation.invocation_id = NEW.source_model_invocation_id
              AND invocation.finished_at_ms = NEW.occurred_at_ms
              AND ((invocation.status = 2 AND NEW.outcome = 1)
                OR (invocation.status = 3 AND NEW.outcome = 3)
                OR (invocation.status = 4 AND NEW.outcome = 2))
              AND NEW.actor_principal_id = executor.actor_principal_id
              AND NEW.actor_principal_kind = executor.actor_principal_kind
              AND NEW.correlation_id = admitted.correlation_id
              AND NEW.trace_id = decode(substring(run.traceparent FROM 4 FOR 32), 'hex')
        ) THEN
            RAISE EXCEPTION 'security audit Model terminal authority binding mismatch';
        END IF;

    ELSIF NEW.action IN (10, 12) THEN
        IF NEW.resource_count <> 1 OR NOT EXISTS (
            SELECT 1
            FROM tool.tool_invocations AS invocation
            JOIN runtime.attempts AS attempt
              ON attempt.tenant_id = invocation.tenant_id
             AND attempt.run_id = invocation.run_id
             AND attempt.attempt_id = invocation.requested_by_attempt_id
            JOIN runtime.runs AS run
              ON run.tenant_id = invocation.tenant_id
             AND run.run_id = invocation.run_id
            JOIN security_audit.run_executor_authorities AS executor
              ON executor.tenant_id = run.tenant_id AND executor.run_id = run.run_id
            JOIN event_store.ledger_records AS admitted
              ON admitted.tenant_id = run.tenant_id
             AND admitted.conversation_id = run.conversation_id
             AND admitted.conversation_seq = run.admitted_sequence
             AND admitted.record_kind = 1
             AND admitted.participant_id = run.requested_by_participant_id
            JOIN security_audit.resource_refs AS run_resource
              ON run_resource.tenant_id = run.tenant_id
             AND run_resource.audit_record_id = NEW.audit_record_id
             AND run_resource.resource_kind = 4
             AND run_resource.resource_id = run.run_id
            WHERE invocation.tenant_id = NEW.tenant_id
              AND invocation.invocation_id = NEW.source_tool_invocation_id
              AND (
                (NEW.action = 10
                 AND invocation.finished_at_ms = NEW.occurred_at_ms
                 AND ((invocation.status = 4 AND NEW.outcome = 1)
                   OR (invocation.status = 5 AND NEW.outcome = 3)
                   OR (invocation.status = 7 AND NEW.outcome = 2)))
                OR
                (NEW.action = 12
                 AND invocation.indeterminate_observed_at_ms = NEW.occurred_at_ms
                 AND invocation.status IN (4, 5, 6, 7)
                 AND NEW.outcome = 3)
              )
              AND NEW.actor_principal_id = executor.actor_principal_id
              AND NEW.actor_principal_kind = executor.actor_principal_kind
              AND NEW.correlation_id = admitted.correlation_id
              AND NEW.trace_id = decode(substring(run.traceparent FROM 4 FOR 32), 'hex')
        ) THEN
            RAISE EXCEPTION 'security audit Tool authority binding mismatch';
        END IF;

    ELSIF NEW.action = 2 THEN
        IF NEW.resource_count <> 1 OR NOT EXISTS (
            SELECT 1
            FROM runtime.model_invocations AS invocation
            JOIN runtime.execution_grant_invocations AS grant_use
              ON grant_use.invocation_id = invocation.invocation_id
            JOIN runtime.execution_grant_consumptions AS grant_authority
              ON grant_authority.grant_ref = grant_use.grant_ref
             AND grant_authority.tenant_id = invocation.tenant_id
             AND grant_authority.run_id = invocation.run_id
            JOIN runtime.runs AS run
              ON run.tenant_id = invocation.tenant_id
             AND run.run_id = invocation.run_id
            JOIN security_audit.run_executor_authorities AS executor
              ON executor.tenant_id = run.tenant_id AND executor.run_id = run.run_id
             AND (grant_use.actor_principal_id = executor.actor_principal_id
                AND grant_use.actor_principal_kind = executor.actor_principal_kind)
            JOIN event_store.ledger_records AS admitted
              ON admitted.tenant_id = run.tenant_id
             AND admitted.conversation_id = run.conversation_id
             AND admitted.conversation_seq = run.admitted_sequence
             AND admitted.record_kind = 1
             AND admitted.participant_id = run.requested_by_participant_id
            JOIN security_audit.resource_refs AS run_resource
              ON run_resource.tenant_id = run.tenant_id
             AND run_resource.audit_record_id = NEW.audit_record_id
             AND run_resource.resource_kind = 4
             AND run_resource.resource_id = run.run_id
            WHERE invocation.tenant_id = NEW.tenant_id
              AND invocation.invocation_id = NEW.source_model_invocation_id
              AND grant_use.actor_principal_id = NEW.actor_principal_id
              AND grant_use.actor_principal_kind = NEW.actor_principal_kind
              AND grant_use.consumed_at_ms = NEW.occurred_at_ms
              AND admitted.correlation_id = NEW.correlation_id
              AND decode(substring(run.traceparent FROM 4 FOR 32), 'hex') = NEW.trace_id
              AND NEW.outcome = 1
        ) THEN
            RAISE EXCEPTION 'security audit Credential authority binding mismatch';
        END IF;

    ELSIF NEW.action IN (1, 11) THEN
        IF NEW.resource_count <> 2 OR NOT EXISTS (
            SELECT 1
            FROM approval.interactions AS interaction
            JOIN approval.interaction_responses AS response
              ON response.interaction_id = interaction.interaction_id
             AND response.responded_by = interaction.responded_by
             AND response.responded_at_ms = interaction.responded_at_ms
             AND response.response_ledger_record_id = NEW.source_ledger_record_id
            JOIN runtime.runs AS run
              ON run.tenant_id = interaction.tenant_id AND run.run_id = interaction.run_id
            JOIN conversation.participants AS responder
              ON responder.tenant_id = interaction.tenant_id
             AND responder.conversation_id = interaction.conversation_id
             AND responder.kind = 1 AND responder.principal_ref = response.responded_by
            JOIN event_store.ledger_records AS record
              ON record.tenant_id = interaction.tenant_id
             AND record.record_id = response.response_ledger_record_id
             AND record.run_id = interaction.run_id
             AND record.participant_id = responder.participant_id
             AND record.record_kind = 1
             AND record.occurred_at_ms = response.responded_at_ms
            JOIN event_store.domain_events AS response_event
              ON response_event.record_id = record.record_id
             AND response_event.payload_hash = record.payload_hash
             AND response_event.payload_hash = response.response_ledger_payload_hash
            JOIN security_audit.resource_refs AS run_resource
              ON run_resource.tenant_id = interaction.tenant_id
             AND run_resource.audit_record_id = NEW.audit_record_id
             AND run_resource.resource_kind = 4
             AND run_resource.resource_id = interaction.run_id
            JOIN security_audit.resource_refs AS interaction_resource
              ON interaction_resource.tenant_id = interaction.tenant_id
             AND interaction_resource.audit_record_id = NEW.audit_record_id
             AND interaction_resource.resource_kind = 5
             AND interaction_resource.resource_id = interaction.interaction_id
            WHERE interaction.tenant_id = NEW.tenant_id
              AND interaction.status = 2
              AND response.responded_by = NEW.actor_principal_id
              AND response.response_ledger_event_kind = 1
              AND NEW.actor_principal_kind = 1
              AND record.correlation_id = NEW.correlation_id
              AND record.occurred_at_ms = NEW.occurred_at_ms
              AND decode(substring(run.traceparent FROM 4 FOR 32), 'hex') = NEW.trace_id
              AND ((NEW.action = 1 AND interaction.kind = 1
                    AND ((response.approval_decision = 1 AND NEW.outcome = 1)
                      OR (response.approval_decision = 2 AND NEW.outcome = 2)))
                OR (NEW.action = 11 AND interaction.kind <> 1 AND NEW.outcome = 1))
        ) THEN
            RAISE EXCEPTION 'security audit Interaction authority binding mismatch';
        END IF;

    ELSIF NEW.action = 3 THEN
        IF NEW.resource_count <> 1 OR NOT EXISTS (
            SELECT 1
            FROM security_audit.admission_denials AS denial
            JOIN security_audit.resource_refs AS conversation_resource
              ON conversation_resource.tenant_id = denial.tenant_id
             AND conversation_resource.audit_record_id = NEW.audit_record_id
             AND conversation_resource.resource_kind = 1
             AND conversation_resource.resource_id = denial.conversation_id
            WHERE denial.tenant_id = NEW.tenant_id
              AND denial.audit_record_id = NEW.audit_record_id
              AND denial.actor_principal_id = NEW.actor_principal_id
              AND denial.actor_principal_kind = NEW.actor_principal_kind
              AND denial.correlation_id = NEW.correlation_id
              AND denial.trace_id = NEW.trace_id
              AND denial.occurred_at_ms = NEW.occurred_at_ms
              AND NEW.outcome = 2
        ) THEN
            RAISE EXCEPTION 'security audit denial authority binding mismatch';
        END IF;

    ELSIF NEW.action = 6 THEN
        IF NEW.resource_count <> 2 OR NOT EXISTS (
            SELECT 1
            FROM privacy_erasure.receipts AS receipt
            JOIN privacy_erasure.requests AS request
              ON request.tenant_id = receipt.tenant_id
             AND request.erasure_job_id = receipt.erasure_job_id
            JOIN security_audit.resource_refs AS job
              ON job.tenant_id = receipt.tenant_id
             AND job.audit_record_id = NEW.audit_record_id
             AND job.resource_kind = 9
             AND job.resource_id = receipt.erasure_job_id
            JOIN security_audit.resource_refs AS receipt_resource
              ON receipt_resource.tenant_id = receipt.tenant_id
             AND receipt_resource.audit_record_id = NEW.audit_record_id
             AND receipt_resource.resource_kind = 10
             AND receipt_resource.resource_id = receipt.erasure_receipt_id
            WHERE receipt.tenant_id = NEW.tenant_id
              AND receipt.erasure_job_id = NEW.source_erasure_job_id
              AND receipt.completed_at_ms = NEW.occurred_at_ms
              AND request.actor_principal_id = NEW.actor_principal_id
              AND request.actor_principal_kind = NEW.actor_principal_kind
              AND NEW.correlation_id = request.erasure_job_id
              AND NEW.trace_id IS NULL
              AND NEW.outcome = 1
        ) THEN
            RAISE EXCEPTION 'security audit Erasure receipt binding mismatch';
        END IF;

    ELSE
        RAISE EXCEPTION 'security audit v2 action has no canonical transaction owner';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_ledger_source_tenant(); Type: FUNCTION; Schema: security_audit; Owner: -
--

CREATE FUNCTION security_audit.validate_ledger_source_tenant() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    source_tenant_id UUID;
    source_trace_id BYTEA;
BEGIN
    IF NEW.action IN (4, 5, 7) THEN
        RAISE EXCEPTION 'security audit typed source owner is not implemented';
    END IF;
    IF NEW.source_ledger_record_id IS NOT NULL THEN
        SELECT record.tenant_id,
               CASE WHEN run.traceparent IS NULL THEN NULL
                    ELSE decode(substring(run.traceparent FROM 4 FOR 32), 'hex') END
        INTO source_tenant_id, source_trace_id
        FROM event_store.ledger_records AS record
        LEFT JOIN runtime.runs AS run
          ON run.tenant_id = record.tenant_id AND run.run_id = record.run_id
        WHERE record.record_id = NEW.source_ledger_record_id;
    ELSIF NEW.source_erasure_job_id IS NOT NULL THEN
        SELECT tenant_id, NULL INTO source_tenant_id, source_trace_id
        FROM privacy_erasure.requests
        WHERE erasure_job_id = NEW.source_erasure_job_id;
    ELSIF NEW.source_model_invocation_id IS NOT NULL THEN
        SELECT invocation.tenant_id,
               decode(substring(run.traceparent FROM 4 FOR 32), 'hex')
        INTO source_tenant_id, source_trace_id
        FROM runtime.model_invocations AS invocation
        JOIN runtime.runs AS run
          ON run.tenant_id = invocation.tenant_id AND run.run_id = invocation.run_id
        WHERE invocation.invocation_id = NEW.source_model_invocation_id;
    ELSIF NEW.source_tool_invocation_id IS NOT NULL THEN
        SELECT invocation.tenant_id,
               decode(substring(run.traceparent FROM 4 FOR 32), 'hex')
        INTO source_tenant_id, source_trace_id
        FROM tool.tool_invocations AS invocation
        JOIN runtime.runs AS run
          ON run.tenant_id = invocation.tenant_id AND run.run_id = invocation.run_id
        WHERE invocation.invocation_id = NEW.source_tool_invocation_id;
    ELSE
        RETURN NEW;
    END IF;

    IF source_tenant_id IS NULL THEN
        RAISE EXCEPTION 'security audit typed source does not exist';
    END IF;
    IF source_tenant_id <> NEW.tenant_id THEN
        RAISE EXCEPTION 'security audit typed source tenant mismatch';
    END IF;
    IF NEW.trace_id IS NOT NULL
       AND source_trace_id IS NOT NULL
       AND source_trace_id <> NEW.trace_id
    THEN
        RAISE EXCEPTION 'security audit typed source trace mismatch';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_maintenance_admission_binding(); Type: FUNCTION; Schema: security_audit; Owner: -
--

CREATE FUNCTION security_audit.validate_maintenance_admission_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.schema_version <> 'musteragent.legacy.security.audit.v2'
       OR NEW.action <> 8
       OR NEW.actor_principal_kind <> 3
    THEN
        RAISE EXCEPTION 'security audit Maintenance admission shape mismatch';
    END IF;

    IF NEW.resource_count <> 2 OR NOT EXISTS (
        SELECT 1
        FROM runtime.runs AS run
        JOIN conversation.conversations AS conversation
          ON conversation.tenant_id = run.tenant_id
         AND conversation.conversation_id = run.conversation_id
         AND conversation.kind = 4
         AND conversation.lifecycle = 1
         AND conversation.created_by = NEW.actor_principal_id
        JOIN conversation.participants AS requester
          ON requester.tenant_id = run.tenant_id
         AND requester.conversation_id = run.conversation_id
         AND requester.participant_id = run.requested_by_participant_id
         AND requester.kind = 3
         AND requester.principal_ref IS NULL
         AND requester.agent_ref IS NULL
         AND requester.left_at_ms IS NULL
        JOIN security_audit.run_executor_authorities AS executor
              ON executor.tenant_id = run.tenant_id AND executor.run_id = run.run_id
         AND executor.principal_ref IS NULL
         AND executor.left_at_ms IS NULL
        JOIN event_store.ledger_records AS admitted
          ON admitted.tenant_id = run.tenant_id
         AND admitted.conversation_id = run.conversation_id
         AND admitted.conversation_seq = run.admitted_sequence
         AND admitted.record_id = NEW.source_ledger_record_id
         AND admitted.record_kind = 1
         AND admitted.participant_id = run.requested_by_participant_id
        JOIN security_audit.resource_refs AS conversation_resource
          ON conversation_resource.tenant_id = run.tenant_id
         AND conversation_resource.audit_record_id = NEW.audit_record_id
         AND conversation_resource.resource_kind = 1
         AND conversation_resource.resource_id = run.conversation_id
        JOIN security_audit.resource_refs AS run_resource
          ON run_resource.tenant_id = run.tenant_id
         AND run_resource.audit_record_id = NEW.audit_record_id
         AND run_resource.resource_kind = 4
         AND run_resource.resource_id = run.run_id
        WHERE run.tenant_id = NEW.tenant_id
          AND run.activity_kind = 5
          AND requester.service_ref='musteragent.legacy.runtime.evolution'
          AND executor.kind=2 AND executor.agent_ref IS NOT NULL AND executor.service_ref IS NULL
          AND admitted.correlation_id = NEW.correlation_id
          AND admitted.occurred_at_ms = NEW.occurred_at_ms
          AND decode(substring(run.traceparent FROM 4 FOR 32), 'hex') = NEW.trace_id
          AND NEW.outcome = 1
    ) THEN
        RAISE EXCEPTION 'security audit Maintenance admission authority binding mismatch';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION validate_maintenance_admission_binding(); Type: COMMENT; Schema: security_audit; Owner: -
--

COMMENT ON FUNCTION security_audit.validate_maintenance_admission_binding() IS 'Validates message-free Dream Maintenance admission against its private System conversation, service requester, Agent executor, Run, Ledger source, trace, and complete resource set';


--
-- Name: validate_resource_set(); Type: FUNCTION; Schema: security_audit; Owner: -
--

CREATE FUNCTION security_audit.validate_resource_set() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    expected_count SMALLINT;
    actual_count BIGINT;
    minimum_ordinal SMALLINT;
    maximum_ordinal SMALLINT;
BEGIN
    SELECT resource_count INTO expected_count
    FROM security_audit.records
    WHERE tenant_id = NEW.tenant_id AND audit_record_id = NEW.audit_record_id;

    SELECT count(*), min(ordinal), max(ordinal)
    INTO actual_count, minimum_ordinal, maximum_ordinal
    FROM security_audit.resource_refs
    WHERE tenant_id = NEW.tenant_id AND audit_record_id = NEW.audit_record_id;

    IF expected_count IS NULL
        OR actual_count <> expected_count
        OR minimum_ordinal <> 0
        OR maximum_ordinal <> expected_count - 1
    THEN
        RAISE EXCEPTION 'security audit resource set is incomplete or non-contiguous';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: enforce_identity_audit_signature(); Type: FUNCTION; Schema: skill; Owner: -
--

CREATE FUNCTION skill.enforce_identity_audit_signature() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Changing an identity's trust must not retroactively attest unsigned bytes.
    IF NEW.trust_level IN (1, 2) AND EXISTS (
        SELECT 1 FROM skill.skill_versions v JOIN skill.package_audits a USING(skill_version_id)
        WHERE v.skill_id = NEW.skill_id AND NOT a.signature_verified
    ) THEN
        RAISE EXCEPTION 'verified Skill identity has an unsigned package'
            USING ERRCODE = '23514', CONSTRAINT = 'skill_audit_signature_for_trust';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: enforce_package_audit_signature(); Type: FUNCTION; Schema: skill; Owner: -
--

CREATE FUNCTION skill.enforce_package_audit_signature() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE package_trust SMALLINT;
BEGIN
    -- The original immutable version is inserted before its audit in the same
    -- transaction. Lock the identity so a concurrent trust change cannot race it.
    SELECT s.trust_level INTO STRICT package_trust
        FROM skill.skill_versions v JOIN skill.skills s USING(skill_id)
        WHERE v.skill_version_id = NEW.skill_version_id FOR SHARE OF s;
    IF package_trust IN (1, 2) AND NOT NEW.signature_verified THEN
        RAISE EXCEPTION 'verified Skill package requires verified signature'
            USING ERRCODE = '23514', CONSTRAINT = 'skill_audit_signature_for_trust';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: reject_retained_catalog_mutation(); Type: FUNCTION; Schema: skill; Owner: -
--

CREATE FUNCTION skill.reject_retained_catalog_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'retained Skill admission catalogs are immutable';
END;
$$;


--
-- Name: guard_invocation_activity_timing(); Type: FUNCTION; Schema: tool; Owner: -
--

CREATE FUNCTION tool.guard_invocation_activity_timing() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.activity_timing IS DISTINCT FROM OLD.activity_timing
     OR NEW.activity_timing_hash IS DISTINCT FROM OLD.activity_timing_hash THEN
    RAISE EXCEPTION 'Original invocation activity timing is immutable';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: notify_origin_tool_call(); Type: FUNCTION; Schema: tool; Owner: -
--

CREATE FUNCTION tool.notify_origin_tool_call() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM pg_notify('origin_tool_call', NEW.intent_id::text);
    RETURN NEW;
END;
$$;


