    CONSTRAINT dialogue_admission_outcomes_reason_check CHECK ((reason = ANY (ARRAY['account_unavailable'::text, 'execution_not_allowed'::text, 'agent_inactive'::text, 'runtime_contract_failure'::text, 'user_requested'::text, 'source_authority_changed'::text]))),
