--
-- Name: public_delivery_candidates; Type: TABLE; Schema: agent; Owner: -
--

CREATE TABLE agent.public_delivery_candidates (
    delivery_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    run_id uuid NOT NULL,
    invocation_id uuid NOT NULL,
    output_id uuid NOT NULL,
    ordinal smallint NOT NULL,
    contract_key text NOT NULL,
    contract_sha256 bytea NOT NULL,
    source_content_id uuid NOT NULL,
    source_sha256 bytea NOT NULL,
    kind text NOT NULL,
    purpose text NOT NULL,
    body_content_ref bytea,
    body_content_id uuid,
    interaction_id uuid,
    artifact_id uuid,
    artifact_version_id uuid,
    permission_revision bigint NOT NULL,
    created_at_ms bigint NOT NULL,
    satisfied_publication_id uuid,
    CONSTRAINT dialogue_candidate_shape CHECK ((((satisfied_publication_id IS NULL) AND (((kind = 'message'::text) AND (body_content_ref IS NOT NULL) AND (octet_length(body_content_ref) > 0) AND (body_content_id IS NOT NULL) AND (interaction_id IS NULL) AND (artifact_id IS NULL) AND (artifact_version_id IS NULL)) OR ((kind = 'interaction'::text) AND (body_content_ref IS NULL) AND (body_content_id IS NULL) AND (interaction_id IS NOT NULL) AND (artifact_id IS NULL) AND (artifact_version_id IS NULL)) OR ((kind = 'artifact'::text) AND (body_content_ref IS NULL) AND (body_content_id IS NULL) AND (interaction_id IS NULL) AND (artifact_id IS NOT NULL) AND (artifact_version_id IS NOT NULL)))) OR ((kind = 'partner_created'::text) AND (purpose = 'result'::text) AND (contract_key = ANY (ARRAY['musteragent.public-delivery@4'::text, 'musteragent.public-delivery@5'::text, 'musteragent.public-delivery@6'::text, 'musteragent.public-delivery@7'::text])) AND (body_content_ref IS NULL) AND (body_content_id IS NULL) AND (interaction_id IS NULL) AND (artifact_id IS NULL) AND (artifact_version_id IS NULL) AND (satisfied_publication_id IS NOT NULL)))),
    CONSTRAINT public_delivery_candidates_contract_key_check CHECK (((length(contract_key) >= 1) AND (length(contract_key) <= 128))),
    CONSTRAINT public_delivery_candidates_contract_sha256_check CHECK ((octet_length(contract_sha256) = 32)),
    CONSTRAINT public_delivery_candidates_kind_check CHECK ((kind = ANY (ARRAY['message'::text, 'interaction'::text, 'artifact'::text, 'partner_created'::text]))),
    CONSTRAINT public_delivery_candidates_ordinal_check CHECK (((ordinal >= 0) AND (ordinal <= 15))),
    CONSTRAINT public_delivery_candidates_permission_revision_check CHECK ((permission_revision > 0)),
    CONSTRAINT public_delivery_candidates_purpose_check CHECK ((purpose = ANY (ARRAY['reply'::text, 'result'::text, 'important_update'::text, 'clarification'::text, 'required_decision'::text, 'blocked'::text]))),
    CONSTRAINT public_delivery_candidates_source_sha256_check CHECK ((octet_length(source_sha256) = 32))
);


