    CONSTRAINT device_admissions_admitted_snapshot_hash_check CHECK (((admitted_snapshot_hash IS NULL) OR (octet_length(admitted_snapshot_hash) = 32))),
    CONSTRAINT device_admissions_check CHECK (((signed_grant_proof IS NULL) = (signed_grant_hash IS NULL))),
    CONSTRAINT device_admissions_check1 CHECK (((admitted_at_ms IS NULL) = (admitted_snapshot_hash IS NULL))),
    CONSTRAINT device_admissions_check2 CHECK (((admitted_at_ms IS NULL) OR (signed_grant_proof IS NOT NULL))),
    CONSTRAINT device_admissions_claim_generation_check CHECK ((claim_generation > 0)),
    CONSTRAINT device_admissions_signed_grant_hash_check CHECK (((signed_grant_hash IS NULL) OR (octet_length(signed_grant_hash) = 32))),
    CONSTRAINT device_admissions_signed_grant_proof_check CHECK (((signed_grant_proof IS NULL) OR ((octet_length(signed_grant_proof) >= 1) AND (octet_length(signed_grant_proof) <= 4194304)))),
    CONSTRAINT device_admissions_source_digest_check CHECK ((octet_length(source_digest) = 32)),
    CONSTRAINT device_admissions_source_envelope_check CHECK (((octet_length(source_envelope) >= 1) AND (octet_length(source_envelope) <= 4194304))),
    CONSTRAINT device_admissions_source_sha256_check CHECK ((octet_length(source_sha256) = 32))
);


