    CONSTRAINT device_grant_versions_revision_check CHECK ((revision > 0)),
    CONSTRAINT device_grant_versions_signed_grant_hash_check CHECK ((octet_length(signed_grant_hash) = 32)),
    CONSTRAINT device_grant_versions_signed_grant_proof_check CHECK (((octet_length(signed_grant_proof) >= 1) AND (octet_length(signed_grant_proof) <= 4194304))),
    CONSTRAINT device_grant_versions_source_digest_check CHECK ((octet_length(source_digest) = 32))
);


