    CONSTRAINT device_source_refusals_check CHECK (((grant_revision = 0) = (grant_proof_hash IS NULL))),
    CONSTRAINT device_source_refusals_check1 CHECK ((refusal_sha256 = sha256(canonical_refusal))),
    CONSTRAINT device_source_refusals_detected_at_ms_check CHECK ((detected_at_ms > 0)),
    CONSTRAINT device_source_refusals_grant_proof_hash_check CHECK (((grant_proof_hash IS NULL) OR (octet_length(grant_proof_hash) = 32))),
    CONSTRAINT device_source_refusals_grant_revision_check CHECK ((grant_revision >= 0)),
    CONSTRAINT device_source_refusals_reason_check CHECK ((reason = ANY (ARRAY[1, 2]))),
