    canonical_control bytea NOT NULL,
    created_at_ms bigint NOT NULL,
    CONSTRAINT native_execution_controls_canonical_control_check CHECK (((octet_length(canonical_control) >= 1) AND (octet_length(canonical_control) <= 16384))),
    CONSTRAINT native_execution_controls_check CHECK (((grant_revision = 0) = (grant_proof_hash IS NULL))),
    CONSTRAINT native_execution_controls_control_sha256_check CHECK ((octet_length(control_sha256) = 32)),
    CONSTRAINT native_execution_controls_created_at_ms_check CHECK ((created_at_ms > 0)),
    CONSTRAINT native_execution_controls_grant_proof_hash_check CHECK (((grant_proof_hash IS NULL) OR (octet_length(grant_proof_hash) = 32))),
