    CONSTRAINT native_execution_not_admitted_canonical_receipt_check CHECK (((octet_length(canonical_receipt) >= 1) AND (octet_length(canonical_receipt) <= 16384))),
    CONSTRAINT native_execution_not_admitted_receipt_sha256_check CHECK ((octet_length(receipt_sha256) = 32)),
    CONSTRAINT native_execution_not_admitted_recorded_at_ms_check CHECK ((recorded_at_ms > 0))
);


--
-- Name: device_grants_for_receipts; Type: VIEW; Schema: agent; Owner: -
--

CREATE VIEW agent.device_grants_for_receipts AS
 SELECT intent_id,
    revision,
    previous_grant_hash,
    signed_grant_hash,
    signed_grant_proof,
    source_digest,
    claim_generation,
    native_membership_authority,
    recorded_at_ms
   FROM agent.device_grant_versions v
  WHERE ((NOT (EXISTS ( SELECT 1
           FROM agent.native_execution_controls c
          WHERE ((c.intent_id = v.intent_id) AND ((c.source_digest <> v.source_digest) OR (c.grant_revision < v.revision)))))) AND (NOT (EXISTS ( SELECT 1
           FROM agent.native_execution_not_admitted n
          WHERE (n.intent_id = v.intent_id)))) AND (NOT (EXISTS ( SELECT 1
           FROM agent.device_source_refusals r
          WHERE ((r.intent_id = v.intent_id) AND ((r.source_digest <> v.source_digest) OR (r.grant_revision < v.revision)))))) AND (NOT (EXISTS ( SELECT 1
           FROM agent.device_source_not_admitted n
          WHERE (n.intent_id = v.intent_id)))));


