CREATE TABLE agent.dialogue_execution_activity (
    agent_id uuid NOT NULL,
    revision bigint NOT NULL,
    state smallint NOT NULL,
    step smallint,
    active_count bigint NOT NULL,
    waiting_count bigint NOT NULL,
    unconfirmed_count bigint NOT NULL,
    last_outcome smallint,
    observed_at_ms bigint NOT NULL,
    next_refresh_at_ms bigint,
    wait_details_revision bigint,
    waiting_approval_count bigint DEFAULT 0 NOT NULL,
    scheduled_retry_count bigint DEFAULT 0 NOT NULL,
    earliest_retry_at_ms bigint,
    permission_wait_revision bigint,
    waiting_permission_count bigint DEFAULT 0 NOT NULL,
    foreground_execution_count bigint DEFAULT 0 NOT NULL,
    pending_cancellation_count bigint DEFAULT 0 NOT NULL,
    observed_cancellation_sequence bigint DEFAULT 0 NOT NULL,
    locally_completed_unconfirmed_count bigint,
    unconfirmed_cancellation_count bigint,
    CONSTRAINT dialogue_execution_activity_active_count_check CHECK (((active_count >= 0) AND (active_count <= '4294967295'::bigint))),
    CONSTRAINT dialogue_execution_activity_check CHECK (((pending_cancellation_count >= 0) AND (pending_cancellation_count <= foreground_execution_count))),
    CONSTRAINT dialogue_execution_activity_earliest_retry_at_ms_check CHECK ((earliest_retry_at_ms > 0)),
    CONSTRAINT dialogue_execution_activity_foreground_execution_count_check CHECK ((foreground_execution_count >= 0)),
    CONSTRAINT dialogue_execution_activity_last_outcome_check CHECK (((last_outcome >= 1) AND (last_outcome <= 4))),
    CONSTRAINT dialogue_execution_activity_next_refresh_at_ms_check CHECK ((next_refresh_at_ms >= 0)),
    CONSTRAINT dialogue_execution_activity_observed_at_ms_check CHECK ((observed_at_ms >= 0)),
    CONSTRAINT dialogue_execution_activity_observed_cancellation_sequenc_check CHECK ((observed_cancellation_sequence >= 0)),
    CONSTRAINT dialogue_execution_activity_revision_check CHECK ((revision > 0)),
    CONSTRAINT dialogue_execution_activity_scheduled_retry_count_check CHECK ((scheduled_retry_count >= 0)),
    CONSTRAINT dialogue_execution_activity_state_check CHECK (((state >= 1) AND (state <= 5))),
    CONSTRAINT dialogue_execution_activity_step_check CHECK (((step >= 1) AND (step <= 7))),
    CONSTRAINT dialogue_execution_activity_unconfirmed_count_check CHECK (((unconfirmed_count >= 0) AND (unconfirmed_count <= '4294967295'::bigint))),
    CONSTRAINT dialogue_execution_activity_waiting_approval_count_check CHECK ((waiting_approval_count >= 0)),
    CONSTRAINT dialogue_execution_activity_waiting_count_check CHECK (((waiting_count >= 0) AND (waiting_count <= '4294967295'::bigint))),
    CONSTRAINT dialogue_execution_activity_waiting_permission_count_check CHECK ((waiting_permission_count >= 0)),
    CONSTRAINT dialogue_local_completion_detail CHECK ((((locally_completed_unconfirmed_count IS NULL) AND (unconfirmed_cancellation_count IS NULL)) OR ((locally_completed_unconfirmed_count IS NOT NULL) AND (unconfirmed_cancellation_count IS NOT NULL) AND ((locally_completed_unconfirmed_count >= 0) AND (locally_completed_unconfirmed_count <= '4294967295'::bigint)) AND ((unconfirmed_cancellation_count >= 0) AND (unconfirmed_cancellation_count <= locally_completed_unconfirmed_count)) AND (unconfirmed_cancellation_count <= pending_cancellation_count))))
);


