CREATE TABLE agent.dialogue_user_intents (
    intent_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    dialogue_id uuid NOT NULL,
    command_id uuid NOT NULL,
    source_entry_id uuid NOT NULL,
    content_ref bytea NOT NULL,
    origin_surface text NOT NULL,
    origin_installation_id uuid,
    observed_epoch bigint NOT NULL,
    observed_seq bigint NOT NULL,
    reply_to_intent_id uuid,
    accepted_epoch bigint NOT NULL,
    accepted_seq bigint NOT NULL,
    accepted_at_ms bigint NOT NULL,
    input_attachments bytea DEFAULT '\x'::bytea NOT NULL,
    input_attachment_count smallint DEFAULT 0 NOT NULL,
    continuation_interaction_id uuid,
    task_target bytea,
    reply_binding bytea,
    CONSTRAINT dialogue_capability_origin_closed CHECK (((origin_surface = 'capability'::text) = (continuation_interaction_id IS NOT NULL))),
    CONSTRAINT dialogue_intent_attachment_shape CHECK ((((input_attachment_count = 0) = (octet_length(input_attachments) = 0)) AND (octet_length(input_attachments) <= 32768))),
    CONSTRAINT dialogue_intent_origin_closed CHECK ((((origin_surface = ANY (ARRAY['desktop'::text, 'mobile'::text])) AND (origin_installation_id IS NOT NULL)) OR (origin_surface = ANY (ARRAY['web'::text, 'capability'::text])) OR ((origin_surface = 'schedule'::text) AND (origin_installation_id IS NULL)))),
    CONSTRAINT dialogue_user_intents_accepted_epoch_check CHECK ((accepted_epoch > 0)),
    CONSTRAINT dialogue_user_intents_accepted_seq_check CHECK ((accepted_seq > 0)),
    CONSTRAINT dialogue_user_intents_check1 CHECK (((accepted_epoch = observed_epoch) AND (observed_seq < accepted_seq))),
    CONSTRAINT dialogue_user_intents_content_ref_check CHECK ((octet_length(content_ref) > 0)),
    CONSTRAINT dialogue_user_intents_input_attachment_count_check CHECK (((input_attachment_count >= 0) AND (input_attachment_count <= 64))),
    CONSTRAINT dialogue_user_intents_observed_epoch_check CHECK ((observed_epoch > 0)),
    CONSTRAINT dialogue_user_intents_observed_seq_check CHECK ((observed_seq >= 0)),
    CONSTRAINT dialogue_user_intents_reply_binding_check CHECK (((reply_binding IS NULL) OR ((octet_length(reply_binding) >= 1) AND (octet_length(reply_binding) <= 32768))))
);


--
-- Name: dialogue_execution_visible_source_roots; Type: VIEW; Schema: agent; Owner: -
--

CREATE VIEW agent.dialogue_execution_visible_source_roots AS
 SELECT root.intent_id,
    root.tenant_id,
    root.owner_id,
    root.agent_id,
    root.dialogue_id,
    root.source_entry_id,
    root.source_content_ref,
    root.source_epoch,
    root.source_seq,
    root.root_intent_id,
    root.root_entry_id,
    root.root_content_ref,
    root.root_epoch,
    root.root_seq,
    root.direct_user_root
   FROM (((((agent.dialogue_execution_source_roots root
     JOIN agent.dialogue_user_intents i ON (((i.intent_id = root.intent_id) AND (i.tenant_id = root.tenant_id) AND (i.owner_id = root.owner_id) AND (i.dialogue_id = root.dialogue_id) AND (i.source_entry_id = root.source_entry_id) AND (i.content_ref = root.source_content_ref) AND (i.accepted_epoch = root.source_epoch) AND (i.accepted_seq = root.source_seq))))
     JOIN agent.dialogue_user_intents origin ON (((origin.intent_id = root.root_intent_id) AND (origin.tenant_id = root.tenant_id) AND (origin.owner_id = root.owner_id) AND (origin.dialogue_id = root.dialogue_id) AND (origin.source_entry_id = root.root_entry_id) AND (origin.content_ref = root.root_content_ref) AND (origin.accepted_epoch = root.root_epoch) AND (origin.accepted_seq = root.root_seq))))
     JOIN agent.agent_dialogues visible ON (((visible.dialogue_id = root.dialogue_id) AND (visible.tenant_id = root.tenant_id) AND (visible.owner_id = root.owner_id) AND (visible.epoch = root.root_epoch))))
     JOIN agent.agent_dialogue_entries root_entry ON (((root_entry.entry_id = root.root_entry_id) AND (root_entry.tenant_id = root.tenant_id) AND (root_entry.owner_id = root.owner_id) AND (root_entry.dialogue_id = root.dialogue_id) AND (root_entry.epoch = root.root_epoch) AND (root_entry.seq = root.root_seq) AND (root_entry.kind = 'user_message'::text) AND (root_entry.source_intent_id = root.root_intent_id) AND (root_entry.content_ref = root.root_content_ref) AND (root_entry.erasure_job_id IS NULL))))
     JOIN agent.agent_dialogue_entries current_entry ON (((current_entry.entry_id = root.source_entry_id) AND (current_entry.tenant_id = root.tenant_id) AND (current_entry.owner_id = root.owner_id) AND (current_entry.dialogue_id = root.dialogue_id) AND (current_entry.epoch = root.source_epoch) AND (current_entry.seq = root.source_seq) AND (current_entry.erasure_job_id IS NULL))))
  WHERE (root.direct_user_root AND (root.source_content_ref = root.root_content_ref) AND (((i.origin_surface <> 'capability'::text) AND (current_entry.kind = 'user_message'::text) AND (current_entry.source_intent_id = i.intent_id) AND (current_entry.content_ref = root.source_content_ref)) OR ((i.origin_surface = 'capability'::text) AND (current_entry.kind = 'interaction'::text) AND (current_entry.content_ref IS NULL) AND (current_entry.interaction_id = i.continuation_interaction_id) AND (current_entry.source_intent_id = i.reply_to_intent_id))));


