--
-- Name: dialogue_intent_admissions; Type: TABLE; Schema: agent; Owner: -
--

CREATE TABLE agent.dialogue_intent_admissions (
    intent_id uuid NOT NULL,
    status text NOT NULL,
    claim_generation bigint DEFAULT 0 NOT NULL,
    claim_owner uuid,
    lease_expires_at_ms bigint,
    attempt_count bigint DEFAULT 0 NOT NULL,
    available_at_ms bigint NOT NULL,
    last_error_code text,
    handed_off_at_ms bigint,
    terminal_at_ms bigint,
    execution_target text DEFAULT 'cloud'::text NOT NULL,
    target_device_id uuid,
    target_installation_id uuid,
    native_subject_proof bytea,
    reply_origin_device_id uuid,
    reply_origin_installation_id uuid,
    reply_origin_subject_proof bytea,
    desktop_source_membership_id uuid,
    desktop_source_membership_epoch bigint,
    origin_tool_device_id uuid,
    CONSTRAINT dialogue_cloud_desktop_source CHECK ((((desktop_source_membership_id IS NULL) AND (desktop_source_membership_epoch IS NULL)) OR ((execution_target = 'cloud'::text) AND (desktop_source_membership_id IS NOT NULL) AND (desktop_source_membership_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (desktop_source_membership_epoch IS NOT NULL) AND (desktop_source_membership_epoch > 0)))),
    CONSTRAINT dialogue_intent_admissions_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT dialogue_intent_admissions_check CHECK ((((status = 'claimed'::text) AND (claim_owner IS NOT NULL) AND (lease_expires_at_ms IS NOT NULL)) OR ((status <> 'claimed'::text) AND (claim_owner IS NULL) AND (lease_expires_at_ms IS NULL)))),
    CONSTRAINT dialogue_intent_admissions_check1 CHECK ((((status = 'handed_off'::text) AND (handed_off_at_ms IS NOT NULL)) OR ((status <> 'handed_off'::text) AND (handed_off_at_ms IS NULL)))),
    CONSTRAINT dialogue_intent_admissions_check2 CHECK (((origin_tool_device_id IS NULL) OR ((execution_target = 'cloud'::text) AND (desktop_source_membership_id IS NULL) AND (origin_tool_device_id <> '00000000-0000-0000-0000-000000000000'::uuid)))),
    CONSTRAINT dialogue_intent_admissions_claim_generation_check CHECK ((claim_generation >= 0)),
    CONSTRAINT dialogue_intent_admissions_claim_owner_check CHECK (((claim_owner IS NULL) OR (claim_owner <> '00000000-0000-0000-0000-000000000000'::uuid))),
    CONSTRAINT dialogue_intent_admissions_execution_target_check CHECK ((execution_target = ANY (ARRAY['cloud'::text, 'origin_device'::text]))),
    CONSTRAINT dialogue_intent_admissions_last_error_code_check CHECK (((last_error_code IS NULL) OR (last_error_code = ANY (ARRAY['authority_unavailable'::text, 'policy_denied'::text, 'preparation_changed'::text, 'admission_failed'::text, 'dependency_unavailable'::text, 'invalid_contract'::text])))),
    CONSTRAINT dialogue_intent_admissions_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'claimed'::text, 'handed_off'::text, 'rejected'::text, 'cancelled'::text, 'failed'::text]))),
    CONSTRAINT dialogue_intent_admissions_terminal_check CHECK (((status = ANY (ARRAY['rejected'::text, 'cancelled'::text, 'failed'::text])) = (terminal_at_ms IS NOT NULL))),
    CONSTRAINT dialogue_intent_target_shape CHECK ((((execution_target = 'cloud'::text) AND (target_device_id IS NULL) AND (target_installation_id IS NULL) AND (native_subject_proof IS NULL)) OR ((execution_target = 'origin_device'::text) AND (target_device_id IS NOT NULL) AND (target_installation_id IS NOT NULL) AND (native_subject_proof IS NOT NULL) AND ((octet_length(native_subject_proof) >= 1) AND (octet_length(native_subject_proof) <= 24576))))),
    CONSTRAINT dialogue_reply_origin_shape CHECK ((((reply_origin_device_id IS NULL) AND (reply_origin_installation_id IS NULL) AND (reply_origin_subject_proof IS NULL)) OR ((execution_target = 'cloud'::text) AND (reply_origin_device_id IS NOT NULL) AND (reply_origin_installation_id IS NOT NULL) AND (reply_origin_subject_proof IS NOT NULL) AND ((octet_length(reply_origin_subject_proof) >= 1) AND (octet_length(reply_origin_subject_proof) <= 24576)))))
);


--
-- Name: native_execution_control_candidates; Type: VIEW; Schema: agent; Owner: -
--

CREATE VIEW agent.native_execution_control_candidates AS
 SELECT d.tenant_id,
    d.owner_id,
    d.agent_id,
    d.dialogue_id,
    d.run_id AS target_id,
    d.intent_id,
    d.run_id,
    d.conversation_id,
    d.device_id,
    d.installation_id,
    d.source_digest,
    COALESCE(h.current_revision, (0)::bigint) AS grant_revision,
    v.signed_grant_hash AS grant_proof_hash,
    agent.native_control_target_bytes(d.tenant_id, d.owner_id, d.agent_id, d.dialogue_id, d.intent_id, d.run_id, d.conversation_id, d.device_id, d.installation_id, d.source_digest, COALESCE(h.current_revision, (0)::bigint), v.signed_grant_hash) AS native_target
   FROM (((agent.device_admissions d
     LEFT JOIN agent.device_grant_heads h ON ((h.intent_id = d.intent_id)))
     LEFT JOIN agent.device_grant_versions v ON (((v.intent_id = h.intent_id) AND (v.revision = h.current_revision) AND (v.source_digest = d.source_digest))))
     JOIN agent.dialogue_execution_visible_source_roots root ON (((root.intent_id = d.intent_id) AND (root.tenant_id = d.tenant_id) AND (root.owner_id = d.owner_id) AND (root.agent_id = d.agent_id) AND (root.dialogue_id = d.dialogue_id))))
  WHERE (root.direct_user_root AND (NOT (EXISTS ( SELECT 1
           FROM agent.native_dialogue_terminals t
          WHERE (t.run_id = d.run_id)))) AND (NOT (EXISTS ( SELECT 1
           FROM agent.native_execution_not_admitted n
          WHERE (n.intent_id = d.intent_id)))) AND (NOT (EXISTS ( SELECT 1
           FROM agent.device_source_not_admitted n
          WHERE (n.intent_id = d.intent_id)))));


--
-- Name: owner_outbox; Type: TABLE; Schema: agent; Owner: -
--

CREATE TABLE agent.owner_outbox (
    outbox_id uuid NOT NULL,
    space_id uuid NOT NULL,
    account_epoch bigint NOT NULL,
    account_seq bigint NOT NULL,
    tenant_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    topic text NOT NULL,
    aggregate_id uuid NOT NULL,
    epoch bigint NOT NULL,
    seq bigint NOT NULL,
    event_kind text NOT NULL,
    payload bytea NOT NULL,
    created_at_ms bigint NOT NULL,
    published_at_ms bigint,
    CONSTRAINT owner_outbox_account_epoch_check CHECK ((account_epoch > 0)),
    CONSTRAINT owner_outbox_account_seq_check CHECK ((account_seq > 0)),
    CONSTRAINT owner_outbox_epoch_check CHECK ((epoch > 0)),
    CONSTRAINT owner_outbox_event_kind_check CHECK ((event_kind = ANY (ARRAY['agent_activated'::text, 'user_intent_accepted'::text, 'configuration_changed'::text, 'public_entry_published'::text, 'public_entry_changed'::text, 'agent_version_changed'::text, 'applications_changed'::text, 'file_head_changed'::text, 'notification_preferences_changed'::text, 'publication_visibility_changed'::text, 'admission_progress_changed'::text, 'reactions_changed'::text, 'activity_changed'::text, 'partner_deleted'::text, 'agenda_changed'::text, 'event_subscription_changed'::text, 'work_changed'::text]))),
    CONSTRAINT owner_outbox_payload_check CHECK ((octet_length(payload) > 0)),
