    CONSTRAINT interaction_response_kind_closed CHECK (((response_kind >= 1) AND (response_kind <= 3))),
    CONSTRAINT interaction_response_ledger_authority_closed CHECK ((((response_ledger_record_id IS NULL) AND (response_ledger_event_kind IS NULL) AND (response_ledger_payload_hash IS NULL)) OR ((response_ledger_record_id IS NOT NULL) AND (response_ledger_event_kind = 1) AND (octet_length(response_ledger_payload_hash) = 32)))),
    CONSTRAINT interaction_response_sha256 CHECK ((octet_length(response_hash) = 32))
);


