    kind smallint NOT NULL,
    lifecycle smallint NOT NULL,
    current_version numeric(20,0) NOT NULL,
    title character varying(512) NOT NULL,
    created_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    origin smallint DEFAULT 1 NOT NULL,
    search_text text GENERATED ALWAYS AS (lower((((title)::text || ' '::text) ||
CASE kind
    WHEN 1 THEN 'note 笔记 markdown document'::text
    WHEN 3 THEN 'presentation slides ppt pptx 演示文稿 幻灯片'::text
    WHEN 4 THEN 'image picture photo 图片'::text
    WHEN 5 THEN 'video movie 视频'::text
    WHEN 6 THEN 'file document attachment 文件 附件'::text
    ELSE ''::text
END))) STORED,
    workspace_id uuid,
    work_item_erasure_job_id uuid,
    title_source_known boolean DEFAULT false NOT NULL,
    title_source_invocation_id uuid,
    title_erasure_job_id uuid,
    CONSTRAINT artifact_current_version_positive CHECK ((current_version >= (1)::numeric)),
    CONSTRAINT artifact_kind_closed CHECK (((kind >= 1) AND (kind <= 7))),
    CONSTRAINT artifact_lifecycle_closed CHECK (((lifecycle >= 1) AND (lifecycle <= 4))),
    CONSTRAINT artifact_origin_closed CHECK (((origin >= 1) AND (origin <= 3))),
    CONSTRAINT artifact_origin_identity CHECK ((((origin = 1) AND (activity_id IS NOT NULL) AND (created_by_run_id IS NOT NULL)) OR ((origin = ANY (ARRAY[2, 3])) AND (activity_id IS NULL) AND (created_by_run_id IS NULL)))),
    CONSTRAINT artifact_source_identity CHECK (((num_nonnulls(conversation_id, workspace_id) = 1) AND ((workspace_id IS NULL) OR ((kind = 6) AND (origin = 3)))))
);


