    CONSTRAINT content_gc_job_lifecycle_consistent CHECK ((((status = 1) AND (storage_ref_protected IS NOT NULL) AND (completed_at_ms IS NULL)) OR ((status = 2) AND (storage_ref_protected IS NULL) AND (completed_at_ms IS NOT NULL)))),
    CONSTRAINT content_gc_job_retention_policy_nonempty CHECK (((char_length(btrim((retention_policy_ref)::text)) >= 1) AND (char_length(btrim((retention_policy_ref)::text)) <= 256))),
    CONSTRAINT content_gc_job_status_closed CHECK (((status >= 1) AND (status <= 2))),
