-- Name: content_refs; Type: TABLE; Schema: artifact; Owner: -
--

CREATE TABLE artifact.content_refs (
    content_id uuid NOT NULL,
    tenant_id uuid,
    media_type character varying(255) NOT NULL,
    byte_length numeric(20,0) NOT NULL,
    content_hash bytea NOT NULL,
    storage_ref character varying(1024),
    created_at_ms bigint NOT NULL,
    storage_ref_protected bytea,
    state smallint DEFAULT 2 NOT NULL,
    updated_at_ms bigint DEFAULT (floor((EXTRACT(epoch FROM clock_timestamp()) * (1000)::numeric)))::bigint NOT NULL,
    ownership_kind smallint DEFAULT 1 NOT NULL,
    gc_eligible_at_ms bigint,
    blob_content_id uuid,
    CONSTRAINT content_ref_length_nonnegative CHECK ((byte_length >= (0)::numeric)),
    CONSTRAINT content_ref_ownership_kind_closed CHECK (((ownership_kind >= 1) AND (ownership_kind <= 3))),
    CONSTRAINT content_ref_ownership_shape CHECK ((((ownership_kind = 1) AND (tenant_id IS NOT NULL)) OR ((ownership_kind = 2) AND (tenant_id IS NULL) AND (state = 2) AND ((storage_ref)::text ~~ 'runtime-builtin://%'::text) AND (storage_ref_protected IS NULL)) OR ((ownership_kind = 3) AND (tenant_id IS NULL) AND (storage_ref IS NULL) AND (((state = 1) AND (storage_ref_protected IS NULL)) OR ((state = 2) AND (storage_ref_protected IS NOT NULL)) OR (state = 3))))),
    CONSTRAINT content_ref_sha256 CHECK ((octet_length(content_hash) = 32)),
    CONSTRAINT content_ref_shared_blob_scope CHECK (((blob_content_id IS NULL) OR ((blob_content_id <> content_id) AND (tenant_id IS NOT NULL) AND (state <> 1)))),
    CONSTRAINT content_ref_state_closed CHECK (((state >= 1) AND (state <= 3))),
    CONSTRAINT content_ref_storage_state_consistent CHECK ((((state = 1) AND (storage_ref IS NULL) AND (storage_ref_protected IS NULL)) OR ((state = 2) AND (num_nonnulls(storage_ref, storage_ref_protected) = 1)) OR (state = 3)))
);


