--
-- Name: tool_invocations; Type: TABLE; Schema: tool; Owner: -
--

CREATE TABLE tool.tool_invocations (
    sandbox_executor text,
    sandbox_reason text,
    sandbox_compatibility text,
    sandbox_decided_at_ms bigint,
    sandbox_route_hash bytea,
    invocation_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    run_id uuid NOT NULL,
    requested_by_attempt_id uuid NOT NULL,
    execution_attempt_id uuid,
    tool_call_id character varying(256) NOT NULL,
    tool_ref character varying(255) NOT NULL,
    capability_provider_id uuid NOT NULL,
    status smallint NOT NULL,
    effect smallint NOT NULL,
    approval_policy smallint NOT NULL,
    retry_contract smallint NOT NULL,
    idempotency_key character varying(200) NOT NULL,
    request_content_id uuid NOT NULL,
    result_content_id uuid,
    interaction_id uuid,
    deadline_ms bigint,
    started_at_ms bigint,
    finished_at_ms bigint,
    terminal_error bytea,
    request_hash bytea NOT NULL,
    reconciliation_ref_protected bytea,
    terminal_reason bytea,
    indeterminate_observed_at_ms bigint,
    activity_timing bytea,
    activity_timing_hash bytea,
    erasure_job_id uuid,
    CONSTRAINT sandbox_route_complete CHECK ((((sandbox_executor IS NULL) AND (sandbox_reason IS NULL) AND (sandbox_compatibility IS NULL) AND (sandbox_decided_at_ms IS NULL) AND (sandbox_route_hash IS NULL)) OR ((sandbox_executor IS NOT NULL) AND (sandbox_compatibility IS NOT NULL) AND (sandbox_route_hash IS NOT NULL) AND (sandbox_executor = ANY (ARRAY['browser'::text, 'server'::text])) AND (sandbox_reason IS NOT NULL) AND (sandbox_compatibility = ANY (ARRAY['browser-compatible'::text, 'server-required'::text])) AND (sandbox_decided_at_ms IS NOT NULL) AND (octet_length(sandbox_route_hash) = 32)))),
    CONSTRAINT tool_activity_timing_bound CHECK (((activity_timing IS NULL) OR ((octet_length(activity_timing) >= 1) AND (octet_length(activity_timing) <= 4096)))),
    CONSTRAINT tool_activity_timing_digest CHECK (((activity_timing_hash IS NULL) OR (octet_length(activity_timing_hash) = 32))),
    CONSTRAINT tool_approval_policy_closed CHECK (((approval_policy >= 1) AND (approval_policy <= 3))),
    CONSTRAINT tool_erased_payload CHECK (((erasure_job_id IS NULL) OR (num_nonnulls(reconciliation_ref_protected, terminal_error, terminal_reason) = 0))),
    CONSTRAINT tool_execution_timing_closed CHECK ((((deadline_ms IS NOT NULL) AND (activity_timing IS NULL) AND (activity_timing_hash IS NULL)) OR ((deadline_ms IS NULL) AND (activity_timing IS NOT NULL) AND (activity_timing_hash IS NOT NULL)))),
    CONSTRAINT tool_indeterminate_observation_time CHECK ((((status = ANY (ARRAY[1, 2, 3])) AND (indeterminate_observed_at_ms IS NULL)) OR (status = ANY (ARRAY[4, 5, 7])) OR ((status = 6) AND (indeterminate_observed_at_ms IS NOT NULL)))),
    CONSTRAINT tool_invocation_effect_closed CHECK (((effect >= 1) AND (effect <= 4))),
    CONSTRAINT tool_invocation_request_sha256 CHECK ((octet_length(request_hash) = 32)),
    CONSTRAINT tool_invocation_status_closed CHECK (((status >= 1) AND (status <= 7))),
    CONSTRAINT tool_retry_contract_closed CHECK (((retry_contract >= 1) AND (retry_contract <= 4)))
);


--
-- Name: COLUMN tool_invocations.reconciliation_ref_protected; Type: COMMENT; Schema: tool; Owner: -
--

COMMENT ON COLUMN tool.tool_invocations.reconciliation_ref_protected IS 'Versioned AEAD envelope required to reconcile an indeterminate external effect.';


--
-- Name: requester_file_publications; Type: VIEW; Schema: artifact; Owner: -
--

CREATE VIEW artifact.requester_file_publications AS
 SELECT ret.entry_id,
    ret.result_id,
    ret.item_id,
    ret.report_run_id
   FROM ((((((((artifact.work_item_result_asset_returns ret
     JOIN collaboration.work_item_execution_reports r ON (((r.report_run_id = ret.report_run_id) AND (r.producing_run_id = ret.producer_run_id) AND (r.private_result_id = ret.result_id) AND (r.outcome = 'completed'::text))))
     JOIN collaboration.work_item_execution_reservations x ON (((x.run_id = r.producing_run_id) AND x.requester_uses_result AND ((x.work_item_id = ret.task_id) AND (x.tenant_id = ret.tenant_id) AND (x.owner_id = ret.owner_id) AND (x.executing_agent_id = ret.producer_id) AND (x.requesting_agent_id = ret.requester_id)))))
     JOIN collaboration.work_item_result_items item ON (((item.item_id = ret.item_id) AND (item.result_id = ret.result_id) AND ((item.artifact_id = ret.artifact_id) AND (item.artifact_version_id = ret.version_id) AND (item.asset_authority_sha256 = ret.authority_sha256)))))
     JOIN collaboration.work_item_requester_actions a ON (((a.report_run_id = r.report_run_id) AND (a.next_run_id IS NULL))))
     JOIN collaboration.work_item_revisions v ON (((v.work_item_id = x.work_item_id) AND (v.state_revision = ret.accepted_state_revision) AND (v.status = 'completed'::text) AND ((v.goal_revision = r.goal_revision) AND (v.control_revision = r.control_revision) AND (v.assignment_epoch = r.assignment_epoch)))))
     JOIN agent.dialogue_publications p ON (((p.entry_id = ret.entry_id) AND (p.source_kind = 'tool_owner'::text) AND (p.source_run_id = r.report_run_id) AND (p.source_tool_invocation_id = ret.publication_invocation_id) AND (p.dialogue_id = r.source_dialogue_id) AND (p.dialogue_id = ret.dialogue_id) AND ((p.tenant_id = ret.tenant_id) AND (p.owner_id = ret.owner_id) AND (p.agent_id = ret.requester_id)))))
     JOIN agent.agent_dialogue_entries e ON (((e.entry_id = p.entry_id) AND (e.kind = 'artifact'::text) AND ((e.artifact_id = ret.artifact_id) AND (e.artifact_version_id = ret.version_id)))))
     JOIN tool.tool_invocations i ON (((i.invocation_id = p.source_tool_invocation_id) AND (i.run_id = p.source_run_id) AND (i.tenant_id = p.tenant_id) AND ((i.tool_ref)::text = 'artifacts.deliver@2'::text) AND (i.status = 4) AND (i.erasure_job_id IS NULL))));


