    consumed_at_ms bigint NOT NULL,
    CONSTRAINT browser_gateway_ticket_consumptions_check CHECK ((expires_at_ms > issued_at_ms)),
    CONSTRAINT browser_gateway_ticket_consumptions_check1 CHECK (((consumed_at_ms >= issued_at_ms) AND (consumed_at_ms < expires_at_ms)))
);


