--
-- Name: browser_jobs; Type: TABLE; Schema: capability; Owner: -
--

CREATE TABLE capability.browser_jobs (
    job_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    principal_id uuid NOT NULL,
    invocation_id uuid NOT NULL,
    capability_key text NOT NULL,
    runtime_release_ref text NOT NULL,
    lease_id uuid NOT NULL,
    browser_session_id uuid NOT NULL,
    page_instance_id uuid NOT NULL,
    provider_id uuid NOT NULL,
    lease_epoch bigint NOT NULL,
    lease_fence bigint NOT NULL,
    delivery_sequence bigint NOT NULL,
    state smallint NOT NULL,
    last_provider_sequence bigint DEFAULT 0 NOT NULL,
    request_proto bytea NOT NULL,
    terminal_result_proto bytea,
    terminal_result_hash bytea,
    created_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    terminal_at_ms bigint,
    progress_history jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT browser_job_terminal_shape CHECK ((((state = 5) AND (terminal_result_proto IS NOT NULL) AND ((octet_length(terminal_result_proto) >= 1) AND (octet_length(terminal_result_proto) <= 4194304)) AND (terminal_result_hash IS NOT NULL) AND (octet_length(terminal_result_hash) = 32) AND (terminal_at_ms IS NOT NULL)) OR ((state <> 5) AND (terminal_result_proto IS NULL) AND (terminal_result_hash IS NULL) AND (terminal_at_ms IS NULL)))),
    CONSTRAINT browser_jobs_capability_key_check CHECK (((length(capability_key) >= 3) AND (length(capability_key) <= 160))),
    CONSTRAINT browser_jobs_delivery_sequence_check CHECK ((delivery_sequence > 0)),
    CONSTRAINT browser_jobs_last_provider_sequence_check CHECK ((last_provider_sequence >= 0)),
    CONSTRAINT browser_jobs_lease_epoch_check CHECK ((lease_epoch > 0)),
    CONSTRAINT browser_jobs_lease_fence_check CHECK ((lease_fence > 0)),
    CONSTRAINT browser_jobs_progress_history_check CHECK (((jsonb_typeof(progress_history) = 'array'::text) AND (jsonb_array_length(progress_history) <= 64))),
    CONSTRAINT browser_jobs_request_proto_check CHECK (((octet_length(request_proto) >= 1) AND (octet_length(request_proto) <= 4194304))),
    CONSTRAINT browser_jobs_runtime_release_ref_check CHECK (((length(runtime_release_ref) >= 3) AND (length(runtime_release_ref) <= 160))),
    CONSTRAINT browser_jobs_state_check CHECK (((state >= 1) AND (state <= 5)))
);


--
-- Name: browser_provider_identities; Type: TABLE; Schema: capability; Owner: -
--

CREATE TABLE capability.browser_provider_identities (
    provider_id uuid NOT NULL,
    executor_kind text NOT NULL,
    registration_scope text NOT NULL,
    tenant_id uuid,
    principal_id uuid,
    CONSTRAINT browser_provider_identities_check CHECK ((((registration_scope = 'actor'::text) AND (tenant_id IS NOT NULL) AND (principal_id IS NOT NULL)) OR ((registration_scope = 'tenant'::text) AND (tenant_id IS NOT NULL) AND (principal_id IS NULL)) OR ((registration_scope = 'global'::text) AND (tenant_id IS NULL) AND (principal_id IS NULL)))),
    CONSTRAINT browser_provider_identities_check1 CHECK (((executor_kind = 'server'::text) OR (registration_scope = 'actor'::text))),
    CONSTRAINT browser_provider_identities_executor_kind_check CHECK ((executor_kind = ANY (ARRAY['browser'::text, 'server'::text]))),
    CONSTRAINT browser_provider_identities_registration_scope_check CHECK ((registration_scope = ANY (ARRAY['actor'::text, 'tenant'::text, 'global'::text])))
);


--
-- Name: browser_provider_slots; Type: TABLE; Schema: capability; Owner: -
--

CREATE TABLE capability.browser_provider_slots (
    executor_kind text NOT NULL,
    tenant_id uuid NOT NULL,
    principal_id uuid NOT NULL,
    browser_session_id uuid NOT NULL,
    page_instance_id uuid NOT NULL,
    last_epoch bigint NOT NULL,
    last_fence bigint NOT NULL,
    active_lease_id uuid,
    provider_id uuid,
    runtime_release_ref text,
    capability_keys text[],
    resource_profile_ref text,
    feature_probe_proto bytea,
    issued_at_ms bigint,
    expires_at_ms bigint,
    last_delivery_sequence bigint DEFAULT 0 NOT NULL,
    CONSTRAINT browser_provider_slot_active_shape CHECK ((((active_lease_id IS NULL) AND (provider_id IS NULL) AND (runtime_release_ref IS NULL) AND (capability_keys IS NULL) AND (resource_profile_ref IS NULL) AND (feature_probe_proto IS NULL) AND (issued_at_ms IS NULL) AND (expires_at_ms IS NULL)) OR ((active_lease_id IS NOT NULL) AND (provider_id IS NOT NULL) AND (runtime_release_ref IS NOT NULL) AND ((length(runtime_release_ref) >= 3) AND (length(runtime_release_ref) <= 160)) AND (capability_keys IS NOT NULL) AND ((cardinality(capability_keys) >= 1) AND (cardinality(capability_keys) <= 8)) AND (resource_profile_ref IS NOT NULL) AND ((length(resource_profile_ref) >= 3) AND (length(resource_profile_ref) <= 160)) AND (feature_probe_proto IS NOT NULL) AND ((octet_length(feature_probe_proto) >= 1) AND (octet_length(feature_probe_proto) <= 16384)) AND (issued_at_ms IS NOT NULL) AND (expires_at_ms IS NOT NULL) AND (expires_at_ms > issued_at_ms)))),
    CONSTRAINT browser_provider_slots_executor_kind_check CHECK ((executor_kind = ANY (ARRAY['browser'::text, 'server'::text]))),
    CONSTRAINT browser_provider_slots_last_delivery_sequence_check CHECK ((last_delivery_sequence >= 0)),
    CONSTRAINT browser_provider_slots_last_epoch_check CHECK ((last_epoch > 0)),
    CONSTRAINT browser_provider_slots_last_fence_check CHECK ((last_fence > 0))
);


