    execution_grant_proof_hash bytea,
    execution_grant_claims_hash bytea,
    erasure_job_id uuid,
    requires_model_routing_reader boolean DEFAULT false NOT NULL,
    CONSTRAINT runtime_snapshot_erasure_shape CHECK ((((erasure_job_id IS NULL) AND (encoded_snapshot IS NOT NULL)) OR ((erasure_job_id IS NOT NULL) AND (encoded_snapshot IS NULL) AND (execution_grant_proof_schema IS NULL) AND (execution_grant_proof IS NULL) AND (execution_grant_proof_hash IS NULL) AND (execution_grant_claims_hash IS NULL)))),
    CONSTRAINT runtime_snapshot_execution_grant_claims_sha256 CHECK (((execution_grant_claims_hash IS NULL) OR (octet_length(execution_grant_claims_hash) = 32))),
    CONSTRAINT runtime_snapshot_execution_grant_proof_consistent CHECK ((num_nonnulls(execution_grant_proof_schema, execution_grant_proof, execution_grant_proof_hash, execution_grant_claims_hash) = ANY (ARRAY[0, 4]))),
    CONSTRAINT runtime_snapshot_execution_grant_proof_nonempty CHECK (((execution_grant_proof IS NULL) OR (octet_length(execution_grant_proof) > 0))),
    CONSTRAINT runtime_snapshot_execution_grant_proof_sha256 CHECK (((execution_grant_proof_hash IS NULL) OR (octet_length(execution_grant_proof_hash) = 32))),
    CONSTRAINT runtime_snapshot_nonempty CHECK ((octet_length(encoded_snapshot) > 0)),
    CONSTRAINT runtime_snapshot_sha256 CHECK ((octet_length(content_hash) = 32))
);


--
-- Name: COLUMN runtime_snapshots.execution_grant_proof; Type: COMMENT; Schema: capability; Owner: -
--

COMMENT ON COLUMN capability.runtime_snapshots.execution_grant_proof IS 'Authenticated admission proof retained so a Standing Goal can obtain narrowly-scoped continuation authority after the source Run is terminal.';


--
-- Name: work_item_commands; Type: TABLE; Schema: collaboration; Owner: -
--

CREATE TABLE collaboration.work_item_commands (
    tenant_id uuid NOT NULL,
    owner_id uuid NOT NULL,
