    request_hash bytea NOT NULL,
    work_item_id uuid NOT NULL,
    state_revision bigint NOT NULL,
    operation text,
    source_run_id uuid,
    source_invocation_id uuid,
    source_snapshot_id uuid,
    source_home text DEFAULT 'cloud'::text NOT NULL,
    cloud_source_run_id uuid GENERATED ALWAYS AS (
CASE
    WHEN (source_home = 'cloud'::text) THEN source_run_id
    ELSE NULL::uuid
END) STORED,
    cloud_source_invocation_id uuid GENERATED ALWAYS AS (
CASE
    WHEN (source_home = 'cloud'::text) THEN source_invocation_id
    ELSE NULL::uuid
END) STORED,
    cloud_source_snapshot_id uuid GENERATED ALWAYS AS (
CASE
    WHEN (source_home = 'cloud'::text) THEN source_snapshot_id
    ELSE NULL::uuid
END) STORED,
    device_source_invocation_id uuid GENERATED ALWAYS AS (
CASE
    WHEN (source_home = 'device'::text) THEN source_invocation_id
    ELSE NULL::uuid
END) STORED,
    CONSTRAINT work_item_command_execution_cause CHECK ((((operation IS NULL) AND (source_run_id IS NULL) AND (source_invocation_id IS NULL) AND (source_snapshot_id IS NULL)) OR ((operation IS NOT NULL) AND (source_run_id IS NOT NULL) AND (source_invocation_id IS NOT NULL) AND (source_snapshot_id IS NOT NULL)))),
    CONSTRAINT work_item_commands_operation_check CHECK ((operation = ANY (ARRAY['cancel'::text, 'amend'::text, 'verify'::text]))),
    CONSTRAINT work_item_commands_request_hash_check CHECK ((octet_length(request_hash) = 32)),
    CONSTRAINT work_item_commands_source_home_check CHECK ((source_home = ANY (ARRAY['cloud'::text, 'device'::text])))
);


