    CONSTRAINT work_item_device_custody_admitted_snapshot_hash_check CHECK ((octet_length(admitted_snapshot_hash) = 32)),
    CONSTRAINT work_item_device_custody_check CHECK (((admitted_snapshot_hash IS NULL) = (admitted_at_ms IS NULL))),
    CONSTRAINT work_item_device_custody_check1 CHECK (((admitted_grant_revision IS NULL) = (admitted_at_ms IS NULL))),
    CONSTRAINT work_item_device_custody_check2 CHECK (((admitted_grant_revision IS NULL) OR (admitted_grant_revision <= current_grant_revision))),
    CONSTRAINT work_item_device_custody_current_grant_revision_check CHECK ((current_grant_revision > 0)),
    CONSTRAINT work_item_device_custody_signed_grant_hash_check CHECK ((octet_length(signed_grant_hash) = 32)),
    CONSTRAINT work_item_device_custody_signed_grant_proof_check CHECK (((octet_length(signed_grant_proof) >= 1) AND (octet_length(signed_grant_proof) <= 4194304))),
    CONSTRAINT work_item_device_custody_source_digest_check CHECK ((octet_length(source_digest) = 32)),
    CONSTRAINT work_item_device_custody_source_envelope_check CHECK (((octet_length(source_envelope) >= 1) AND (octet_length(source_envelope) <= 4194304))),
    CONSTRAINT work_item_device_custody_source_sha256_check CHECK ((octet_length(source_sha256) = 32))
);


--
-- Name: work_item_device_grant_versions; Type: TABLE; Schema: collaboration; Owner: -
