    signed_grant_hash bytea NOT NULL,
    signed_grant_proof bytea NOT NULL,
    source_digest bytea NOT NULL,
    claim_generation bigint,
    recorded_at_ms bigint NOT NULL,
    CONSTRAINT work_item_device_grant_versions_check CHECK (((revision = 1) = (previous_grant_hash IS NULL))),
    CONSTRAINT work_item_device_grant_versions_check1 CHECK (((revision = 1) OR (claim_generation IS NOT NULL))),
    CONSTRAINT work_item_device_grant_versions_claim_generation_check CHECK ((claim_generation > 0)),
    CONSTRAINT work_item_device_grant_versions_previous_grant_hash_check CHECK (((previous_grant_hash IS NULL) OR (octet_length(previous_grant_hash) = 32))),
    CONSTRAINT work_item_device_grant_versions_revision_check CHECK ((revision > 0)),
    CONSTRAINT work_item_device_grant_versions_signed_grant_hash_check CHECK ((octet_length(signed_grant_hash) = 32)),
    CONSTRAINT work_item_device_grant_versions_signed_grant_proof_check CHECK (((octet_length(signed_grant_proof) >= 1) AND (octet_length(signed_grant_proof) <= 4194304))),
    CONSTRAINT work_item_device_grant_versions_source_digest_check CHECK ((octet_length(source_digest) = 32))
);


--
-- Name: work_item_device_admitted_custody; Type: VIEW; Schema: collaboration; Owner: -
--

CREATE VIEW collaboration.work_item_device_admitted_custody AS
 SELECT d.run_id,
    d.conversation_id,
    d.runtime_snapshot_id,
    d.work_item_id,
    d.goal_revision,
    d.control_revision,
    d.assignment_epoch,
    d.source_digest,
    d.source_sha256,
    d.source_envelope,
    v.signed_grant_hash,
    v.signed_grant_proof,
    d.created_at_ms,
    d.admitted_snapshot_hash,
    d.admitted_at_ms,
    d.current_grant_revision,
    d.admitted_grant_revision
   FROM (collaboration.work_item_device_custody d
     JOIN collaboration.work_item_device_grant_versions v ON (((v.run_id = d.run_id) AND (v.revision = d.admitted_grant_revision))));


--
-- Name: work_item_device_terminals; Type: TABLE; Schema: collaboration; Owner: -
--

CREATE TABLE collaboration.work_item_device_terminals (
    run_id uuid NOT NULL,
    admission_commitment bytea NOT NULL,
    outcome text NOT NULL,
    last_run_sequence bigint NOT NULL,
    terminal_record_id uuid NOT NULL,
    terminal_payload_hash bytea NOT NULL,
    liveness_commitment bytea NOT NULL,
    publication_cut bytea NOT NULL,
    publication_commitment bytea NOT NULL,
    receipt_commitment bytea NOT NULL,
    committed_at_ms bigint NOT NULL,
    result_cut bytea,
    result_cut_commitment bytea,
    CONSTRAINT work_item_device_result_cut_hash CHECK ((((result_cut IS NULL) = (result_cut_commitment IS NULL)) AND ((result_cut IS NULL) OR ((octet_length(result_cut) >= 1) AND (octet_length(result_cut) <= 2048) AND (sha256(result_cut) = result_cut_commitment))))),
    CONSTRAINT work_item_device_terminals_admission_commitment_check CHECK ((octet_length(admission_commitment) = 32)),
    CONSTRAINT work_item_device_terminals_last_run_sequence_check CHECK ((last_run_sequence > 0)),
    CONSTRAINT work_item_device_terminals_liveness_commitment_check CHECK ((octet_length(liveness_commitment) = 32)),
    CONSTRAINT work_item_device_terminals_outcome_check CHECK ((outcome = ANY (ARRAY['completed'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT work_item_device_terminals_publication_commitment_check CHECK ((octet_length(publication_commitment) = 32)),
    CONSTRAINT work_item_device_terminals_publication_cut_check CHECK (((octet_length(publication_cut) >= 1) AND (octet_length(publication_cut) <= 4194304))),
    CONSTRAINT work_item_device_terminals_receipt_commitment_check CHECK ((octet_length(receipt_commitment) = 32)),
    CONSTRAINT work_item_device_terminals_terminal_payload_hash_check CHECK ((octet_length(terminal_payload_hash) = 32))
);


