    accepted_state_revision bigint NOT NULL,
    device_terminal_run_id uuid,
    publication_run_id uuid GENERATED ALWAYS AS (COALESCE(report_run_id, device_terminal_run_id)) STORED,
    CONSTRAINT result_delivery_origin CHECK ((((report_run_id IS NOT NULL) AND (verification_invocation_id IS NOT NULL) AND (device_terminal_run_id IS NULL)) OR ((report_run_id IS NULL) AND (verification_invocation_id IS NULL) AND (device_terminal_run_id IS NOT NULL)))),
    CONSTRAINT work_item_result_deliveries_accepted_state_revision_check CHECK ((accepted_state_revision > 0))
);


--
-- Name: work_item_result_submissions; Type: TABLE; Schema: collaboration; Owner: -
--

CREATE TABLE collaboration.work_item_result_submissions (
    result_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    work_item_id uuid NOT NULL,
    goal_revision bigint NOT NULL,
    control_revision bigint NOT NULL,
    assignment_epoch bigint NOT NULL,
    producing_run_id uuid NOT NULL,
    producing_snapshot_id uuid NOT NULL,
    producing_agent_id uuid NOT NULL,
    producer_home text NOT NULL,
    requesting_agent_id uuid NOT NULL,
    source_dialogue_id uuid NOT NULL,
    source_intent_id uuid NOT NULL,
    submission_invocation_id uuid NOT NULL,
    request_sha256 bytea NOT NULL,
    manifest_ref bytea NOT NULL,
    manifest_content_id uuid NOT NULL,
    manifest_sha256 bytea NOT NULL,
    receipt_ref bytea NOT NULL,
    receipt_content_id uuid NOT NULL,
    item_count smallint NOT NULL,
    created_at_ms bigint NOT NULL,
    submission_call_id text,
    CONSTRAINT work_item_result_submissions_item_count_check CHECK (((item_count >= 1) AND (item_count <= 16))),
    CONSTRAINT work_item_result_submissions_manifest_sha256_check CHECK ((octet_length(manifest_sha256) = 32)),
    CONSTRAINT work_item_result_submissions_producer_home_check CHECK ((producer_home = ANY (ARRAY['cloud'::text, 'device'::text]))),
    CONSTRAINT work_item_result_submissions_request_sha256_check CHECK ((octet_length(request_sha256) = 32))
);


--
-- Name: authorized_result_deliveries; Type: VIEW; Schema: collaboration; Owner: -
--

CREATE VIEW collaboration.authorized_result_deliveries AS
 SELECT d.result_id,
    d.delivery_id,
    d.verification_invocation_id,
    d.report_run_id,
    d.accepted_state_revision,
    d.device_terminal_run_id,
    d.publication_run_id,
    s.work_item_id,
    s.owner_id,
    s.tenant_id,
    s.requesting_agent_id,
    s.source_dialogue_id,
    s.source_intent_id,
    s.item_count
   FROM (((collaboration.work_item_result_deliveries d
     JOIN collaboration.work_item_result_submissions s USING (result_id))
     JOIN collaboration.work_item_execution_reports r ON (((r.producing_run_id = s.producing_run_id) AND (r.private_result_id = s.result_id) AND (r.private_result_sha256 = s.manifest_sha256) AND (r.outcome = 'completed'::text) AND ((r.tenant_id = s.tenant_id) AND (r.owner_id = s.owner_id) AND (r.work_item_id = s.work_item_id) AND (r.goal_revision = s.goal_revision) AND (r.control_revision = s.control_revision) AND (r.assignment_epoch = s.assignment_epoch) AND (r.requesting_agent_id = s.requesting_agent_id) AND (r.source_dialogue_id = s.source_dialogue_id)))))
     JOIN collaboration.work_item_revisions v ON (((v.work_item_id = s.work_item_id) AND (v.state_revision = d.accepted_state_revision) AND (v.status = 'completed'::text) AND ((v.goal_revision = s.goal_revision) AND (v.control_revision = s.control_revision) AND (v.assignment_epoch = s.assignment_epoch)))))
  WHERE (((d.report_run_id = r.report_run_id) AND (EXISTS ( SELECT 1
           FROM (collaboration.work_item_commands c
             JOIN tool.tool_invocations i ON (((i.invocation_id = c.source_invocation_id) AND (i.run_id = c.source_run_id) AND (i.tenant_id = c.tenant_id))))
          WHERE ((c.source_invocation_id = d.verification_invocation_id) AND (c.source_run_id = r.report_run_id) AND (c.work_item_id = s.work_item_id) AND (c.tenant_id = s.tenant_id) AND (c.owner_id = s.owner_id) AND (c.operation = 'verify'::text) AND (c.state_revision = d.accepted_state_revision) AND ((i.tool_ref)::text = 'tasks.verify@3'::text) AND (i.status = 4) AND (i.result_content_id IS NOT NULL))))) OR ((d.device_terminal_run_id = s.producing_run_id) AND (s.producer_home = 'device'::text) AND (r.producer_home = 'device'::text) AND (r.state_revision = d.accepted_state_revision) AND (EXISTS ( SELECT 1
           FROM (collaboration.work_item_device_terminals t
             JOIN collaboration.work_item_device_admitted_custody a USING (run_id))
          WHERE ((t.run_id = d.device_terminal_run_id) AND (t.outcome = 'completed'::text) AND (t.result_cut_commitment IS NOT NULL) AND (a.admitted_snapshot_hash IS NOT NULL) AND (a.runtime_snapshot_id = s.producing_snapshot_id) AND ((a.work_item_id = s.work_item_id) AND (a.goal_revision = s.goal_revision) AND (a.control_revision = s.control_revision) AND (a.assignment_epoch = s.assignment_epoch)))))));


