--
-- Name: work_item_device_stops; Type: TABLE; Schema: collaboration; Owner: -
--

CREATE TABLE collaboration.work_item_device_stops (
    run_id uuid NOT NULL,
    receipt_commitment bytea NOT NULL,
    control_commitment bytea NOT NULL,
    canonical_receipt bytea NOT NULL,
