    approval_decision smallint DEFAULT 1 NOT NULL,
    approved_by uuid NOT NULL,
    approved_at_ms bigint NOT NULL,
    published_at_ms bigint NOT NULL,
    execution_home text DEFAULT 'cloud'::text NOT NULL,
    cloud_invocation_id uuid GENERATED ALWAYS AS (
CASE
    WHEN (execution_home = 'cloud'::text) THEN tool_invocation_id
    ELSE NULL::uuid
END) STORED,
    cloud_interaction_id uuid GENERATED ALWAYS AS (
CASE
    WHEN (execution_home = 'cloud'::text) THEN approval_interaction_id
    ELSE NULL::uuid
END) STORED,
    cloud_source_record_id uuid GENERATED ALWAYS AS (
CASE
    WHEN (execution_home = 'cloud'::text) THEN source_user_record_id
    ELSE NULL::uuid
END) STORED,
    native_interaction_id uuid GENERATED ALWAYS AS (
CASE
    WHEN (execution_home = 'device'::text) THEN approval_interaction_id
    ELSE NULL::uuid
END) STORED,
    CONSTRAINT explicit_publication_time_order CHECK ((published_at_ms >= approved_at_ms)),
    CONSTRAINT explicit_publications_approval_decision_check CHECK ((approval_decision = 1)),
    CONSTRAINT explicit_publications_approval_response_kind_check CHECK ((approval_response_kind = 1)),
    CONSTRAINT explicit_publications_execution_home_check CHECK ((execution_home = ANY (ARRAY['cloud'::text, 'device'::text])))
);


