    CONSTRAINT work_item_execution_coverage_shape CHECK (((num_nonnulls(execution_coverage_version, execution_run_ids, execution_content_refs, execution_coverage_hash, execution_covered_at_ms, execution_source_invocation_ids) = 0) OR ((num_nonnulls(execution_coverage_version, execution_run_ids, execution_content_refs, execution_coverage_hash, execution_covered_at_ms) = 5) AND ((cardinality(execution_run_ids) >= 1) AND (cardinality(execution_run_ids) <= 4096)) AND ((cardinality(execution_content_refs) >= 1) AND (cardinality(execution_content_refs) <= 65536)) AND (octet_length(execution_coverage_hash) = 32) AND (execution_covered_at_ms >= frozen_at_ms) AND (((execution_coverage_version = 1) AND (COALESCE(cardinality(execution_source_invocation_ids), 0) = 0)) OR ((execution_coverage_version = 2) AND (execution_source_invocation_ids IS NOT NULL) AND ((cardinality(execution_source_invocation_ids) >= 1) AND (cardinality(execution_source_invocation_ids) <= 65536))))))),
    CONSTRAINT work_item_lineage_check CHECK ((revision_count = state_revision)),
    CONSTRAINT work_item_lineage_control_revision_check CHECK ((control_revision > 0)),
