    created_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    activated_at_ms bigint,
    retired_at_ms bigint,
    last_error_code text,
    CONSTRAINT embedding_spaces_check CHECK ((updated_at_ms >= created_at_ms)),
    CONSTRAINT embedding_spaces_check1 CHECK ((((state = 2) AND (activated_at_ms IS NOT NULL)) OR ((state <> 2) AND (activated_at_ms IS NULL)))),
    CONSTRAINT embedding_spaces_check2 CHECK ((((state = 3) AND (retired_at_ms IS NOT NULL)) OR ((state <> 3) AND (retired_at_ms IS NULL)))),
    CONSTRAINT embedding_spaces_content_policy_hash_check CHECK ((octet_length(content_policy_hash) = 32)),
    CONSTRAINT embedding_spaces_dimensions_check CHECK (((dimensions >= 1) AND (dimensions <= 16000))),
    CONSTRAINT embedding_spaces_index_version_check CHECK (((length(TRIM(BOTH FROM index_version)) >= 1) AND (length(TRIM(BOTH FROM index_version)) <= 128))),
    CONSTRAINT embedding_spaces_metric_check CHECK ((metric = 'cosine'::text)),
    CONSTRAINT embedding_spaces_model_class_check CHECK ((model_class = 'resource.embedding'::text)),
    CONSTRAINT embedding_spaces_model_key_check CHECK (((length(TRIM(BOTH FROM model_key)) >= 1) AND (length(TRIM(BOTH FROM model_key)) <= 512))),
    CONSTRAINT embedding_spaces_model_revision_check CHECK (((length(TRIM(BOTH FROM model_revision)) >= 1) AND (length(TRIM(BOTH FROM model_revision)) <= 512))),
    CONSTRAINT embedding_spaces_normalization_check CHECK ((normalization = 'l2'::text)),
    CONSTRAINT embedding_spaces_state_check CHECK (((state >= 1) AND (state <= 4)))
);


