    CONSTRAINT execution_workspace_preparations_project_revision_check CHECK ((project_revision >= 0)),
    CONSTRAINT execution_workspace_preparations_request_hash_check CHECK ((octet_length(request_hash) = 32)),
    CONSTRAINT execution_workspace_preparations_total_bytes_check CHECK ((total_bytes >= 0))
