    CONSTRAINT execution_workspace_snapshot_entries_mount_kind_check CHECK ((mount_kind = ANY (ARRAY[0, 1]))),
    CONSTRAINT execution_workspace_snapshot_entries_path_check CHECK (((octet_length(path) >= 1) AND (octet_length(path) <= 4096)))
