    CONSTRAINT file_retraction_outcomes_check CHECK (((disposition = 1) = (change_set_id IS NOT NULL))),
    CONSTRAINT file_retraction_outcomes_disposition_check CHECK ((disposition = ANY (ARRAY[1, 2, 3]))),
    CONSTRAINT file_retraction_outcomes_reason_check CHECK (((reason)::text = ANY (ARRAY[('creation_retracted'::character varying)::text, ('effective_reference'::character varying)::text, ('already_removed'::character varying)::text, ('source_changed'::character varying)::text, ('version_changed'::character varying)::text, ('node_changed'::character varying)::text, ('edit_in_progress'::character varying)::text, ('scope_changed'::character varying)::text])))
);


--
-- Name: file_versions; Type: VIEW; Schema: resource; Owner: -
--

CREATE VIEW resource.file_versions AS
 SELECT v.artifact_version_id,
    v.artifact_id,
    v.version,
    v.content_id,
    v.content_hash
   FROM (artifact.artifact_versions v
     JOIN artifact.artifacts a USING (artifact_id))
  WHERE (a.kind = 6);


