-- Name: nodes; Type: TABLE; Schema: resource; Owner: -
--

CREATE TABLE resource.nodes (
    node_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    scope_kind smallint NOT NULL,
    scope_id uuid NOT NULL,
    parent_node_id uuid,
    original_parent_node_id uuid,
    name character varying(255) NOT NULL,
    comparison_name character varying(255) NOT NULL,
    kind smallint NOT NULL,
    lifecycle smallint NOT NULL,
    file_artifact_id uuid,
    sort_key character varying(512) NOT NULL,
    actor_principal_id uuid NOT NULL,
    actor_principal_kind smallint NOT NULL,
    source_conversation_id uuid,
    source_invocation_id uuid,
    source_tool_key character varying(255),
    created_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    revision bigint NOT NULL,
    name_source_known boolean DEFAULT false NOT NULL,
    name_source_invocation_id uuid,
    name_erasure_job_id uuid,
    sort_key_erasure_job_id uuid,
    name_source_device_invocation_id uuid,
    is_result boolean DEFAULT false NOT NULL,
    CONSTRAINT resource_node_active_original_parent_empty CHECK (((lifecycle <> 1) OR (original_parent_node_id IS NULL))),
    CONSTRAINT resource_node_actor_kind_closed CHECK (((actor_principal_kind >= 1) AND (actor_principal_kind <= 3))),
    CONSTRAINT resource_node_binding_closed CHECK ((((kind = 1) AND (file_artifact_id IS NULL)) OR ((kind = 2) AND (file_artifact_id IS NOT NULL)))),
    CONSTRAINT resource_node_kind_closed CHECK ((kind = ANY (ARRAY[1, 2]))),
    CONSTRAINT resource_node_lifecycle_closed CHECK ((lifecycle = ANY (ARRAY[1, 2]))),
    CONSTRAINT resource_node_name_nonempty CHECK ((((name)::text <> ''::text) AND ((comparison_name)::text <> ''::text) AND ((sort_key)::text <> ''::text))),
    CONSTRAINT resource_node_revision_positive CHECK ((revision >= 1)),
    CONSTRAINT resource_node_time_order CHECK ((updated_at_ms >= created_at_ms)),
    CONSTRAINT resource_result_file_only CHECK (((NOT is_result) OR (kind = 2)))
);


