--
-- Name: device_commands; Type: TABLE; Schema: resource; Owner: -
--

CREATE TABLE resource.device_commands (
    invocation_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    agent_id uuid NOT NULL,
    dialogue_id uuid NOT NULL,
    intent_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    run_id uuid NOT NULL,
    device_id uuid NOT NULL,
    installation_id uuid NOT NULL,
    command_commitment bytea NOT NULL,
    tool_key text NOT NULL,
    tool_call_id text NOT NULL,
    source_participant_id uuid NOT NULL,
    command_content_id uuid NOT NULL,
    request_content_id uuid NOT NULL,
    result_content_id uuid,
    receipt_content_id uuid,
    receipt_commitment bytea,
    committed_at_ms bigint,
    outcome text,
    admission_kind text DEFAULT 'intent'::text NOT NULL,
    work_item_run_id uuid,
    intent_admission_id uuid GENERATED ALWAYS AS (
CASE
    WHEN (admission_kind = 'intent'::text) THEN intent_id
    ELSE NULL::uuid
END) STORED,
    CONSTRAINT device_commands_admission_kind_check CHECK ((admission_kind = ANY (ARRAY['intent'::text, 'work_item'::text]))),
    CONSTRAINT device_commands_check CHECK ((((receipt_content_id IS NULL) = (committed_at_ms IS NULL)) AND ((receipt_content_id IS NULL) = (receipt_commitment IS NULL)) AND ((receipt_content_id IS NULL) = (outcome IS NULL)))),
    CONSTRAINT device_commands_check1 CHECK ((((outcome IS NULL) AND (result_content_id IS NULL)) OR ((outcome = 'succeeded'::text) AND (result_content_id IS NOT NULL)) OR ((outcome = 'rejected'::text) AND (result_content_id IS NULL)))),
    CONSTRAINT device_commands_check2 CHECK ((((admission_kind = 'intent'::text) AND (work_item_run_id IS NULL)) OR ((admission_kind = 'work_item'::text) AND (work_item_run_id = run_id)))),
    CONSTRAINT device_commands_command_commitment_check CHECK ((octet_length(command_commitment) = 32)),
    CONSTRAINT device_commands_outcome_check CHECK ((outcome = ANY (ARRAY['succeeded'::text, 'rejected'::text]))),
    CONSTRAINT device_commands_receipt_commitment_check CHECK (((receipt_commitment IS NULL) OR (octet_length(receipt_commitment) = 32)))
);


