CASE
    WHEN (scope_kind = 3) THEN scope_id
    ELSE NULL::uuid
END) STORED,
    CONSTRAINT resource_scope_kind_closed CHECK ((scope_kind = ANY (ARRAY[1, 2, 3, 4]))),
    CONSTRAINT resource_scope_revision_nonnegative CHECK ((revision >= 0))
);


