    dialogue_source_conversation_id uuid,
    CONSTRAINT owned_agent_scope_history_evidence CHECK ((((evidence_source = 6) = (dialogue_source_conversation_id IS NOT NULL)) AND ((evidence_source <> 6) OR (scope_kind = 4)))),
    CONSTRAINT resource_scope_history_assignment_evidence CHECK (((evidence_source = 5) = (assignment_command_id IS NOT NULL))),
    CONSTRAINT resource_scope_history_evidence_closed CHECK ((evidence_source = ANY (ARRAY[1, 2, 3, 4, 5, 6]))),
    CONSTRAINT resource_scope_history_generation_positive CHECK ((ownership_generation >= 1)),
    CONSTRAINT resource_scope_history_scope_kind_closed CHECK ((scope_kind = ANY (ARRAY[1, 2, 3, 4]))),
    CONSTRAINT resource_scope_history_transfer_evidence CHECK (((evidence_source = 3) = (transfer_change_set_id IS NOT NULL)))
);


