    CONSTRAINT resource_search_chunk_page_positive CHECK (((page_number IS NULL) OR (page_number >= 1))),
    CONSTRAINT resource_search_chunk_slide_positive CHECK (((slide_number IS NULL) OR (slide_number >= 1))),
    CONSTRAINT search_chunks_check CHECK ((end_byte >= start_byte)),
    CONSTRAINT search_chunks_chunk_ordinal_check CHECK (((chunk_ordinal >= 0) AND (chunk_ordinal <= 65535))),
    CONSTRAINT search_chunks_start_byte_check CHECK ((start_byte >= 0))
);


