    CONSTRAINT resource_search_job_lease_complete CHECK ((((status = 2) AND (lease_owner IS NOT NULL) AND (lease_expires_at_ms IS NOT NULL)) OR ((status <> 2) AND (lease_owner IS NULL) AND (lease_expires_at_ms IS NULL)))),
    CONSTRAINT resource_search_job_scope_closed CHECK ((scope_kind = ANY (ARRAY[1, 2, 3, 4]))),
    CONSTRAINT search_index_jobs_attempt_count_check CHECK (((attempt_count >= 0) AND (attempt_count <= 10))),
    CONSTRAINT search_index_jobs_status_check CHECK (((status >= 1) AND (status <= 5)))
);


