    CONSTRAINT attempt_trigger_closed CHECK (((trigger >= 1) AND (trigger <= 7)))
);


--
-- Name: context_compaction_slots; Type: TABLE; Schema: runtime; Owner: -
--

CREATE TABLE runtime.context_compaction_slots (
    slot_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    run_id uuid NOT NULL,
    loop_iteration integer NOT NULL,
    generation integer NOT NULL,
    plan_fingerprint bytea NOT NULL,
    active_branch_id uuid,
    ledger_cutoff numeric(20,0) NOT NULL,
    source_sequence_from numeric(20,0) NOT NULL,
    source_sequence_to numeric(20,0) NOT NULL,
    summarized_record_ids uuid[] NOT NULL,
    retained_record_ids uuid[] NOT NULL,
    serialized_history_hash bytea NOT NULL,
    previous_summary_content_id uuid,
    previous_summary_hash bytea,
    model_route_ref character varying(255) NOT NULL,
    route_identity_hash bytea NOT NULL,
    credential_grant_ref character varying(255) NOT NULL,
    input_budget bigint NOT NULL,
    input_tokens_before bigint NOT NULL,
    summary_budget bigint NOT NULL,
    max_output_tokens bigint NOT NULL,
    prompt_schema character varying(96) NOT NULL,
    codec_schema character varying(96) NOT NULL,
    compaction_policy_ref character varying(255) NOT NULL,
    causation_id uuid NOT NULL,
    invocation_id uuid NOT NULL,
    correlation_id uuid NOT NULL,
    sealed_attempt_id uuid NOT NULL,
    sealed_attempt_number integer NOT NULL,
    sealed_worker_id character varying(128) NOT NULL,
    sealed_lease_id uuid NOT NULL,
    sealed_fencing_token numeric(20,0) NOT NULL,
    sealed_lease_expires_at_ms bigint NOT NULL,
    sealed_deadline_ms bigint,
    owner_attempt_id uuid NOT NULL,
    owner_fencing_token numeric(20,0) NOT NULL,
    dispatch_state smallint NOT NULL,
    created_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    logical_plan_hash bytea,
    activity_timing bytea,
    activity_timing_hash bytea,
    source_key character varying(80) DEFAULT 'runtime-ledger'::character varying NOT NULL,
    CONSTRAINT compaction_activity_timing_bound CHECK (((activity_timing IS NULL) OR ((octet_length(activity_timing) >= 1) AND (octet_length(activity_timing) <= 4096)))),
    CONSTRAINT compaction_activity_timing_digest CHECK (((activity_timing_hash IS NULL) OR (octet_length(activity_timing_hash) = 32))),
    CONSTRAINT compaction_execution_timing_closed CHECK ((((sealed_deadline_ms IS NOT NULL) AND (activity_timing IS NULL) AND (activity_timing_hash IS NULL)) OR ((sealed_deadline_ms IS NULL) AND (activity_timing IS NOT NULL) AND (activity_timing_hash IS NOT NULL)))),
    CONSTRAINT context_compaction_slot_budgets_positive CHECK (((input_budget >= 1) AND (input_tokens_before >= 1) AND (summary_budget >= 1) AND (max_output_tokens >= 1))),
    CONSTRAINT context_compaction_slot_dispatch_closed CHECK (((dispatch_state >= 1) AND (dispatch_state <= 2))),
    CONSTRAINT context_compaction_slot_fences_positive CHECK (((sealed_attempt_number >= 1) AND (sealed_fencing_token >= (1)::numeric) AND (owner_fencing_token >= (1)::numeric))),
    CONSTRAINT context_compaction_slot_generation_positive CHECK ((generation >= 1)),
    CONSTRAINT context_compaction_slot_history_hash_sha256 CHECK ((octet_length(serialized_history_hash) = 32)),
    CONSTRAINT context_compaction_slot_iteration_positive CHECK ((loop_iteration >= 1)),
    CONSTRAINT context_compaction_slot_plan_hash_sha256 CHECK ((octet_length(plan_fingerprint) = 32)),
    CONSTRAINT context_compaction_slot_previous_summary_hash CHECK ((((previous_summary_content_id IS NULL) AND (previous_summary_hash IS NULL)) OR ((previous_summary_content_id IS NOT NULL) AND (octet_length(previous_summary_hash) = 32)))),
    CONSTRAINT context_compaction_slot_records_nonempty CHECK (((cardinality(summarized_record_ids) >= 1) AND (cardinality(retained_record_ids) >= 1))),
    CONSTRAINT context_compaction_slot_route_hash_sha256 CHECK ((octet_length(route_identity_hash) = 32)),
    CONSTRAINT context_compaction_slot_source_range CHECK (((source_sequence_from >= (1)::numeric) AND (source_sequence_to >= source_sequence_from) AND (ledger_cutoff >= source_sequence_to))),
    CONSTRAINT context_compaction_slots_logical_plan_hash_check CHECK (((logical_plan_hash IS NULL) OR (octet_length(logical_plan_hash) = 32))),
    CONSTRAINT context_compaction_source_key_closed CHECK ((((source_key)::text = 'runtime-ledger'::text) OR ((source_key)::text ~ '^dialogue_history:[a-f0-9]{64}$'::text) OR ((source_key)::text ~ '^control:[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'::text)))
);


--
-- Name: TABLE context_compaction_slots; Type: COMMENT; Schema: runtime; Owner: -
--

COMMENT ON TABLE runtime.context_compaction_slots IS 'Fenced logical Compression intents. dispatch_state=1 is sealed/not dispatched; 2 is dispatched and therefore indeterminate until the bound model invocation is terminal.';


--
-- Name: COLUMN context_compaction_slots.source_key; Type: COMMENT; Schema: runtime; Owner: -
--

COMMENT ON COLUMN runtime.context_compaction_slots.source_key IS 'runtime-ledger or dialogue_history:SHA256 of the canonical immutable source coverage and parent checkpoint. Not a physical attempt or retry generation.';


--
-- Name: context_plans; Type: TABLE; Schema: runtime; Owner: -
--

CREATE TABLE runtime.context_plans (
    snapshot_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    run_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    iteration integer NOT NULL,
    parent_snapshot_id uuid,
    source_sequence_from numeric(20,0) NOT NULL,
    source_sequence_to numeric(20,0) NOT NULL,
    retained_record_ids uuid[] NOT NULL,
    summary_content_id uuid NOT NULL,
    summary_content_hash bytea NOT NULL,
    summary_content_bytes numeric(20,0) NOT NULL,
    request_content_id uuid NOT NULL,
    request_content_hash bytea NOT NULL,
    request_content_bytes numeric(20,0) NOT NULL,
    input_tokens_before bigint NOT NULL,
    input_tokens_after bigint NOT NULL,
    model_route_ref character varying(255) NOT NULL,
    checksum bytea NOT NULL,
    invocation_id uuid NOT NULL,
    assistant_message_id uuid NOT NULL,
    assistant_output_id uuid NOT NULL,
    reasoning_output_id uuid NOT NULL,
    ledger_record_id uuid NOT NULL,
    committed_sequence numeric(20,0) NOT NULL,
    created_at_ms bigint NOT NULL,
    delivery_repair_binding bytea,
    delivery_repair_source_invocation_id uuid,
    lineage_generation integer,
    predecessor_snapshot_id uuid,
    predecessor_generation integer,
    predecessor_checksum bytea,
    control_record_id uuid,
    control_sequence numeric(20,0),
    control_kind smallint,
    CONSTRAINT context_delivery_repair_shape CHECK ((((delivery_repair_binding IS NULL) AND (delivery_repair_source_invocation_id IS NULL)) OR ((delivery_repair_source_invocation_id IS NOT NULL) AND (delivery_repair_binding IS NOT NULL) AND ((octet_length(delivery_repair_binding) >= 1) AND (octet_length(delivery_repair_binding) <= 16384))))),
    CONSTRAINT context_plan_checksum_sha256 CHECK ((octet_length(checksum) = 32)),
    CONSTRAINT context_plan_content_bytes_nonnegative CHECK (((summary_content_bytes >= (0)::numeric) AND (request_content_bytes >= (0)::numeric))),
    CONSTRAINT context_plan_iteration_positive CHECK ((iteration >= 1)),
    CONSTRAINT context_plan_lineage_shape CHECK ((((lineage_generation IS NULL) AND (predecessor_snapshot_id IS NULL) AND (predecessor_generation IS NULL) AND (predecessor_checksum IS NULL) AND (control_record_id IS NULL) AND (control_sequence IS NULL) AND (control_kind IS NULL)) OR ((lineage_generation IS NOT NULL) AND (lineage_generation >= 1) AND (((lineage_generation = 1) AND (predecessor_snapshot_id IS NULL) AND (predecessor_generation IS NULL) AND (predecessor_checksum IS NULL)) OR ((lineage_generation > 1) AND (predecessor_snapshot_id IS NOT NULL) AND (predecessor_generation IS NOT NULL) AND (predecessor_generation = (lineage_generation - 1)) AND (predecessor_checksum IS NOT NULL) AND (octet_length(predecessor_checksum) = 32) AND (predecessor_snapshot_id <> snapshot_id) AND (control_record_id IS NOT NULL))) AND (((control_record_id IS NULL) AND (control_sequence IS NULL) AND (control_kind IS NULL)) OR ((control_record_id IS NOT NULL) AND (control_sequence IS NOT NULL) AND (control_sequence >= (1)::numeric) AND (control_sequence <= source_sequence_to) AND (control_kind IS NOT NULL) AND (control_kind = ANY (ARRAY[1, 2]))))))),
    CONSTRAINT context_plan_request_sha256 CHECK ((octet_length(request_content_hash) = 32)),
    CONSTRAINT context_plan_retained_nonempty CHECK ((cardinality(retained_record_ids) >= 1)),
    CONSTRAINT context_plan_sequence_positive CHECK ((committed_sequence >= (1)::numeric)),
    CONSTRAINT context_plan_source_range_valid CHECK (((source_sequence_from >= (1)::numeric) AND (source_sequence_to >= source_sequence_from))),
    CONSTRAINT context_plan_summary_sha256 CHECK ((octet_length(summary_content_hash) = 32)),
    CONSTRAINT context_plan_token_counts_valid CHECK (((input_tokens_before >= 0) AND (input_tokens_after >= 0) AND (input_tokens_after <= input_tokens_before)))
);


--
