    child_activity_id uuid NOT NULL,
    child_run_id uuid NOT NULL,
    objective_content_id uuid NOT NULL,
    result_schema_key text NOT NULL,
    result_schema_hash bytea NOT NULL,
    status smallint NOT NULL,
    report_content_id uuid,
    report_media_type text,
    report_byte_length numeric(20,0),
    report_hash bytea,
    created_at_ms bigint NOT NULL,
    resolved_at_ms bigint,
    completion_mode smallint DEFAULT 1 NOT NULL,
    placement text DEFAULT 'cloud'::text NOT NULL,
    retry_of uuid,
    spawn_spec jsonb,
    CONSTRAINT delegation_kind_closed CHECK ((kind = ANY (ARRAY[1, 2]))),
    CONSTRAINT delegation_report_consistent CHECK ((((status = 1) AND (report_content_id IS NULL) AND (report_media_type IS NULL) AND (report_byte_length IS NULL) AND (report_hash IS NULL) AND (resolved_at_ms IS NULL)) OR ((status <> 1) AND (report_content_id IS NOT NULL) AND (report_media_type IS NOT NULL) AND (report_byte_length IS NOT NULL) AND (report_hash IS NOT NULL) AND (resolved_at_ms IS NOT NULL)))),
    CONSTRAINT delegation_report_hash_shape CHECK (((report_hash IS NULL) OR (octet_length(report_hash) = 32))),
    CONSTRAINT delegation_result_schema_hash_shape CHECK ((octet_length(result_schema_hash) = 32)),
    CONSTRAINT delegation_status_closed CHECK (((status >= 1) AND (status <= 5))),
    CONSTRAINT delegations_completion_mode_check CHECK ((completion_mode = ANY (ARRAY[1, 2]))),
    CONSTRAINT delegations_placement_check CHECK ((placement = 'cloud'::text))
);


