    policy_digest bytea NOT NULL,
    encoded_record bytea NOT NULL,
    record_hash bytea NOT NULL,
    due_at_ms bigint,
    closed boolean NOT NULL,
    CONSTRAINT execution_liveness_check CHECK (((NOT closed) OR ((due_at_ms IS NULL) AND (record_kind = 1)))),
    CONSTRAINT execution_liveness_encoded_record_check CHECK (((octet_length(encoded_record) >= 1) AND (octet_length(encoded_record) <= 32768))),
    CONSTRAINT execution_liveness_operation_identity_check CHECK ((octet_length(operation_identity) = 32)),
    CONSTRAINT execution_liveness_owner_fence_check CHECK ((owner_fence > 0)),
    CONSTRAINT execution_liveness_policy_digest_check CHECK ((octet_length(policy_digest) = 32)),
    CONSTRAINT execution_liveness_producer_generation_check CHECK ((producer_generation > 0)),
    CONSTRAINT execution_liveness_record_hash_check CHECK ((octet_length(record_hash) = 32)),
    CONSTRAINT execution_liveness_record_kind_check CHECK ((record_kind = ANY (ARRAY[1, 2]))),
    CONSTRAINT execution_liveness_revision_check CHECK ((revision > 0)),
    CONSTRAINT execution_liveness_scope_kind_check CHECK ((scope_kind = ANY (ARRAY[1, 2])))
);


