    model_entry_id uuid NOT NULL,
    endpoint_hash bytea NOT NULL,
    generation uuid NOT NULL,
    failures bigint NOT NULL,
    retry_not_before_ms bigint NOT NULL,
    probe_invocation_id uuid,
    probe_expires_at_ms bigint,
    repair_reason text,
    CONSTRAINT model_dependency_recovery_check CHECK (((probe_invocation_id IS NULL) = (probe_expires_at_ms IS NULL))),
    CONSTRAINT model_dependency_recovery_check1 CHECK (((probe_expires_at_ms IS NULL) OR (probe_expires_at_ms > retry_not_before_ms))),
    CONSTRAINT model_dependency_recovery_check2 CHECK (((failures > 0) OR ((retry_not_before_ms = 0) AND (probe_invocation_id IS NULL)))),
    CONSTRAINT model_dependency_recovery_check3 CHECK ((((repair_reason = ANY (ARRAY['credential'::text, 'payment'::text, 'quota'::text])) AND (failures > 0)) OR (repair_reason IS NULL))),
    CONSTRAINT model_dependency_recovery_endpoint_hash_check CHECK ((octet_length(endpoint_hash) = 32)),
    CONSTRAINT model_dependency_recovery_failures_check CHECK (((failures >= 0) AND (failures <= '4294967295'::bigint))),
    CONSTRAINT model_dependency_recovery_retry_not_before_ms_check CHECK ((retry_not_before_ms >= 0))
);


