--
-- Name: model_invocations; Type: TABLE; Schema: runtime; Owner: -
--

CREATE TABLE runtime.model_invocations (
    invocation_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    run_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    purpose smallint NOT NULL,
    status smallint NOT NULL,
    model_route_ref character varying(255) NOT NULL,
    idempotency_key character varying(200) NOT NULL,
    request_content_id uuid NOT NULL,
    request_hash bytea NOT NULL,
    response_content_id uuid,
    provider_request_ref bytea,
    continuation_input_ref bytea,
    continuation_output_ref bytea,
    usage_fact bytea,
    started_at_ms bigint NOT NULL,
    finished_at_ms bigint,
    terminal_error bytea,
    conversation_id uuid NOT NULL,
    requested_model_key character varying(200),
    pricing_version_ref character varying(255),
    assistant_message_id uuid,
    assistant_output_id uuid,
    reasoning_output_id uuid,
    started_conversation_seq bigint,
    reasoning_replay_content_id uuid,
    reasoning_replay_content_hash bytea,
    reasoning_replay_content_bytes numeric(20,0),
    credential_grant_ref character varying(512) NOT NULL,
    response_model_key character varying(200),
    route_role smallint NOT NULL,
    route_identity_hash bytea,
    public_output_observed boolean DEFAULT true NOT NULL,
    terminal_stop_reason smallint,
    provider_state_policy smallint,
    completion_intent_protected bytea,
    provider_recovery_capability smallint DEFAULT 4 NOT NULL,
    provider_dispatched_at_ms bigint,
    completion_intent_content_id uuid,
    replay_barrier_observed boolean DEFAULT true NOT NULL,
    terminal_error_retryable boolean,
    retry_not_before_ms bigint,
    parent_invocation_id uuid,
    begin_intent_hash bytea,
    erasure_job_id uuid,
    context_erasure_job_id uuid,
    early_provider_cause text,
    CONSTRAINT model_context_erased_payload CHECK (((context_erasure_job_id IS NULL) OR (num_nonnulls(provider_request_ref, continuation_input_ref, continuation_output_ref, completion_intent_protected, terminal_error) = 0))),
    CONSTRAINT model_erased_payload CHECK (((erasure_job_id IS NULL) OR (num_nonnulls(provider_request_ref, continuation_input_ref, continuation_output_ref, completion_intent_protected, terminal_error) = 0))),
    CONSTRAINT model_invocation_credential_grant_nonempty CHECK ((length((credential_grant_ref)::text) > 0)),
    CONSTRAINT model_invocation_dispatch_after_start CHECK (((provider_dispatched_at_ms IS NULL) OR (provider_dispatched_at_ms >= started_at_ms))),
    CONSTRAINT model_invocation_provider_state_policy_closed CHECK (((provider_state_policy IS NULL) OR (provider_state_policy = ANY (ARRAY[1, 2])))),
    CONSTRAINT model_invocation_reasoning_replay_consistent CHECK ((((reasoning_replay_content_id IS NULL) AND (reasoning_replay_content_hash IS NULL) AND (reasoning_replay_content_bytes IS NULL)) OR ((reasoning_replay_content_id IS NOT NULL) AND (reasoning_replay_content_hash IS NOT NULL) AND (octet_length(reasoning_replay_content_hash) = 32) AND (reasoning_replay_content_bytes IS NOT NULL) AND (reasoning_replay_content_bytes > (0)::numeric)))),
    CONSTRAINT model_invocation_recovery_capability_closed CHECK (((provider_recovery_capability >= 1) AND (provider_recovery_capability <= 4))),
    CONSTRAINT model_invocation_requested_model_nonempty CHECK (((requested_model_key IS NULL) OR (length((requested_model_key)::text) > 0))),
    CONSTRAINT model_invocation_response_model_nonempty CHECK (((response_model_key IS NULL) OR (length((response_model_key)::text) > 0))),
    CONSTRAINT model_invocation_route_identity_hash_length CHECK (((route_identity_hash IS NULL) OR (octet_length(route_identity_hash) = 32))),
    CONSTRAINT model_invocation_route_metadata_complete CHECK ((((requested_model_key IS NULL) = (pricing_version_ref IS NULL)) AND ((response_model_key IS NULL) OR (requested_model_key IS NOT NULL)))),
    CONSTRAINT model_invocation_route_role_closed CHECK (((route_role >= 0) AND (route_role <= 8))),
    CONSTRAINT model_invocation_terminal_stop_reason_closed CHECK (((terminal_stop_reason IS NULL) OR ((terminal_stop_reason >= 1) AND (terminal_stop_reason <= 7)))),
    CONSTRAINT model_invocations_begin_intent_hash_check CHECK (((begin_intent_hash IS NULL) OR ((octet_length(begin_intent_hash) = 32) AND (begin_intent_hash <> decode(repeat('00'::text, 32), 'hex'::text))))),
    CONSTRAINT model_invocations_check CHECK (((early_provider_cause IS NULL) OR ((status = 3) AND (early_provider_cause = ANY (ARRAY['rate_limited'::text, 'provider_server'::text, 'deadline_exceeded'::text, 'transport_failed'::text, 'payment_required'::text, 'quota_exceeded'::text, 'authentication_failed'::text]))))),
    CONSTRAINT model_purpose_closed CHECK (((purpose >= 1) AND (purpose <= 6))),
    CONSTRAINT model_request_hash_sha256 CHECK ((octet_length(request_hash) = 32)),
    CONSTRAINT model_retry_deadline_contract CHECK (((retry_not_before_ms IS NULL) OR ((status = 3) AND (terminal_error_retryable IS TRUE) AND (finished_at_ms IS NOT NULL) AND (retry_not_before_ms >= finished_at_ms)))),
    CONSTRAINT model_status_closed CHECK (((status >= 1) AND (status <= 4)))
);


