-- Name: COLUMN model_invocations.continuation_output_ref; Type: COMMENT; Schema: runtime; Owner: -
--

COMMENT ON COLUMN runtime.model_invocations.continuation_output_ref IS 'Encrypted provider-bound continuation reference.';


