-- Name: COLUMN model_invocations.credential_grant_ref; Type: COMMENT; Schema: runtime; Owner: -
--

COMMENT ON COLUMN runtime.model_invocations.credential_grant_ref IS 'Admission-authorized opaque grant reference; never resolved credential material.';


