-- Name: COLUMN model_invocations.provider_dispatched_at_ms; Type: COMMENT; Schema: runtime; Owner: -
--

COMMENT ON COLUMN runtime.model_invocations.provider_dispatched_at_ms IS 'Durable dispatch marker committed immediately before the production Provider port is invoked.';


