    CONSTRAINT model_usage_response_model_key_nonempty CHECK ((length((response_model_key)::text) > 0)),
    CONSTRAINT model_usage_tokens_nonnegative CHECK (((input_tokens_uncached >= 0) AND (output_tokens >= 0) AND (reasoning_tokens >= 0) AND (provider_cache_read_tokens >= 0) AND (provider_cache_write_tokens >= 0) AND ((total_tokens IS NULL) OR (total_tokens >= 0)))),
    CONSTRAINT model_usage_total_lower_bound CHECK (((total_tokens IS NULL) OR ((total_tokens)::numeric >= ((input_tokens_uncached)::numeric + (output_tokens)::numeric)))),
    CONSTRAINT usage_lineage_shape CHECK (((parent_run_id IS NULL) OR (billing_subject IS NOT NULL)))
);


