    CONSTRAINT pending_tool_calls_check CHECK (((argument_diagnostic_json IS NULL) OR ((planning_failure IS NOT NULL) AND (octet_length(argument_diagnostic_json) <= 1024) AND (jsonb_typeof((argument_diagnostic_json)::jsonb) = 'object'::text)))),
    CONSTRAINT pending_tool_erased_payload CHECK ((((erasure_job_id IS NULL) AND (arguments_json IS NOT NULL)) OR ((erasure_job_id IS NOT NULL) AND (arguments_json IS NULL) AND (argument_diagnostic_json IS NULL)))),
    CONSTRAINT pending_tool_name_nonempty CHECK ((length((wire_name)::text) > 0)),
    CONSTRAINT pending_tool_ordinal_nonnegative CHECK ((ordinal >= 0)),
    CONSTRAINT pending_tool_planning_failure_known CHECK (((planning_failure IS NULL) OR (planning_failure = ANY (ARRAY[1, 2, 3, 4])))),
    CONSTRAINT pending_tool_provider_replay_consistent CHECK ((((provider_replay_content_id IS NULL) AND (provider_replay_content_hash IS NULL) AND (provider_replay_content_bytes IS NULL)) OR ((provider_replay_content_id IS NOT NULL) AND (provider_replay_content_hash IS NOT NULL) AND (octet_length(provider_replay_content_hash) = 32) AND (provider_replay_content_bytes IS NOT NULL) AND (provider_replay_content_bytes > (0)::numeric)))),
    CONSTRAINT pending_tool_result_consistent CHECK ((((completed_at_ms IS NULL) AND (result_content_id IS NULL) AND (result_content_hash IS NULL) AND (result_content_bytes IS NULL)) OR ((completed_at_ms IS NOT NULL) AND (result_content_id IS NOT NULL) AND (result_content_hash IS NOT NULL) AND (octet_length(result_content_hash) = 32) AND (result_content_bytes IS NOT NULL) AND ((result_content_bytes)::numeric >= (0)::numeric))))
);


