    CONSTRAINT dialogue_context_bindings_check1 CHECK ((completes_cut = (through_seq = frozen_through_seq))),
    CONSTRAINT dialogue_context_bindings_epoch_check CHECK ((epoch > 0)),
    CONSTRAINT dialogue_context_bindings_from_seq_check CHECK ((from_seq > 0)),
