-- Name: runs; Type: TABLE; Schema: runtime; Owner: -
--

CREATE TABLE runtime.runs (
    run_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    activity_id uuid NOT NULL,
    activity_kind smallint NOT NULL,
    executor_participant_id uuid NOT NULL,
    requested_by_participant_id uuid NOT NULL,
    parent_run_id uuid,
    delegation_id uuid,
    execution_scope_kind smallint NOT NULL,
    workspace_id uuid,
    device_id uuid,
    control_home_kind smallint NOT NULL,
    control_device_id uuid,
    execution_home_kind smallint NOT NULL,
    execution_device_id uuid,
    home_epoch bigint NOT NULL,
    runtime_snapshot_id uuid NOT NULL,
    admitted_sequence bigint NOT NULL,
    last_run_sequence bigint DEFAULT 1 NOT NULL,
    next_fencing_token bigint DEFAULT 1 NOT NULL,
    status smallint NOT NULL,
    wait_reason smallint,
    wait_interaction_id uuid,
    wait_invocation_id uuid,
    next_attempt_number integer NOT NULL,
    not_before_ms bigint,
    cancel_requested_at_ms bigint,
    admitted_at_ms bigint NOT NULL,
    started_at_ms bigint,
    finished_at_ms bigint,
    terminal_error bytea,
    run_version bigint DEFAULT 1 NOT NULL,
    next_attempt_trigger smallint DEFAULT 1 NOT NULL,
    traceparent character varying(55) NOT NULL,
    tracestate character varying(512),
    wait_child_activity_id uuid,
    wait_error_code text,
    erasure_job_id uuid,
    CONSTRAINT run_activity_kind_closed CHECK (((activity_kind >= 1) AND (activity_kind <= 6))),
    CONSTRAINT run_admitted_sequence_positive CHECK (((admitted_sequence)::numeric >= (1)::numeric)),
    CONSTRAINT run_budget_amendment_trigger_retired CHECK ((next_attempt_trigger <> 5)),
    CONSTRAINT run_budget_wait_retired CHECK ((wait_reason IS DISTINCT FROM 5)),
    CONSTRAINT run_control_home_consistent CHECK ((((control_home_kind = 1) AND (control_device_id IS NULL)) OR ((control_home_kind = 2) AND (control_device_id IS NOT NULL)))),
    CONSTRAINT run_erased_payload CHECK (((erasure_job_id IS NULL) OR (terminal_error IS NULL))),
    CONSTRAINT run_execution_home_consistent CHECK ((((execution_home_kind = 1) AND (execution_device_id IS NULL)) OR ((execution_home_kind = 2) AND (execution_device_id IS NOT NULL)))),
    CONSTRAINT run_execution_scope_consistent CHECK ((((execution_scope_kind = 1) AND (workspace_id IS NULL) AND (device_id IS NULL)) OR ((execution_scope_kind = 2) AND (workspace_id IS NOT NULL) AND (device_id IS NULL)) OR ((execution_scope_kind = 3) AND (device_id IS NOT NULL)))),
    CONSTRAINT run_home_epoch_positive CHECK (((home_epoch)::numeric >= (1)::numeric)),
    CONSTRAINT run_interaction_wait_invocation_bound CHECK (((wait_interaction_id IS NULL) OR (wait_invocation_id IS NOT NULL))),
    CONSTRAINT run_next_attempt_positive CHECK ((next_attempt_number >= 1)),
    CONSTRAINT run_next_attempt_trigger_closed CHECK (((next_attempt_trigger >= 1) AND (next_attempt_trigger <= 7))),
    CONSTRAINT run_next_fencing_positive CHECK (((next_fencing_token)::numeric >= (1)::numeric)),
    CONSTRAINT run_repair_wait_error CHECK ((((wait_error_code IS NULL) AND ((wait_reason IS NULL) OR (wait_reason <> 10))) OR ((status = 3) AND (wait_reason = 10) AND (wait_error_code IS NOT NULL) AND (length(wait_error_code) > 0)))),
    CONSTRAINT run_sequence_positive CHECK (((last_run_sequence)::numeric >= (1)::numeric)),
    CONSTRAINT run_status_closed CHECK (((status >= 1) AND (status <= 8))),
    CONSTRAINT run_trace_context_pair CHECK (((traceparent IS NOT NULL) OR (tracestate IS NULL))),
    CONSTRAINT run_version_positive CHECK (((run_version)::numeric >= (1)::numeric)),
    CONSTRAINT run_wait_fields_consistent CHECK ((((status = 3) AND (wait_reason IS NOT NULL)) OR ((status <> 3) AND (wait_reason IS NULL) AND (wait_interaction_id IS NULL) AND (wait_invocation_id IS NULL) AND (wait_child_activity_id IS NULL))))
);


