-- Name: standing_goals; Type: TABLE; Schema: runtime; Owner: -
--

CREATE TABLE runtime.standing_goals (
    goal_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    revision numeric(20,0) NOT NULL,
    owner_principal_id uuid NOT NULL,
    origin smallint NOT NULL,
    creator_agent_id uuid,
    target_agent_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    title character varying(240) NOT NULL,
    objective_content_id uuid NOT NULL,
    constraints jsonb NOT NULL,
    success_criteria jsonb NOT NULL,
    evidence_requirements jsonb NOT NULL,
    failure_conditions jsonb NOT NULL,
    minimum_evidence_items smallint NOT NULL,
    max_runs integer NOT NULL,
    max_elapsed_millis numeric(20,0) NOT NULL,
    max_model_tokens numeric(20,0) NOT NULL,
    max_tool_invocations numeric(20,0) NOT NULL,
    max_consecutive_failures integer NOT NULL,
    status smallint NOT NULL,
    active_pursuit_id uuid,
    created_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    completion_risk_class smallint DEFAULT 1 NOT NULL,
    mode smallint DEFAULT 1 NOT NULL,
    input_accepted_seq bigint DEFAULT 0 NOT NULL,
    input_consumed_seq bigint DEFAULT 0 NOT NULL,
    input_batch_first bigint,
    input_batch_last bigint,
    input_batch_run_id uuid,
    CONSTRAINT standing_goal_continuous_status CHECK (((mode = 1) OR (status <> 4))),
    CONSTRAINT standing_goal_input_batch CHECK ((((input_batch_first IS NULL) AND (input_batch_last IS NULL) AND (input_batch_run_id IS NULL)) OR ((input_batch_first IS NOT NULL) AND (input_batch_last IS NOT NULL) AND (input_batch_first = (input_consumed_seq + 1)) AND (input_batch_last >= input_batch_first) AND (input_batch_last <= input_accepted_seq) AND ((input_batch_last - input_batch_first) < 100)))),
    CONSTRAINT standing_goals_check CHECK (((max_consecutive_failures >= 1) AND (max_consecutive_failures <= max_runs))),
    CONSTRAINT standing_goals_check1 CHECK ((updated_at_ms >= created_at_ms)),
    CONSTRAINT standing_goals_check2 CHECK ((((origin = 1) AND (creator_agent_id IS NULL)) OR ((origin = 2) AND (creator_agent_id IS NOT NULL)))),
    CONSTRAINT standing_goals_check3 CHECK ((((status = 2) AND (active_pursuit_id IS NOT NULL)) OR ((status <> 2) AND (active_pursuit_id IS NULL)))),
    CONSTRAINT standing_goals_check4 CHECK (((input_consumed_seq >= 0) AND (input_consumed_seq <= input_accepted_seq))),
    CONSTRAINT standing_goals_completion_risk_class_check CHECK ((completion_risk_class = ANY (ARRAY[1, 2]))),
    CONSTRAINT standing_goals_constraints_check CHECK ((jsonb_typeof(constraints) = 'array'::text)),
    CONSTRAINT standing_goals_evidence_requirements_check CHECK ((jsonb_typeof(evidence_requirements) = 'array'::text)),
    CONSTRAINT standing_goals_failure_conditions_check CHECK ((jsonb_typeof(failure_conditions) = 'array'::text)),
    CONSTRAINT standing_goals_input_accepted_seq_check CHECK ((input_accepted_seq >= 0)),
    CONSTRAINT standing_goals_max_elapsed_millis_check CHECK ((max_elapsed_millis > (0)::numeric)),
    CONSTRAINT standing_goals_max_model_tokens_check CHECK ((max_model_tokens > (0)::numeric)),
    CONSTRAINT standing_goals_max_runs_check CHECK (((max_runs >= 1) AND (max_runs <= 10000))),
    CONSTRAINT standing_goals_max_tool_invocations_check CHECK ((max_tool_invocations > (0)::numeric)),
    CONSTRAINT standing_goals_minimum_evidence_items_check CHECK (((minimum_evidence_items >= 0) AND (minimum_evidence_items <= 128))),
    CONSTRAINT standing_goals_mode_check CHECK ((mode = ANY (ARRAY[1, 2]))),
    CONSTRAINT standing_goals_origin_check CHECK (((origin >= 1) AND (origin <= 2))),
    CONSTRAINT standing_goals_revision_check CHECK ((revision >= (1)::numeric)),
    CONSTRAINT standing_goals_status_check CHECK (((status >= 1) AND (status <= 6))),
    CONSTRAINT standing_goals_success_criteria_check CHECK ((jsonb_typeof(success_criteria) = 'array'::text)),
    CONSTRAINT standing_goals_title_check CHECK ((length(btrim((title)::text)) > 0))
);


--
-- Name: TABLE standing_goals; Type: COMMENT; Schema: runtime; Owner: -
--

COMMENT ON TABLE runtime.standing_goals IS 'Durable Goal definition owned independently from any individual Run.';


--
-- Name: COLUMN standing_goals.completion_risk_class; Type: COMMENT; Schema: runtime; Owner: -
--

COMMENT ON COLUMN runtime.standing_goals.completion_risk_class IS '1=standard semantic Judge permitted; 2=high risk deterministic verifier or explicit human confirmation required';


--
-- Name: tool_exposures; Type: TABLE; Schema: runtime; Owner: -
--

CREATE TABLE runtime.tool_exposures (
    tenant_id uuid NOT NULL,
    run_id uuid NOT NULL,
    tool_key text NOT NULL,
    schema_hash bytea NOT NULL,
    ordinal integer NOT NULL,
    source_invocation_id uuid NOT NULL,
    reason_content_id uuid NOT NULL,
    exposed_at_ms bigint NOT NULL,
    record_id uuid NOT NULL,
    CONSTRAINT tool_exposures_ordinal_check CHECK ((ordinal > 0)),
    CONSTRAINT tool_exposures_schema_hash_check CHECK ((octet_length(schema_hash) = 32))
);


--
-- Name: TABLE tool_exposures; Type: COMMENT; Schema: runtime; Owner: -
--

COMMENT ON TABLE runtime.tool_exposures IS 'Run-scoped monotonic Tool disclosure facts; bootstrap and carry-forward prefixes remain sealed in Runtime Snapshot.';


--
-- Name: admission_denials; Type: TABLE; Schema: security_audit; Owner: -
--

CREATE TABLE security_audit.admission_denials (
    tenant_id uuid NOT NULL,
    command_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    actor_principal_id uuid NOT NULL,
    actor_principal_kind smallint NOT NULL,
    correlation_id uuid NOT NULL,
    trace_id bytea NOT NULL,
    command_fingerprint bytea NOT NULL,
    error_code character varying(96) NOT NULL,
    retryable boolean NOT NULL,
    occurred_at_ms bigint NOT NULL,
    audit_record_id uuid,
    committed_at_ms bigint DEFAULT (floor((EXTRACT(epoch FROM clock_timestamp()) * (1000)::numeric)))::bigint NOT NULL,
    diagnostic_ref character varying(512),
    CONSTRAINT security_audit_admission_denial_diagnostic_ref_shape CHECK (((diagnostic_ref IS NULL) OR ((length((diagnostic_ref)::text) >= 1) AND (length((diagnostic_ref)::text) <= 512) AND ((diagnostic_ref)::text ~ '^[!-~]+$'::text)))),
    CONSTRAINT security_audit_admission_denial_error_nonempty CHECK ((length((error_code)::text) > 0)),
    CONSTRAINT security_audit_admission_denial_fingerprint_shape CHECK ((octet_length(command_fingerprint) = 32)),
    CONSTRAINT security_audit_admission_denial_principal_kind_closed CHECK (((actor_principal_kind >= 1) AND (actor_principal_kind <= 3))),
    CONSTRAINT security_audit_admission_denial_trace_shape CHECK ((octet_length(trace_id) = 16))
);


--
-- Name: COLUMN admission_denials.diagnostic_ref; Type: COMMENT; Schema: security_audit; Owner: -
--

COMMENT ON COLUMN security_audit.admission_denials.diagnostic_ref IS 'Opaque non-secret correlation key for operator logs and incident tooling.';


--
-- Name: records; Type: TABLE; Schema: security_audit; Owner: -
--

CREATE TABLE security_audit.records (
    audit_record_id uuid NOT NULL,
    schema_version character varying(160) NOT NULL,
    tenant_id uuid NOT NULL,
    actor_principal_id uuid NOT NULL,
    actor_principal_kind smallint NOT NULL,
    action smallint NOT NULL,
    outcome smallint NOT NULL,
    resource_count smallint NOT NULL,
    source_ledger_record_id uuid,
    correlation_id uuid NOT NULL,
    detail_content_id uuid,
    detail_media_type character varying(255),
    detail_byte_length numeric(20,0),
    detail_sha256 bytea,
    retention_policy_ref character varying(256) NOT NULL,
    occurred_at_ms bigint NOT NULL,
    committed_at_ms bigint DEFAULT (floor((EXTRACT(epoch FROM clock_timestamp()) * (1000)::numeric)))::bigint NOT NULL,
    proposal_fingerprint bytea NOT NULL,
    source_erasure_job_id uuid,
    source_model_invocation_id uuid,
    source_tool_invocation_id uuid,
    trace_id bytea,
    CONSTRAINT security_audit_action_closed CHECK (((action >= 1) AND (action <= 12))),
    CONSTRAINT security_audit_detail_shape CHECK ((((detail_content_id IS NULL) AND (detail_media_type IS NULL) AND (detail_byte_length IS NULL) AND (detail_sha256 IS NULL)) OR ((detail_content_id IS NOT NULL) AND (detail_media_type IS NOT NULL) AND (length((detail_media_type)::text) > 0) AND (detail_byte_length IS NOT NULL) AND (detail_byte_length >= (0)::numeric) AND (detail_sha256 IS NOT NULL) AND (octet_length(detail_sha256) = 32)))),
    CONSTRAINT security_audit_outcome_closed CHECK (((outcome >= 1) AND (outcome <= 3))),
    CONSTRAINT security_audit_principal_kind_closed CHECK (((actor_principal_kind >= 1) AND (actor_principal_kind <= 3))),
    CONSTRAINT security_audit_proposal_fingerprint_sha256 CHECK ((octet_length(proposal_fingerprint) = 32)),
    CONSTRAINT security_audit_resource_count_bounded CHECK (((resource_count >= 1) AND (resource_count <= 32))),
    CONSTRAINT security_audit_retention_policy_nonempty CHECK ((length((retention_policy_ref)::text) > 0)),
    CONSTRAINT security_audit_schema_version_nonempty CHECK ((length((schema_version)::text) > 0)),
    CONSTRAINT security_audit_source_shape CHECK ((((action = ANY (ARRAY[1, 4, 5, 7, 8, 11])) AND (source_ledger_record_id IS NOT NULL) AND (source_erasure_job_id IS NULL) AND (source_model_invocation_id IS NULL) AND (source_tool_invocation_id IS NULL)) OR ((action = 6) AND (source_ledger_record_id IS NULL) AND (source_erasure_job_id IS NOT NULL) AND (source_model_invocation_id IS NULL) AND (source_tool_invocation_id IS NULL)) OR ((action = 2) AND (source_ledger_record_id IS NULL) AND (source_erasure_job_id IS NULL) AND (source_model_invocation_id IS NOT NULL) AND (source_tool_invocation_id IS NULL)) OR ((action = 9) AND (source_ledger_record_id IS NULL) AND (source_erasure_job_id IS NULL) AND (source_model_invocation_id IS NOT NULL) AND (source_tool_invocation_id IS NULL)) OR ((action = ANY (ARRAY[10, 12])) AND (source_ledger_record_id IS NULL) AND (source_erasure_job_id IS NULL) AND (source_model_invocation_id IS NULL) AND (source_tool_invocation_id IS NOT NULL)) OR ((action = 3) AND (source_ledger_record_id IS NULL) AND (source_erasure_job_id IS NULL) AND (source_model_invocation_id IS NULL) AND (source_tool_invocation_id IS NULL)))),
    CONSTRAINT security_audit_trace_shape CHECK (((((schema_version)::text <> 'musteragent.legacy.security.audit.v2'::text) AND ((trace_id IS NULL) OR (octet_length(trace_id) = 16))) OR (((schema_version)::text = 'musteragent.legacy.security.audit.v2'::text) AND (action = ANY (ARRAY[1, 2, 3, 8, 9, 10, 11, 12])) AND (trace_id IS NOT NULL) AND (octet_length(trace_id) = 16)) OR (((schema_version)::text = 'musteragent.legacy.security.audit.v2'::text) AND (action = ANY (ARRAY[4, 5, 7])) AND ((trace_id IS NULL) OR (octet_length(trace_id) = 16))) OR (((schema_version)::text = 'musteragent.legacy.security.audit.v2'::text) AND (action = 6) AND (trace_id IS NULL))))
);


--
-- Name: TABLE records; Type: COMMENT; Schema: security_audit; Owner: -
--

COMMENT ON TABLE security_audit.records IS 'Independent immutable compliance facts; never Conversation Ledger records.';


--
-- Name: COLUMN records.detail_content_id; Type: COMMENT; Schema: security_audit; Owner: -
--

COMMENT ON COLUMN security_audit.records.detail_content_id IS 'Optional ContentRef identity only; raw detail and secrets are forbidden.';


--
-- Name: COLUMN records.retention_policy_ref; Type: COMMENT; Schema: security_audit; Owner: -
--

COMMENT ON COLUMN security_audit.records.retention_policy_ref IS 'Approved versioned retention-policy reference admitted by the Runtime.';


--
-- Name: COLUMN records.trace_id; Type: COMMENT; Schema: security_audit; Owner: -
--

COMMENT ON COLUMN security_audit.records.trace_id IS 'Fixed 16-byte W3C trace id; never a copied traceparent or tracestate header.';


--
-- Name: resource_refs; Type: TABLE; Schema: security_audit; Owner: -
--

CREATE TABLE security_audit.resource_refs (
    tenant_id uuid NOT NULL,
    audit_record_id uuid NOT NULL,
    ordinal smallint NOT NULL,
    resource_kind smallint NOT NULL,
    resource_id uuid,
    content_id uuid,
    content_media_type character varying(255),
    content_byte_length numeric(20,0),
    content_sha256 bytea,
    resource_fingerprint bytea NOT NULL,
    CONSTRAINT security_audit_resource_fingerprint_sha256 CHECK ((octet_length(resource_fingerprint) = 32)),
    CONSTRAINT security_audit_resource_kind_closed CHECK (((resource_kind >= 1) AND (resource_kind <= 10))),
    CONSTRAINT security_audit_resource_ordinal_bounded CHECK (((ordinal >= 0) AND (ordinal <= 31))),
    CONSTRAINT security_audit_resource_shape CHECK ((((resource_kind <> 7) AND (resource_id IS NOT NULL) AND (content_id IS NULL) AND (content_media_type IS NULL) AND (content_byte_length IS NULL) AND (content_sha256 IS NULL)) OR ((resource_kind = 7) AND (resource_id IS NULL) AND (content_id IS NOT NULL) AND (content_media_type IS NOT NULL) AND (length((content_media_type)::text) > 0) AND (content_byte_length IS NOT NULL) AND (content_byte_length >= (0)::numeric) AND (content_sha256 IS NOT NULL) AND (octet_length(content_sha256) = 32))))
);


--
-- Name: run_executor_authorities; Type: VIEW; Schema: security_audit; Owner: -
--

CREATE VIEW security_audit.run_executor_authorities AS
 SELECT run.tenant_id,
    run.run_id,
    run.conversation_id,
    executor.participant_id,
    executor.kind,
    executor.principal_ref,
    executor.agent_ref,
    executor.service_ref,
    executor.left_at_ms,
        CASE executor.kind
            WHEN 1 THEN executor.principal_ref
            WHEN 2 THEN executor.agent_ref
            ELSE NULL::uuid
        END AS actor_principal_id,
    (
        CASE executor.kind
            WHEN 1 THEN 1
            WHEN 2 THEN 3
            ELSE NULL::integer
        END)::smallint AS actor_principal_kind
   FROM (runtime.runs run
     JOIN conversation.participants executor ON (((executor.tenant_id = run.tenant_id) AND (executor.conversation_id = run.conversation_id) AND (executor.participant_id = run.executor_participant_id))))
  WHERE (executor.kind = ANY (ARRAY[1, 2]));


--
-- Name: active_version_pointers; Type: TABLE; Schema: skill; Owner: -
--

CREATE TABLE skill.active_version_pointers (
    tenant_id uuid NOT NULL,
    skill_id uuid NOT NULL,
    skill_version_id uuid NOT NULL,
    pointer_version numeric(20,0) NOT NULL,
    activated_at_ms bigint NOT NULL,
    activated_by uuid NOT NULL,
    installed boolean DEFAULT true NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    saved boolean DEFAULT true NOT NULL,
    CONSTRAINT skill_active_pointer_version_positive CHECK ((pointer_version > (0)::numeric)),
    CONSTRAINT skill_pointer_availability_shape CHECK ((installed OR (NOT enabled))),
    CONSTRAINT skill_pointer_saved_shape CHECK ((saved OR ((NOT installed) AND (NOT enabled))))
);


--
-- Name: COLUMN active_version_pointers.saved; Type: COMMENT; Schema: skill; Owner: -
--

COMMENT ON COLUMN skill.active_version_pointers.saved IS 'Authoritative private My Skills ownership. saved=false is a deletion tombstone; installed and enabled must also be false.';


--
-- Name: package_audits; Type: TABLE; Schema: skill; Owner: -
--

CREATE TABLE skill.package_audits (
    tenant_id uuid NOT NULL,
    skill_version_id uuid NOT NULL,
    manifest_hash bytea NOT NULL,
    file_set_hash bytea NOT NULL,
    signature_verified boolean NOT NULL,
    manifest_verified boolean NOT NULL,
    file_hashes_verified boolean NOT NULL,
    static_audit_passed boolean NOT NULL,
    scripts_executed boolean NOT NULL,
    quarantine_disposition smallint NOT NULL,
    audit_digest bytea NOT NULL,
    CONSTRAINT skill_audit_activation_gate CHECK ((manifest_verified AND file_hashes_verified AND static_audit_passed AND (NOT scripts_executed) AND (quarantine_disposition = 1))),
    CONSTRAINT skill_audit_digest_sha256 CHECK ((octet_length(audit_digest) = 32)),
    CONSTRAINT skill_audit_file_set_sha256 CHECK ((octet_length(file_set_hash) = 32)),
    CONSTRAINT skill_audit_manifest_sha256 CHECK ((octet_length(manifest_hash) = 32)),
    CONSTRAINT skill_audit_quarantine_closed CHECK ((quarantine_disposition = ANY (ARRAY[1, 2])))
);


--
-- Name: product_account_installations; Type: TABLE; Schema: skill; Owner: -
--

CREATE TABLE skill.product_account_installations (
    tenant_id uuid NOT NULL,
    principal_id uuid NOT NULL,
    market_skill_id uuid NOT NULL,
    product text NOT NULL,
    revision bigint NOT NULL,
    installed boolean NOT NULL,
    skill_version_id uuid,
    changed_at_ms bigint NOT NULL,
    CONSTRAINT product_account_installations_check CHECK (((NOT installed) OR (skill_version_id IS NOT NULL))),
    CONSTRAINT product_account_installations_product_check CHECK ((product ~ '^[a-z][a-z0-9-]{0,31}$'::text)),
    CONSTRAINT product_account_installations_revision_check CHECK ((revision > 0))
);


--
-- Name: product_import_commands; Type: TABLE; Schema: skill; Owner: -
--

CREATE TABLE skill.product_import_commands (
    tenant_id uuid NOT NULL,
    principal_id uuid NOT NULL,
    command_id uuid NOT NULL,
    market_skill_id uuid,
    market_version_id uuid,
    surface text NOT NULL,
    request_bytes bytea NOT NULL,
    request_digest bytea NOT NULL,
    archive_content_id uuid,
    skill_id uuid NOT NULL,
    skill_key text NOT NULL,
    identity_created_at_ms bigint NOT NULL,
    skill_version_id uuid NOT NULL,
    version bigint NOT NULL,
    parent_skill_version_id uuid,
    expected_skill_version_id uuid,
    expected_pointer_version bigint,
    compatible_surfaces smallint[] NOT NULL,
    payload_hash bytea NOT NULL,
    created_version boolean NOT NULL,
    accepted_at_ms bigint NOT NULL,
    status smallint DEFAULT 1 NOT NULL,
    completed_at_ms bigint,
    receipt_pointer_version bigint,
    retained_version_id uuid,
    source_kind smallint DEFAULT 1 NOT NULL,
    CONSTRAINT product_import_commands_check CHECK (((expected_skill_version_id IS NULL) = (expected_pointer_version IS NULL))),
    CONSTRAINT product_import_commands_check1 CHECK (((completed_at_ms IS NULL) OR (completed_at_ms >= accepted_at_ms))),
    CONSTRAINT product_import_commands_check2 CHECK ((((status = 1) AND (archive_content_id IS NOT NULL) AND (completed_at_ms IS NULL) AND (receipt_pointer_version IS NULL) AND (retained_version_id IS NULL)) OR ((status = 2) AND (archive_content_id IS NULL) AND (completed_at_ms IS NOT NULL) AND (receipt_pointer_version IS NOT NULL) AND (retained_version_id = skill_version_id)) OR ((status = 3) AND (archive_content_id IS NULL) AND (completed_at_ms IS NOT NULL) AND (receipt_pointer_version IS NULL) AND (retained_version_id IS NULL)))),
    CONSTRAINT product_import_commands_compatible_surfaces_check CHECK (((cardinality(compatible_surfaces) >= 1) AND (cardinality(compatible_surfaces) <= 6))),
    CONSTRAINT product_import_commands_expected_pointer_version_check CHECK ((expected_pointer_version > 0)),
    CONSTRAINT product_import_commands_payload_hash_check CHECK ((octet_length(payload_hash) = 32)),
    CONSTRAINT product_import_commands_receipt_pointer_version_check CHECK ((receipt_pointer_version > 0)),
    CONSTRAINT product_import_commands_request_bytes_check CHECK (((octet_length(request_bytes) >= 1) AND (octet_length(request_bytes) <= 16384))),
    CONSTRAINT product_import_commands_request_digest_check CHECK ((octet_length(request_digest) = 32)),
    CONSTRAINT product_import_commands_source_kind_check CHECK ((source_kind = ANY (ARRAY[1, 2]))),
    CONSTRAINT product_import_commands_status_check CHECK ((status = ANY (ARRAY[1, 2, 3]))),
    CONSTRAINT product_import_commands_surface_check CHECK ((surface = ANY (ARRAY['web'::text, 'desktop'::text, 'mobile'::text]))),
    CONSTRAINT product_import_commands_version_check CHECK ((version > 0)),
    CONSTRAINT product_import_origin_shape CHECK ((((source_kind = 1) AND (market_skill_id IS NOT NULL) AND (market_version_id IS NOT NULL)) OR ((source_kind = 2) AND (market_skill_id IS NULL) AND (market_version_id IS NULL))))
);


--
-- Name: retained_admission_catalogs; Type: TABLE; Schema: skill; Owner: -
