    CONSTRAINT retained_admission_catalogs_archived_at_ms_check CHECK ((archived_at_ms > 0)),
    CONSTRAINT retained_admission_catalogs_base_skill_ref_check CHECK ((base_skill_ref ~ '^[a-z][a-z0-9.-]*@[1-9][0-9]*$'::text)),
    CONSTRAINT retained_admission_catalogs_catalog_sha256_check CHECK ((octet_length(catalog_sha256) = 32)),
    CONSTRAINT retained_admission_catalogs_encoded_catalog_check CHECK (((octet_length(encoded_catalog) >= 1) AND (octet_length(encoded_catalog) <= 2097152))),
    CONSTRAINT retained_admission_catalogs_product_check CHECK ((product ~ '^[a-z][a-z0-9-]{0,31}$'::text)),
    CONSTRAINT retained_admission_catalogs_source_contract_sha256_check CHECK ((octet_length(source_contract_sha256) = 32))
);


--
-- Name: TABLE retained_admission_catalogs; Type: COMMENT; Schema: skill; Owner: -
--

COMMENT ON TABLE skill.retained_admission_catalogs IS 'Verified public historical admission material. Exact original Skill identities and ContentRefs; no tenant installs or execution grants.';


