);


--
-- Name: skill_package_previews; Type: TABLE; Schema: skill; Owner: -
--

CREATE TABLE skill.skill_package_previews (
    preview_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    owner_principal_id uuid NOT NULL,
    identity_key character varying(160) NOT NULL,
    target_skill_id uuid,
    baseline_skill_version_id uuid,
    revision numeric(20,0) NOT NULL,
