    creation_idempotency_key character varying(200) NOT NULL,
    last_mutation_idempotency_key character varying(200) NOT NULL,
    created_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    CONSTRAINT skill_package_previews_check CHECK ((updated_at_ms >= created_at_ms)),
    CONSTRAINT skill_package_previews_check1 CHECK (((target_skill_id IS NULL) = (baseline_skill_version_id IS NULL))),
    CONSTRAINT skill_package_previews_check2 CHECK ((((status = 1) AND (NOT validation_passed)) OR ((status = 2) AND validation_passed) OR (status = 3))),
    CONSTRAINT skill_package_previews_revision_check CHECK ((revision > (0)::numeric)),
    CONSTRAINT skill_package_previews_source_archive_byte_length_check CHECK ((source_archive_byte_length > (0)::numeric)),
    CONSTRAINT skill_package_previews_source_archive_hash_check CHECK ((octet_length(source_archive_hash) = 32)),
    CONSTRAINT skill_package_previews_source_payload_hash_check CHECK ((octet_length(source_payload_hash) = 32)),
    CONSTRAINT skill_package_previews_status_check CHECK (((status >= 1) AND (status <= 3))),
    CONSTRAINT skill_package_previews_validation_report_byte_length_check CHECK ((validation_report_byte_length > (0)::numeric)),
    CONSTRAINT skill_package_previews_validation_report_hash_check CHECK ((octet_length(validation_report_hash) = 32))
);


--
-- Name: TABLE skill_package_previews; Type: COMMENT; Schema: skill; Owner: -
--

COMMENT ON TABLE skill.skill_package_previews IS 'Private mutable Skill Package checkouts. Saving and installation are separate lifecycle pointer operations; there is no ordinary-user publication state.';


--
-- Name: skill_versions; Type: TABLE; Schema: skill; Owner: -
--

CREATE TABLE skill.skill_versions (
    skill_version_id uuid NOT NULL,
    skill_id uuid NOT NULL,
    version numeric(20,0) NOT NULL,
    manifest_hash bytea NOT NULL,
    skill_ref character varying(192) NOT NULL,
    supersedes uuid,
    title character varying(120) NOT NULL,
    description character varying(1000) NOT NULL,
    when_to_use character varying(1000) NOT NULL,
    instructions_content_id uuid NOT NULL,
    instructions_media_type character varying(255) NOT NULL,
    instructions_byte_length numeric(20,0) NOT NULL,
    instructions_hash bytea NOT NULL,
    manifest_content_id uuid NOT NULL,
    manifest_media_type character varying(255) NOT NULL,
    manifest_byte_length numeric(20,0) NOT NULL,
    required_tools jsonb NOT NULL,
    optional_tools jsonb NOT NULL,
    compatible_agent_contracts jsonb NOT NULL,
    compatible_surfaces smallint[] NOT NULL,
    file_set_hash bytea NOT NULL,
    audit_digest bytea NOT NULL,
    created_at_ms bigint NOT NULL,
    declared_version character varying(200),
    source_format smallint NOT NULL,
    package_content_id uuid NOT NULL,
    package_media_type character varying(255) NOT NULL,
    package_byte_length numeric(20,0) NOT NULL,
    package_hash bytea NOT NULL,
    package_dependencies jsonb NOT NULL,
    resources jsonb NOT NULL,
    compatibility_findings jsonb NOT NULL,
    CONSTRAINT skill_manifest_sha256 CHECK ((octet_length(manifest_hash) = 32)),
    CONSTRAINT skill_version_audit_sha256 CHECK ((octet_length(audit_digest) = 32)),
    CONSTRAINT skill_version_compatibility_findings_array CHECK ((jsonb_typeof(compatibility_findings) = 'array'::text)),
    CONSTRAINT skill_version_declared_version_nonempty CHECK (((declared_version IS NULL) OR (btrim((declared_version)::text) <> ''::text))),
    CONSTRAINT skill_version_description_nonempty CHECK ((btrim((description)::text) <> ''::text)),
    CONSTRAINT skill_version_file_set_sha256 CHECK ((octet_length(file_set_hash) = 32)),
    CONSTRAINT skill_version_instructions_nonempty CHECK ((instructions_byte_length > (0)::numeric)),
    CONSTRAINT skill_version_instructions_sha256 CHECK ((octet_length(instructions_hash) = 32)),
    CONSTRAINT skill_version_manifest_ref_nonempty CHECK ((manifest_byte_length > (0)::numeric)),
    CONSTRAINT skill_version_package_dependencies_array CHECK ((jsonb_typeof(package_dependencies) = 'array'::text)),
    CONSTRAINT skill_version_package_ref_nonempty CHECK ((package_byte_length > (0)::numeric)),
    CONSTRAINT skill_version_package_sha256 CHECK ((octet_length(package_hash) = 32)),
    CONSTRAINT skill_version_parent_distinct CHECK (((supersedes IS NULL) OR (supersedes <> skill_version_id))),
    CONSTRAINT skill_version_positive CHECK ((version >= (1)::numeric)),
    CONSTRAINT skill_version_resources_array CHECK (((jsonb_typeof(resources) = 'array'::text) AND (jsonb_array_length(resources) > 0))),
    CONSTRAINT skill_version_source_format_closed CHECK (((source_format >= 1) AND (source_format <= 5))),
    CONSTRAINT skill_version_title_nonempty CHECK ((btrim((title)::text) <> ''::text)),
    CONSTRAINT skill_version_when_to_use_nonempty CHECK ((btrim((when_to_use)::text) <> ''::text))
);


--
-- Name: TABLE skill_versions; Type: COMMENT; Schema: skill; Owner: -
--

COMMENT ON TABLE skill.skill_versions IS 'Immutable tenant-owned Skill package versions. Official Built-in history is not projected into lifecycle storage.';


--
-- Name: COLUMN skill_versions.source_format; Type: COMMENT; Schema: skill; Owner: -
--

COMMENT ON COLUMN skill.skill_versions.source_format IS 'Compatibility provenance only: 1=legacy agent, 2=Codex, 3=retired generic, 4=plugin, 5=generic.';


--
-- Name: COLUMN skill_versions.package_content_id; Type: COMMENT; Schema: skill; Owner: -
--

COMMENT ON COLUMN skill.skill_versions.package_content_id IS 'Reference to canonical envelope plus payload .dskill bytes owned exclusively by the Content Store.';


--
-- Name: COLUMN skill_versions.resources; Type: COMMENT; Schema: skill; Owner: -
--

COMMENT ON COLUMN skill.skill_versions.resources IS 'Complete canonical payload inventory used for restart-safe validation and governed disclosure.';


--
-- Name: skills; Type: TABLE; Schema: skill; Owner: -
--

CREATE TABLE skill.skills (
    skill_id uuid NOT NULL,
    skill_key character varying(200) NOT NULL,
    lifecycle smallint NOT NULL,
    created_at_ms bigint NOT NULL,
    tenant_id uuid NOT NULL,
    provenance_kind smallint NOT NULL,
    source_kind smallint,
    source_ref character varying(2000),
    publisher_ref character varying(500),
    created_by uuid,
    trust_level smallint NOT NULL,
    CONSTRAINT skill_lifecycle_closed CHECK (((lifecycle >= 1) AND (lifecycle <= 3))),
    CONSTRAINT skill_provenance_kind_closed CHECK ((provenance_kind = ANY (ARRAY[2, 3]))),
    CONSTRAINT skill_provenance_shape CHECK ((((provenance_kind = 2) AND (source_kind IS NULL) AND (source_ref IS NULL) AND (publisher_ref IS NULL) AND (created_by IS NOT NULL) AND (trust_level = 4)) OR ((provenance_kind = 3) AND (source_kind IS NOT NULL) AND (source_ref IS NOT NULL) AND (publisher_ref IS NOT NULL) AND (created_by IS NULL) AND (trust_level = ANY (ARRAY[2, 3]))))),
    CONSTRAINT skill_source_kind_closed CHECK (((source_kind IS NULL) OR ((source_kind >= 1) AND (source_kind <= 4)))),
    CONSTRAINT skill_trust_level_closed CHECK (((trust_level >= 1) AND (trust_level <= 4)))
);


--
-- Name: TABLE skills; Type: COMMENT; Schema: skill; Owner: -
--

COMMENT ON TABLE skill.skills IS 'Tenant-owned Local and Installed Skill identities. Official Built-ins are compiled Runtime Release facts.';


--
-- Name: origin_tool_calls; Type: TABLE; Schema: tool; Owner: -
--

CREATE TABLE tool.origin_tool_calls (
    invocation_id uuid NOT NULL,
    intent_id uuid NOT NULL,
    installation_id uuid NOT NULL,
    claim_id uuid,
    request_ref bytea NOT NULL,
    result_ref bytea,
    failed boolean,
    progress_units bigint DEFAULT 0 NOT NULL,
    CONSTRAINT origin_tool_calls_check CHECK (((result_ref IS NULL) = (failed IS NULL))),
    CONSTRAINT origin_tool_calls_check1 CHECK (((result_ref IS NULL) OR (claim_id IS NOT NULL))),
    CONSTRAINT origin_tool_calls_progress_units_check CHECK ((progress_units >= 0)),
    CONSTRAINT origin_tool_calls_request_ref_check CHECK (((octet_length(request_ref) >= 1) AND (octet_length(request_ref) <= 4096))),
    CONSTRAINT origin_tool_calls_result_ref_check CHECK (((octet_length(result_ref) >= 1) AND (octet_length(result_ref) <= 4096)))
);


--
-- Name: tool_results; Type: TABLE; Schema: tool; Owner: -
--

CREATE TABLE tool.tool_results (
    invocation_id uuid NOT NULL,
    result_content_id uuid NOT NULL,
    result_hash bytea NOT NULL,
    provider_request_ref character varying(255),
    committed_at_ms bigint NOT NULL,
    result_schema_key character varying(255),
    result_schema_hash bytea,
    provider_request_ref_protected bytea,
    erasure_job_id uuid,
    CONSTRAINT tool_result_erased_payload CHECK (((erasure_job_id IS NULL) OR (num_nonnulls(provider_request_ref, provider_request_ref_protected) = 0))),
    CONSTRAINT tool_result_schema_pair CHECK (((result_schema_key IS NULL) = (result_schema_hash IS NULL))),
    CONSTRAINT tool_result_schema_sha256 CHECK (((result_schema_hash IS NULL) OR (octet_length(result_schema_hash) = 32))),
    CONSTRAINT tool_result_sha256 CHECK ((octet_length(result_hash) = 32))
);


--
-- Name: COLUMN tool_results.provider_request_ref; Type: COMMENT; Schema: tool; Owner: -
--

COMMENT ON COLUMN tool.tool_results.provider_request_ref IS 'Retired plaintext column. Rust Runtime writes only provider_request_ref_protected.';


--
-- Name: COLUMN tool_results.provider_request_ref_protected; Type: COMMENT; Schema: tool; Owner: -
--

COMMENT ON COLUMN tool.tool_results.provider_request_ref_protected IS 'Versioned AEAD envelope bound to Tool invocation identity.';


