--
-- Name: runs report_run_terminal_wake; Type: TRIGGER; Schema: runtime; Owner: -
--

CREATE TRIGGER report_run_terminal_wake AFTER UPDATE OF status ON runtime.runs FOR EACH ROW WHEN (((new.status = ANY (ARRAY[5, 6, 7])) AND (new.status IS DISTINCT FROM old.status))) EXECUTE FUNCTION collaboration.notify_supervisor_lane('report');


--
-- Name: runs run_dispatch_notify; Type: TRIGGER; Schema: runtime; Owner: -
--

CREATE TRIGGER run_dispatch_notify AFTER INSERT OR UPDATE OF status, not_before_ms ON runtime.runs FOR EACH ROW EXECUTE FUNCTION runtime.notify_dispatch_change();


--
-- Name: runs runtime_run_learning_enqueue_insert; Type: TRIGGER; Schema: runtime; Owner: -
--

CREATE TRIGGER runtime_run_learning_enqueue_insert AFTER INSERT ON runtime.runs FOR EACH ROW WHEN (((new.status >= 5) AND (new.status <= 8))) EXECUTE FUNCTION evolution.enqueue_terminal_run_learning();


--
-- Name: runs runtime_run_learning_enqueue_update; Type: TRIGGER; Schema: runtime; Owner: -
--

CREATE TRIGGER runtime_run_learning_enqueue_update AFTER UPDATE OF status ON runtime.runs FOR EACH ROW WHEN (((new.status >= 5) AND (new.status <= 8) AND ((old.status < 5) OR (old.status > 8)))) EXECUTE FUNCTION evolution.enqueue_terminal_run_learning();


